# ================= V6.248: SETUPY vs KIERUNEK BTC - czy setupy krypto przeciw sygnalom BTC wypadaja gorzej =================
_V248 = {'btc_ser': None, 'wynik': [], 'filtry': {}, 'teraz': {}, 'zmienione': 0}
V248_KANDYDACI = ('top vs tlum + stablecoiny zgodne', 'top vs tlum (za top)', 'likwidacje skrajne (kaskada, w strone)', 'kapitulacja OI (kontra)',
                  'stablecoiny 7d (za nimi)', 'model kierunku BTC 24h (za nim)', 'CVD 24h (za nim)',
                  'CVD coina 24h (setup za przeplywem)', 'CVD coina 4h (setup za przeplywem)',   # V6.275: + CVD   # sygnaly, ktore moga zmieniac ocene; V6.272: + model
                  'arkusz bid/ask (za przewaga)', 'mapa likwidacji (od wiekszego skupiska)',      # V6.296: kontekst CoinGlass dla setupow
                  'BTC wybicie 24h (za nim)', 'BTC po silnym ruchu 24h (kontra)')                 # V6.296: squeeze shortow / kupowanie szczytu
V296_RUCH_PROG = 3.0     # V6.296: BTC 24h > +3% / < -3% -> 'po silnym ruchu (kontra)'
V248_MIN_N = 30          # min. setupow przeciw sygnalowi w KAZDEJ probie
V249_ROZNICA_MIN = -0.15  # V6.249: prog lagodny - srednio przeciw gorzej o co najmniej tyle R
V248_BLOKADA_R = -0.30   # blokada, gdy setupy przeciw maja srednio <= tyle R w obu probach i roznica <= -0.2R


def _v248_seria_btc(dane_poz, ceny4h, stab=None, zt_sig=None):
    """Szereg czasowy kierunku sygnalow BTC (t = chwila, gdy sygnal jest znany)."""
    ser = []
    df = (dane_poz or {}).get('BTCUSDT')
    a = (ceny4h or {}).get('BTCUSDT')
    if df is not None and len(df) and a is not None:
        d = _v230_cechy(df)
        tt, cc = a[:, T], a[:, C]
        rows = []
        for r in d.to_dict('records'):
            i = int(np.searchsorted(tt, r['t'] - 4 * HOUR_MS))
            if i < 6 or i >= len(cc) or abs(tt[i] + 4 * HOUR_MS - r['t']) > 4 * HOUR_MS:
                continue
            r['ch24'] = (cc[i] / cc[i - 6] - 1) * 100
            r['_sym'] = 'BTCUSDT'
            rows.append({'t': int(r['t']), **_v230_sygnaly(r)})
        if rows:
            ser.append(('poz', pd.DataFrame(rows), 6 * HOUR_MS))
    if a is not None and len(a) > 7:                         # V6.296: cena BTC (tylko zamkniete swiece 4h)
        try:
            cen = _v296_cena_btc(a)
            if len(cen):
                ser.append(('cena', cen, 4 * HOUR_MS))
        except Exception as exc:
            print(f'V6.296 cena BTC: blad ({str(exc)[:100]})')
    if stab is not None and len(stab):
        s = stab.dropna().copy()
        s['t'] = s.t.astype('int64') + DAY_MS                   # wartosc dzienna znana po zakonczeniu dnia
        s['stablecoiny 7d (za nimi)'] = np.where(s.z > 1, 1, np.where(s.z < -1, -1, 0))
        ser.append(('stab', s[['t', 'stablecoiny 7d (za nimi)']], 2 * DAY_MS))
        poz = next((x[1] for x in ser if x[0] == 'poz'), None)          # V6.258: sygnal laczony
        if poz is not None and 'top vs tlum (za top)' in poz.columns:
            m = pd.merge_asof(poz[['t', 'top vs tlum (za top)']].sort_values('t'), s[['t', 'stablecoiny 7d (za nimi)']].sort_values('t'),
                              on='t', direction='backward', tolerance=2 * DAY_MS).fillna(0)
            m['top vs tlum + stablecoiny zgodne'] = np.where(m['top vs tlum (za top)'] == m['stablecoiny 7d (za nimi)'], m['top vs tlum (za top)'], 0).astype(int)
            ser.append(('zgodne', m[['t', 'top vs tlum + stablecoiny zgodne']], 6 * HOUR_MS))
    mo = _V241.get('oos_btc')                              # V6.272: model kierunku (prognozy poza probka)
    if mo is not None and len(mo):
        ser.append(('model', mo, 6 * HOUR_MS))
    if zt_sig is not None and len(zt_sig):
        z = zt_sig.copy()
        cols = [c for c in ZT_OPIS if c in z.columns]
        for c in cols:                                          # aktywny na ostatnich 2 swiecach 4h
            v = z[c].replace(0, np.nan).ffill(limit=1).fillna(0)
            z[c] = v.astype(int)
        ser.append(('zt', z[['t'] + cols], 4 * HOUR_MS))
    return ser


def _v296_cena_btc(a, now_ms=None):
    """V6.296: sygnaly z ceny BTC na zamknieciu swiecy 4h (t = koniec swiecy).
    'BTC wybicie 24h (za nim)': zamkniecie nad szczytem / pod dolkiem poprzednich 24h -> +1 / -1 (short przeciw = squeeze).
    'BTC po silnym ruchu 24h (kontra)': BTC 24h > +3% -> -1, < -3% -> +1 (long przeciw = kupowanie po wybiciu)."""
    now_ms = int(time.time() * 1000) if now_ms is None else int(now_ms)
    tt, hh, ll, cc = a[:, T], a[:, H], a[:, L], a[:, C]
    rows = []
    for i in range(6, len(cc)):
        tk = int(tt[i]) + 4 * HOUR_MS
        if tk > now_ms:                                       # swieca niezamknieta
            continue
        hi, lo = float(np.max(hh[i - 6:i])), float(np.min(ll[i - 6:i]))
        ch = (cc[i] / cc[i - 6] - 1) * 100 if cc[i - 6] else 0.0
        rows.append({'t': tk,
                     'BTC wybicie 24h (za nim)': 1 if cc[i] > hi else -1 if cc[i] < lo else 0,
                     'BTC po silnym ruchu 24h (kontra)': -1 if ch > V296_RUCH_PROG else 1 if ch < -V296_RUCH_PROG else 0})
    d = pd.DataFrame(rows)
    if len(d):
        ost = d.iloc[-1]
        _V248['cena_teraz'] = {k: int(ost[k]) for k in d.columns if k != 't'} if now_ms - int(ost.t) <= 4 * HOUR_MS + 15 * 60_000 else {}
    return d


def _v248_setupy(df):
    """Rozliczone setupy krypto z czasem wejscia (ms) i strona (+1/-1)."""
    if df is None or not len(df) or 'r' not in df.columns:
        return pd.DataFrame()
    d = df.copy()
    if 'asset_type' in d.columns:
        d = d[d.asset_type.fillna('COIN').eq('COIN')]
    d = d[d.r.notna() & d.status.isin(FINAL)].copy()
    if not len(d):
        return d
    d['t'] = pd.to_datetime(d.snapshot_utc, utc=True, errors='coerce').dt.tz_convert(None).values.astype('datetime64[ms]').astype('int64')
    d = d[d.t > 0].sort_values('t')
    d['s'] = np.where(d.side.astype(str).eq('LONG'), 1, -1)
    d['r'] = pd.to_numeric(d.r, errors='coerce')
    return d.dropna(subset=['r'])


def _v248_porownanie(d, kol):
    """Setupy przeciw / zgodne / bez sygnalu + roznica (przeciw - reszta) w trzech tercjach czasu."""
    x = d.dropna(subset=[kol])
    al = np.sign(x[kol].astype(float)) * x.s
    if not len(x):
        return None
    q = x.t.quantile([1 / 3, 2 / 3]).values
    tc = np.where(x.t < q[0], 1, np.where(x.t < q[1], 2, 3))
    pr = al < 0
    roz = []
    for k in (1, 2, 3):
        a_, b_ = x.r[pr & (tc == k)], x.r[~pr & (tc == k)]
        roz.append(rnd(a_.mean() - b_.mean(), 3) if len(a_) >= 5 and len(b_) >= 5 else None)
    sr = lambda m: rnd(x.r[m].mean(), 3) if m.sum() else None
    return {'n_przeciw': int(pr.sum()), 'R_przeciw': sr(pr), 'n_zgodne': int((al > 0).sum()), 'R_zgodne': sr(al > 0),
            'n_brak': int((al == 0).sum()), 'R_brak': sr(al == 0), 'R_reszta': sr(~pr), 'roznica_tercje': roz}


def _v249_werdykt(w, nm):
    """Werdykt filtra dla jednego sygnalu (prog scisly -> mozliwa blokada; lagodny V6.249 -> ocena -1)."""
    ok_ = lambda pr: (w.get(f'{pr}_n_przeciw') or 0) >= V248_MIN_N and \
        all(x is not None and x < 0 for x in (w.get(f'{pr}_roznica_tercje') or [None]))
    if ok_('30d') and ok_('archiwum'):
        mocny = all((w.get(f'{pr}_R_przeciw') or 0) <= V248_BLOKADA_R and
                    np.mean(w.get(f'{pr}_roznica_tercje')) <= -0.2 for pr in ('30d', 'archiwum'))
        return ('FILTR: ' + ('BLOKADA' if mocny else 'ocena -1')) if nm in V248_KANDYDACI else \
            'przeciw gorzej w obu probach (tylko raport - sygnal spoza listy)'
    elif nm in V248_KANDYDACI and all(                 # V6.249: prog lagodny -> tylko ocena -1
            (w.get(f'{pr}_n_przeciw') or 0) >= V248_MIN_N
            and sum(1 for x in (w.get(f'{pr}_roznica_tercje') or []) if x is not None and x < 0) >= 2
            and w.get(f'{pr}_R_przeciw') is not None and w.get(f'{pr}_R_reszta') is not None
            and w[f'{pr}_R_przeciw'] - w[f'{pr}_R_reszta'] <= V249_ROZNICA_MIN
            for pr in ('30d', 'archiwum')):
        return 'FILTR: ocena -1 (przeciw gorzej w 2 z 3 okresow obu prob)'
    elif not any(w.get(f'{pr}_n_przeciw') for pr in ('30d', 'archiwum')):
        return 'brak setupow przeciw sygnalowi'
    else:
        return 'brak stalej roznicy'


def _v251_typy(proby, filtry):
    """V6.251: wynik kazdego typu/strony: wszystkie / zgodne z aktywnymi filtrami BTC / + funding alta przeciw tlumowi.
    Polowy czasu osobno. Tylko raport - wlaczenie typu dopiero po decyzji."""
    out = []
    if not len(proby.get('30d', [])) or 'setup_type' not in proby['30d'].columns:
        return out
    for (tp, sd), _ in (proby.get('30d') if len(proby.get('30d', [])) else pd.DataFrame(columns=['setup_type', 'side'])).groupby(['setup_type', 'side']):
        w = {'typ': tp, 'side': sd, 'wylaczony': bool(typ_wylaczony(tp, sd))}
        for pr, d in proby.items():
            if not len(d):
                continue
            x = d[(d.setup_type == tp) & (d.side == sd)].sort_values('t')
            zg = pd.Series(True, index=x.index)
            for f in filtry:
                c = 'v248_' + f
                if c in x.columns:
                    zg &= ~(np.sign(x[c].astype(float)) * x.s < 0)        # nie przeciw filtrowi
            fz = pd.to_numeric(x.get('funding_z_hist'), errors='coerce') * x.s
            for nm, m in (('wszystkie', pd.Series(True, index=x.index)), ('zgodne_BTC', zg), ('zgodne_BTC_i_przeciw_tlumowi', zg & (fz <= 0))):
                y = x[m]
                h = len(y) // 2
                w[f'{pr}_{nm}_n'] = len(y)
                w[f'{pr}_{nm}_R'] = rnd(y.r.mean(), 3) if len(y) else None
                w[f'{pr}_{nm}_polowy'] = [rnd(y.r.iloc[:h].mean(), 2), rnd(y.r.iloc[h:].mean(), 2)] if len(y) >= 20 else None
        out.append(w)
    return out


def badanie_setupy_btc_v248(hist_df, arch_df, ser):
    """Dla kazdego sygnalu BTC: R setupow krypto przeciw / zgodnych, w tescie 30 dni i w archiwum."""
    proby = {'30d': _v248_setupy(hist_df), 'archiwum': _v248_setupy(arch_df)}
    nazwy = []
    for nm_p, d in list(proby.items()):
        if not len(d):
            continue
        for _, s, tol in ser:
            cols = [c for c in s.columns if c != 't']
            d = pd.merge_asof(d.sort_values('t'), s.sort_values('t').rename(columns={c: 'v248_' + c for c in cols}),
                              on='t', direction='backward', tolerance=int(tol))
            nazwy += [c for c in cols if c not in nazwy]
        proby[nm_p] = d
    nazwy += ['BTC trend 1h (setup w strone trendu)', 'BTC trend 4h (setup w strone trendu)']
    for nm_p, d in list(proby.items()):                    # V6.275: CVD coina (wlasny przeplyw kazdego setupu)
        if len(d):
            for nm, (c, prog) in V275_CVD_COINA.items():
                x = pd.to_numeric(d[c], errors='coerce') if c in d.columns else pd.Series(np.nan, index=d.index)
                d['v275_' + nm] = np.where(x.isna(), np.nan, np.where(x - 50 >= prog, 1, np.where(x - 50 <= -prog, -1, 0)))
            proby[nm_p] = d
    nazwy += list(V275_CVD_COINA)
    wyn = []
    for nm in nazwy:
        w = {'sygnal': nm}
        for nm_p, d in proby.items():
            kol = {'BTC trend 1h (setup w strone trendu)': 'btc_trend_1h',
                   'BTC trend 4h (setup w strone trendu)': 'btc_trend_4h'}.get(nm, ('v275_' if nm in V275_CVD_COINA else 'v248_') + nm)
            p = _v248_porownanie(d, kol) if len(d) and kol in d.columns else None
            for k, v in (p or {}).items():
                w[f'{nm_p}_{k}'] = v
        w['wniosek'] = _v249_werdykt(w, nm)
        if nm in V275_CVD_COINA and not str(w['wniosek']).startswith('FILTR') and (w.get('archiwum_n_przeciw') or 0) < V248_MIN_N:
            r30 = w.get('30d_roznica_tercje') or [None]       # V6.275: archiwum bez cech CVD -> sam test 30 dni, prog scisly, tylko ocena -1
            if ((w.get('30d_n_przeciw') or 0) >= V248_MIN_N and all(x is not None and x < 0 for x in r30)
                    and w.get('30d_R_przeciw') is not None and w.get('30d_R_reszta') is not None
                    and w['30d_R_przeciw'] - w['30d_R_reszta'] <= V249_ROZNICA_MIN):
                w['wniosek'] = 'FILTR: ocena -1 (tylko test 30 dni - archiwum jeszcze bez CVD coina)'
        wyn.append(w)
    try:                                                   # V6.251: typy (tez wylaczone) w zgodzie z filtrami BTC i przeciw tlumowi
        _V248['typy'] = _v251_typy(proby, [w['sygnal'] for w in wyn if str(w.get('wniosek', '')).startswith('FILTR')])
    except Exception as exc:
        _V248['typy'] = []
        print(f'V6.251 typy: blad ({str(exc)[:100]})')
    return wyn


def _v248_btc_teraz():
    """Biezacy kierunek sygnalow BTC (+1/-1/0)."""
    t = {}
    t.update({k: int(v) for k, v in ((((_V230.get('teraz') or {}).get('BTCUSDT') or {}).get('syg')) or {}).items() if v})
    st = (_V243.get('dni_teraz') or {}).get('stablecoiny')
    if st and st[2] is not None:
        t['stablecoiny 7d (za nimi)'] = 1 if st[2] > 1 else -1 if st[2] < -1 else 0
    if t.get('top vs tlum (za top)') and t.get('top vs tlum (za top)') == t.get('stablecoiny 7d (za nimi)'):   # V6.258
        t['top vs tlum + stablecoiny zgodne'] = t['top vs tlum (za top)']
    t.update({k: int(v) for k, v in ((_V246.get('teraz') or {}).get('BTCUSDT') or {}).items() if not k.startswith('_') and v})
    t.update({k: int(v) for k, v in (_V248.get('cena_teraz') or {}).items() if v})   # V6.296
    p_ = (_V241.get('teraz') or {}).get('BTCUSDT')         # V6.272
    if p_ is not None and p_ == p_:
        t['model kierunku BTC 24h (za nim)'] = 1 if p_ >= 0.5 + MODEL_PROG else -1 if p_ <= 0.5 - MODEL_PROG else 0
    return {k: v for k, v in t.items() if v}


V275_CVD_COINA = {'CVD coina 24h (setup za przeplywem)': ('cvd_24h_pct', 2.0), 'CVD coina 4h (setup za przeplywem)': ('cvd_4h_pct', 3.0)}


def zastosuj_cvd_coina_v275(out_dir):
    """V6.275: setup krypto przeciw wlasnemu przeplywowi (CVD coina), gdy test = FILTR -> ocena -1; zgodny -> dopisek."""
    filtry = {w['sygnal']: w for w in _V248.get('wynik') or [] if w['sygnal'] in V275_CVD_COINA and str(w.get('wniosek', '')).startswith('FILTR')}
    _V248['filtry_cvd'] = list(filtry)
    if not filtry:
        return 0
    n, nizej = 0, {'A': 'B', 'B': 'C', 'C': 'D', 'D': 'D'}
    for plik in ('top_market.csv', 'top_limit.csv', 'setups.csv'):
        f = Path(out_dir) / plik
        if not f.is_file():
            continue
        try:
            df = pd.read_csv(f, low_memory=False)
        except Exception:
            continue
        if not len(df) or 'side' not in df.columns:
            continue
        for c in ('zdarzenie_v242', 'ocena'):
            if c not in df.columns:
                df[c] = None
            df[c] = df[c].astype(object)
        coin = df.get('asset_type', pd.Series('COIN', index=df.index)).fillna('COIN').eq('COIN')
        for i in df.index[coin]:
            sd = 1 if str(df.at[i, 'side']) == 'LONG' else -1
            dop, obniz = [], False
            for nm, w in filtry.items():
                c, prog = V275_CVD_COINA[nm]
                v = pd.to_numeric(pd.Series([df.at[i, c] if c in df.columns else None]), errors='coerce').iloc[0]
                if v != v:
                    continue
                k = 1 if v - 50 >= prog else -1 if v - 50 <= -prog else 0
                if k == sd:
                    dop.append(f"zgodne z przeplywem coina ({c} {v:.1f}%)")
                elif k == -sd:
                    obniz = True
                    dop.append(f"PRZECIW przeplywowi coina ({c} {v:.1f}%; przeciw {w.get('30d_R_przeciw')}R vs reszta {w.get('30d_R_reszta')}R w 30d)")
            if obniz:                                      # jedna obnizka, nawet gdy oba okna przeciw
                o = str(df.at[i, 'ocena']) if isinstance(df.at[i, 'ocena'], str) else ''
                if o in nizej:
                    df.at[i, 'ocena'] = nizej[o]
                    dop[-1] += f", ocena {o}->{nizej[o]}"
                n += plik != 'setups.csv'
            if dop:
                old = df.at[i, 'zdarzenie_v242']
                df.at[i, 'zdarzenie_v242'] = '; '.join(([old] if isinstance(old, str) and old else []) + dop)
        df.to_csv(f, index=False)
    return n


def zastosuj_v248(out_dir):
    """Setupy krypto przeciw aktywnemu sygnalowi-FILTROWI: ocena -1 albo blokada; zgodne: dopisek."""
    filtry = {w['sygnal']: w for w in _V248.get('wynik') or [] if str(w.get('wniosek', '')).startswith('FILTR')}
    teraz = _v248_btc_teraz()
    _V248['filtry'], _V248['teraz'] = filtry, teraz
    akt = {k: v for k, v in teraz.items() if k in filtry}
    if not akt:
        return 0
    n, nizej = 0, {'A': 'B', 'B': 'C', 'C': 'D', 'D': 'D'}
    for plik in ('top_market.csv', 'top_limit.csv', 'setups.csv'):
        f = Path(out_dir) / plik
        if not f.is_file():
            continue
        try:
            df = pd.read_csv(f, low_memory=False)
        except Exception:
            continue
        if not len(df) or 'side' not in df.columns:
            continue
        for c in ('zdarzenie_v242', 'blokady_bezpieczenstwa', 'warunki', 'status_setupu', 'ocena'):
            if c not in df.columns:
                df[c] = None
            df[c] = df[c].astype(object)
        coin = df.get('asset_type', pd.Series('COIN', index=df.index)).fillna('COIN').eq('COIN')
        for i in df.index[coin]:
            sd = 1 if str(df.at[i, 'side']) == 'LONG' else -1
            dop = []
            for nm, k in akt.items():
                w = filtry[nm]
                if sd == k:
                    dop.append(f"zgodne z BTC: {nm}")
                    continue
                if _V255.get('zwrot') == sd and str((_V255.get('badanie') or {}).get('werdykt')) == 'DZIALA':   # V6.256: tylko po tescie
                    dop.append(f"przeciw BTC: {nm}, ale ZWROT {'W GORE' if sd > 0 else 'W DOL'} POTWIERDZONY - bez obnizki")
                    continue
                opis = f"przeciw BTC: {nm} (setupy przeciw {w.get('archiwum_R_przeciw')}R vs reszta {w.get('archiwum_R_reszta')}R)"
                if 'BLOKADA' in w['wniosek']:
                    for c in ('blokady_bezpieczenstwa', 'warunki'):
                        old = df.at[i, c]
                        df.at[i, c] = opis if not isinstance(old, str) or not old else f"{opis}; {old}"
                    df.at[i, 'status_setupu'] = 'ZABLOKOWANY'
                    if 'do_handlu' in df.columns:
                        df.at[i, 'do_handlu'] = False
                else:
                    o = str(df.at[i, 'ocena']) if isinstance(df.at[i, 'ocena'], str) else ''
                    if o in nizej:
                        df.at[i, 'ocena'] = nizej[o]
                    dop.append(opis + f", ocena {o}->{nizej.get(o, o)}")
                n += plik != 'setups.csv'
            if dop:
                old = df.at[i, 'zdarzenie_v242']
                df.at[i, 'zdarzenie_v242'] = '; '.join(([old] if isinstance(old, str) and old else []) + dop)
        df.to_csv(f, index=False)
    _V248['zmienione'] = n
    return n


# ================= V6.255: ZWROT POTWIERDZONY (2 z 3 warunkow) + tryb ochronny bez blokady =================
_V255 = {'zwrot': 0, 'warunki': {}, 'badanie': None, 'ochrona': None}
ZWROT_TOP_Z = 0.5          # top traderzy: z > +0.5 (zwrot w gore) / < -0.5 (w dol)


def _v255_warunki(close, high, low, i, top_z, kaskada):
    """Warunki zwrotu na swiecy i (zamknietej): cena (zamkniecie poza zakresem 24h), top traderzy, kaskada likwidacji."""
    w = {}
    if i >= 7:
        w['cena'] = 1 if close[i] > np.max(high[i - 6:i]) else -1 if close[i] < np.min(low[i - 6:i]) else 0
    else:
        w['cena'] = 0
    w['top traderzy'] = (1 if top_z > ZWROT_TOP_Z else -1 if top_z < -ZWROT_TOP_Z else 0) if top_z is not None and top_z == top_z else 0
    w['kaskada likwidacji'] = int(kaskada or 0)
    up, dn = sum(v == 1 for v in w.values()), sum(v == -1 for v in w.values())
    zw = 1 if up >= 2 and dn == 0 else -1 if dn >= 2 and up == 0 else 0
    return zw, w


def zwrot_teraz_v255(PP, now_ms):
    """Biezacy stan zwrotu BTC (ostatnia zamknieta swieca 4h)."""
    P = (PP or {}).get('BTCUSDT') or {}
    a = (P.get('arr') or {}).get('4h')
    if a is None or len(a) < 8:
        return 0, {}
    a = a[a[:, T] + 4 * HOUR_MS <= now_ms]
    pz = (_V230.get('teraz') or {}).get('BTCUSDT') or {}
    kas = (pz.get('syg') or {}).get('likwidacje skrajne (kaskada, w strone)', 0)
    st1 = (_V243.get('teraz1h') or {}).get('BTCUSDT') or {}
    if not kas and str((_V243.get('kaskada1h') or {}).get('werdykt')) == 'DZIALA' and st1.get('kier') and st1.get('t', 0) >= now_ms - 3 * HOUR_MS:
        kas = st1['kier']
    zw, w = _v255_warunki(a[:, C], a[:, H], a[:, L], len(a) - 1, pz.get('top_z'), kas)
    w['_poziomy'] = (rnd(float(np.max(a[-7:-1, H])), 1), rnd(float(np.min(a[-7:-1, L])), 1))
    return zw, w


def badanie_zwrotu_v255(dpz, c4):
    """Historia: kazde pierwsze 'zwrot potwierdzony' (min. 24h odstepu) -> ruch BTC po 12h/24h/48h w strone zwrotu."""
    df = (dpz or {}).get('BTCUSDT')
    a = (c4 or {}).get('BTCUSDT')
    if df is None or a is None or not len(df) or len(a) < 50:
        return None
    d = _v230_cechy(df)
    tt, cc, hh, ll = a[:, T], a[:, C], a[:, H], a[:, L]
    rows, ost = [], {1: -10 ** 18, -1: -10 ** 18}
    for r in d.to_dict('records'):
        i = int(np.searchsorted(tt, r['t'] - 4 * HOUR_MS))
        if i < 7 or i + 12 >= len(cc) or abs(tt[i] + 4 * HOUR_MS - r['t']) > 4 * HOUR_MS:
            continue
        r['ch24'] = (cc[i] / cc[i - 6] - 1) * 100
        r['_sym'] = 'BTCUSDT'
        kas = _v230_sygnaly(r).get('likwidacje skrajne (kaskada, w strone)', 0)
        zw, _ = _v255_warunki(cc, hh, ll, i, r.get('top_z'), kas)
        if zw and r['t'] - ost[zw] >= DAY_MS:
            rows.append({'t': r['t'], 'kier': zw, **{f'r{h}': zw * (cc[i + h // 4] / cc[i] - 1) * 1e4 for h in (12, 24, 48)}})
        if zw:
            ost[zw] = r['t']
    x = pd.DataFrame(rows)
    if len(x) < 10:
        return {'n': len(x), 'werdykt': 'za malo zdarzen'}
    q = x.t.quantile([1 / 3, 2 / 3]).values
    x['tc'] = np.where(x.t < q[0], 1, np.where(x.t < q[1], 2, 3))
    tr = x.groupby('tc').r24.mean()
    w = {'n': len(x), 'n_gora': int((x.kier == 1).sum()), 'n_dol': int((x.kier == -1).sum()),
         'traf_12h': rnd((x.r12 > 0).mean() * 100, 1), 'traf_24h': rnd((x.r24 > 0).mean() * 100, 1), 'traf_48h': rnd((x.r48 > 0).mean() * 100, 1),
         'sr_24h_bps': rnd(x.r24.mean(), 0), 'sr_48h_bps': rnd(x.r48.mean(), 0), 'tercje_24h': [rnd(tr.get(k), 0) for k in (1, 2, 3)],
         'gora_traf_24h': rnd((x[x.kier == 1].r24 > 0).mean() * 100, 1) if (x.kier == 1).any() else None,
         'dol_traf_24h': rnd((x[x.kier == -1].r24 > 0).mean() * 100, 1) if (x.kier == -1).any() else None}
    w['werdykt'] = _v247_werdykt(w['tercje_24h'], w['traf_24h'])
    return w


def ochrona_wplyw_v255(arch):
    """Co dalby tryb ochronny jako blokada: setupy (typy aktywne, po filtrach) w chwili, gdy strona miala ujemny wynik
    z ostatnich OCHRONA_DNI dni (transakcje zamkniete przed wejsciem, min. 5), vs reszta; polowy czasu."""
    try:
        a = _v222_baza_arch(arch)
    except Exception:
        return None
    if a is None or not len(a) or 'exit_utc' not in a.columns:
        return None
    ms_ = lambda s: pd.to_datetime(s, utc=True, errors='coerce').dt.tz_convert(None).values.astype('datetime64[ms]').astype('int64')
    a = a.assign(t=ms_(a.snapshot_utc), te=ms_(a.exit_utc))
    a = a[a.t > 0].sort_values('t')
    out = []
    for sd in ('LONG', 'SHORT'):
        x = a[a.side == sd]
        te, rr = x.te.values, x.r.values.astype(float)
        st = []
        for t in x.t.values:
            m = (te <= t) & (te > t - OCHRONA_DNI * DAY_MS)
            st.append(rr[m].mean() if m.sum() >= 5 else np.nan)
        st = np.array(st)
        p1 = np.arange(len(x)) < len(x) // 2
        w = {'strona': sd}
        for nm, m in (('blokowane', st < 0), ('przepuszczone', st >= 0)):
            w[f'{nm}_n'] = int(m.sum())
            w[f'{nm}_R'] = rnd(float(rr[m].mean()), 3) if m.sum() else None
            w[f'{nm}_suma'] = rnd(float(rr[m].sum()), 1) if m.sum() else None
            w[f'{nm}_polowy'] = [rnd(float(rr[m & p1].mean()), 2) if (m & p1).sum() else None,
                                 rnd(float(rr[m & ~p1].mean()), 2) if (m & ~p1).sum() else None]
        out.append(w)
    return out


_V256 = {'blok': {}}


def _v256_blokuje(side=None):
    """Czy tryb ochronny blokuje te strone (OCHRONA_BLOKUJE True/False albo 'AUTO' wg _V256['blok'])."""
    if OCHRONA_BLOKUJE == 'AUTO':
        return any(_V256['blok'].values()) if side is None else bool(_V256['blok'].get(side))
    return bool(OCHRONA_BLOKUJE)


def _v256_ustaw_auto(wplyw):
    """Blokada strony tylko gdy zablokowane setupy byly gorsze od przepuszczonych lacznie i w obu polowach (min. 30/30)."""
    blok = {}
    for w in wplyw or []:
        b, p = w.get('blokowane_R'), w.get('przepuszczone_R')
        bp, pp = w.get('blokowane_polowy') or [None, None], w.get('przepuszczone_polowy') or [None, None]
        ok = ((w.get('blokowane_n') or 0) >= 30 and (w.get('przepuszczone_n') or 0) >= 30 and b is not None and p is not None and b < p
              and all(x is not None and y is not None and x < y for x, y in zip(bp, pp)))
        blok[w['strona']] = bool(ok)
    _V256['blok'] = blok
    return blok


# ================= V6.258: wyniki na zywo, alerty, koncentracja, zgodnosc sygnalow, kalendarz makro =================
_V258 = {'pozycje': [], 'live': None, 'zgodnosc': None, 'makro': None, 'alerty': 0}
LIVE_PROG_N = 30                 # tyle transakcji na zywo przed decyzja o wiekszej stawce
DZIENNIK_AUTO_CSV = 'dziennik_auto.csv'   # na Drive: pozycje zamkniete wykryte automatycznie z konta WEEX (wynik szacunkowy)
AUTO_PETLA_MIN = 0               # >0: kolektor uruchamia sie w petli co tyle minut (Colab), np. 15
AUTO_PETLA_MAX_H = 10            # petla konczy sie po tylu godzinach
AUTO_PETLA_4H = True             # V6.284: dodatkowy przebieg 3 min po zamknieciu kazdej swiecy 4h (00:03, 04:03, ... UTC)
MAKRO_URL = 'https://nfs.faireconomy.media/ff_calendar_thisweek.json'
MAKRO_OKNO_PRZED_H, MAKRO_OKNO_PO_H = 4, 1
KONCENTRACJA_PROG = 2            # dopisek, gdy w te strone sa juz >= tyle pozycji/setupow krypto
ZGODNOSC_SYG = 'top vs tlum + stablecoiny zgodne'


def _v258_zamkniete(state, live_ids, now_ms):
    """Pozycje widziane wczesniej, ktorych juz nie ma na koncie -> wiersze dziennika (wynik z ostatniego PnL, szacunek)."""
    out = []
    for pid, st in (state or {}).items():
        if pid in live_ids or not st.get('symbol') or st.get('zamknieta'):
            continue
        try:
            ryz = abs(float(st['entry']) - float(st['sl_start'])) * float(st['ilosc'])
            r = float(st.get('pnl_last') or 0) / ryz if ryz > 0 else None
        except (KeyError, TypeError, ValueError):
            r = None
        t = datetime.fromtimestamp(now_ms / 1000, tz=timezone.utc)
        if ZoneInfo is not None:
            try:
                t = t.astimezone(ZoneInfo('Europe/Warsaw'))
            except Exception:
                pass
        out.append({'data_pl': t.strftime('%Y-%m-%d'), 'symbol': st['symbol'], 'side': st['side'],
                    'wynik_R': rnd(r, 3) if r is not None else None, 'pnl_usdt': rnd(st.get('pnl_last'), 3),
                    'zrodlo': 'auto (szacunek z ostatniego PnL)', 'setup': None,
                    'uwagi': f"otwarta {st.get('otwarta')}, ostatnio widziana {st.get('widziana')}, wejscie {st.get('entry')}, SL start {st.get('sl_start')}"})
    return out


def wyniki_live_v258(drive_ok):
    """Twoje transakcje: dziennik.csv (recznie) + dziennik_auto.csv (konto WEEX). Liczba, srednie R, LONG/SHORT, postep do progu."""
    ramki = []
    for nazwa in (DZIENNIK_CSV, DZIENNIK_AUTO_CSV):
        fp = Path(DRIVE_DIR) / nazwa
        if drive_ok and fp.is_file():
            try:
                d = pd.read_csv(fp)
                d['_plik'] = nazwa
                ramki.append(d)
            except Exception as exc:
                print(f'{nazwa}: blad odczytu ({str(exc)[:80]})')
    if not ramki:
        return {'n': 0}
    df = pd.concat(ramki, ignore_index=True)
    ryz = KAPITAL_USDT * RYZYKO_NA_TRANSAKCJE_PCT / 100
    r = pd.to_numeric(df.get('wynik_R'), errors='coerce')
    if 'pnl_usdt' in df:
        r = r.fillna(pd.to_numeric(df['pnl_usdt'], errors='coerce') / ryz)
    df['R'] = r
    df = df.dropna(subset=['R'])
    if not len(df):
        return {'n': 0}
    w = {'n': len(df), 'suma_R': rnd(df.R.sum(), 2), 'sredni_R': rnd(df.R.mean(), 3), 'skutecznosc': rnd((df.R > 0).mean() * 100, 1),
         'auto': int((df._plik == DZIENNIK_AUTO_CSV).sum())}
    for sd in ('LONG', 'SHORT'):
        x = df[df.get('side', pd.Series('', index=df.index)).astype(str).str.upper() == sd]
        w[sd] = (len(x), rnd(x.R.mean(), 3) if len(x) else None)
    if len(df) >= 10:
        se = df.R.std() / np.sqrt(len(df))
        w['t'] = rnd(df.R.mean() / se, 2) if se > 0 else None
    w['werdykt'] = ('za malo transakcji' if len(df) < LIVE_PROG_N else
                    'PRZEWAGA POTWIERDZONA' if (w.get('t') or 0) >= 2 else
                    'na plus, ale niepewne' if w['sredni_R'] > 0 else 'BRAK PRZEWAGI')
    return w


def _v258_wysylka(tekst):
    """Telegram (sekrety Colab TELEGRAM_TOKEN, TELEGRAM_CHAT_ID). Bez sekretow: tylko wydruk."""
    tok, chat = api_secret('TELEGRAM_TOKEN'), api_secret('TELEGRAM_CHAT_ID')
    if not (tok and chat):
        print('ALERT (Telegram nieustawiony):', tekst)
        return False
    try:
        r = requests.post(f'https://api.telegram.org/bot{tok}/sendMessage', data={'chat_id': chat, 'text': tekst}, timeout=10)
        return r.status_code == 200
    except Exception as exc:
        print(f'Telegram: blad ({str(exc)[:80]})')
        return False


def alerty_v258(out_dir, drive_ok):
    """Alert przy NOWYM setupie DO GRY (ten sam symbol+kierunek+typ nie czesciej niz raz na 6h)."""
    plik = (Path(DRIVE_DIR) if drive_ok and not REPLAY_ZIP else OUT_ROOT / 'weex_cache') / 'alerty_v258.json'
    try:
        stan = json.loads(plik.read_text()) if plik.is_file() else {}
    except Exception:
        stan = {}
    teraz, nowe = time.time(), []
    for k_ in _V277.get('plan') or []:                    # V6.284: plan gry na gorze alertu
        kl = f"PLAN|{k_['symbol']}|{k_['side']}|{k_['typ']}"
        if teraz - float(stan.get(kl, 0)) < 4 * 3600:
            continue
        stan[kl] = teraz
        nowe.append(f"PLAN: {k_['symbol'].replace('USDT', '')} {k_['side']} {'RYNEK' if k_['entry_type'] == 'MARKET' else 'LIMIT'} [{k_['ocena']}] wejscie {psig(k_['entry'])} "
                    f"SL {psig(k_['sl'])} TP {psig(k_['tp1'])} RR {k_['rr']:.2f} dzwignia {k_.get('dzwignia')}x ryzyko {k_.get('ryzyko_usdt')} USDT | {k_['typ']}")
    for tytul, nazwa in (('MARKET', 'top_market.csv'), ('LIMIT', 'top_limit.csv')):
        f = Path(out_dir) / nazwa
        if not f.is_file():
            continue
        try:
            df = pd.read_csv(f, low_memory=False)
        except Exception:
            continue
        for r in df.to_dict('records'):
            if not _v201_powod(r).startswith('DO GRY'):
                continue
            k = f"{r.get('symbol')}|{r.get('side')}|{r.get('setup_type')}"
            if teraz - float(stan.get(k, 0)) < 6 * 3600:
                continue
            stan[k] = teraz
            nowe.append(f"{tytul} {str(r.get('symbol')).replace('USDT', '')} {r.get('side')} {r.get('setup_type')} [{r.get('ocena')}] "
                        f"wejscie {r.get('entry')} SL {r.get('sl')} TP1 {r.get('tp1')} RR {r.get('rr_tp1_net')}")
    for r in _V267.get('teraz') or []:                  # V6.268: setupy z sygnalow (tabela 1b)
        if not r.get('do_gry'):
            continue
        k = f"SYG|{r['symbol']}|{r['side']}|{r['sygnal']}|{r.get('entry_type', 'MARKET')}"
        if teraz - float(stan.get(k, 0)) < 6 * 3600:
            continue
        stan[k] = teraz
        nowe.append(f"SYGNAL {r['symbol'].replace('USDT', '')} {r['side']} {'LIMIT' if r.get('entry_type') == 'LIMIT' else 'RYNEK'} [{r['ocena']}] wejscie {psig(r['entry'])} SL {psig(r['sl'])} "
                    f"TP {psig(r['tp1'])} ({r['rr']}R) | {r['sygnal']}")
    if nowe and not REPLAY_ZIP:
        _v258_wysylka(f'WEEX {VERSION}: nowe DO GRY\n' + '\n'.join(nowe))
        try:
            plik.parent.mkdir(parents=True, exist_ok=True)
            plik.write_text(json.dumps(stan))
        except Exception:
            pass
    return len(nowe)


def koncentracja_v258(out_dir):
    """Dopisek przy setupach krypto: ile pozycji otwartych i innych setupow krypto juz w te strone (to jeden zaklad na BTC)."""
    otw = {'LONG': 0, 'SHORT': 0}
    for p in _V258.get('pozycje') or []:
        sd = str(p.get('side', '')).upper()
        if sd in otw and str(p.get('asset_type', 'COIN')) in ('COIN', 'nan', 'None'):
            otw[sd] += 1
    pliki = {}
    for nazwa in ('top_market.csv', 'top_limit.csv'):
        f = Path(out_dir) / nazwa
        try:
            pliki[nazwa] = pd.read_csv(f, low_memory=False) if f.is_file() else None
        except Exception:
            pliki[nazwa] = None
    syms = {'LONG': set(), 'SHORT': set()}
    for df in pliki.values():
        if df is None or not len(df) or 'side' not in df:
            continue
        coin = df.get('asset_type', pd.Series('COIN', index=df.index)).fillna('COIN').eq('COIN')
        for r in df[coin].to_dict('records'):
            if str(r.get('side')) in syms:
                syms[str(r['side'])].add(r.get('symbol'))
    n = 0
    for nazwa, df in pliki.items():
        if df is None or not len(df) or 'side' not in df:
            continue
        if 'zdarzenie_v242' not in df.columns:
            df['zdarzenie_v242'] = None
        df['zdarzenie_v242'] = df['zdarzenie_v242'].astype(object)
        coin = df.get('asset_type', pd.Series('COIN', index=df.index)).fillna('COIN').eq('COIN')
        for i in df.index[coin]:
            sd = str(df.at[i, 'side'])
            inne = len(syms.get(sd, set()) - {df.at[i, 'symbol']})
            if sd in otw and otw[sd] + inne >= KONCENTRACJA_PROG:
                dop = f"koncentracja {sd}: otwarte {otw[sd]}, inne setupy {inne} (wszystkie zaleza od BTC)"
                old = df.at[i, 'zdarzenie_v242']
                df.at[i, 'zdarzenie_v242'] = f"{old}; {dop}" if isinstance(old, str) and old else dop
                n += 1
        df.to_csv(Path(out_dir) / nazwa, index=False)
    return n


def badanie_zgodnosci_v258(dpz, c4, stab):
    """BTC/ETH: trafnosc 24h, gdy top vs tlum i stablecoiny wskazuja to samo / tylko top vs tlum / sprzecznie."""
    if stab is None or not len(stab):
        return None
    s = stab.dropna().copy()
    s['t'] = s.t.astype('int64') + DAY_MS
    s['k_stab'] = np.where(s.z > 1, 1, np.where(s.z < -1, -1, 0))
    rows = []
    for sym in ('BTCUSDT', 'ETHUSDT'):
        df, a = (dpz or {}).get(sym), (c4 or {}).get(sym)
        if df is None or a is None or not len(df):
            continue
        d = _v230_cechy(df)
        tt, cc = a[:, T], a[:, C]
        for r in d.to_dict('records'):
            i = int(np.searchsorted(tt, r['t'] - 4 * HOUR_MS))
            if i < 6 or i + 6 >= len(cc) or abs(tt[i] + 4 * HOUR_MS - r['t']) > 4 * HOUR_MS:
                continue
            r['ch24'] = (cc[i] / cc[i - 6] - 1) * 100
            r['_sym'] = sym
            k = _v230_sygnaly(r).get('top vs tlum (za top)', 0)
            if k:
                rows.append({'sym': sym, 't': int(r['t']), 'k': k, 'r24': (cc[i + 6] / cc[i] - 1) * 1e4})
    x = pd.DataFrame(rows)
    if not len(x):
        return None
    x = pd.merge_asof(x.sort_values('t'), s[['t', 'k_stab']].sort_values('t'), on='t', direction='backward', tolerance=3 * DAY_MS)
    x['k_stab'] = x.k_stab.fillna(0)
    x['g'] = x.k * x.r24
    q = x.t.quantile([1 / 3, 2 / 3]).values
    x['tc'] = np.where(x.t < q[0], 1, np.where(x.t < q[1], 2, 3))
    out = []
    for nm, m in (('oba zgodne', x.k == x.k_stab), ('stablecoiny neutralne', x.k_stab == 0), ('sprzeczne', x.k == -x.k_stab)):
        y = x[m]
        if not len(y):
            out.append({'grupa': nm, 'n': 0})
            continue
        tr = y.groupby('tc').g.mean()
        out.append({'grupa': nm, 'n': len(y), 'traf_24h': rnd((y.g > 0).mean() * 100, 1), 'sr_24h_bps': rnd(y.g.mean(), 0),
                    'tercje': [rnd(tr.get(k), 0) for k in (1, 2, 3)], 'BTC_n': int((y.sym == 'BTCUSDT').sum()),
                    'BTC_traf': rnd((y[y.sym == 'BTCUSDT'].g > 0).mean() * 100, 1) if (y.sym == 'BTCUSDT').any() else None})
    return out


def makro_v258(now_ms, drive_ok):
    """Kalendarz ForexFactory (ten tydzien): wydarzenia USD o wysokim wplywie. Log na Drive (do przyszlego testu)."""
    if REPLAY_ZIP:
        return None
    r = requests.get(MAKRO_URL, timeout=15, headers={'User-Agent': 'Mozilla/5.0'})
    ev = []
    for x in r.json() or []:
        if str(x.get('country')).upper() != 'USD' or str(x.get('impact')).lower() != 'high':
            continue
        try:
            t = int(pd.Timestamp(x['date']).tz_convert('UTC').value // 10 ** 6)
        except Exception:
            continue
        ev.append({'t': t, 'czas_utc': iso(t)[:16], 'nazwa': x.get('title')})
    ev.sort(key=lambda e: e['t'])
    try:
        plik = Path(DRIVE_DIR) / 'makro_log_v258.csv'
        if drive_ok:
            stary = pd.read_csv(plik) if plik.is_file() else pd.DataFrame(columns=['t', 'czas_utc', 'nazwa'])
            pd.concat([stary, pd.DataFrame(ev)], ignore_index=True).drop_duplicates(['t', 'nazwa']).to_csv(plik, index=False)
    except Exception:
        pass
    blisko = [e for e in ev if now_ms - MAKRO_OKNO_PO_H * HOUR_MS <= e['t'] <= now_ms + MAKRO_OKNO_PRZED_H * HOUR_MS]
    nast = [e for e in ev if e['t'] > now_ms]
    return {'blisko': blisko, 'nastepne': nast[:3]}


def makro_dopisek_v258(out_dir):
    """Dopisek przy setupach krypto, gdy wazne dane USA za <= 4h albo byly w ostatniej godzinie."""
    m = _V258.get('makro') or {}
    if not m.get('blisko'):
        return 0
    txt = 'MAKRO: ' + ', '.join(f"{e['nazwa']} {e['czas_utc'][11:16]} UTC" for e in m['blisko']) + ' (gwaltowne ruchy w obie strony)'
    n = 0
    for nazwa in ('top_market.csv', 'top_limit.csv'):
        f = Path(out_dir) / nazwa
        if not f.is_file():
            continue
        try:
            df = pd.read_csv(f, low_memory=False)
        except Exception:
            continue
        if not len(df):
            continue
        if 'zdarzenie_v242' not in df.columns:
            df['zdarzenie_v242'] = None
        df['zdarzenie_v242'] = df['zdarzenie_v242'].astype(object)
        coin = df.get('asset_type', pd.Series('COIN', index=df.index)).fillna('COIN').eq('COIN')
        for i in df.index[coin]:
            old = df.at[i, 'zdarzenie_v242']
            df.at[i, 'zdarzenie_v242'] = f"{old}; {txt}" if isinstance(old, str) and old else txt
            n += 1
        df.to_csv(f, index=False)
    return n


def badanie_weekendu_v259(dane246):
    """BTC: ruch weekendu (sob 00:00 -> pon 00:00 UTC) > 2% -> kontra; ruch pon 00:00 -> wt 00:00 (24h) i -> sr 00:00 (48h)."""
    df = (dane246 or {}).get('BTCUSDT')
    if df is None or len(df) < 500:
        return None
    c = df.assign(tz=lambda x: x.t + 4 * HOUR_MS).set_index('tz').c        # cena na zamknieciu swiecy
    idx = pd.to_datetime(c.index, unit='ms', utc=True)
    pon = [int(t.value // 10 ** 6) for t in idx if t.weekday() == 0 and t.hour == 0]
    rows = []
    for t in pon:
        sob, wt, sr = t - 2 * DAY_MS, t + DAY_MS, t + 2 * DAY_MS
        if sob in c.index and wt in c.index:
            ruch = (c[t] / c[sob] - 1) * 100
            if abs(ruch) > 2:
                k = -1 if ruch > 0 else 1
                rows.append({'t': t, 'ruch': ruch, 'r24': k * (c[wt] / c[t] - 1) * 1e4,
                             'r48': k * (c[sr] / c[t] - 1) * 1e4 if sr in c.index else np.nan})
    x = pd.DataFrame(rows)
    if len(x) < 10:
        return {'n': len(x), 'werdykt': 'za malo zdarzen'}
    q = x.t.quantile([1 / 3, 2 / 3]).values
    x['tc'] = np.where(x.t < q[0], 1, np.where(x.t < q[1], 2, 3))
    tr = x.groupby('tc').r24.mean()
    w = {'n': len(x), 'traf_24h': rnd((x.r24 > 0).mean() * 100, 1), 'sr_24h_bps': rnd(x.r24.mean(), 0),
         'traf_48h': rnd((x.r48.dropna() > 0).mean() * 100, 1), 'sr_48h_bps': rnd(x.r48.mean(), 0),
         'tercje_24h': [rnd(tr.get(k), 0) for k in (1, 2, 3)]}
    w['werdykt'] = _v247_werdykt(w['tercje_24h'], w['traf_24h'])
    ost = pon[-1] if pon else None
    if ost and ost - 2 * DAY_MS in c.index and ost in c.index:
        w['ostatni_weekend_pct'] = rnd((c[ost] / c[ost - 2 * DAY_MS] - 1) * 100, 2)
    return w


# ================= V6.262: MACIERZ REZIMOW - setupy dopasowane do biezacego stanu rynku =================
# Zamiast blokowania strony po stratach z ostatnich dni: dla kazdego (typ, kierunek, trend BTC 4h) wynik z archiwum
# i testu 30 dni (obie polowy). Biezacy trend BTC 4h wybiera, co wolno grac. Liczone od nowa przy kazdym uruchomieniu.
REZIM_MIN_N_ARCH, REZIM_MIN_N_30D = 50, 20
REZIM_MNOZNIK = 0.5               # ryzyko setupu dopuszczonego przez macierz (dowod statystyczny, ale nowa regula)
REZIM_ZDEJMIJ = ('typ_wylaczony', 'przeciw_trendowi', 'fvg4h', 'short_godziny', 'azja_short', 'bezpiecznik')
_V262 = {'macierz': [], 'btc4h': None}


def _v262_staty(x):
    h = len(x) // 2
    return {'n': len(x), 'R': rnd(float(x.r.mean()), 3) if len(x) else None,
            'p1': rnd(float(x.r.iloc[:h].mean()), 3) if h else None, 'p2': rnd(float(x.r.iloc[h:].mean()), 3) if len(x) - h else None}


def macierz_rezimow_v262(arch, hist, alt=None):
    """Status (typ, kierunek, trend BTC 4h[, alty vs BTC 72h]): DOZWOLONY (plus w obu polowach obu prob), ZAKAZANY (minus w obu probach), NIEPEWNY."""
    def prep(df):
        if df is None or not len(df):
            return pd.DataFrame()
        d = df.copy()
        if 'asset_type' in d.columns:
            d = d[d.asset_type.fillna('COIN').eq('COIN')]
        d = d[d.status.isin(FINAL)].copy()
        d['r'] = pd.to_numeric(d.r, errors='coerce')
        d['t'] = pd.to_datetime(d.snapshot_utc, utc=True, errors='coerce')
        d['b4'] = pd.to_numeric(d.get('btc_trend_4h'), errors='coerce')
        d = d.dropna(subset=['r', 't', 'b4']).sort_values('t')
        d['alt3'] = np.nan
        if alt is not None and len(alt) and len(d):            # V6.264: sila altow vs BTC w chwili setupu
            tm = d.t.dt.tz_convert(None).values.astype('datetime64[ms]').astype('int64')
            m = pd.merge_asof(pd.DataFrame({'tm': tm, 'i': np.arange(len(d))}).sort_values('tm'),
                              alt[['t', 'alt3']].rename(columns={'t': 'tm'}).sort_values('tm'), on='tm', direction='backward',
                              tolerance=8 * HOUR_MS).sort_values('i')
            d['alt3'] = m.alt3.values
        return d
    A, H = prep(arch), prep(hist)
    out = []
    if not len(A):
        return out
    klucze = [(['setup_type', 'side', 'b4'], None)] + ([(['setup_type', 'side', 'b4', 'alt3'], 'alt3')] if A.alt3.notna().any() else [])
    for kol, wym in klucze:
        AA = A.dropna(subset=['alt3']) if wym else A
        HH = H.dropna(subset=['alt3']) if (wym and len(H)) else H
        for key, x in AA.groupby(kol):
            tp, sd, b4 = key[:3]
            msk = (HH.setup_type == tp) & (HH.side == sd) & (HH.b4 == b4) if len(HH) else None
            if wym and len(HH):
                msk &= HH.alt3 == key[3]
            y = HH[msk] if len(HH) else pd.DataFrame(columns=['r'])
            a, h = _v262_staty(x), _v262_staty(y)
            dosc = a['n'] >= REZIM_MIN_N_ARCH and h['n'] >= REZIM_MIN_N_30D
            plus = dosc and all(v is not None and v > 0 for v in (a['p1'], a['p2'], h['p1'], h['p2']))
            minus = dosc and (a['R'] or 0) < 0 and (h['R'] or 0) < 0
            out.append({'typ': tp, 'side': sd, 'btc4h': int(b4), 'alt3': int(key[3]) if wym else None, 'dosc': bool(dosc),
                        'status': 'DOZWOLONY' if plus else 'ZAKAZANY' if minus else 'NIEPEWNY',
                        'arch_n': a['n'], 'arch_R': a['R'], 'arch_polowy': [a['p1'], a['p2']],
                        'd30_n': h['n'], 'd30_R': h['R'], 'd30_polowy': [h['p1'], h['p2']]})
    return out


_V283 = {'macierz': [], 'teraz': None, 'opis': None}
STAN_BTC24 = 1.5                 # V6.283: ruch BTC 24h (%) - powyzej w gore, ponizej -1.5 w dol
STAN_ALT = 2.0                   # alty vs BTC 72h (%)


def _v283_stan(PP):
    """Godzinowy stan rynku: b24 (+1/0/-1 ruch BTC 24h) i alt (+1/0/-1 alty vs BTC 72h); ostatni wiersz = teraz."""
    f = _v273_cechy_btc(PP)
    if f is None:
        return None
    f = f.dropna(subset=['ch24']).copy()
    f['b24'] = np.where(f.ch24 > STAN_BTC24, 1, np.where(f.ch24 < -STAN_BTC24, -1, 0))
    f['alt'] = np.where(f.alt72 > STAN_ALT, 1, np.where(f.alt72 < -STAN_ALT, -1, np.where(f.alt72.isna(), np.nan, 0)))
    return f


def macierz_stanu_v283(arch, hist, stan):
    """(typ, kierunek, b24, alt) -> DOZWOLONY / ZAKAZANY / NIEPEWNY (te same kryteria co macierz rezimow V6.262)."""
    if stan is None or not len(stan):
        return []
    st = stan[['b24', 'alt']].copy()
    st['tm'] = st.index.tz_convert(None).values.astype('datetime64[ms]').astype('int64')
    def prep(df):
        if df is None or not len(df):
            return pd.DataFrame()
        d = df.copy()
        if 'asset_type' in d.columns:
            d = d[d.asset_type.fillna('COIN').eq('COIN')]
        d = d[d.status.isin(FINAL)].copy()
        d['r'] = pd.to_numeric(d.r, errors='coerce')
        d['t'] = pd.to_datetime(d.snapshot_utc, utc=True, errors='coerce')
        d = d.dropna(subset=['r', 't']).sort_values('t')
        if not len(d):
            return d
        tm = d.t.dt.tz_convert(None).values.astype('datetime64[ms]').astype('int64')
        m = pd.merge_asof(pd.DataFrame({'tm': tm, 'i': np.arange(len(d))}).sort_values('tm'), st.sort_values('tm'),
                          on='tm', direction='backward', tolerance=2 * HOUR_MS).sort_values('i')
        d['b24'], d['alt'] = m.b24.values, m.alt.values
        return d.dropna(subset=['b24', 'alt'])
    A, Hh = prep(arch), prep(hist)
    out = []
    if not len(A):
        return out
    for (tp, sd, b24, al), x in A.groupby(['setup_type', 'side', 'b24', 'alt']):
        y = Hh[(Hh.setup_type == tp) & (Hh.side == sd) & (Hh.b24 == b24) & (Hh.alt == al)] if len(Hh) else pd.DataFrame(columns=['r'])
        a, h = _v262_staty(x), _v262_staty(y)
        dosc = a['n'] >= REZIM_MIN_N_ARCH and h['n'] >= REZIM_MIN_N_30D
        plus = dosc and all(v is not None and v > 0 for v in (a['p1'], a['p2'], h['p1'], h['p2']))
        minus = dosc and (a['R'] or 0) < 0 and (h['R'] or 0) < 0
        out.append({'typ': tp, 'side': sd, 'b24': int(b24), 'alt': int(al), 'dosc': bool(dosc),
                    'status': 'DOZWOLONY' if plus else 'ZAKAZANY' if minus else 'NIEPEWNY',
                    'arch_n': a['n'], 'arch_R': a['R'], 'arch_polowy': [a['p1'], a['p2']], 'd30_n': h['n'], 'd30_R': h['R'], 'd30_polowy': [h['p1'], h['p2']]})
    return out


def _v283_komorka(typ, side):
    t_ = _V283.get('teraz')
    if not t_:
        return None
    return next((m for m in _V283.get('macierz') or [] if m['typ'] == typ and m['side'] == side and m['b24'] == t_[0] and m['alt'] == t_[1]), None)


def alt_stan_v264(now_ms, drive_ok, PP):
    """Szereg stanu altow vs BTC (72h): +1 silniejsze (> +2%), -1 slabsze (< -2%), 0 neutralne."""
    c4m, _ = majors_4h_dane_v229(now_ms, drive_ok, PP)
    a = alt_btc_v239(c4m)
    if a is None or not len(a):
        return None
    a = a.sort_values('t').copy()
    a['alt72'] = a.alt_idx.diff(18) * 100
    a['alt3'] = np.where(a.alt72 > 2, 1, np.where(a.alt72 < -2, -1, 0))
    return a.dropna(subset=['alt72'])


ANALOG_MIN_DNI = 10             # V6.274: min. roznych dni w KAZDEJ probie, zeby analogie zmienialy status typu


def _v274_analog_typ(typ, side):
    """+1: typ na plus w analogiach w obu probach (>= ANALOG_MIN_DNI dni w kazdej); -1: na minus w obu; 0: brak zdania."""
    w = _V273.get('wynik') or {}
    x = {r['proba']: r for r in w.get('typy') or [] if r['typ'] == typ and r['side'] == side}
    if len(x) < 2 or any(v['dni'] < ANALOG_MIN_DNI for v in x.values()):
        return 0
    if all(v['R_analog'] > 0 for v in x.values()):
        return 1
    if all(v['R_analog'] < 0 for v in x.values()):
        return -1
    return 0


def zastosuj_rezim_v262(live):
    """Setupy krypto: DOZWOLONY -> zdjete filtry strategii (nie kosztowe), bramka jak zatwierdzona, ryzyko x0.5;
    ZAKAZANY -> filtr 'rezim_v262'. NIEPEWNY -> bez zmian."""
    mac = {(m['typ'], m['side'], m['btc4h']): m for m in _V262['macierz'] if m.get('alt3') is None}
    mac2 = {(m['typ'], m['side'], m['btc4h'], m['alt3']): m for m in _V262['macierz'] if m.get('alt3') is not None and m.get('dosc')}
    a3 = _V262.get('alt3')
    n = {'DOZWOLONY': 0, 'ZAKAZANY': 0}
    for r in live:
        if r.get('asset_type') not in (None, 'COIN'):
            continue
        try:
            b4 = int(float(r.get('btc_trend_4h')))
        except (TypeError, ValueError):
            continue
        m = mac2.get((r.get('setup_type'), r.get('side'), b4, a3)) if a3 is not None else None   # V6.264: komorka 2D
        if m is None:
            m = mac.get((r.get('setup_type'), r.get('side'), b4))
        wy3 = (_V293.get('wybor') or {}).get((r.get('setup_type'), r.get('side')))   # V6.293: wyjscie dopasowane do stanu
        if wy3:
            try:
                e_, sl_ = float(r['entry']), float(r['sl'])
                kk_ = 1 if r.get('side') == 'LONG' else -1
                tryb_, par_ = WYJSCIA_TYPOW_V293[wy3['wyjscie']]
                if tryb_ == 'tp':
                    r['tp1'] = e_ + kk_ * par_ * abs(e_ - sl_)
                    r['rr_tp1_net'] = rnd(par_ - float(r.get('cost_R') or 0), 2)
                tags = [t for t in str(r.get('filtr') or '').split(';') if t]
                r['filtr'] = ';'.join(t for t in tags if t not in REZIM_ZDEJMIJ and t != 'rezim_v262')
                r['status_bramki'] = 'DO GRY'
                r['rezim_v262'] = 'DOZWOLONY'
                r['rezim_opis_v262'] = (f"DOZWOLONY z wyjsciem '{wy3['wyjscie']}' (stan rynku teraz: {wy3['R']}R, t {wy3['t']}, polowy {wy3['polowy']}, n={wy3['n']}; "
                                        f"obecne wyjscie {wy3['obecne_R']}R)")
                n['DOZWOLONY'] += 1
                continue
            except (TypeError, ValueError, KeyError):
                pass
        ms_ = _v283_komorka(r.get('setup_type'), r.get('side'))      # V6.283: stan rynku ma pierwszenstwo
        if ms_ and ms_['status'] != 'NIEPEWNY':
            tags = [t for t in str(r.get('filtr') or '').split(';') if t]
            op_ = (f"STAN RYNKU (BTC 24h {ms_['b24']:+d}, alty {ms_['alt']:+d}): arch {ms_['arch_R']}R (n={ms_['arch_n']}), 30d {ms_['d30_R']}R (n={ms_['d30_n']})")
            if ms_['status'] == 'DOZWOLONY':
                r['filtr'] = ';'.join(t for t in tags if t not in REZIM_ZDEJMIJ and t != 'rezim_v262')
                r['status_bramki'] = 'DO GRY'
                r['rezim_v262'] = 'DOZWOLONY'
                r['rezim_opis_v262'] = 'DOZWOLONY ' + op_
            else:
                if 'rezim_v262' not in tags:
                    tags.append('rezim_v262')
                r['filtr'] = ';'.join(tags)
                r['rezim_v262'] = 'ZAKAZANY'
                r['rezim_opis_v262'] = 'ZAKAZANY ' + op_
            n[ms_['status']] += 1
            continue
        an_ = _v274_analog_typ(r.get('setup_type'), r.get('side'))   # V6.274
        if an_ == 1 and (not m or m['status'] != 'DOZWOLONY'):
            tags = [t for t in str(r.get('filtr') or '').split(';') if t]
            r['filtr'] = ';'.join(t for t in tags if t not in REZIM_ZDEJMIJ and t != 'rezim_v262')
            r['status_bramki'] = 'DO GRY'
            r['rezim_v262'] = 'DOZWOLONY'
            r['rezim_opis_v262'] = 'DOZWOLONY (ANALOGIE: typ na plus w podobnych sytuacjach w obu probach' + (f"; macierz: {m['status']}" if m else '') + ')'
            n['DOZWOLONY'] += 1
            continue
        if an_ == -1:
            r['analogie_v274'] = 'typ na minus w podobnych sytuacjach (obie proby)'
        if not m or m['status'] == 'NIEPEWNY':
            continue
        tags = [t for t in str(r.get('filtr') or '').split(';') if t]
        opis = (f"rezim BTC4h {b4:+d}" + (f", alty {m['alt3']:+d}" if m.get('alt3') is not None else '')
                + f": arch {m['arch_R']}R (n={m['arch_n']}), 30d {m['d30_R']}R (n={m['d30_n']})")
        if m['status'] == 'DOZWOLONY':
            r['filtr'] = ';'.join(t for t in tags if t not in REZIM_ZDEJMIJ)
            r['status_bramki'] = 'DO GRY'
            r['rezim_v262'] = 'DOZWOLONY'
            r['rezim_opis_v262'] = 'DOZWOLONY ' + opis
        else:
            if 'rezim_v262' not in tags:
                tags.append('rezim_v262')
            r['filtr'] = ';'.join(tags)
            r['rezim_v262'] = 'ZAKAZANY'
            r['rezim_opis_v262'] = 'ZAKAZANY ' + opis
        n[m['status']] += 1
    return n


_V264 = {'badanie': None, 'ostrzezenie': None}
ZR_SYGNALY = ('top vs tlum (za top)', 'tlum zmiana 24h (kontra)', 'likwidacje skrajne (kaskada, w strone)', 'top traderzy zmiana 24h (za nimi)')


def _v264_trend4h(cc):
    """Stan trendu jak trend_of (close vs EMA20 vs EMA50) dla kazdej swiecy."""
    c = pd.Series(cc)
    e20, e50 = c.ewm(span=20, adjust=False).mean(), c.ewm(span=50, adjust=False).mean()
    return np.where((c > e20) & (e20 > e50), 1, np.where((c < e20) & (e20 < e50), -1, 0))


def badanie_zmiany_rezimu_v264(dpz, c4):
    """Czy sygnal kierunku zapowiada, ze trend BTC 4h w ciagu 24h przejdzie w ten kierunek (z innego stanu)?
    Szansa warunkowa vs bazowa (te same stany startowe), polowy czasu."""
    df, a = (dpz or {}).get('BTCUSDT'), (c4 or {}).get('BTCUSDT')
    if df is None or a is None or not len(df) or len(a) < 120:
        return None
    tt, cc = a[:, T], a[:, C]
    st = _v264_trend4h(cc)
    d = _v230_cechy(df)
    rows = []
    for r in d.to_dict('records'):
        i = int(np.searchsorted(tt, r['t'] - 4 * HOUR_MS))
        if i < 60 or i + 6 >= len(cc) or abs(tt[i] + 4 * HOUR_MS - r['t']) > 4 * HOUR_MS:
            continue
        r['ch24'] = (cc[i] / cc[i - 6] - 1) * 100
        r['_sym'] = 'BTCUSDT'
        syg = _v230_sygnaly(r)
        przysz = st[i + 1:i + 7]
        rows.append({'t': r['t'], 's0': int(st[i]), 'up': bool((przysz == 1).any()) and st[i] != 1,
                     'dn': bool((przysz == -1).any()) and st[i] != -1, **{k: syg.get(k, 0) for k in ZR_SYGNALY}})
    x = pd.DataFrame(rows)
    if len(x) < 100:
        return None
    h = x.t.median()
    out = []
    for k in ZR_SYGNALY:
        for kier, cel, nazwa in ((1, 'up', 'w gore'), (-1, 'dn', 'w dol')):
            baza = x[x.s0 != kier]                               # tylko gdy trend jeszcze nie jest w tym kierunku
            m = baza[k] == kier
            if m.sum() < 10:
                out.append({'sygnal': k, 'zmiana': nazwa, 'n': int(m.sum()), 'wniosek': 'za malo zdarzen'})
                continue
            pw, pb = baza[m][cel].mean(), baza[cel].mean()
            pol = [(baza[m & (baza.t < h)][cel].mean(), baza[baza.t < h][cel].mean()), (baza[m & (baza.t >= h)][cel].mean(), baza[baza.t >= h][cel].mean())]
            ok = int(m.sum()) >= 20 and pw >= 1.25 * pb and all(np.isfinite(a_) and a_ > b_ for a_, b_ in pol)
            out.append({'sygnal': k, 'zmiana': nazwa, 'n': int(m.sum()), 'szansa_pct': rnd(pw * 100, 1), 'bazowa_pct': rnd(pb * 100, 1),
                        'polowy': [rnd(a_ * 100, 0) if np.isfinite(a_) else None for a_, _ in pol], 'wniosek': 'DZIALA' if ok else 'brak przewagi'})
    return out


def ostrzezenie_zmiany_v264():
    """Aktywne sygnaly BTC, ktore przeszly test zapowiedzi zmiany trendu 4h."""
    b = {(w['sygnal'], w['zmiana']): w for w in (_V264.get('badanie') or []) if w.get('wniosek') == 'DZIALA'}
    syg = (((_V230.get('teraz') or {}).get('BTCUSDT') or {}).get('syg')) or {}
    cz = []
    for k, v in syg.items():
        w = b.get((k, 'w gore' if v > 0 else 'w dol'))
        if w:
            cz.append(f"mozliwa zmiana trendu BTC 4h {w['zmiana']} w 24h: {w['szansa_pct']}% (bazowo {w['bazowa_pct']}%, sygnal '{k}', n={w['n']})")
    return '; '.join(cz) if cz else None


# ================= V6.267: SETUPY Z SYGNALOW (BTC, ETH, SOL, XRP, BNB, DOGE) =================
SYG_SETUP_SYGNALY = ('likwidacje skrajne (kaskada, w strone)', 'top vs tlum (za top)', 'tlum zmiana 24h (kontra)', 'kapitulacja OI (kontra)',
                     'mapa likwidacji (magnes)', 'mapa likwidacji (od wiekszego skupiska)', 'CVD 24h (za nim)',
                     'dywergencja CVD (kontra ruchu)', 'arkusz bid/ask (za przewaga)',   # V6.274; V6.272: + kapitulacja OI
                     'CVD spot 24h (za nim)', 'rozjazd futures vs spot (za spotem)', 'spot i futures zgodne (za nimi)')   # V6.282
SYG_SL_ATR = 1.5               # SL = 1.5 ATR(14) na 4h
SYG_RR = (1.5, 2.0)            # cele w R (test obu)
SYG_HOLD = 12                  # max 12 swiec 4h (48h)
SYG_KOSZT = 0.0017             # prowizje + poslizg (ulamek ceny, w obie strony)
SYG_SPOZN_R = 0.5              # V6.271: ucieczka ceny od zamkniecia sygnalu (w R), od ktorej wejscie po rynku jest spoznione
SYG_RETEST_R = 0.25            # V6.271: limit na retest = zamkniecie sygnalu + 0.25R w strone sygnalu
_V267 = {'badanie': [], 'teraz': []}


def _v267_atr(a, n=14):
    h, l, c = a[:, H], a[:, L], a[:, C]
    pc = np.r_[c[0], c[:-1]]
    tr = np.maximum(h - l, np.maximum(np.abs(h - pc), np.abs(l - pc)))
    return pd.Series(tr).rolling(n).mean().values


def _v267_sym(a, i, kier, atr, rr):
    """Wejscie na zamknieciu swiecy i, SL 1.5 ATR, TP rr*R, max SYG_HOLD swiec; SL przed TP w tej samej swiecy."""
    e = a[i, C]
    risk = SYG_SL_ATR * atr
    if not (risk > 0):
        return None
    sl, tp = e - kier * risk, e + kier * rr * risk
    koszt = SYG_KOSZT * e / risk
    for k in range(i + 1, min(i + 1 + SYG_HOLD, len(a))):
        if (kier == 1 and a[k, L] <= sl) or (kier == -1 and a[k, H] >= sl):
            return -1.0 - koszt
        if (kier == 1 and a[k, H] >= tp) or (kier == -1 and a[k, L] <= tp):
            return rr - koszt
    k = min(i + SYG_HOLD, len(a) - 1)
    if k <= i:
        return None
    return kier * (a[k, C] - e) / risk - koszt


def _v271_retest(a, i, kier, atr, rr):
    """V6.271: sygnal na zamknieciu i; najpierw cena ucieka >= SYG_SPOZN_R w strone sygnalu (bez SL), potem LIMIT e+0.25R
    wypelniony w KOLEJNEJ swiecy; SL/TP jak w wariancie rynkowym. Wynik w R limitu (ryzyko 1.25R) albo None (brak wypelnienia)."""
    e = a[i, C]
    risk = SYG_SL_ATR * atr
    if not (risk > 0):
        return None
    sl, tp = e - kier * risk, e + kier * rr * risk
    lim, uc = e + kier * SYG_RETEST_R * risk, e + kier * SYG_SPOZN_R * risk
    koniec = min(i + 1 + SYG_HOLD, len(a))
    j = None
    for k in range(i + 1, koniec):
        if (kier == 1 and a[k, L] <= sl) or (kier == -1 and a[k, H] >= sl):
            return None
        if (kier == 1 and a[k, H] >= tp) or (kier == -1 and a[k, L] <= tp):
            return None                                    # TP przed retestem = brak transakcji
        if (kier == 1 and a[k, H] >= uc) or (kier == -1 and a[k, L] <= uc):
            j = k
            break
    if j is None:
        return None
    rl = abs(lim - sl)
    koszt = SYG_KOSZT * lim / rl
    f = None
    for k in range(j + 1, koniec):
        if f is None:
            if (kier == 1 and a[k, H] >= tp) or (kier == -1 and a[k, L] <= tp):
                return None                                # odjechal do TP bez wypelnienia
            if (kier == 1 and a[k, L] <= lim) or (kier == -1 and a[k, H] >= lim):
                f = k
                if (kier == 1 and a[k, L] <= sl) or (kier == -1 and a[k, H] >= sl):
                    return -1.0 - koszt
                continue
        else:
            if (kier == 1 and a[k, L] <= sl) or (kier == -1 and a[k, H] >= sl):
                return -1.0 - koszt
            if (kier == 1 and a[k, H] >= tp) or (kier == -1 and a[k, L] <= tp):
                return abs(tp - lim) / rl - koszt
    if f is None:
        return None
    return kier * (a[koniec - 1, C] - lim) / rl - koszt


SYG_SPOZN_TEST = (0.25, 0.5)     # V6.280: testowane spoznienie wejscia (R od zamkniecia swiecy sygnalu)


def _v280_spozn(a, i, kier, atr, rr, d):
    """Wejscie po rynku po cenie zamkniecie + d*R, gdy swieca i+1 do niej doszla (bez wczesniejszego SL w tej swiecy).
    SL i TP jak przy wejsciu na zamknieciu; wynik w R nowego ryzyka (1+d) po kosztach."""
    e0 = a[i, C]
    risk0 = SYG_SL_ATR * atr
    if not (risk0 > 0) or i + 1 >= len(a):
        return None
    sl, tp = e0 - kier * risk0, e0 + kier * rr * risk0
    e = e0 + kier * d * risk0
    b = a[i + 1]
    if not ((kier == 1 and b[H] >= e) or (kier == -1 and b[L] <= e)):
        return None                                        # cena nie przesunela sie o d - brak spoznionego wejscia
    if (kier == 1 and b[L] <= sl) or (kier == -1 and b[H] >= sl):
        return None                                        # niejednoznaczne w swiecy 4h
    risk = risk0 * (1 + d)
    koszt = SYG_KOSZT * e / risk
    if (kier == 1 and b[H] >= tp) or (kier == -1 and b[L] <= tp):
        return None                                        # TP w tej samej swiecy - niejednoznaczne
    for k in range(i + 2, min(i + 1 + SYG_HOLD, len(a))):
        if (kier == 1 and a[k, L] <= sl) or (kier == -1 and a[k, H] >= sl):
            return -1.0 - koszt
        if (kier == 1 and a[k, H] >= tp) or (kier == -1 and a[k, L] <= tp):
            return (rr - d) / (1 + d) - koszt
    k = min(i + SYG_HOLD, len(a) - 1)
    return kier * (a[k, C] - e) / risk - koszt


WYJSCIA_V284 = ('SL na wejscie po +1R', 'polowa na 1R + reszta do 3R', 'wyjscie po 24h')


def _v284_wyjscie(a, i, kier, atr, rr, tryb):
    """Wariant wyjscia dla wejscia na zamknieciu swiecy i (SL 1.5 ATR). SL przed TP w tej samej swiecy (ostroznie). R po kosztach."""
    e = a[i, C]
    risk = SYG_SL_ATR * atr
    if not (risk > 0):
        return None
    sl, tp = e - kier * risk, e + kier * rr * risk
    koszt = SYG_KOSZT * e / risk
    koniec = min(i + 1 + SYG_HOLD, len(a))
    if koniec <= i + 1:
        return None
    dotk = lambda b, poz: (kier == 1 and b[H] >= poz) or (kier == -1 and b[L] <= poz)
    spad = lambda b, poz: (kier == 1 and b[L] <= poz) or (kier == -1 and b[H] >= poz)
    if tryb == 'wyjscie po 24h':
        for k in range(i + 1, min(i + 7, koniec)):
            if spad(a[k], sl):
                return -1.0 - koszt
            if dotk(a[k], tp):
                return rr - koszt
        k = min(i + 6, len(a) - 1)
        return kier * (a[k, C] - e) / risk - koszt
    if tryb == 'SL na wejscie po +1R':
        be = False
        for k in range(i + 1, koniec):
            if spad(a[k], e if be else sl):
                return (0.0 if be else -1.0) - koszt
            if dotk(a[k], tp):
                return rr - koszt
            if not be and dotk(a[k], e + kier * risk):
                be = True
        return kier * (a[koniec - 1, C] - e) / risk - koszt
    if tryb == 'polowa na 1R + reszta do 3R':
        pol = False
        tp3 = e + kier * 3 * risk
        for k in range(i + 1, koniec):
            if spad(a[k], e if pol else sl):
                return (0.5 if pol else -1.0) - koszt
            if not pol and dotk(a[k], e + kier * risk):
                pol = True
                if dotk(a[k], tp3):
                    return 0.5 + 1.5 - koszt
                continue
            if pol and dotk(a[k], tp3):
                return 0.5 + 1.5 - koszt
        reszta = kier * (a[koniec - 1, C] - e) / risk
        return (0.5 + 0.5 * reszta if pol else reszta) - koszt
    return None


def badanie_setupow_sygnalowych_v267(dpz, c4, meta=None):
    """Historia (Gate 4h): kazde pierwsze wystapienie sygnalu (odstep >= 24h) -> transakcja z SL/TP; R po kosztach, polowy i tercje."""
    rows = []
    for sym, df in (dpz or {}).items():
        a = (c4 or {}).get(sym)
        if df is None or a is None or not len(df) or len(a) < 60:
            continue
        atr = _v267_atr(a)
        d = _v230_cechy(df)
        tt, cc = a[:, T], a[:, C]
        ost = {}
        for r in d.to_dict('records'):
            i = int(np.searchsorted(tt, r['t'] - 4 * HOUR_MS))
            if i < 14 or i + 1 >= len(cc) or abs(tt[i] + 4 * HOUR_MS - r['t']) > 4 * HOUR_MS:
                continue
            r['ch24'] = (cc[i] / cc[i - 6] - 1) * 100
            r['_sym'] = sym
            syg = _v230_sygnaly(r)
            for nm in SYG_SETUP_SYGNALY:
                k = syg.get(nm, 0)
                zest = tuple(sorted(x for x in SYG_SETUP_SYGNALY if syg.get(x, 0) == k)) if k else ()   # V6.284: sygnaly zgodne naraz
                if not k or r['t'] - ost.get((nm, k), -10 ** 18) < DAY_MS:
                    if k:
                        ost[(nm, k)] = ost.get((nm, k), r['t'])
                    continue
                ost[(nm, k)] = r['t']
                for rr in SYG_RR:
                    wynik = _v267_sym(a, i, k, atr[i], rr)
                    if wynik is not None and i + SYG_HOLD < len(a):
                        wy = {w_: _v284_wyjscie(a, i, k, atr[i], rr, w_) for w_ in WYJSCIA_V284}   # V6.284
                        rows.append({'sygnal': nm, 'symbol': sym, 't': r['t'], 'kier': k, 'rr': rr, 'r': wynik, 'wariant': 'rynek', 'zest': zest, **wy})
                    if i + SYG_HOLD < len(a):              # V6.280: spoznione wejscie po rynku
                        for d_ in SYG_SPOZN_TEST:
                            w3 = _v280_spozn(a, i, k, atr[i], rr, d_)
                            if w3 is not None:
                                rows.append({'sygnal': nm, 'symbol': sym, 't': r['t'], 'kier': k, 'rr': rr, 'r': w3, 'wariant': f'spozn{d_}'})
                    if i + SYG_HOLD < len(a):              # V6.271: limit na retest po ucieczce ceny
                        w2 = _v271_retest(a, i, k, atr[i], rr)
                        if w2 is not None:
                            rows.append({'sygnal': nm, 'symbol': sym, 't': r['t'], 'kier': k, 'rr': rr, 'r': w2, 'wariant': 'retest'})
    x = pd.DataFrame(rows)
    out = []
    if not len(x):
        return out
    for (nm, rr, wr), y in x.groupby(['sygnal', 'rr', 'wariant']):
        y = y.sort_values('t')
        q = y.t.quantile([1 / 3, 2 / 3]).values
        tc = np.where(y.t < q[0], 1, np.where(y.t < q[1], 2, 3))
        tr = [rnd(float(y.r[tc == k].mean()), 3) if (tc == k).any() else None for k in (1, 2, 3)]
        h = len(y) // 2
        w = {'sygnal': nm, 'rr': rr, 'wariant': wr, 'rr_limit': rnd((rr - SYG_RETEST_R) / (1 + SYG_RETEST_R), 2) if wr == 'retest' else rr, 'n': len(y), 'sr_R': rnd(float(y.r.mean()), 3), 'suma_R': rnd(float(y.r.sum()), 1),
             'traf_pct': rnd(float((y.r > 0).mean() * 100), 1), 'polowy': [rnd(float(y.r.iloc[:h].mean()), 3), rnd(float(y.r.iloc[h:].mean()), 3)],
             'tercje': tr, 'BTC_ETH_sr_R': rnd(float(y[y.symbol.isin(['BTCUSDT', 'ETHUSDT'])].r.mean()), 3) if y.symbol.isin(['BTCUSDT', 'ETHUSDT']).any() else None,
             'LONG_sr_R': rnd(float(y[y.kier == 1].r.mean()), 3) if (y.kier == 1).any() else None,
             'SHORT_sr_R': rnd(float(y[y.kier == -1].r.mean()), 3) if (y.kier == -1).any() else None}
        strony = {}                                        # V6.291: osobny werdykt dla LONG i SHORT
        for kk in (1, -1):
            z_ = y[y.kier == kk]
            hz = len(z_) // 2
            pz = [z_.r.iloc[:hz].mean(), z_.r.iloc[hz:].mean()] if hz else [None, None]
            strony[kk] = bool(len(z_) >= 15 and z_.r.mean() > 0 and all(v is not None and v > 0 for v in pz))
        w['strony'] = strony
        w['t'], w['n_niezal'] = _v292_t(y, 'r')            # V6.292
        w['wniosek'] = 'DZIALA' if (len(y) >= (15 if wr == 'retest' else 20) and all(v is not None and v > 0 for v in tr) and all(v > 0 for v in w['polowy'])
                                    and w['t'] is not None and w['t'] >= DZ_T_MIN) else 'brak przewagi'
        out.append(w)
    if meta is not None:                                   # V6.284: zbieznosc i warianty wyjscia
        try:
            dz = {(w['sygnal'], w['rr']) for w in out if w['wariant'] == 'rynek' and w['wniosek'] == 'DZIALA'}
            rk = x[x.wariant == 'rynek'].copy()
            rk = rk[[(a_, b_) in dz for a_, b_ in zip(rk.sygnal, rk.rr)]]
            zb = {}
            if len(rk):
                rk['zb'] = [sum(1 for z_ in zs if (z_, rr_) in dz) for zs, rr_ in zip(rk.zest, rk.rr)]
                ev = rk.groupby(['symbol', 't', 'kier', 'rr'], as_index=False).agg(r=('r', 'mean'), zb=('zb', 'max')).sort_values('t')
                for rr_, y in ev.groupby('rr'):
                    j, wiele = y[y.zb <= 1], y[y.zb >= 2]
                    h_ = len(wiele) // 2
                    zb[rr_] = {'n1': len(j), 'R1': rnd(float(j.r.mean()), 3) if len(j) else None, 'n2': len(wiele),
                               'R2': rnd(float(wiele.r.mean()), 3) if len(wiele) else None,
                               'polowy2': [rnd(float(wiele.r.iloc[:h_].mean()), 3), rnd(float(wiele.r.iloc[h_:].mean()), 3)] if h_ else None}
                    z_ = zb[rr_]
                    z_['wniosek'] = 'LEPIEJ' if (z_['n2'] >= 30 and z_['R2'] is not None and z_['R1'] is not None and z_['R2'] >= z_['R1'] + 0.05
                                                 and z_['polowy2'] and min(z_['polowy2']) > 0) else 'bez roznicy'
            wyj = []
            if len(rk):
                rk = rk.sort_values('t')
                h_ = len(rk) // 2
                baza = [rk.r.iloc[:h_].mean(), rk.r.iloc[h_:].mean()]
                for w_ in WYJSCIA_V284:
                    v = pd.to_numeric(rk[w_], errors='coerce')
                    pl = [v.iloc[:h_].mean(), v.iloc[h_:].mean()]
                    wyj.append({'wyjscie': w_, 'n': int(v.notna().sum()), 'R': rnd(float(v.mean()), 3), 'R_baza': rnd(float(rk.r.mean()), 3),
                                'polowy': [rnd(float(x_), 3) for x_ in pl], 'polowy_baza': [rnd(float(x_), 3) for x_ in baza],
                                'wniosek': 'LEPSZE' if all(pl[k_] > baza[k_] for k_ in (0, 1)) else 'nie lepsze'})
            meta['zbieznosc'], meta['wyjscia'] = zb, wyj
        except Exception as exc:
            meta['blad'] = str(exc)[:120]
    return out


def _v271_cena_teraz(P):
    """Biezaca cena: tworzaca sie swieca 5m/1m/1h, inaczej ostatnia zamknieta (5m, 1h)."""
    fo = P.get('forming') or {}
    for tf in ('1m', '5m', '15m', '1h'):
        x = fo.get(tf)
        if x is not None and len(x) > C and x[C] > 0:
            return float(x[C]), int(x[T])
    for tf in ('1m', '5m', '15m', '1h'):
        x = (P.get('arr') or {}).get(tf)
        if x is not None and len(x):
            return float(x[-1, C]), int(x[-1, T])
    return None, None


def setupy_sygnalowe_teraz_v267(dpz, PP, now_ms):
    """Aktywny sygnal (ostatni odczyt, nie starszy niz 8h) -> setup. V6.271: wejscie po rynku od biezacej ceny (SL/TP od zamkniecia
    swiecy sygnalu); ucieczka > 0.5R -> rynek SPOZNIONY + LIMIT na retest (ocena z testu wariantu retest); dotkniety SL/TP -> pomin."""
    wyn_g = {(w['sygnal'], w['rr'], w.get('wariant', 'rynek')): w for w in _V267.get('badanie') or []}
    wyn_e = {(w['sygnal'], w['rr'], w.get('wariant', 'rynek')): w for w in _V267.get('badanie_ext') or []}   # V6.272
    out = []
    for sym, df in (dpz or {}).items():
        wyn = wyn_g if sym in POZ_SYMBOLE else wyn_e
        P = (PP or {}).get(sym) or {}
        a = (P.get('arr') or {}).get('4h')
        if df is None or not len(df) or a is None or len(a) < 20:
            continue
        a = a[a[:, T] + 4 * HOUR_MS <= now_ms]
        d = _v230_cechy(df)
        r = d.iloc[-1].to_dict()
        if now_ms - int(r['t']) > 8 * HOUR_MS:
            continue
        i = int(np.searchsorted(a[:, T], int(r['t']) - 4 * HOUR_MS))
        if i >= len(a) or abs(a[i, T] + 4 * HOUR_MS - int(r['t'])) > 4 * HOUR_MS:
            i = len(a) - 1
        r['ch24'] = (a[i, C] / a[i - 6, C] - 1) * 100 if i >= 6 else None
        r['_sym'] = sym
        syg = _v230_sygnaly(r)
        atr = _v267_atr(a)[i]
        baza = float(a[i, C])
        t_baza = int(a[i, T]) + 4 * HOUR_MS
        cena, _tc = _v271_cena_teraz(P)
        cena = cena or baza
        hi = lo = cena                                     # ekstrema od zamkniecia swiecy sygnalu
        for tf in ('5m', '15m', '1h'):
            x = (P.get('arr') or {}).get(tf)
            if x is not None and len(x):
                x = x[x[:, T] >= t_baza]
                if len(x):
                    hi, lo = max(hi, float(x[:, H].max())), min(lo, float(x[:, L].min()))
                    break
        for nm in SYG_SETUP_SYGNALY:
            k = syg.get(nm, 0)
            if not k:
                continue
            risk = SYG_SL_ATR * atr
            if not (risk > 0):
                continue
            sl = baza - k * risk
            uciekl = k * (cena - baza) / risk
            for rr in SYG_RR:
                w = wyn.get((nm, rr, 'rynek'))
                if not w:
                    continue
                tp = baza + k * rr * risk
                if (k == 1 and (lo <= sl or hi >= tp)) or (k == -1 and (hi >= sl or lo <= tp)):
                    continue                               # sygnal juz rozegrany (SL albo TP od zamkniecia)
                w0 = w                                     # V6.280: ocena wg testu wariantu o podobnym spoznieniu
                if uciekl > 0.125:
                    d_ = 0.25 if uciekl <= 0.375 else 0.5
                    w = wyn.get((nm, rr, f'spozn{d_}')) or {'sr_R': None, 'n': 0, 'traf_pct': None, 'polowy': None, 'wniosek': 'brak testu spoznienia'}
                ok = w['wniosek'] == 'DZIALA' and (w.get('strony') is None or bool(w['strony'].get(k, False)))   # V6.291: tylko kierunek z testem
                spozn = uciekl > SYG_SPOZN_R
                rr_teraz = k * (tp - cena) / (k * (cena - sl)) if k * (cena - sl) > 0 else 0

                def _dzw(e_, typ_):
                    try:
                        return leverage_plan({'entry': e_, 'sl': sl, 'side': 'LONG' if k > 0 else 'SHORT', 'entry_type': typ_}, P).get('dzwignia')
                    except Exception:
                        return None
                ocena = ('A' if (w['sr_R'] or 0) >= 0.3 else 'B') if ok else 'D'
                if w['wniosek'] == 'DZIALA' and not ok:
                    w = dict(w, wniosek=f"DZIALA tylko w {'LONG' if k < 0 else 'SHORT'} - w tym kierunku brak przewagi")
                opis = (f"cel TP {rr}R od zamkniecia swiecy sygnalu (staly wariant testowany); " + (f"test wejscia spoznionego o ~{0.25 if uciekl <= 0.375 else 0.5}R: " if w is not w0 else 'test: ')
                        + f"{nm} {w['sr_R']}R/transakcje (n={w['n']}, trafnosc {w['traf_pct']}%, polowy {w['polowy']}) -> {w['wniosek']}")
                out.append({'symbol': sym, 'side': 'LONG' if k > 0 else 'SHORT', 'setup_type': 'SYGNAL', 'entry_type': 'MARKET', 'sygnal': nm, 'test_R': w['sr_R'],
                            'cel': f"TP {rr}R od zamkniecia (test {w['sr_R']}R, n={w['n']})", 't_sygnal': t_baza,
                            'rr': rnd(rr_teraz, 2), 'rr_testu': rr, 'dzwignia': _dzw(cena, 'MARKET'), 'entry': cena, 'sl': sl, 'tp1': tp,
                            'baza': baza, 'uciekl_R': rnd(uciekl, 2), 'ryzyko_pct': rnd(abs(cena - sl) / cena * 100, 2),
                            'ocena': 'D' if spozn else ocena, 'do_gry': ok and not spozn,
                            'v339_powody_odrzucenia': (['TEST_BRAK_PRZEWAGI: ' + str(w.get('wniosek'))] if not ok else []
                                + (['TEST_KIERUNKU_NIEPOTWIERDZONY'] if w0.get('wniosek') == 'DZIALA' and not ok else [])
                                + (['WEJSCIE_SPOZNIONE: uciekl_R=' + str(rnd(uciekl, 2))] if spozn else [])),
                            'v339_etap_filtra': 'OCENA_1B_PRZY_UTWORZENIU',
                            'opis': (f"SPOZNIONY: cena uciekla {uciekl:.2f}R od zamkniecia {psig(baza)} (RR teraz {rr_teraz:.2f}) -> nie gonic, czekac na nowy sygnal (limit na retest przegrywa w tescie); " if spozn
                                     else f"od zamkniecia {psig(baza)} przesuniecie {uciekl:+.2f}R; ") + opis})
    return out


_V242 = {'twarde': None, 'miekkie': []}
V242_TWARDE = ('likwidacje skrajne (kaskada, w strone)',)
V242_MIEKKIE = ('top vs tlum (za top)', 'kapitulacja OI (kontra)')


def zdarzenia_rynku_v242():
    """Aktywne zdarzenia z biezacego pozycjonowania BTC/ETH. Twarde (blokuja przeciwne setupy) tylko gdy sygnal przeszedl test."""
    dziala = {b['sygnal'] for b in (_V230.get('badanie') or []) if str(b.get('wniosek', '')).startswith('DZIALA')}
    tw, mk = None, []
    for sym in ('BTCUSDT', 'ETHUSDT'):
        syg = ((_V230.get('teraz') or {}).get(sym) or {}).get('syg') or {}
        for nm in V242_TWARDE:
            if syg.get(nm) and nm in dziala and tw is None:
                tw = {'kier': int(syg[nm]), 'opis': f"{nm} na {sym[:-4]} -> rynek {'LONG' if syg[nm] > 0 else 'SHORT'}"}
        if sym == 'BTCUSDT':
            for nm in V242_MIEKKIE:
                if syg.get(nm):
                    mk.append({'kier': int(syg[nm]), 'opis': f"{nm} BTC {'LONG' if syg[nm] > 0 else 'SHORT'}"
                               + ('' if nm in dziala else ' (kandydat)')})
    zt_ok = {w['sygnal'] for w in (_V246.get('wynik') or []) if w.get('wniosek') == 'DZIALA'}   # V6.246
    for nm, kz in ((_V246.get('teraz') or {}).get('BTCUSDT') or {}).items():
        if nm in zt_ok and kz:
            mk.append({'kier': int(kz), 'opis': f"zwrot: {nm} BTC {'LONG' if kz > 0 else 'SHORT'}"})
    k1 = _V243.get('kaskada1h') or {}                      # V6.243: kaskada 1h (gdy przeszla test)
    if tw is None and str(k1.get('werdykt')) == 'DZIALA':
        for sym in ('BTCUSDT', 'ETHUSDT'):
            st = (_V243.get('teraz1h') or {}).get(sym) or {}
            if st.get('kier') and st.get('t', 0) >= time.time() * 1000 - 3 * HOUR_MS:   # tylko swieza kaskada
                tw = {'kier': int(st['kier']), 'opis': f"kaskada likwidacji 1h na {sym[:-4]} -> rynek {'LONG' if st['kier'] > 0 else 'SHORT'}"}
                break
    _V242['twarde'], _V242['miekkie'] = tw, mk
    return tw, mk


def zastosuj_zdarzenia_v242(out_dir):
    """Blokuje krypto setupy przeciw twardemu zdarzeniu, dopisuje miekkie. Modyfikuje top_market/top_limit/setups.csv."""
    tw, mk = _V242['twarde'], _V242['miekkie']
    if not tw and not mk:
        return 0
    n = 0
    for plik in ('top_market.csv', 'top_limit.csv', 'setups.csv'):
        f = Path(out_dir) / plik
        if not f.is_file():
            continue
        try:
            df = pd.read_csv(f, low_memory=False)
        except Exception:
            continue
        if not len(df) or 'side' not in df.columns:
            continue
        for c in ('zdarzenie_v242', 'blokady_bezpieczenstwa', 'warunki', 'status_setupu'):
            if c not in df.columns:
                df[c] = None
            df[c] = df[c].astype(object)
        coin = df.get('asset_type', pd.Series('COIN', index=df.index)).fillna('COIN').eq('COIN')
        sd = np.where(df.side.astype(str).eq('LONG'), 1, -1)
        for i in df.index[coin]:
            dop = []
            if tw:
                if sd[df.index.get_loc(i)] != tw['kier']:
                    pow_ = f"zdarzenie: {tw['opis']} (przeciw)"
                    for c in ('blokady_bezpieczenstwa', 'warunki'):
                        old = df.at[i, c]
                        df.at[i, c] = pow_ if not isinstance(old, str) or not old else f"{pow_}; {old}"
                    df.at[i, 'status_setupu'] = 'ZABLOKOWANY'
                    if 'do_handlu' in df.columns:
                        df.at[i, 'do_handlu'] = False
                    n += plik != 'setups.csv'
                else:
                    dop.append(f"zgodne z: {tw['opis']}")
            for m in mk:
                dop.append(('zgodne z ' if sd[df.index.get_loc(i)] == m['kier'] else 'przeciw ') + m['opis'])
            if dop:
                df.at[i, 'zdarzenie_v242'] = '; '.join(dop)
        df.to_csv(f, index=False)
    return n


def _v242_dopisek(r):
    z = r.get('zdarzenie_v242')
    o = r.get('ochrona_v255')                              # V6.255
    rz = r.get('rezim_opis_v262')                          # V6.262
    return (f"; {rz}" if isinstance(rz, str) and rz else '') + (f"; {z}" if isinstance(z, str) and z else '') + (f"; {o}" if isinstance(o, str) and o else '')


def _v201_powod(r):
    """Najkrotszy czytelny powod, dlaczego setup nie jest do gry (pusty = do gry)."""
    st = _v201_txt(r.get('ranking_status'))
    sts = _v201_txt(r.get('status_setupu'))
    if (sts in ('DO GRY', 'PROBA') or (not sts and st in ('DO GRY', 'PROBA'))) and not _v201_txt(r.get('blokady_kwalifikacji')):
        return 'DO GRY' if sts != 'PROBA' else 'DO GRY (PROBA, ryzyko x0.5)'      # V6.205: status_setupu decyduje
    czesci = []
    if r.get('asset_type') not in (None, 'COIN') and _v201_txt(r.get('asset_type')):
        czesci.append('TradFi bez testu')
    for k in ('blokady_bezpieczenstwa', 'blokady_kwalifikacji', 'ranking_powod', 'warunki'):
        t = _v201_txt(r.get(k))
        if t and t != 'OK':
            czesci += [x.strip() for x in t.split(';') if x.strip()]
            break
    wynik = []
    for c in czesci:
        if c not in wynik:
            wynik.append(c)
    return '; '.join(wynik)[:90] or st




def _v316_tp23(r):
    """V6.316: TP2 i TP3 do tabel (orientacyjne, do czesciowego zamykania - wynik testow liczony do TP1).
    TP2 = tp2 setupu, gdy lezy za TP1; inaczej 1.5 x odleglosc TP1. TP3 = 2 x odleglosc TP1 (albo 1.5 x odleglosc TP2, gdy TP2 juz dalej)."""
    try:
        e, t1 = float(r.get('entry')), float(r.get('tp1'))
    except (TypeError, ValueError):
        return None, None
    k = 1 if str(r.get('side')) == 'LONG' else -1
    d1 = abs(t1 - e)
    if not d1 > 0:
        return None, None
    try:
        t2 = float(r.get('tp2'))
        t2 = t2 if t2 == t2 and k * (t2 - t1) > 0 else None
    except (TypeError, ValueError):
        t2 = None
    t2 = t2 if t2 is not None else e + k * 1.5 * d1
    d2 = abs(t2 - e)
    t3 = e + k * (2 * d1 if d2 < 2 * d1 * 0.999 else 1.5 * d2)
    return t2, t3


def _v316_txt(r):
    t2, t3 = _v316_tp23(r)
    return (_v201_cena(t2) if t2 is not None else '-'), (_v201_cena(t3) if t3 is not None else '-')


def _v315_rr(r):
    try:
        e, sl, tp = float(r.get('entry')), float(r.get('sl')), float(r.get('tp1'))
        return f"{abs(tp - e) / abs(e - sl):.2f}" if abs(e - sl) > 0 else '-'
    except (TypeError, ValueError):
        return '-'


def _v315_dzw(r):
    """Dzwignia z kolektora; gdy brak - taka, by depozyt ~20% konta przy ryzyku 1.5% (min 2x, max 10x)."""
    d = r.get('dzwignia')
    try:
        if d is not None and d == d and float(d) > 0:
            return f"{int(float(d))}x"
        e, sl = float(r.get('entry')), float(r.get('sl'))
        ryz = abs(e - sl) / e
        poz = KAPITAL_USDT * RYZYKO_NA_TRANSAKCJE_PCT / 100 / ryz if ryz > 0 else None
        return f"{int(min(10, max(2, round(poz / (KAPITAL_USDT * 0.2)))))}x" if poz else '-'
    except (TypeError, ValueError, ZeroDivisionError):
        return '-'


def _v228_przeciw_btc(r):
    """V6.228: dopisek, gdy krypto setup idzie przeciw przewadze BTC z sekcji 5 (tylko informacja)."""
    if r.get('asset_type') not in (None, '', 'COIN'):
        return ''
    kd = (_V300.get('kierunek') if '_V300' in globals() else None)   # V6.309: potwierdzony kierunek (test) ma pierwszenstwo
    if kd:
        if r.get('side') != kd['strona']:
            return f"; przeciw kierunkowi rynku ({kd['strona']} {kd['p'] * 100:.0f}%, test)"
        return f"; zgodne z kierunkiem rynku ({kd['strona']}, test)"
    if not _V226_KIER:
        return ''
    b = next((k for k in _V226_KIER if k.get('symbol') == 'BTCUSDT'), None)
    if not b:
        return ''
    p = str(b.get('przewaga') or '')
    if r.get('side') == 'LONG' and p.startswith('SHORT'):
        return '; przeciw BTC (SHORT)'
    if r.get('side') == 'SHORT' and p.startswith('LONG'):
        return '; przeciw BTC (LONG)'
    return ''


def _v201_tabela(rows, elliott=False):
    if elliott:
        nag = ['Symbol', 'Kier.', 'Wejscie', 'SL', 'TP1', 'TP2*', 'TP3*', 'RR', 'Dzwignia', 'Wiek h', 'Status']   # V6.315: + RR, dzwignia; V6.316: + TP3
        dane = [[_v201_txt(r.get('symbol')).replace('USDT', ''), _v201_txt(r.get('side')), _v201_cena(r.get('entry')),
                 _v201_cena(r.get('sl')), _v201_cena(r.get('tp1')), *_v316_txt(r), _v315_rr(r), _v315_dzw(r),
                 _v201_txt(r.get('elliott_abc_wiek_h')).replace('.0', ''), 'obserwacja' + _v228_przeciw_btc(r)] for r in rows]
    else:
        nag = ['Symbol', 'Kier.', 'Typ', 'Wejscie', 'SL', 'TP1', 'TP2*', 'TP3*', 'RR', 'Dzwignia', 'Ocena', 'Uwagi']   # V6.315: + dzwignia; V6.316: + TP2/TP3
        dane = []
        _kol = {'A': 0, 'B': 1, 'C': 2, 'D': 3}
        rows = sorted(rows, key=lambda r: _kol.get(_v201_txt(r.get('ocena')), 9))   # V6.217: A na gorze (stabilnie)
        for r in rows:
            rr = r.get('rr_tp1_net')
            try:
                rr = f'{float(rr):.2f}'
            except (TypeError, ValueError):
                rr = '-'
            dane.append([_v201_txt(r.get('symbol')).replace('USDT', ''), _v201_txt(r.get('side')), _v201_txt(r.get('setup_type')),
                         _v201_cena(r.get('entry')), _v201_cena(r.get('sl')), _v201_cena(r.get('tp1')), *_v316_txt(r), rr, _v315_dzw(r),
                         _v201_txt(r.get('ocena')), _v201_powod(r) + _v228_przeciw_btc(r) + _v242_dopisek(r)])
    if not dane:
        return ['  (brak)']
    sz = [max(len(str(x)) for x in [h] + [d[i] for d in dane]) for i, h in enumerate(nag)]
    lin = lambda w: '  ' + ' | '.join(str(x).ljust(sz[i]) if i == len(w) - 1 else str(x).ljust(sz[i]) for i, x in enumerate(w)).rstrip()
    return [lin(nag), '  ' + '-+-'.join('-' * n for n in sz)] + [lin(d) for d in dane]


