def kierunek_majors_v226(PP, summary):
    """V6.226: opis kierunku BTC/ETH ze swiec zamknietych (bez prognozy): trend, struktura, poziomy, przewaga i uniewaznienie."""
    out = []
    sm = {r.get('symbol'): r for r in summary or []}
    for sym in V226_SYMBOLE:
        P, f = (PP or {}).get(sym), sm.get(sym) or {}
        if P is None or '1h' not in P.get('arr', {}):
            continue
        a1 = P['arr']['1h']
        h, l, c = a1[:, H], a1[:, L], a1[:, C]
        price = _num(f.get('live_price')) or float(c[-1])
        ph, pl = pivots(h, l, 3)
        sh = float(h[ph[-1]]) if len(ph) else None
        slo = float(l[pl[-1]]) if len(pl) else None
        hi24, lo24 = float(h[-24:].max()), float(l[-24:].min())
        atr = _num(f.get('atr_1h_pct'))
        t4, t1, t15 = (f.get('trend_4h'), f.get('trend_1h'), f.get('trend_15m'))
        ev1 = str(f.get('last_event_1h') or '')
        z1 = -1 if ev1.startswith(('CHoCH-', 'BOS-')) else 1 if ev1.startswith(('CHoCH+', 'BOS+')) else 0
        pkt = sum(int(x) for x in (t4, t1) if x in (1, -1)) + z1
        if pkt <= -2:
            przew = f"SHORT (4h {_v226_trend_txt(t4)}, 1h {_v226_trend_txt(t1)}, 1h {ev1 or '-'})"
            uniew = f"powyzej {psig(sh, 6)} (ostatni szczyt 1h)" if sh else 'brak szczytu 1h'
            niz = [float(l[p]) for p in pl if l[p] < price]          # V6.227: najblizszy dolek 1h pod cena
            cel = (f"{psig(max(niz), 6)} (najblizszy dolek 1h pod cena)" if niz else 'brak nizszego dolka 1h w historii okna')
        elif pkt >= 2:
            przew = f"LONG (4h {_v226_trend_txt(t4)}, 1h {_v226_trend_txt(t1)}, 1h {ev1 or '-'})"
            uniew = f"ponizej {psig(slo, 6)} (ostatni dolek 1h)" if slo else 'brak dolka 1h'
            wyz = [float(h[p]) for p in ph if h[p] > price]          # V6.227: najblizszy szczyt 1h nad cena
            cel = (f"{psig(min(wyz), 6)} (najblizszy szczyt 1h nad cena)" if wyz else 'brak wyzszego szczytu 1h w historii okna')
        else:
            przew = f"BRAK (sygnaly mieszane: 4h {_v226_trend_txt(t4)}, 1h {_v226_trend_txt(t1)}, 1h {ev1 or '-'})"
            uniew = f"wybicie {psig(sh, 6)} albo zejscie pod {psig(slo, 6)}" if sh and slo else '-'
            cel = '-'
        out.append({'symbol': sym, 'cena': psig(price, 6), 'zm_1h_pct': rnd(f.get('chg_1h_pct'), 2), 'zm_4h_pct': rnd(f.get('chg_4h_pct'), 2),
                    'zm_24h_pct': rnd(f.get('chg_24h_pct'), 2), 'trend_4h': _v226_trend_txt(t4), 'trend_1h': _v226_trend_txt(t1),
                    'trend_15m': _v226_trend_txt(t15), 'struktura_1h': f"{f.get('struct_1h') or '-'} {ev1}".strip(),
                    'struktura_15m': f"{f.get('struct_15m') or '-'} {f.get('last_event_15m') or ''}".strip(),
                    'rezim_1h': f.get('regime_1h'), 'adx_1h': rnd(f.get('adx_1h'), 1), 'atr_1h_pct': rnd(atr, 2),
                    'szczyt_1h': (f"{psig(sh, 6)}{' (przebity)' if price > sh else ''}" if sh else None),
                    'dolek_1h': (f"{psig(slo, 6)}{' (przebity)' if price < slo else ''}" if slo else None),
                    'max_24h': psig(hi24, 6), 'min_24h': psig(lo24, 6), 'punkty': pkt, 'przewaga': przew,
                    'uniewaznienie': uniew, 'cel': cel})
    return out


_V228_TRAF = {}
