def _v228_ocen(log, PP, now_ms):
    """Uzupelnia ruch ceny po 4h/12h w strone oceny (SHORT: spadek = plus) z zamknietych swiec 1h."""
    for r in log:
        sym = r.get('symbol'); P = (PP or {}).get(sym)
        if P is None or '1h' not in P.get('arr', {}):
            continue
        a = P['arr']['1h']
        try:
            ts, cena, pkt = int(float(r['ts_ms'])), float(r['cena']), int(float(r['punkty']))
        except (KeyError, TypeError, ValueError):
            continue
        kier = -1 if pkt <= -2 else 1 if pkt >= 2 else 0
        for hh, kol in ((4, 'ruch_4h_pct'), (12, 'ruch_12h_pct')):
            if r.get(kol) not in (None, '') and r.get(kol) == r.get(kol):
                continue
            cel = ts + hh * HOUR_MS
            i = int(np.searchsorted(a[:, T], cel - HOUR_MS))        # swieca 1h zamknieta najpozniej w chwili cel
            if cel > now_ms or i >= len(a) or a[i, T] + HOUR_MS > now_ms:
                continue
            ruch = (float(a[i, C]) / cena - 1) * 100
            r[kol] = rnd(ruch * (kier if kier else 1), 3) if kier else rnd(ruch, 3)
    return log


def _v228_podsumuj(log):
    out = {}
    df = pd.DataFrame(log)
    if not len(df):
        return out
    df['punkty'] = pd.to_numeric(df.punkty, errors='coerce')
    for sym, x in df[(df.punkty <= -2) | (df.punkty >= 2)].groupby('symbol'):
        d = {}
        for kol, nm in (('ruch_4h_pct', '4h'), ('ruch_12h_pct', '12h')):
            v = pd.to_numeric(x[kol], errors='coerce').dropna()
            d[nm] = (int(len(v)), rnd(float((v > 0).mean() * 100), 0) if len(v) else None, rnd(float(v.mean()), 2) if len(v) else None)
        out[sym] = d
    return out


def kierunek_log_v228(kier, PP, now_ms, drive_ok):
    """V6.228: dziennik ocen kierunku (raz na godzine na symbol) + ocena po 4h/12h. Na Drive albo lokalnie."""
