def _v269_cg_key():
    """V6.269: sekret Colab COINGLASS_API_KEY ma pierwszenstwo przed stala w pliku."""
    try:
        k = api_secret('COINGLASS_API_KEY')
    except Exception:
        k = None
    return (k or COINGLASS_API_KEY or '').strip()


def _v269_cg_odcisk():
    import hashlib as _h
    return _h.sha256(_v269_cg_key().encode()).hexdigest()[:12]
COINGLASS_URL = 'https://open-api-v4.coinglass.com'
COINGLASS_GIELDY = 'Binance,OKX,Bybit,Bitget,Gate,Hyperliquid'
_V234_OST = {'t': 0.0, 'bledy': [], 'diag': []}


def _v234_cg(sciezki, params):
    """GET CoinGlass v4 z limitem 30/min; probuje kolejne warianty sciezki. Zwraca liste wierszy (dict)."""
    ostatni = None
    for path in sciezki:
        czekaj = 2.1 - (time.time() - _V234_OST['t'])
        if czekaj > 0:
            time.sleep(czekaj)
        _V234_OST['t'] = time.time()
        try:
            r = requests.get(COINGLASS_URL + path, params=params, headers={'CG-API-KEY': _v269_cg_key(), 'accept': 'application/json'}, timeout=20)
            try:
                d = r.json()
            except Exception:
                d = {'code': str(r.status_code), 'msg': r.text[:150]}
            if not isinstance(d, dict):
                d = {'code': str(r.status_code), 'msg': str(d)[:150]}
            _V234_OST['diag'].append({'sciezka': path, 'symbol': params.get('symbol'), 'http': r.status_code, 'code': d.get('code'),
                                      'msg': str(d.get('msg'))[:150], 'wiersze': len(d['data']) if isinstance(d.get('data'), list) else None})
        except Exception as exc:
            ostatni = str(exc)[:120]
            _V234_OST['diag'].append({'sciezka': path, 'symbol': params.get('symbol'), 'http': None, 'code': None, 'msg': ostatni, 'wiersze': None})
            continue
        if str(d.get('code')) == '0' and isinstance(d.get('data'), list):
            return d['data']
        ostatni = f"{path}: {d.get('code')} {str(d.get('msg'))[:100]}"
    _V234_OST['bledy'].append(ostatni)
    raise ValueError(ostatni)


def _v234_kol(rows, *frazy):
    """Szereg (t, wartosc) z pierwszego pola zawierajacego ktoras z fraz."""
    if not rows:
        return pd.DataFrame(columns=['t', 'v'])
    klucze = [k for k in rows[0] if k != 'time']
    k = next((k for f in frazy for k in klucze if f in k), None)
    if k is None:
        return pd.DataFrame(columns=['t', 'v'])
    tt = [int(float(x['time'])) for x in rows]
    tt = [t if t > 1e12 else t * 1000 for t in tt]
    return pd.DataFrame({'t': tt, 'v': [float(x[k]) if x.get(k) not in (None, '') else np.nan for x in rows]})


def _v234_coinglass(sym, start_ms, end_ms, interwal='4h'):
    """V6.234: DataFrame(t, ls, top, oi, fund, liq_long, liq_short) na siatce 4h z CoinGlass. V6.312: interwal '1d' (dane dzienne, cala historia)."""
    if not _v269_cg_key() or _V234_OST.get('brak_planu'):
        return None
    coin = sym[:-4].replace('1000', '') if sym.endswith('USDT') else sym
    krok = DAY_MS if interwal == '1d' else 4 * HOUR_MS
    p4 = {'interval': interwal, 'limit': 1000, 'start_time': int(start_ms), 'end_time': int(end_ms)}
    p4b = {'interval': interwal, 'limit': min(1000, int((end_ms - start_ms) / krok) + 1)}

    def jeden(sciezki, extra, extra_b=None):              # V6.237: blad jednego endpointu nie przerywa reszty
        for prm in (dict(p4, **extra), dict(p4b, **(extra_b or extra))):
            try:
                return _v234_cg(sciezki, prm)
            except Exception:
                continue
        return []
    liq = jeden(['/api/futures/liquidation/aggregated-history'], {'symbol': coin, 'exchange_list': COINGLASS_GIELDY},
                {'symbol': coin, 'exchange_list': 'Binance'})
    oi = jeden(['/api/futures/open-interest/aggregated-history', '/api/futures/openInterest/aggregated-history'], {'symbol': coin})
    fu = jeden(['/api/futures/funding-rate/oi-weight-history', '/api/futures/fundingRate/oi-weight-ohlc-history'], {'symbol': coin})
    ls = jeden(['/api/futures/global-long-short-account-ratio/history'], {'exchange': 'Binance', 'symbol': sym})
    top = jeden(['/api/futures/top-long-short-account-ratio/history'], {'exchange': 'Binance', 'symbol': sym})
    ekstra = {}
    if True:                                               # V6.275: CVD dla wszystkich; arkusz tylko BTC/ETH
        ekstra['tk'] = jeden(['/api/futures/aggregated-taker-buy-sell-volume/history', '/api/futures/taker-buy-sell-volume/history'],
                             {'symbol': coin, 'exchange_list': COINGLASS_GIELDY}, {'symbol': coin, 'exchange_list': 'Binance'})
    ekstra['sp'] = jeden(['/api/spot/aggregated-taker-buy-sell-volume/history', '/api/spot/taker-buy-sell-volume/history'],   # V6.282
                         {'symbol': coin, 'exchange_list': 'Binance,OKX,Bybit,Coinbase,Bitget'}, {'symbol': coin, 'exchange_list': 'Binance'})
    if coin in ('BTC', 'ETH') and interwal == '4h':
        ekstra['ob'] = jeden(['/api/futures/orderbook/aggregated-ask-bids-history'],
                             {'symbol': coin, 'exchange_list': COINGLASS_GIELDY, 'range': '1'}, {'symbol': coin, 'exchange_list': 'Binance', 'range': '1'})
        _V297.setdefault('ob_zrodlo', {})[coin] = 'aggregated-ask-bids-history' if ekstra['ob'] else None   # V6.299
        if not ekstra['ob']:                               # V6.297: plan odrzuca dluga historie arkusza -> krotsze okna, potem jedna gielda
            for lim in (500, 180, 60, 12):
                if lim > p4b['limit'] and lim != 12:
                    continue
                for sc, prm in (('/api/futures/orderbook/aggregated-ask-bids-history', {'symbol': coin, 'exchange_list': COINGLASS_GIELDY}),
                                ('/api/futures/orderbook/ask-bids-history', {'symbol': coin + 'USDT', 'exchange': 'Binance'})):
                    try:
                        ekstra['ob'] = _v234_cg([sc], dict(prm, interval='4h', limit=lim, range='1'))
                    except Exception:
                        ekstra['ob'] = []
                    if ekstra['ob']:
                        _V297.setdefault('ob_zrodlo', {})[coin] = sc.rsplit('/', 1)[-1]   # V6.299
                        break
                if ekstra['ob']:
                    break
    if not any((liq, oi, fu, ls, top)):
        if _V234_OST['diag'] and all('Upgrade plan' in str(x.get('msg')) or str(x.get('code')) == '404' for x in _V234_OST['diag']):
            _V234_OST['brak_planu'] = True                # V6.238: konto bez aktywnego planu - nie probuj reszty
        return None
    _V234_OST.setdefault('dostepne', set()).update(k for k, v in (('likwidacje', liq), ('OI', oi), ('funding', fu), ('L/S', ls), ('top', top)) if v)
    baza = ls or top or oi or fu or liq
    d = _v234_kol(baza, 'long_short_ratio', 'ratio', 'close', 'liquidation')[['t']]
    d = d.merge(_v234_kol(ls, 'long_short_ratio', 'ratio').rename(columns={'v': 'ls'}), on='t', how='left') if ls else d.assign(ls=np.nan)
    for nm, rows, fr in (('top', top, ('long_short_ratio', 'ratio')), ('oi', oi, ('close',)), ('fund', fu, ('close',)),
                         ('liq_long', liq, ('long_liquidation',)), ('liq_short', liq, ('short_liquidation',))):
        x = _v234_kol(rows, *fr).rename(columns={'v': nm})
        d = d.merge(x, on='t', how='left') if len(x) else d.assign(**{nm: np.nan})
    for nm, rows, fr in (('cvd_buy', ekstra.get('tk'), ('buy_vol', 'buy')), ('cvd_sell', ekstra.get('tk'), ('sell_vol', 'sell')),
                         ('spot_buy', ekstra.get('sp'), ('buy_vol', 'buy')), ('spot_sell', ekstra.get('sp'), ('sell_vol', 'sell')),
                         ('ob_bid', ekstra.get('ob'), ('bids_usd', 'bids_amount', 'bid')), ('ob_ask', ekstra.get('ob'), ('asks_usd', 'asks_amount', 'ask'))):
        if rows:                                           # V6.274
            x = _v234_kol(rows, *fr).rename(columns={'v': nm})
            if len(x):
                d = d.merge(x.drop_duplicates('t'), on='t', how='left')
                _V234_OST.setdefault('dostepne', set()).add('CVD' if nm.startswith('cvd') else 'CVD spot' if nm.startswith('spot') else 'arkusz')
    if 'fund' in d and d['fund'].abs().max() > 0.01:
        d['fund'] = d['fund'] / 100                          # CoinGlass podaje funding w %
    return d.drop_duplicates('t').sort_values('t').reset_index(drop=True)


_V260 = {'porownanie': None}


def gate_porownanie_v260(now_ms, drive_ok, c4):
    """Te same sygnaly na danych Gate (dla porownania z CoinGlass). Cache dobowy."""
    plik = (Path(DRIVE_DIR) if drive_ok else OUT_ROOT / 'weex_cache') / 'pozycje_gate_v260.json'
    dzien = int(now_ms // DAY_MS)
    dane = None
    if plik.is_file():
        try:
            c = json.loads(plik.read_text())
            if c.get('dzien') == dzien:
                dane = {k: pd.DataFrame(v) for k, v in c['dane'].items()}
        except Exception:
            dane = None
    if dane is None:
        dane = {}
        for sym in POZ_SYMBOLE:
            g = _v231_gate(sym, now_ms - POZ_DNI * DAY_MS, now_ms)
            if g is not None and len(g) >= 60:
                dane[sym] = g
        try:
            plik.parent.mkdir(parents=True, exist_ok=True)
            plik.write_text(json.dumps({'dzien': dzien, 'dane': {k: v.to_dict('list') for k, v in dane.items()}}))
        except Exception:
            pass
    return badanie_pozycji_v230(_v290_czas_znany(dane, now_ms), c4) if dane else []   # V6.290


POZ_SYMBOLE = ('BTCUSDT', 'ETHUSDT', 'SOLUSDT', 'XRPUSDT', 'BNBUSDT', 'DOGEUSDT')
POZ_HYBRYDA = True               # V6.272: L/S tlumu, top, taker z Gate; likwidacje/OI/funding z CoinGlass
POZ_GATE_KOLUMNY = ('ls', 'top', 'taker')
POZ_DNI = 165                    # V6.234: CoinGlass Hobbyist 4h do 180 dni (limit 1000 swiec)
POZ_Z_PROG = 1.5                 # skrajne pozycjonowanie: z-score (wzgledem 30 dni) powyzej tego progu
_V230 = {'teraz': {}, 'badanie': [], 'zrodlo': None}


def _v230_bybit(path, params, klucz_czasu, max_stron=8):
    """Stronicowanie Bybit v5 (cursor). Zwraca liste dictow."""
    out, cur = [], None
    for _ in range(max_stron):
        p_ = dict(params, **({'cursor': cur} if cur else {}))
        d = request_json('https://api.bybit.com', path, p_)
        if not isinstance(d, dict) or str(d.get('retCode')) != '0':
            raise ValueError(f"bybit {path}: {d.get('retMsg') if isinstance(d, dict) else d}")
        res = d.get('result') or {}
        out += res.get('list') or []
        cur = res.get('nextPageCursor')
        if not cur or not res.get('list'):
            break
    return out


def _v272_gate_kol(cg, g):
    """V6.272: kolumny tlumu (ls, top, taker) z Gate w miejsce CoinGlass; L/S z CoinGlass zostaje jako ls_cg."""
    if cg is None or g is None or not len(g):
        return cg
    kol = [k for k in POZ_GATE_KOLUMNY if k in g.columns and pd.to_numeric(g[k], errors='coerce').notna().any()]
    if not kol:
        return cg
    x = cg.sort_values('t').copy()
    if 'ls' in kol and 'ls' in x.columns and 'ls_cg' not in x.columns:
        x = x.rename(columns={'ls': 'ls_cg'})
    x = x.drop(columns=[k for k in kol if k in x.columns])
    gg = g[['t'] + kol].copy()
    x['t'] = x['t'].astype('int64'); gg['t'] = gg['t'].astype('int64')
    return pd.merge_asof(x, gg.sort_values('t'), on='t', direction='backward', tolerance=4 * HOUR_MS)


def _v272_gate_stare(df):
    """Kolumny tlumu z Gate juz zapisane w danych (do sklejenia ze swiezym ogonem)."""
    kol = [k for k in POZ_GATE_KOLUMNY if k in df.columns]
    return df[['t'] + kol].dropna(subset=kol, how='all') if kol else pd.DataFrame({'t': []})


def _v272_symbole():
    return tuple(dict.fromkeys(tuple(POZ_SYMBOLE) + tuple(MAJORS_4H)))


POZ_CZAS_PRZESUNIECIE_MS = 4 * 3600000   # V6.290: wiersz 4h znany dopiero po zamknieciu swiecy


def _v290_czas_znany(dane, now_ms):
    """Przesuwa czas wierszy pozycjonowania na koniec swiecy 4h i odrzuca swiece jeszcze niezamkniete."""
    out = {}
    for k, df in (dane or {}).items():
        if df is None or not len(df) or 't' not in df.columns:
            continue
        d = df.copy()
        d['t'] = pd.to_numeric(d['t'], errors='coerce').astype('int64') + POZ_CZAS_PRZESUNIECIE_MS
        d = d[d.t <= int(now_ms)].reset_index(drop=True)
        if len(d):
            out[k] = d
    return out


def pozycje_dane_v230(now_ms, drive_ok):
    """V6.290: dane jak dotad, z czasem = zamkniecie swiecy 4h (bez zagladania w przyszlosc)."""
    dane, zr = _v230_pozycje_surowe(now_ms, drive_ok)
    try:                                                   # V6.297: trwale archiwum arkusza bid/ask
        dane = _v297_arkusz(dane, (Path(DRIVE_DIR) if drive_ok else OUT_ROOT / 'weex_cache') / 'arkusz_v297.json')
    except Exception as exc:
        print(f'Arkusz V6.297: blad ({str(exc)[:100]})')
    _V317['surowe'] = dane                                 # V6.317: surowe (z niezamknieta swieca) do wstepnego odczytu
    return _v290_czas_znany(dane, now_ms), zr


_V317 = {'surowe': None, 'wstepne': {}, 'wyjscie': None, 'potwierdzenia': None}


_V297 = {'wiersze': {}, 'nowe': {}}


ARKUSZ_MIN_SWIEC = 60       # V6.298: tyle swiec potrzebuje z-score arkusza (rolling min_periods)


_V299_OB_ZRODLA = {'aggregated-ask-bids-history': lambda c: {'symbol': c, 'exchange_list': COINGLASS_GIELDY},
                   'ask-bids-history': lambda c: {'symbol': c + 'USDT', 'exchange': 'Binance'}}


def _v299_ob_wiersze(rows):
    b = _v234_kol(rows, 'bids_usd', 'bids_amount', 'bid').rename(columns={'v': 'ob_bid'})
    a = _v234_kol(rows, 'asks_usd', 'asks_amount', 'ask').rename(columns={'v': 'ob_ask'})
    if not len(b) or not len(a):
        return pd.DataFrame(columns=['t', 'ob_bid', 'ob_ask'])
    return b.drop_duplicates('t').merge(a.drop_duplicates('t'), on='t').dropna()


def _v299_arkusz_ogon(coin, zrodlo, lim=12):
    """V6.299: ogon arkusza z TEGO SAMEGO zrodla co archiwum (zagregowany i Binance maja inny rozklad - nie mieszac)."""
    try:
        rows = _v234_cg(['/api/futures/orderbook/' + zrodlo], dict(_V299_OB_ZRODLA[zrodlo](coin), interval='4h', limit=lim, range='1'))
    except Exception:
        return pd.DataFrame(columns=['t', 'ob_bid', 'ob_ask'])
    return _v299_ob_wiersze(rows) if rows else pd.DataFrame(columns=['t', 'ob_bid', 'ob_ask'])


def _v298_arkusz_historia(coin):
    """V6.298: najdluzsza historia arkusza, jaka przepuszcza plan (od 500 swiec w dol); wiersze (t, ob_bid, ob_ask), t = poczatek swiecy.
    V6.299: zrodlo zapisane w _V297['hist_zrodlo'] (zagregowany ma pierwszenstwo)."""
    for lim in (500, 250, 180, 120, 60):
        for sc, prm in (('/api/futures/orderbook/aggregated-ask-bids-history', {'symbol': coin, 'exchange_list': COINGLASS_GIELDY}),
                        ('/api/futures/orderbook/ask-bids-history', {'symbol': coin + 'USDT', 'exchange': 'Binance'})):
            try:
                rows = _v234_cg([sc], dict(prm, interval='4h', limit=lim, range='1'))
            except Exception:
                continue
            if rows:
                b = _v234_kol(rows, 'bids_usd', 'bids_amount', 'bid').rename(columns={'v': 'ob_bid'})
                a = _v234_kol(rows, 'asks_usd', 'asks_amount', 'ask').rename(columns={'v': 'ob_ask'})
                if len(b) and len(a):
                    _V297.setdefault('historia', {})[coin] = f'{len(rows)} swiec (limit {lim}, {sc.rsplit("/", 1)[-1]})'
                    _V297.setdefault('hist_zrodlo', {})[coin] = sc.rsplit('/', 1)[-1]
                    return b.drop_duplicates('t').merge(a.drop_duplicates('t'), on='t').dropna()
    _V297.setdefault('historia', {})[coin] = 'plan odrzucil kazde okno >= 60 swiec'
    return pd.DataFrame(columns=['t', 'ob_bid', 'ob_ask'])


def _v297_arkusz(dane, plik):
    """V6.297: arkusz bid/ask (BTC/ETH) zapisywany w osobnym pliku, ktory nie jest kasowany przy dobowym odswiezeniu cache.
    V6.299: jedno zrodlo na symbol (zagregowany ALBO Binance) - archiwum pamieta zrodlo, ogon spoza tego zrodla jest odrzucany
    i pobierany z wlasciwego; kolumny arkusza w danych zastepowane archiwum (bez mieszania). Archiwum bez znanego zrodla -> od nowa."""
    plik = Path(plik)
    arch = {}
    if plik.is_file():
        try:
            arch = json.loads(plik.read_text())
        except Exception:
            arch = {}
    zmiana = False
    pusty = lambda: pd.DataFrame({'t': [], 'ob_bid': [], 'ob_ask': []})
    for sym in ('BTCUSDT', 'ETHUSDT'):
        coin = sym[:-4]
        d = dane.get(sym)
        zap = arch.get(sym) or {}
        zr = zap.get('zrodlo')
        a = pd.DataFrame({k: zap.get(k, []) for k in ('t', 'ob_bid', 'ob_ask')}) if zr else pusty()   # V6.299: bez zrodla -> od nowa
        n0 = len(a)
        if n0 < ARKUSZ_MIN_SWIEC and COINGLASS_API_KEY and not REPLAY_ZIP and d is not None and len(d):   # V6.298: dociagnij historie od razu
            try:
                h = _v298_arkusz_historia(coin)
                zh = (_V297.get('hist_zrodlo') or {}).get(coin)
                if len(h) and zh:
                    if zh != zr:
                        a, zr = pusty(), zh                   # inne zrodlo -> archiwum od nowa
                    a = pd.concat([a, h], ignore_index=True).drop_duplicates('t', keep='last').sort_values('t').reset_index(drop=True)
            except Exception as exc:
                print(f'Arkusz V6.298: historia {sym} - blad ({str(exc)[:80]})')
        if zr and d is not None and len(d) and not REPLAY_ZIP:
            zd = (_V297.get('ob_zrodlo') or {}).get(coin)
            x = d[['t', 'ob_bid', 'ob_ask']].dropna() if {'ob_bid', 'ob_ask'} <= set(d.columns) and zd == zr else pusty()
            if not len(x) and COINGLASS_API_KEY:
                x = _v299_arkusz_ogon(coin, zr)          # ogon z tego samego zrodla
            if len(x):
                a = pd.concat([a, x], ignore_index=True).drop_duplicates('t', keep='last').sort_values('t').reset_index(drop=True)
        _V297['nowe'][sym] = len(a) - n0
        _V297['wiersze'][sym] = len(a)
        _V297.setdefault('zrodlo', {})[sym] = zr
        if zr and (len(a) != n0 or zap.get('zrodlo') != zr):
            arch[sym] = {'zrodlo': zr, **{k: [None if v != v else v for v in a[k].tolist()] for k in ('t', 'ob_bid', 'ob_ask')}}
            zmiana = True
        if d is not None and len(d):
            d = d.copy()
            d['t'] = pd.to_numeric(d['t'], errors='coerce').astype('int64')
            if len(a) and zr:
                m = d[['t']].merge(a.astype({'t': 'int64'}).drop_duplicates('t'), on='t', how='left')
                for c in ('ob_bid', 'ob_ask'):
                    d[c] = m[c].values                         # V6.299: tylko archiwum (jedno zrodlo)
            else:
                d = d.drop(columns=[c for c in ('ob_bid', 'ob_ask') if c in d.columns])
            dane[sym] = d
    if zmiana and not REPLAY_ZIP:
        try:
            plik.parent.mkdir(parents=True, exist_ok=True)
            plik.write_text(json.dumps(arch))
        except Exception as exc:
            print(f'Arkusz V6.297: blad zapisu ({str(exc)[:80]})')
    return dane


def _v230_pozycje_surowe(now_ms, drive_ok):
    """{sym: DataFrame(t, ls, oi, fund)} na siatce 4h; Bybit, zapasowo Binance futures. Cache dobowy."""
    plik = (Path(DRIVE_DIR) if drive_ok else OUT_ROOT / 'weex_cache') / 'pozycje_v230.json'
    dzien = int(now_ms // DAY_MS)
    if plik.is_file():
        try:
            c = json.loads(plik.read_text())
            if (c.get('dzien') == dzien and c.get('dane') and COINGLASS_API_KEY and 'coinglass' not in str(c.get('zrodlo'))
                    and (c.get('cg_proba260') != dzien or c.get('cg_klucz') != _v269_cg_odcisk()) and not REPLAY_ZIP):   # V6.260/269: nowy dzien albo nowy klucz
                c = {}                                      # V6.235: sprobuj CoinGlass (raz na dobe)
            if c.get('dane') and not REPLAY_ZIP and not c.get('v282'):
                c = {}                                      # V6.272: hybryda zrodel + 24 kontrakty -> pobierz raz od nowa
            if (c.get('dane') and 'gate' in str(c.get('zrodlo')) and not REPLAY_ZIP
                    and 'taker' not in (c['dane'].get('BTCUSDT') or {})):
                c = {}                                      # V6.252: cache bez taker -> pobierz pelna historie raz
            if c.get('dzien') == dzien and c.get('dane'):
                dane = {k: pd.DataFrame(v) for k, v in c['dane'].items()}
                zmiany = False
                ost_zamk = (int(now_ms) // (4 * HOUR_MS)) * 4 * HOUR_MS - 4 * HOUR_MS   # V6.292: poczatek ostatniej zamknietej swiecy 4h
                if not REPLAY_ZIP:                          # V6.233: swiezy ogon (2 dni) przy kazdym uruchomieniu
                    for k in list(dane):
                        try:
                            if 'coinglass' in str(c.get('zrodlo')):
                                g2 = _v231_gate(k, now_ms - 2 * DAY_MS, now_ms) if POZ_HYBRYDA else None   # V6.272
                                brak_sw = int(pd.to_numeric(dane[k].t, errors='coerce').max()) < ost_zamk   # V6.292
                                if k not in ('BTCUSDT', 'ETHUSDT') and not brak_sw:   # limit 30/min: pelny ogon tylko gdy brak ostatniej swiecy
                                    if g2 is not None and len(g2) and 'ls_cg' in dane[k].columns:
                                        dane[k] = _v272_gate_kol(dane[k].drop(columns=[x for x in POZ_GATE_KOLUMNY if x in dane[k].columns]),
                                                                 pd.concat([_v272_gate_stare(dane[k]), g2], ignore_index=True)
                                                                 .drop_duplicates('t', keep='last').sort_values('t'))
                                    continue
                                ogon = _v234_coinglass(k, now_ms - 2 * DAY_MS, now_ms)
                                if ogon is not None and len(ogon) and g2 is not None and len(g2):
                                    ogon = _v272_gate_kol(ogon, pd.concat([_v272_gate_stare(dane[k]), g2], ignore_index=True)
                                                          .drop_duplicates('t', keep='last').sort_values('t'))
                            else:
                                ogon = _v231_gate(k, now_ms - 2 * DAY_MS, now_ms)
                        except Exception:
                            ogon = None
                        if ogon is not None and len(ogon):
                            dane[k] = (pd.concat([dane[k], ogon], ignore_index=True).drop_duplicates('t', keep='last')
                                       .sort_values('t').reset_index(drop=True))
                            zmiany = True
                if zmiany and not REPLAY_ZIP:               # V6.292: zapis odswiezonych danych (kolejny przebieg nie pobiera ponownie)
                    try:
                        c['dane'] = {k: v.to_dict('list') for k, v in dane.items()}
                        plik.write_text(json.dumps(c, default=lambda o: None if isinstance(o, float) and o != o else o))
                    except Exception as exc:
                        print(f'Pozycje V6.292: blad zapisu cache ({str(exc)[:80]})')
                return dane, c.get('zrodlo')
        except Exception:
            pass
    if REPLAY_ZIP:
        return {}, 'brak (replay)'
    start = now_ms - POZ_DNI * DAY_MS
    dane, zrodla = {}, set()
    for sym in _v272_symbole():                            # V6.272: 24 duze kontrakty
        try:                                               # V6.234: CoinGlass (caly rynek) najpierw
            cg = _v234_coinglass(sym, start, now_ms)
        except Exception:
            cg = None
        if cg is not None and len(cg) >= 60 and POZ_HYBRYDA:   # V6.272: tlum z Gate
            g_ = _v231_gate(sym, start, now_ms)
            if g_ is not None and len(g_):
                cg = _v272_gate_kol(cg, g_)
                zrodla.add('gate')
        if cg is not None and len(cg) >= 60:
            braki = [k for k in ('ls', 'top', 'oi', 'fund', 'liq_long', 'liq_short', 'taker') if k not in cg or cg[k].isna().all()]   # V6.260: + taker
            if braki:                                       # V6.237: brakujace kolumny z Gate
                g_ = _v231_gate(sym, start, now_ms)
                if g_ is not None and len(g_):
                    braki = [k for k in braki if k in g_.columns]
                    cg = pd.merge_asof(cg.sort_values('t').drop(columns=[k for k in braki if k in cg]), g_[['t'] + braki].sort_values('t'),
                                       on='t', direction='backward', tolerance=4 * HOUR_MS)
                    zrodla.add('gate')
            dane[sym] = cg; zrodla.add('coinglass')
            continue
        g = _v231_gate(sym, start, now_ms)                 # V6.231: Gate.io (dziala z Colab)
        if g is not None and len(g) >= 60:
            dane[sym] = g; zrodla.add('gate')
            continue
        if sym not in POZ_SYMBOLE:                         # V6.272: Bybit/Binance tylko dla 6 glownych
            continue
        try:
            ls = _v230_bybit('/v5/market/account-ratio', {'category': 'linear', 'symbol': sym, 'period': '4h', 'limit': 500,
                                                          'startTime': start, 'endTime': now_ms}, 'timestamp')
            oi = _v230_bybit('/v5/market/open-interest', {'category': 'linear', 'symbol': sym, 'intervalTime': '4h', 'limit': 200,
                                                          'startTime': start, 'endTime': now_ms}, 'timestamp')
            fu, end = [], now_ms
            for _ in range(6):
                d = request_json('https://api.bybit.com', '/v5/market/funding/history',
                                 {'category': 'linear', 'symbol': sym, 'endTime': end, 'limit': 200})
                lst = ((d or {}).get('result') or {}).get('list') or []
                fu += lst
                if not lst:
                    break
                end = min(int(x['fundingRateTimestamp']) for x in lst) - 1
                if end < start:
                    break
            df = pd.DataFrame({'t': [int(x['timestamp']) for x in ls], 'ls': [float(x['buyRatio']) for x in ls]})
            o = pd.DataFrame({'t': [int(x['timestamp']) for x in oi], 'oi': [float(x['openInterest']) for x in oi]})
            f = pd.DataFrame({'t': [int(x['fundingRateTimestamp']) for x in fu], 'fund': [float(x['fundingRate']) for x in fu]})
            zr = 'bybit'
        except Exception:
            try:                                           # zapas: Binance futures (30 dni)
                b = 'https://fapi.binance.com'
                ls = request_json(b, '/futures/data/globalLongShortAccountRatio', {'symbol': sym, 'period': '4h', 'limit': 500})
                oi = request_json(b, '/futures/data/openInterestHist', {'symbol': sym, 'period': '4h', 'limit': 500})
                fu = request_json(b, '/fapi/v1/fundingRate', {'symbol': sym, 'limit': 1000, 'startTime': start})
                df = pd.DataFrame({'t': [int(x['timestamp']) for x in ls], 'ls': [float(x['longAccount']) for x in ls]})
                o = pd.DataFrame({'t': [int(x['timestamp']) for x in oi], 'oi': [float(x['sumOpenInterest']) for x in oi]})
                f = pd.DataFrame({'t': [int(x['fundingTime']) for x in fu], 'fund': [float(x['fundingRate']) for x in fu]})
                zr = 'binance'
            except Exception:
                continue
        if not len(df):
            continue
        df = df.sort_values('t').merge(o.sort_values('t'), on='t', how='left')
        df = pd.merge_asof(df.sort_values('t'), f.sort_values('t'), on='t', direction='backward')
        dane[sym] = df.dropna(subset=['ls']).reset_index(drop=True)
        zrodla.add(zr)
    zr = ','.join(sorted(zrodla)) or 'brak (API niedostepne)'
    if dane:
        try:
            plik.parent.mkdir(parents=True, exist_ok=True)
            plik.write_text(json.dumps({'dzien': dzien, 'zrodlo': zr, 'v272': True, 'v274': True, 'v275': True, 'v282': True, 'cg_proba260': dzien if COINGLASS_API_KEY else None, 'cg_klucz': _v269_cg_odcisk(),
                                        'dane': {k: v.to_dict('list') for k, v in dane.items()}}))
        except Exception as exc:
            print(f'Pozycje V6.230: blad zapisu cache ({str(exc)[:100]})')
    return dane, zr


def _v231_gate(sym, start_ms, end_ms):
    """V6.231: Gate.io contract_stats 4h (stronicowanie 'from') + funding_rate -> DataFrame(t, ls, oi, fund, top, liq_long, liq_short)."""
    for c in gate_contract(sym):
        rows, od = [], int(start_ms // 1000)
        try:
            for _ in range(12):
                r = requests.get(GATE_URL, params={'contract': c, 'interval': '4h', 'from': od, 'limit': 100}, timeout=10)
                if r.status_code != 200:
                    break
                d = r.json()
                if not isinstance(d, list) or not d:
                    break
                rows += d
                last = max(int(float(x['time'])) for x in d)
                if last * 1000 >= end_ms - 4 * HOUR_MS or len(d) < 2:
                    break
                od = last + 1
            if not rows:
                continue
            fr = requests.get('https://api.gateio.ws/api/v4/futures/usdt/funding_rate', params={'contract': c, 'limit': 1000}, timeout=10)
            fu = fr.json() if fr.status_code == 200 else []
        except Exception:
            continue
        num = lambda x, k: float(x[k]) if x.get(k) not in (None, '') else np.nan
        df = pd.DataFrame({'t': [int(float(x['time'])) * 1000 for x in rows],
                           'ls': [num(x, 'lsr_account') for x in rows], 'top': [num(x, 'top_lsr_account') for x in rows],
                           'taker': [num(x, 'lsr_taker') for x in rows],                       # V6.252
                           'oi': [num(x, 'open_interest_usd') for x in rows],
                           'liq_long': [num(x, 'long_liq_usd') for x in rows], 'liq_short': [num(x, 'short_liq_usd') for x in rows]})
        df = df.drop_duplicates('t').sort_values('t')
        if isinstance(fu, list) and fu:
            f = pd.DataFrame({'t': [int(float(x['t'])) * 1000 for x in fu], 'fund': [float(x['r']) for x in fu]}).sort_values('t')
            df = pd.merge_asof(df, f, on='t', direction='backward')
        else:
            df['fund'] = np.nan
        return df.reset_index(drop=True)
    return None


# ================= V6.252: Deribit - premia kontraktow kwartalnych (basis) i skew opcji; Gate taker =================
_V252 = {'basis_teraz': {}, 'skew': None, 'bledy': []}
DERIBIT = 'https://www.deribit.com/api/v2/public/'


def _v252_get(metoda, params):
    r = requests.get(DERIBIT + metoda, params=params, timeout=15)
    try:
        j = r.json() or {}
    except ValueError:
        j = {}
    if j.get('error') or r.status_code != 200:                 # V6.253: zapisz blad API
        _V252['bledy'].append(f"{metoda} {params.get('instrument_name') or params.get('currency', '')}: http {r.status_code} "
                              f"{str(j.get('error') or r.text[:80])[:120]}")
    return j.get('result')


def _v252_wykres(nazwa, od, do):
    """Swiece 4h instrumentu Deribit -> DataFrame(t = zamkniecie swiecy, c). V6.253: okna po 20 dni."""
    czesci, a = [], int(od)
    while a < int(do):
        b = min(int(do), a + 20 * DAY_MS)
        d = _v252_get('get_tradingview_chart_data', {'instrument_name': nazwa, 'start_timestamp': a,
                                                     'end_timestamp': b, 'resolution': '60'}) or {}
        if d.get('ticks') and d.get('close'):              # V6.254: 1h -> zamkniecia na granicach 4h
            x = pd.DataFrame({'t': [int(v) + HOUR_MS for v in d['ticks']], 'c': [float(v) for v in d['close']]})
            czesci.append(x[x.t % (4 * HOUR_MS) == 0])
        a = b
    if not czesci:
        return pd.DataFrame(columns=['t', 'c'])
    return pd.concat(czesci, ignore_index=True).drop_duplicates('t').sort_values('t').reset_index(drop=True)


def basis_v252(now_ms, drive_ok, waluta='BTC'):
    """Roczna premia kontraktu kwartalnego nad perpetual (%), 4h, ~POZ_DNI dni. Kontrakt: najstarszy z wygasnieciem >= 30 dni.
    Gdy kontrakt nie obejmuje calej historii, dolaczany jest wczesniejszy (w tym wygasly), wiec seria jest ciagla."""
    plik = (Path(DRIVE_DIR) if drive_ok else OUT_ROOT / 'weex_cache') / f'basis_v252_{waluta}.csv'
    stary = None
    if plik.is_file():
        try:
            stary = pd.read_csv(plik)
        except Exception:
            stary = None
    if REPLAY_ZIP:
        return stary if stary is not None else pd.DataFrame(columns=['t', 'basis'])
    start = now_ms - POZ_DNI * DAY_MS
    od = start if (stary is None or not len(stary) or int(stary.t.min()) > start + 2 * DAY_MS) else now_ms - 3 * DAY_MS
    ins = []
    for wyg in (False, True):
        try:
            ins += _v252_get('get_instruments', {'currency': waluta, 'kind': 'future', 'expired': str(wyg).lower()}) or []
        except Exception as exc:
            _V252['bledy'].append(f'instrumenty {waluta}: {str(exc)[:60]}')
    kw = sorted({(int(x['expiration_timestamp']), x['instrument_name']) for x in ins
                 if x.get('settlement_period') in ('quarter', 'month') and 'PERPETUAL' not in x['instrument_name']
                 and int(x['expiration_timestamp']) > od + 30 * DAY_MS})
    perp = _v252_wykres(f'{waluta}-PERPETUAL', od, now_ms)
    _V252.setdefault('diag', {})[waluta] = {'instrumenty': len(ins), 'kontrakty': len(kw), 'swiece_perp': len(perp)}
    if not len(perp) or not kw:
        return stary if stary is not None else pd.DataFrame(columns=['t', 'basis'])
    czesci, pokryte_do = [], od
    for exp, nazwa in kw:                                  # kolejne kontrakty: kazdy do 30 dni przed wygasnieciem
        koniec = min(exp - 30 * DAY_MS, now_ms)
        if koniec <= pokryte_do:
            continue
        f = _v252_wykres(nazwa, pokryte_do, koniec)
        if len(f):
            m = f.merge(perp, on='t', suffixes=('_f', '_p'))
            dni = (exp - m.t) / DAY_MS
            m['basis'] = (m.c_f / m.c_p - 1) * 365 / dni * 100
            czesci.append(m[['t', 'basis']])
            pokryte_do = int(m.t.max()) if len(m) else pokryte_do
        if pokryte_do >= now_ms - 4 * HOUR_MS:
            break
    nowy = pd.concat(czesci, ignore_index=True) if czesci else pd.DataFrame(columns=['t', 'basis'])
    _V252['diag'][waluta]['swiece_premii'] = len(nowy)
    dd = pd.concat([stary, nowy], ignore_index=True) if stary is not None else nowy
    dd = dd.drop_duplicates('t', keep='last').sort_values('t')
    dd = dd[dd.t >= start].reset_index(drop=True)
    try:
        plik.parent.mkdir(parents=True, exist_ok=True)
        dd.to_csv(plik, index=False)
    except Exception:
        pass
    return dd


def skew_v252(now_ms, drive_ok):
    """Skew opcji BTC ~30 dni: IV puta 10% OTM - IV calla 10% OTM (pkt). Historii nie ma za darmo -> dziennik na Drive."""
    plik = (Path(DRIVE_DIR) if drive_ok else OUT_ROOT / 'weex_cache') / 'skew_v252.csv'
    log = None
    if plik.is_file():
        try:
            log = pd.read_csv(plik)
        except Exception:
            log = None
    if REPLAY_ZIP:
        return None, log
    opc = _v252_get('get_book_summary_by_currency', {'currency': 'BTC', 'kind': 'option'}) or []
    rows = []
    for x in opc:
        try:
            _, exp, k, typ = x['instrument_name'].split('-')
            rows.append({'exp': exp, 'k': float(k), 'typ': typ, 'iv': float(x['mark_iv']), 'F': float(x['underlying_price']),
                         'exp_ms': int(pd.Timestamp(datetime.strptime(exp, '%d%b%y'), tz='UTC').value // 10 ** 6) + 8 * HOUR_MS})
        except Exception:
            continue
    o = pd.DataFrame(rows)
    if not len(o):
        return None, log
    o['dni'] = (o.exp_ms - now_ms) / DAY_MS
    o = o[o.dni > 7]
    if not len(o):
        return None, log
    exp = o.loc[(o.dni - 30).abs().idxmin(), 'exp']
    e = o[o.exp == exp]
    F = float(e.F.median())
    p = e[e.typ == 'P'].iloc[(e[e.typ == 'P'].k - 0.9 * F).abs().argsort()[:1]]
    c = e[e.typ == 'C'].iloc[(e[e.typ == 'C'].k - 1.1 * F).abs().argsort()[:1]]
    if not len(p) or not len(c):
        return None, log
    teraz = {'t': int(now_ms), 'exp': exp, 'dni': rnd(float(e.dni.iloc[0]), 1), 'F': rnd(F, 0),
             'iv_put': rnd(float(p.iv.iloc[0]), 2), 'iv_call': rnd(float(c.iv.iloc[0]), 2),
             'skew': rnd(float(p.iv.iloc[0]) - float(c.iv.iloc[0]), 2)}
    log = pd.concat([log, pd.DataFrame([teraz])], ignore_index=True) if log is not None else pd.DataFrame([teraz])
    try:
        plik.parent.mkdir(parents=True, exist_ok=True)
        log.to_csv(plik, index=False)
    except Exception:
        pass
    return teraz, log


def _v252_dolacz(dane, basis_btc, basis_eth):
    """Premia kwartalna do BTC/ETH (znana po zamknieciu swiecy 4h)."""
    out = dict(dane or {})
    for sym, b in (('BTCUSDT', basis_btc), ('ETHUSDT', basis_eth)):
        if sym in out and b is not None and len(b):
            out[sym] = pd.merge_asof(out[sym].sort_values('t'), b.sort_values('t'), on='t', direction='backward', tolerance=6 * HOUR_MS)
    return out


_V239 = {'btcd': None, 'cbp_teraz': None, 'alt_teraz': None, 'zrodlo': None}


def _v239_coinbase_1h(prod, start_ms, end_ms):
    """Swiece 1h Coinbase Exchange (publiczne, max 300/zapytanie) -> DataFrame(t, close)."""
    out, end = [], int(end_ms)
    while end > start_ms:
        st = max(int(start_ms), end - 300 * HOUR_MS)
        r = requests.get(f'https://api.exchange.coinbase.com/products/{prod}/candles',
                         params={'granularity': 3600, 'start': iso(st), 'end': iso(end)}, timeout=15,
                         headers={'User-Agent': 'weex-kolektor'})
        if r.status_code != 200:
            raise ValueError(f'coinbase {r.status_code}: {r.text[:100]}')
        d = r.json()
        if not d:
            break
        out += [(int(x[0]) * 1000, float(x[4])) for x in d]
        end = st
    df = pd.DataFrame(out, columns=['t', 'close']).drop_duplicates('t').sort_values('t')
    return df[(df.t >= start_ms) & (df.t < end_ms)].reset_index(drop=True)


def coinbase_premium_v239(now_ms, drive_ok):
    """Premium % = Coinbase BTC-USD / Binance spot BTCUSDT - 1 (1h). Cache dobowy + ogon 2 dni przy kazdym uruchomieniu."""
    plik = (Path(DRIVE_DIR) if drive_ok else OUT_ROOT / 'weex_cache') / 'coinbase_premium_v239.csv'
    start = now_ms - POZ_DNI * DAY_MS
    dzien = int(now_ms // DAY_MS)
    stary = None
    if plik.is_file():
        try:
            stary = pd.read_csv(plik)
        except Exception:
            stary = None
    if REPLAY_ZIP:
        return stary if stary is not None else pd.DataFrame(columns=['t', 'premium_pct'])
    od = start if (stary is None or not len(stary) or int(stary.t.min()) > start + DAY_MS) else now_ms - 2 * DAY_MS
    cb = _v239_coinbase_1h('BTC-USD', od, now_ms)
    bn = pd.DataFrame(hist_fetch('binance', 'BTCUSDT', '1h', od, now_ms))
    if not len(bn) or not len(cb):
        return stary if stary is not None else pd.DataFrame(columns=['t', 'premium_pct'])
    bn = pd.DataFrame({'t': bn[0].astype(float).astype('int64'), 'bn': bn[4].astype(float)})
    m = cb.merge(bn, on='t')
    nowy = pd.DataFrame({'t': m.t, 'premium_pct': (m.close / m.bn - 1) * 100})
    d = pd.concat([stary, nowy], ignore_index=True) if stary is not None else nowy
    d = d.drop_duplicates('t', keep='last').sort_values('t')
    d = d[d.t >= start].reset_index(drop=True)
    try:
        plik.parent.mkdir(parents=True, exist_ok=True)
        d.to_csv(plik, index=False)
    except Exception:
        pass
    return d


def alt_btc_v239(c4):
    """Indeks ALT/BTC (4h): skumulowana srednia logzwrotow altow minus logzwrot BTC. Rosnie = alty silniejsze (dominacja BTC spada)."""
    b = (c4 or {}).get('BTCUSDT')
    if b is None or len(b) < 50:
        return pd.DataFrame(columns=['t', 'alt_idx'])
    bt = pd.Series(np.log(b[:, C]), index=b[:, T].astype('int64')).diff()
    rr = []
    for k, a in (c4 or {}).items():
        if k == 'BTCUSDT' or a is None or len(a) < 50:
            continue
        rr.append(pd.Series(np.log(a[:, C]), index=a[:, T].astype('int64')).diff())
    if not rr:
        return pd.DataFrame(columns=['t', 'alt_idx'])
    alt = pd.concat(rr, axis=1).mean(axis=1)
    x = (alt - bt.reindex(alt.index)).fillna(0).cumsum()
    return pd.DataFrame({'t': x.index + 4 * HOUR_MS, 'alt_idx': x.values})      # chwila zamkniecia swiecy 4h


def btc_dominacja_v239():
    """BTC.D z CoinGecko /global (tylko biezaco)."""
    try:
        r = requests.get('https://api.coingecko.com/api/v3/global', timeout=10, headers={'User-Agent': 'weex-kolektor'})
        return rnd(float(r.json()['data']['market_cap_percentage']['btc']), 2) if r.status_code == 200 else None
    except Exception:
        return None


def szerokosc_dywergencja_v240(c4, okno=30, prog=0.30):
    """V6.240: +1 gdy BTC zamyka pod minimum 30 swiec 4h, a < prog altow robi to samo (wyczerpanie spadku); -1 lustrzanie."""
    b = (c4 or {}).get('BTCUSDT')
    if b is None or len(b) < okno + 10:
        return pd.DataFrame(columns=['t', 'szer_div'])
    def flagi(a):
        c = pd.Series(a[:, C], index=a[:, T].astype('int64'))
        lo, hi = c.shift(1).rolling(okno).min(), c.shift(1).rolling(okno).max()
        return (c < lo).astype(float), (c > hi).astype(float)
    blo, bhi = flagi(b)
    alo, ahi = [], []
    for k, a in (c4 or {}).items():
        if k != 'BTCUSDT' and a is not None and len(a) > okno + 10:
            x, y = flagi(a); alo.append(x); ahi.append(y)
    if not alo:
        return pd.DataFrame(columns=['t', 'szer_div'])
    flo, fhi = pd.concat(alo, axis=1).mean(axis=1), pd.concat(ahi, axis=1).mean(axis=1)
    idx = blo.index
    sig = np.where((blo == 1) & (flo.reindex(idx) < prog), 1, np.where((bhi == 1) & (fhi.reindex(idx) < prog), -1, 0))
    return pd.DataFrame({'t': idx + 4 * HOUR_MS, 'szer_div': sig})


def dvol_v240(now_ms, drive_ok):
    """V6.240: indeks zmiennosci Deribit DVOL (BTC), 1h, ~POZ_DNI dni. Cache + ogon 2 dni."""
    plik = (Path(DRIVE_DIR) if drive_ok else OUT_ROOT / 'weex_cache') / 'dvol_v240.csv'
    start = now_ms - POZ_DNI * DAY_MS
    stary = None
    if plik.is_file():
        try:
            stary = pd.read_csv(plik)
        except Exception:
            stary = None
    if REPLAY_ZIP:
        return stary if stary is not None else pd.DataFrame(columns=['t', 'dvol'])
    od = start if (stary is None or not len(stary) or int(stary.t.min()) > start + DAY_MS) else now_ms - 2 * DAY_MS
    out, end = [], int(now_ms)
    for _ in range(30):
        r = requests.get('https://www.deribit.com/api/v2/public/get_volatility_index_data',
                         params={'currency': 'BTC', 'start_timestamp': int(od), 'end_timestamp': end, 'resolution': 3600}, timeout=15)
        d = (r.json() or {}).get('result') or {}
        rows = d.get('data') or []
        out += [(int(x[0]), float(x[4])) for x in rows]
        cont = d.get('continuation')
        if not rows or not cont or int(cont) <= od:
            break
        end = int(cont)
    nowy = pd.DataFrame(out, columns=['t', 'dvol'])
    dd = pd.concat([stary, nowy], ignore_index=True) if stary is not None else nowy
    dd = dd.drop_duplicates('t', keep='last').sort_values('t')
    dd = dd[dd.t >= start].reset_index(drop=True)
    try:
        plik.parent.mkdir(parents=True, exist_ok=True)
        dd.to_csv(plik, index=False)
    except Exception:
        pass
    return dd


def _v239_dolacz(dane, cbp, altidx, szer=None, dvol=None):
    """Dokleja premium (srednia 4h) i indeks ALT/BTC do danych pozycjonowania (merge_asof wstecz po czasie)."""
    out = {}
    cb4 = None
    if cbp is not None and len(cbp):
        cb4 = cbp.sort_values('t').assign(cbp=lambda x: x.premium_pct.rolling(4, min_periods=2).mean())[['t', 'cbp']]
        cb4['t'] = cb4.t + HOUR_MS                       # znane po zamknieciu swiecy 1h
    for sym, df in (dane or {}).items():
        d = df.sort_values('t')
        if cb4 is not None:
            d = pd.merge_asof(d, cb4, on='t', direction='backward', tolerance=6 * HOUR_MS)
        if altidx is not None and len(altidx):
            d = pd.merge_asof(d, altidx.sort_values('t'), on='t', direction='backward', tolerance=8 * HOUR_MS)
        if szer is not None and len(szer):                 # V6.240
            d = pd.merge_asof(d, szer.sort_values('t'), on='t', direction='backward', tolerance=8 * HOUR_MS)
        if dvol is not None and len(dvol):
            dv = dvol.sort_values('t').assign(t=lambda x: x.t + HOUR_MS)
            d = pd.merge_asof(d, dv, on='t', direction='backward', tolerance=6 * HOUR_MS)
        out[sym] = d
    return out


def _v230_cechy(df):
    """z-score L/S i fundingu wzgledem 30 dni (180 swiec 4h), zmiana OI 24h (%)."""
    d = df.copy()
    for k in ('ls', 'fund'):
        x = pd.to_numeric(d[k], errors='coerce')
        m, sd = x.rolling(180, min_periods=60).mean(), x.rolling(180, min_periods=60).std()
        d[f'{k}_z'] = (x - m) / sd
    oi = pd.to_numeric(d['oi'], errors='coerce')
    d['oi_24h'] = (oi / oi.shift(6) - 1) * 100
    if 'cbp' in d.columns:                               # V6.239: Coinbase premium
        x = pd.to_numeric(d['cbp'], errors='coerce')
        d['cbp_z'] = (x - x.rolling(180, min_periods=60).mean()) / x.rolling(180, min_periods=60).std()
    if 'fund_z' in d.columns:                            # V6.240: reset fundingu (stan 24h temu)
        d['fund_z_24h_temu'] = d['fund_z'].shift(6)
    if 'dvol' in d.columns:                              # V6.240: zmiana DVOL 24h (z-score)
        x = pd.to_numeric(d['dvol'], errors='coerce').diff(6)
        d['dvol_z'] = (x - x.rolling(180, min_periods=60).mean()) / x.rolling(180, min_periods=60).std()
    for k in ('taker', 'basis'):                         # V6.252
        if k in d.columns:
            x = pd.to_numeric(d[k], errors='coerce')
            if k == 'taker':
                x = np.log(x.where(x > 0))
            d[f'{k}_z'] = (x - x.rolling(180, min_periods=60).mean()) / x.rolling(180, min_periods=60).std()
    if 'alt_idx' in d.columns:                           # V6.239: ALT/BTC 24h
        x = pd.to_numeric(d['alt_idx'], errors='coerce').diff(6)
        d['alt_24h'] = x * 100
        d['alt_z'] = (x - x.rolling(180, min_periods=60).mean()) / x.rolling(180, min_periods=60).std()
    for k in ('top', 'liq_long', 'liq_short'):            # V6.231: Gate
        if k in d.columns:
            x = pd.to_numeric(d[k], errors='coerce')
            if k != 'top':
                x = np.log1p(x.clip(lower=0))
            m, sd = x.rolling(180, min_periods=60).mean(), x.rolling(180, min_periods=60).std()
            d[f'{k}_z'] = (x - m) / sd
    if 'top_z' in d.columns:                             # V6.259: zmiany 24h i nierownowaga likwidacji 24h
        d['top_z_d24'] = d['top_z'] - d['top_z'].shift(6)
    if 'ls_z' in d.columns:
        d['ls_z_d24'] = d['ls_z'] - d['ls_z'].shift(6)
    if 'cvd_buy' in d.columns and 'cvd_sell' in d.columns:   # V6.274: CVD 24h (udzial netto kupna), z-score
        b_, s_ = pd.to_numeric(d['cvd_buy'], errors='coerce'), pd.to_numeric(d['cvd_sell'], errors='coerce')
        x = (b_ - s_).rolling(6).sum() / (b_ + s_).rolling(6).sum()
        d['cvd_z'] = (x - x.rolling(180, min_periods=60).mean()) / x.rolling(180, min_periods=60).std()
    if 'spot_buy' in d.columns and 'spot_sell' in d.columns:   # V6.282: CVD spot 24h
        b_, s_ = pd.to_numeric(d['spot_buy'], errors='coerce'), pd.to_numeric(d['spot_sell'], errors='coerce')
        x = (b_ - s_).rolling(6).sum() / (b_ + s_).rolling(6).sum()
        d['spot_cvd_z'] = (x - x.rolling(180, min_periods=60).mean()) / x.rolling(180, min_periods=60).std()
    if 'ob_bid' in d.columns and 'ob_ask' in d.columns:
        b_, a_ = pd.to_numeric(d['ob_bid'], errors='coerce'), pd.to_numeric(d['ob_ask'], errors='coerce')
        x = np.log(b_.where(b_ > 0) / a_.where(a_ > 0))
        d['ob_z'] = (x - x.rolling(180, min_periods=60).mean()) / x.rolling(180, min_periods=60).std()
    if 'liq_long' in d.columns and 'liq_short' in d.columns:
        ll_, ls__ = pd.to_numeric(d['liq_long'], errors='coerce').rolling(6).sum(), pd.to_numeric(d['liq_short'], errors='coerce').rolling(6).sum()
        tot = ll_ + ls__
        d['liq_imb24'] = ((ls__ - ll_) / tot).where(tot > tot.rolling(180, min_periods=60).median())
    return d


def _v230_sygnaly(r):
    """Sygnaly kontra (kierunek ceny: +1 / -1 / 0) z jednego wiersza cech."""
    out = {}
    lz, fz, oi, ch = r.get('ls_z'), r.get('fund_z'), r.get('oi_24h'), r.get('ch24')
    ok = lambda v: v is not None and v == v
    out['L/S skrajny (kontra)'] = (-1 if lz > POZ_Z_PROG else 1 if lz < -POZ_Z_PROG else 0) if ok(lz) else 0
    out['funding skrajny (kontra)'] = (-1 if fz > POZ_Z_PROG else 1 if fz < -POZ_Z_PROG else 0) if ok(fz) else 0
    if ok(oi) and ok(ch):                                   # nowe pozycje w strone ruchu = tlum goni -> kontra
        out['OI rosnie z ruchem (kontra)'] = (-1 if ch > 2 else 1 if ch < -2 else 0) if oi > 3 else 0
    else:
        out['OI rosnie z ruchem (kontra)'] = 0
    ll, ls_, tz = r.get('liq_long_z'), r.get('liq_short_z'), r.get('top_z')   # V6.231
    if ok(ll) and ok(ls_):
        out['likwidacje skrajne (odbicie)'] = 1 if (ll > 2 and ll - ls_ > 1) else -1 if (ls_ > 2 and ls_ - ll > 1) else 0
        out['likwidacje skrajne (kaskada, w strone)'] = -out['likwidacje skrajne (odbicie)']   # V6.232
    if ok(tz):
        out['top traderzy (za nimi)'] = 1 if tz > POZ_Z_PROG else -1 if tz < -POZ_Z_PROG else 0
        if ok(lz):                                          # V6.232: top traderzy i tlum w przeciwne strony
            out['top vs tlum (za top)'] = 1 if (tz > 1 and lz < -1) else -1 if (tz < -1 and lz > 1) else 0
    ch, oi24 = r.get('ch24'), r.get('oi_24h')               # V6.240: sygnaly zwrotu
    if ok(oi24) and ok(ch):
        out['kapitulacja OI (kontra)'] = (1 if ch < -3 else -1 if ch > 3 else 0) if oi24 < -5 else 0
    f0, f24 = r.get('fund_z'), r.get('fund_z_24h_temu')
    if ok(f0) and ok(f24) and ok(ch):
        out['reset fundingu (kontra)'] = 1 if (f24 > POZ_Z_PROG and f0 < 0 and ch < 0) else -1 if (f24 < -POZ_Z_PROG and f0 > 0 and ch > 0) else 0
    sd_ = r.get('szer_div')
    if ok(sd_):
        out['dywergencja szerokosci (zwrot)'] = int(sd_)
    dz = r.get('dvol_z')
    if ok(dz) and ok(ch):
        out['DVOL skok (panika = zwrot)'] = (1 if ch < -2 else -1 if ch > 2 else 0) if dz > 2 else 0
    td, ld, li = r.get('top_z_d24'), r.get('ls_z_d24'), r.get('liq_imb24')   # V6.259
    if ok(td):
        out['top traderzy zmiana 24h (za nimi)'] = 1 if td > 1.5 else -1 if td < -1.5 else 0
    if ok(ld):
        out['tlum zmiana 24h (kontra)'] = -1 if ld > 1.5 else 1 if ld < -1.5 else 0
    if ok(li):
        out['likwidacje 24h nierownowaga (w strone)'] = 1 if li > 0.6 else -1 if li < -0.6 else 0
    tk, bz = r.get('taker_z'), r.get('basis_z')               # V6.252
    if ok(tk):
        out['agresja taker Gate (za agresorem)'] = 1 if tk > POZ_Z_PROG else -1 if tk < -POZ_Z_PROG else 0
    if ok(bz):
        out['premia kwartalna skrajna (kontra)'] = -1 if bz > 2 else 1 if bz < -2 else 0
        out['premia kwartalna rosnie (za nia)'] = 1 if bz > POZ_Z_PROG else -1 if bz < -POZ_Z_PROG else 0
    cz, az = r.get('cbp_z'), r.get('alt_z')                  # V6.239
    if ok(cz):
        out['Coinbase premium (za nim)'] = 1 if cz > POZ_Z_PROG else -1 if cz < -POZ_Z_PROG else 0
    if ok(az) and r.get('_sym') not in (None, 'BTCUSDT'):
        out['alty vs BTC 24h (za nimi)'] = 1 if az > POZ_Z_PROG else -1 if az < -POZ_Z_PROG else 0
        out['alty vs BTC 24h (kontra)'] = -out['alty vs BTC 24h (za nimi)']
    cv, obz, mp = r.get('cvd_z'), r.get('ob_z'), r.get('mapa_imb')   # V6.274
    sz = r.get('spot_cvd_z')                                  # V6.282: spot vs futures
    if ok(sz):
        out['CVD spot 24h (za nim)'] = 1 if sz > POZ_Z_PROG else -1 if sz < -POZ_Z_PROG else 0
        if ok(cv):
            out['rozjazd futures vs spot (za spotem)'] = 1 if (sz > 1 and cv < -1) else -1 if (sz < -1 and cv > 1) else 0
            out['spot i futures zgodne (za nimi)'] = 1 if (sz > 1 and cv > 1) else -1 if (sz < -1 and cv < -1) else 0
    if ok(cv):
        out['CVD 24h (za nim)'] = 1 if cv > POZ_Z_PROG else -1 if cv < -POZ_Z_PROG else 0
        if ok(ch):
            out['dywergencja CVD (kontra ruchu)'] = -1 if (ch > 2 and cv < -1) else 1 if (ch < -2 and cv > 1) else 0
    if ok(obz):
        out['arkusz bid/ask (za przewaga)'] = 1 if obz > POZ_Z_PROG else -1 if obz < -POZ_Z_PROG else 0
    if ok(mp):
        out['mapa likwidacji (magnes)'] = 1 if mp > MAPA_PROG else -1 if mp < -MAPA_PROG else 0
        out['mapa likwidacji (od wiekszego skupiska)'] = -out['mapa likwidacji (magnes)']   # wariant odwrotny - test rozstrzygnie
    razem = sum(v for k, v in out.items() if k in ('L/S skrajny (kontra)', 'funding skrajny (kontra)', 'OI rosnie z ruchem (kontra)'))
    out['razem (>=2 zgodne)'] = (1 if razem >= 2 else -1 if razem <= -2 else 0)
    return out


MAPA_DZWIGNIE = ((25, 0.4), (50, 0.35), (100, 0.25))   # V6.274: udzial nowych pozycji wg dzwigni
MAPA_PASMO = 0.06                # skupiska liczone w pasmie +-6% od ceny
MAPA_PROG = 0.3                  # nierownowaga (nad - pod) / (nad + pod) dla sygnalu
MAPA_ZANIK = 0.995               # zanik starych pozycji na swiece 4h (~5% tygodniowo)
_V274 = {'mapa': {}}


def mapa_likwidacji_v274(df, a):
    """Przyblizona mapa likwidacji z OI i swiec 4h. Dla kazdego wiersza df (czas t = zamkniecie swiecy) kolumny:
    mapa_imb (nierownowaga nad/pod cena w pasmie), mapa_nad / mapa_pod (poziom najwiekszego skupiska), mapa_nad_usd / mapa_pod_usd."""
    if df is None or a is None or not len(df) or 'oi' not in df.columns or len(a) < 30:
        return df
    d = df.sort_values('t').reset_index(drop=True).copy()
    tt = a[:, T].astype('int64')
    oi = pd.to_numeric(d['oi'], errors='coerce').values
    lv = np.zeros(0); am = np.zeros(0); sd = np.zeros(0, dtype=int)   # poziom, kwota, strona (+1 short liq nad cena, -1 long liq pod)
    imb, nad, pod, nad_u, pod_u = [np.full(len(d), np.nan) for _ in range(5)]
    prev = None
    for j, t in enumerate(d['t'].astype('int64').values):
        i = int(np.searchsorted(tt, t - 4 * HOUR_MS))
        if i >= len(tt) or tt[i] != t - 4 * HOUR_MS or not (oi[j] == oi[j]):
            continue
        hi, lo, cl = a[i, H], a[i, L], a[i, C]
        if len(lv):                                            # przejscie ceny kasuje skupiska
            zyw = ~(((sd == 1) & (lv <= hi)) | ((sd == -1) & (lv >= lo)))
            lv, am, sd = lv[zyw], am[zyw] * MAPA_ZANIK, sd[zyw]
        if prev is not None and prev > 0:
            dz = oi[j] - prev
            if dz > 0:
                p0 = (hi + lo + cl) / 3
                for lev, w in MAPA_DZWIGNIE:
                    lv = np.r_[lv, p0 * (1 + 1 / lev), p0 * (1 - 1 / lev)]
                    am = np.r_[am, dz * w / 2, dz * w / 2]
                    sd = np.r_[sd, 1, -1]
            elif dz < 0 and am.sum() > 0:
                am = am * max(0.0, 1 + dz / prev)
        prev = oi[j]
        if len(lv):
            mn = (sd == 1) & (lv > cl) & (lv <= cl * (1 + MAPA_PASMO))
            mp = (sd == -1) & (lv < cl) & (lv >= cl * (1 - MAPA_PASMO))
            u, l_ = am[mn].sum(), am[mp].sum()
            if u + l_ > 0:
                imb[j] = (u - l_) / (u + l_)
            for msk, out_l, out_u in ((mn, nad, nad_u), (mp, pod, pod_u)):
                if msk.any():
                    b = np.round(lv[msk] / (cl * 0.0025))             # koszyki 0.25%
                    s_ = pd.Series(am[msk]).groupby(b).sum()
                    out_l[j] = float(s_.idxmax() * cl * 0.0025); out_u[j] = float(s_.max())
    d['mapa_imb'], d['mapa_nad'], d['mapa_pod'], d['mapa_nad_oi'], d['mapa_pod_oi'] = imb, nad, pod, nad_u, pod_u
    return d


MODEL_CECHY = ('ls_z', 'top_z', 'fund_z', 'oi_24h', 'liq_long_z', 'liq_short_z', 'cbp_z', 'alt_z', 'dvol_z', 'szer_div', 'ch24', 'trend', 'cvd_z', 'spot_cvd_z')   # V6.282: + spot   # V6.275: + CVD
MODEL_PROG = 0.05                # pewne prognozy: |p - 0.5| >= tyle
_V241 = {'wynik': None, 'teraz': {}}


def _v241_wiersze(dane, ceny4h):
    """Cechy w chwili t (tylko przeszlosc) + cel: ruch ceny w 24h. Ostatni wiersz kazdego symbolu bez celu (prognoza)."""
    rows = []
    for sym, df in (dane or {}).items():
        a = (ceny4h or {}).get(sym)
        if a is None or not len(df):
            continue
        d = _v230_cechy(df)
        tt, cc = a[:, T], a[:, C]
        ema = pd.Series(cc).ewm(span=50, adjust=False).mean().values
        for r in d.to_dict('records'):
            i = int(np.searchsorted(tt, r['t'] - 4 * HOUR_MS))
            if i < 50 or i >= len(cc) or abs(tt[i] + 4 * HOUR_MS - r['t']) > 4 * HOUR_MS:
                continue
            x = {k: r.get(k) for k in MODEL_CECHY}
            x['ch24'] = (cc[i] / cc[i - 6] - 1) * 100
            x['trend'] = 1.0 if cc[i] > ema[i] else -1.0
            if sym == 'BTCUSDT':
                x['alt_z'] = np.nan                         # sygnal altow nie dotyczy BTC
            x.update(symbol=sym, t=int(r['t']), cena=float(cc[i]),
                     r24=((cc[i + 6] / cc[i] - 1) * 1e4) if i + 6 < len(cc) else np.nan)
            rows.append(x)
    return pd.DataFrame(rows)


def _v241_macierz(df, mu=None, sd=None):
    X = df[list(MODEL_CECHY)].apply(pd.to_numeric, errors='coerce').astype(float)
    X['oi_24h'] = X['oi_24h'] / 5.0
    X['ch24'] = X['ch24'] / 3.0
    if mu is None:
        mu, sd = X.mean(), X.std().replace(0, 1).fillna(1)
    Z = ((X - mu) / sd).fillna(0.0).clip(-4, 4)
    return np.c_[np.ones(len(Z)), Z.values], mu, sd


def _v241_fit(X, y, l2=2.0, it=400, lr=0.1):
    w = np.zeros(X.shape[1])
    for _ in range(it):
        p = 1 / (1 + np.exp(-X @ w))
        g = X.T @ (p - y) / len(y) + l2 * np.r_[0, w[1:]] / len(y)
        w -= lr * g
    return w


def model_kierunku_v241(dane, ceny4h, folds=5):
    """Walk-forward: okresy po czasie; trening na wszystkim wczesniej (przerwa 24h), test na nastepnym okresie."""
    df = _v241_wiersze(dane, ceny4h)
    if not len(df):
        return None, {}
    hist = df[df.r24.notna()].sort_values('t').reset_index(drop=True)
    if len(hist) < 300:
        return {'n': len(hist), 'werdykt': 'ZA_MALO_DANYCH'}, {}
    granice = hist.t.quantile(np.linspace(0, 1, folds + 1)).values
    oos, okresy = [], []
    for k in range(1, folds):
        tr = hist[hist.t < granice[k] - 24 * HOUR_MS]
        te = hist[(hist.t >= granice[k]) & (hist.t < granice[k + 1] if k + 1 < folds else hist.t <= granice[-1])]
        if len(tr) < 200 or not len(te):
            continue
        Xtr, mu, sd = _v241_macierz(tr)
        w = _v241_fit(Xtr, (tr.r24 > 0).astype(float).values)
        Xte, _, _ = _v241_macierz(te, mu, sd)
        p = 1 / (1 + np.exp(-Xte @ w))
        te = te.assign(p=p)
        pew = te[(te.p - 0.5).abs() >= MODEL_PROG]
        kier = np.sign(pew.p - 0.5)
        okresy.append({'okres': k, 'n': len(te), 'pewne': len(pew),
                       'traf_pewne': rnd(float(((kier * pew.r24) > 0).mean() * 100), 1) if len(pew) else None,
                       'sr_bps_pewne': rnd(float((kier * pew.r24).mean()), 1) if len(pew) else None})
        oos.append(te)
    if not oos:
        return {'n': len(hist), 'werdykt': 'ZA_MALO_DANYCH'}, {}
    o = pd.concat(oos)
    try:                                                   # V6.272: prognozy OOS BTC do testu w sekcji 11
        ob = o[o.symbol == 'BTCUSDT'][['t', 'p']].copy()
        ob['model kierunku BTC 24h (za nim)'] = np.where(ob.p >= 0.5 + MODEL_PROG, 1, np.where(ob.p <= 0.5 - MODEL_PROG, -1, 0))
        _V241['oos_btc'] = ob[['t', 'model kierunku BTC 24h (za nim)']].astype('int64')
    except Exception:
        _V241['oos_btc'] = None
    pew = o[(o.p - 0.5).abs() >= MODEL_PROG]
    kier = np.sign(pew.p - 0.5)
    kal = []
    for lo, hi in ((0, .4), (.4, .45), (.45, .55), (.55, .6), (.6, 1.01)):
        x = o[(o.p >= lo) & (o.p < hi)]
        if len(x):
            kal.append(f"{lo:.2f}-{min(hi, 1):.2f}: n={len(x)} wzrost {((x.r24 > 0).mean() * 100):.0f}%")
    dobre = sum(1 for z in okresy if (z['traf_pewne'] or 0) > 52 and (z['sr_bps_pewne'] or 0) > 0)
    wyn = {'n': len(hist), 'oos_n': len(o), 'pewne_n': len(pew),
           'traf_pewne': rnd(float(((kier * pew.r24) > 0).mean() * 100), 1) if len(pew) else None,
           'sr_bps_pewne': rnd(float((kier * pew.r24).mean()), 1) if len(pew) else None,
           'BTC_ETH_traf': rnd(float(((kier * pew.r24) > 0)[pew.symbol.isin(['BTCUSDT', 'ETHUSDT'])].mean() * 100), 1) if len(pew) else None,
           'okresy': okresy, 'kalibracja': kal,
           'werdykt': 'DZIALA' if (len(okresy) >= 3 and dobre >= len(okresy) - 1 and (pew.r24 * kier).mean() > 0) else 'NIEPOTWIERDZONY'}
    Xall, mu, sd = _v241_macierz(hist)
    w = _v241_fit(Xall, (hist.r24 > 0).astype(float).values)
    wyn['wagi'] = {k: rnd(float(v), 3) for k, v in zip(('stala',) + MODEL_CECHY, w)}
    teraz = {}
    for sym, x in df.sort_values('t').groupby('symbol'):
        X1, _, _ = _v241_macierz(x.tail(1), mu, sd)
        teraz[sym] = rnd(float(1 / (1 + np.exp(-X1 @ w))[0]), 3)
    return wyn, teraz


def badanie_pozycji_v230(dane, ceny4h):
    """Trafnosc i sredni ruch (bps) po 12h/24h w strone sygnalu, w trzech tercjach okresu."""
    rows = []
    for sym, df in (dane or {}).items():
        a = (ceny4h or {}).get(sym)
        if a is None or not len(df):
            continue
        d = _v230_cechy(df)
        tt, cc = a[:, T], a[:, C]
        for r in d.to_dict('records'):
            i = int(np.searchsorted(tt, r['t'] - 4 * HOUR_MS))      # swieca 4h zamknieta w chwili t
            if i < 6 or i + 6 >= len(cc) or abs(tt[i] + 4 * HOUR_MS - r['t']) > 4 * HOUR_MS:
                continue
            r['ch24'] = (cc[i] / cc[i - 6] - 1) * 100
            r['_sym'] = sym                                 # V6.239
            for nm, kier in _v230_sygnaly(r).items():
                if kier:
                    rows.append({'sygnal': nm, 'symbol': sym, 't': r['t'], 'kier': kier,
                                 'r24_op': kier * (cc[i + 7] / cc[i + 1] - 1) * 1e4 if i + 7 < len(cc) else np.nan,   # V6.292: wejscie swiece pozniej
                                 'r12': kier * (cc[i + 3] / cc[i] - 1) * 1e4, 'r24': kier * (cc[i + 6] / cc[i] - 1) * 1e4,
                                 'r48': kier * (cc[i + 12] / cc[i] - 1) * 1e4 if i + 12 < len(cc) else np.nan})   # V6.259
    df = pd.DataFrame(rows)
    if not len(df):
        return []
    q = df.t.quantile([1 / 3, 2 / 3]).values
    df['tercja'] = np.where(df.t < q[0], 1, np.where(df.t < q[1], 2, 3))
    out = []
    for nm, x in df.groupby('sygnal'):
        tr = x.groupby('tercja').r24.mean()
        tst, neff = _v292_t(x, 'r24')                      # V6.292
        op = x.r24_op.mean() if 'r24_op' in x else np.nan
        out.append({'sygnal': nm, 'n': len(x), 't_24h': tst, 'n_niezal': neff, 'sr_24h_op_bps': rnd(op, 1) if op == op else None, 'traf_12h_pct': rnd((x.r12 > 0).mean() * 100, 1), 'sr_12h_bps': rnd(x.r12.mean(), 1),
                    'traf_24h_pct': rnd((x.r24 > 0).mean() * 100, 1), 'sr_24h_bps': rnd(x.r24.mean(), 1),
                    't1_24h_bps': rnd(tr.get(1), 1), 't2_24h_bps': rnd(tr.get(2), 1), 't3_24h_bps': rnd(tr.get(3), 1),
                    'BTC_ETH_traf_24h_pct': rnd((x[x.symbol.isin(['BTCUSDT', 'ETHUSDT'])].r24 > 0).mean() * 100, 1),
                    'traf_48h_pct': rnd((x.r48.dropna() > 0).mean() * 100, 1) if 'r48' in x and x.r48.notna().any() else None,   # V6.259
                    'sr_48h_bps': rnd(x.r48.mean(), 1) if 'r48' in x and x.r48.notna().any() else None,
                    'wniosek': (lambda w_: 'DZIALA (tercje +, trafnosc > 52%, BTC/ETH > 50%)' if w_ == 'DZIALA' else w_)(
                        _v247_werdykt([tr.get(k) for k in (1, 2, 3)], rnd((x.r24 > 0).mean() * 100, 1),
                                      rnd((x[x.symbol.isin(['BTCUSDT', 'ETHUSDT'])].r24 > 0).mean() * 100, 1),
                                      int(x.symbol.isin(['BTCUSDT', 'ETHUSDT']).sum())))})
        w = out[-1]                                        # V6.292: wyciek i istotnosc
        if str(w['wniosek']).startswith('DZIALA'):
            if w['sr_24h_bps'] and w['sr_24h_op_bps'] is not None and w['sr_24h_bps'] > 20 and w['sr_24h_op_bps'] < 0.3 * w['sr_24h_bps']:
                w['wniosek'] = f"PODEJRZANY WYCIEK (opoznienie 4h: {w['sr_24h_op_bps']} vs {w['sr_24h_bps']} bps)"
            elif tst is None or tst < DZ_T_MIN:
                w['wniosek'] = f"tylko srednia (t {tst} < {DZ_T_MIN})"
    return out


DZ_T_MIN = 2.0                   # V6.292: min. t-statystyka (niezalezne zdarzenia: symbol x dzien)


def audyt_danych_v292(dpz, now_ms):
    """Swiezosc i kompletnosc danych pozycjonowania (po przesunieciu czasu: t = zamkniecie swiecy)."""
    out = []
    for sym, d in sorted((dpz or {}).items()):
        if d is None or not len(d):
            out.append({'symbol': sym, 'wiersze': 0, 'status': 'BRAK DANYCH'})
            continue
        t = pd.to_numeric(d.t, errors='coerce').dropna().astype('int64').sort_values()
        kroki = t.diff().dropna()
        wiek = (int(now_ms) - int(t.iloc[-1])) / HOUR_MS
        braki = {k: rnd(float(pd.to_numeric(d[k], errors='coerce').tail(42).isna().mean() * 100), 0)
                 for k in ('ls', 'top', 'oi', 'fund', 'liq_long', 'liq_short', 'cvd_buy', 'spot_buy') if k in d.columns}
        st = 'OK' if wiek <= 4.5 else 'NIESWIEZE' if wiek <= 12 else 'STARE'
        if any(v and v >= 50 for v in braki.values()):
            st += ' + BRAKI'
        out.append({'symbol': sym, 'wiersze': len(d), 'wiek_h': rnd(wiek, 1), 'luki': int((kroki > 4 * HOUR_MS).sum()),
                    'duplikaty': int(t.duplicated().sum()), 'braki_7d_pct': braki, 'status': st})
    return out


def _v292_t(x, kol):
    """t-statystyka sredniej na zdarzeniach zgrupowanych (symbol, dzien) - nakladajace sie zdarzenia licza sie raz."""
    try:
        g = x.assign(_d=(pd.to_numeric(x.t) // DAY_MS)).groupby(['symbol', '_d'])[kol].mean().dropna()
        if len(g) < 5 or not g.std() > 0:
            return None, len(g)
        return rnd(float(g.mean() / (g.std() / np.sqrt(len(g)))), 2), len(g)
    except Exception:
        return None, 0


def pozycje_teraz_v230(dane, PP):
    """Biezace pozycjonowanie BTC/ETH + aktywne sygnaly i prawdopodobienstwo z badania (tylko sygnaly 'DZIALA')."""
    out = {}
    bad = {b['sygnal']: b for b in _V230['badanie']}
    for sym in ('BTCUSDT', 'ETHUSDT'):
        df = (dane or {}).get(sym)
        if df is None or not len(df):
            continue
        d = _v230_cechy(df).iloc[-1].to_dict()
        P = (PP or {}).get(sym)
        if P is not None and '4h' in P.get('arr', {}):
            c4 = P['arr']['4h'][:, C]
            d['ch24'] = (c4[-1] / c4[-7] - 1) * 100 if len(c4) > 7 else None
        d['_sym'] = sym                                     # V6.239
        syg = {k: v for k, v in _v230_sygnaly(d).items() if v}
        dz = [(k, v, bad[k]) for k, v in syg.items() if k in bad and str(bad[k]['wniosek']).startswith('DZIALA')]
        if dz:
            k, v, b = max(dz, key=lambda x: x[2]['traf_24h_pct'] or 0)
            prawd = f"{'LONG' if v == 1 else 'SHORT'} {b['traf_24h_pct']}% w 24h (sygnal '{k}', n={b['n']}, sr {b['sr_24h_bps']} bps)"
            kdz = {'kier': int(v), 'p': (b['traf_24h_pct'] or 50) / 100, 'sygnal': k, 'n': b['n']}   # V6.300
        elif syg:
            prawd = 'aktywne sygnaly bez potwierdzonej przewagi: ' + ', '.join(f"{k} {'LONG' if v == 1 else 'SHORT'}" for k, v in syg.items())
        else:
            prawd = 'brak skrajnego pozycjonowania - ok. 50/50'
        out[sym] = {'kier_dz': kdz if dz else None, 'syg': syg, 'ls': rnd(d.get('ls'), 3), 'ls_z': rnd(d.get('ls_z'), 2), 'fund': d.get('fund'), 'fund_z': rnd(d.get('fund_z'), 2),
                    'oi_24h': rnd(d.get('oi_24h'), 2), 'prawdopodobienstwo': prawd,
                    'top_z': rnd(d.get('top_z'), 2), 'liq_long_usd': rnd(d.get('liq_long'), 0), 'liq_short_usd': rnd(d.get('liq_short'), 0)}
    return out


