def test_v201():
    import tempfile
    with tempfile.TemporaryDirectory() as d:
        pd.DataFrame([{'symbol': 'BANUSDT', 'side': 'SHORT', 'setup_type': 'CONT_SWEEP', 'entry': 0.05302, 'sl': 0.05381,
                       'tp1': 0.05171, 'rr_tp1_net': 1.55, 'ocena': 'C', 'ranking_status': 'OBSERWACJA', 'asset_type': 'COIN',
                       'blokady_kwalifikacji': 'tryb probny: wymaga oceny A/B (jest C)'},
                      {'symbol': 'NVDAUSDT', 'side': 'SHORT', 'setup_type': 'PULLBACK', 'entry': 204.18, 'sl': 206.05, 'tp1': 200.45,
                       'rr_tp1_net': 1.61, 'ocena': 'D', 'ranking_status': 'DOPUSZCZONY', 'asset_type': 'Stocks', 'ranking_powod': 'OK'},
                      {'symbol': 'XUSDT', 'side': 'LONG', 'setup_type': 'PULLBACK', 'entry': 1.5, 'sl': 1.4, 'tp1': 1.7,
                       'rr_tp1_net': 2, 'ocena': 'A', 'ranking_status': 'DO GRY', 'asset_type': 'COIN'}]).to_csv(Path(d) / 'top_market.csv', index=False)
        pd.DataFrame(columns=['symbol']).to_csv(Path(d) / 'top_limit.csv', index=False)
        t = '\n'.join(tabele_setupow_v201(d))
        assert '0.053020' in t and 'tryb probny: wymaga oceny A/B' in t and 'TradFi bez testu' in t and 'do gry 1' in t
        assert '204.18' in t and '(brak)' in t and t.count('(brak)') == 2      # LIMIT pusty, ELLIOTT brak pliku
    assert _v201_powod({'ranking_status': 'DOPUSZCZONY', 'status_setupu': 'DO GRY', 'asset_type': 'COIN', 'ranking_powod': 'OK'}) == 'DO GRY'
    assert _v201_powod({'ranking_status': 'DOPUSZCZONY', 'status_setupu': 'BEZ BRAMKI', 'asset_type': 'Stocks', 'ranking_powod': 'OK'}) == 'TradFi bez testu'
    t2 = _v201_tabela([{'symbol': 'XUSDT', 'ocena': 'D'}, {'symbol': 'YUSDT', 'ocena': 'B'}, {'symbol': 'ZUSDT', 'ocena': 'A'}, {'symbol': 'WUSDT', 'ocena': 'B'}])
    kol = [l.split('|')[0].strip() for l in t2[2:]]
    assert kol == ['Z', 'Y', 'W', 'X'], kol                          # V6.217: A -> D, stabilnie w obrebie oceny
    return 'PASS (format cen, powod blokady, TradFi, puste i brakujace pliki, DO GRY wg status_setupu, sortowanie A-D)'


_V202_TOP_INFO = {}


def top_setups_info_v202(top, good, market_rank, limit_rank):
    """V6.202: dlaczego top_setups.csv jest pusty (albo krotki): liczba kandydatow i najczestsze powody blokady."""
    kand = list(market_rank or []) + list(limit_rank or [])
    powody = {}
    for r in kand:
        p = _v201_powod(r)
        if p.startswith('DO GRY'):
            continue
        p = p.split(';')[0].strip()
        p = re.split(r'[:(]', p)[0].strip() or p           # grupowanie: 'tryb ochronny SHORT (-0.584R / 3d)' -> 'tryb ochronny SHORT'
        powody[p] = powody.get(p, 0) + 1
    do_gry = sum(1 for r in (top or []) if r.get('status_bramki') in ('DO GRY', 'PROBA'))
    return {'wersja': VERSION, 'top_setups_wiersze': len(top or []), 'top_setups_DO_GRY': do_gry,
            'top_setups_obserwacja': len(top or []) - do_gry, 'setupy_po_filtrach': len(good or []),
            'kandydaci_MARKET': len(market_rank or []), 'kandydaci_LIMIT': len(limit_rank or []),
            'status': ('SA_SETUPY_DO_GRY' if do_gry else 'BRAK_KANDYDATOW' if not kand and not top else 'KANDYDACI_ZABLOKOWANI'),
            'najczestsze_powody': dict(sorted(powody.items(), key=lambda kv: -kv[1])[:6]),
            'uwaga': 'top_setups.csv = setupy z przewaga w historii (status_bramki: DO GRY / PROBA / OBSERWACJA). '
                     'Kandydaci z blokadami: top_market.csv / top_limit.csv.'}


def test_v206():
    dni = [f'2026-10-{d:02d}' for d in range(1, 21)]
    b = {'WSZYSTKIE': {x: 1.0 for x in dni}}
    t1, s1 = _v206_t({x: 1.5 + (0.1 if i % 2 else -0.1) for i, x in enumerate(dni)}, b['WSZYSTKIE'], dni)
    assert t1 > 10 and s1 == 10.0                                   # staly zysk co dzien -> pewny
    t2, _ = _v206_t({x: (1 + (5 if i == 3 else 0)) for i, x in enumerate(dni)}, b['WSZYSTKIE'], dni)
    assert t2 < 2                                                   # jeden szczesliwy dzien -> szum
    assert _v206_t({}, {}, dni[:3]) == (None, None)
    dz = _v206_dzienne(pd.DataFrame({'snapshot_utc': ['2026-10-01T01:00', '2026-10-01T05:00', '2026-10-02T01:00'], 'r': [1.0, -0.5, 2.0],
                                      'typ_wersja': 'A.v1', 'side': 'LONG'}))
    assert dz['WSZYSTKIE'] == {'2026-10-01': 0.5, '2026-10-02': 2.0} and dz['A.v1 LONG']['2026-10-02'] == 2.0
    return 'PASS (t dziennych roznic, jeden szczesliwy dzien = szum, malo dni = brak t)'


def test_v204():
    g = globals(); keep = g['TP_STALE_R']
    try:
        t0 = 1_800_000_000_000
        def bars(path):
            m = np.zeros((len(path), 8))
            for i, (o, h, l, c) in enumerate(path):
                m[i, [O, H, L, C, V, QV, TB, T]] = [o, h, l, c, 1.0, 1.0, 0.5, t0 + i * 300_000]
            return m
        a5 = bars([(100, 100, 100, 100)] + [(100, 101.6, 99.9, 101.5)] + [(101.5, 103.2, 101.4, 103)] * 3)
        row = {'side': 'LONG', 'entry': 100.0, 'sl': 99.0, 'tp1': 110.0, 'wait_h': 1, 'entry_type': 'LIMIT', 'setup_type': 'PULLBACK'}
        g['TP_STALE_R'] = None; r0 = _simulate_core(a5, t0, row, (0.0, 0.0))
        g['TP_STALE_R'] = 1.5; r1 = _simulate_core(a5, t0, row, (0.0, 0.0))
        assert r1['status'] == 'TP1' and r0['status'] != 'TP1', (r0['status'], r1['status'])
        r2 = _simulate_core(a5, t0, dict(row, setup_type='ODBICIE'), (0.0, 0.0))
        assert r2['status'] != 'TP1'                       # ODBICIE: cel ze struktury bez zmian
    finally:
        g['TP_STALE_R'] = keep
    return 'PASS (staly TP w R, ODBICIE bez zmian, domyslnie wylaczony)'


def test_v202():
    i = top_setups_info_v202([], [{}], [{'ranking_status': 'OBSERWACJA', 'asset_type': 'COIN', 'blokady_kwalifikacji': 'tryb ochronny SHORT (-0.584R / 3d)'},
                                        {'ranking_status': 'DOPUSZCZONY', 'asset_type': 'Stocks', 'ranking_powod': 'OK'}],
                             [{'ranking_status': 'OBSERWACJA', 'asset_type': 'COIN', 'blokady_kwalifikacji': 'tryb ochronny SHORT (-0.6R / 3d)'}])
    assert i['status'] == 'KANDYDACI_ZABLOKOWANI' and i['kandydaci_MARKET'] == 2 and i['najczestsze_powody'] == {'tryb ochronny SHORT': 2, 'TradFi bez testu': 1}
    assert top_setups_info_v202([], [], [], [])['status'] == 'BRAK_KANDYDATOW'
    j = top_setups_info_v202([{'status_bramki': 'OBSERWACJA'}, {'status_bramki': 'DO GRY'}], [], [], [])
    assert j['top_setups_DO_GRY'] == 1 and j['top_setups_obserwacja'] == 1 and j['status'] == 'SA_SETUPY_DO_GRY'
    g = os.environ.copy()
    try:                                                   # auto-identyfikacja: marker AUTO_V202 czyszczony w nastepnym uruchomieniu
        os.environ.update(WEEX_EXECUTED_FILE='/nie/ma', WEEX_LAUNCHER_VERSION='AUTO_V202')
        _v189_synchronizuj_launcher('/nie/ma/takiego.py', [])
        assert os.environ.get('WEEX_EXECUTED_FILE') != '/nie/ma'
    finally:
        os.environ.clear(); os.environ.update(g)
    return 'PASS (kandydaci vs DO GRY, grupowanie powodow, marker AUTO_V202)'


def _v207_dodaj(r, tag):
    f0 = r.get('filtr')
    f0 = f0 if isinstance(f0, str) else ''
    if tag in f0.split(';'):
        return 0
    r['filtr'] = ';'.join(x for x in (f0, tag) if x)
    return 1


def _v207_wejscie(rows):
    """V6.207: filtry polozenia wejscia (krypto; TradFi bez zmian). Po analizie, wiec cache testu nie jest naruszony."""
    if (LIMIT_DALEKO_ATR is None and EXT_ENTRY_MAX_ATR is None and PRZEPLYW_FILTR is None and not VWAP_FILTR
            and FUNDING_TLUM_MAX is None) or not rows:
        return 0
    n = 0
    for r in rows:
        if r.get('asset_type') != 'COIN':
            continue
        try:
            d = float(r.get('dist_entry_atr'))
        except (TypeError, ValueError):
            d = None
        try:
            e = float(r.get('ext_entry_atr'))
        except (TypeError, ValueError):
            e = None
        if (LIMIT_DALEKO_ATR is not None and r.get('entry_type') == 'LIMIT' and d is not None and math.isfinite(d)
                and d > LIMIT_DALEKO_ATR):
            n += _v207_dodaj(r, 'limit_daleko')
        if EXT_ENTRY_MAX_ATR is not None and e is not None and math.isfinite(e) and e > EXT_ENTRY_MAX_ATR:
            n += _v207_dodaj(r, 'rozciagniete')
        sd = 1 if r.get('side') == 'LONG' else -1          # V6.222: filtry z wolumenu
        tb, vw = _num(r.get('taker_buy_1h_pct')), _num(r.get('vwap_d_dist_atr'))
        if PRZEPLYW_FILTR == 'KONTRA' and tb is not None and math.isfinite(tb) and ((sd == 1 and tb > 50) or (sd == -1 and tb < 50)):
            n += _v207_dodaj(r, 'przeplyw_zgodny')
        if VWAP_FILTR and vw is not None and math.isfinite(vw) and sd * vw >= 0:
            n += _v207_dodaj(r, 'zla_strona_vwap')
        fz = _num(r.get('funding_z_hist'))                  # V6.251: wejscie razem z tlumem (funding alta)
        if FUNDING_TLUM_MAX is not None and fz is not None and math.isfinite(fz) and sd * fz > FUNDING_TLUM_MAX:
            n += _v207_dodaj(r, 'z_tlumem_funding')
    return n


_V222_TAGI = ('limit_daleko', 'rozciagniete', 'przeplyw_zgodny', 'zla_strona_vwap', 'z_tlumem_funding')
_V222_KLUCZE = {'FUNDING_TLUM_MAX': 'z_tlumem_funding', 'LIMIT_DALEKO_ATR': 'limit_daleko', 'EXT_ENTRY_MAX_ATR': 'rozciagniete',
                'PRZEPLYW_FILTR': 'przeplyw_zgodny', 'VWAP_FILTR': 'zla_strona_vwap'}


def _v222_ustaw(over=None):
    """Biezace ustawienia filtrow wejscia (+ ewentualna zmiana wariantu)."""
    u = {k: globals()[k] for k in _V222_KLUCZE}
    u.update(over or {})
    return u


def _v222_baza_arch(arch):
    """Archiwum krypto rozliczone, bez typow dzis wylaczonych; filtr 'inne' = filtry z chwili zapisu BEZ filtrow wejscia
    (te liczone od nowa z cech, wiec stare i nowe wpisy oceniane jednakowo)."""
    if arch is None or not len(arch):
        return pd.DataFrame()
    a = arch[arch.status.isin(FINAL) & (arch.get('asset_type', pd.Series('COIN', index=arch.index)).fillna('COIN') == 'COIN')].copy()
    if not len(a):
        return a
    a['_inne'] = a.filtr.fillna('').astype(str).map(lambda f: ';'.join(t for t in f.split(';') if t and t not in _V222_TAGI))
    wyl = [bool(typ_wylaczony(str(r.setup_type), str(r.side), str(r.entry_type))) for r in a.itertuples()]
    a = a[(a._inne == '') & ~np.array(wyl, dtype=bool)].copy()
    a['r'] = pd.to_numeric(a.r, errors='coerce')
    return a[a.r.notna()]


def _v222_przepuszcza(df, u):
    """Maska: setup przechodzi filtry wejscia przy ustawieniach u (te same reguly co _v207_wejscie, wektorowo)."""
    idx = df.index
    col = lambda c: pd.to_numeric(df[c], errors='coerce') if c in df.columns else pd.Series(np.nan, index=idx)
    coin = df.get('asset_type', pd.Series('COIN', index=idx)).fillna('COIN').eq('COIN')
    sd = pd.Series(np.where(df.side.astype(str).eq('LONG'), 1, -1), index=idx)
    blok = pd.Series(False, index=idx)
    if u.get('LIMIT_DALEKO_ATR') is not None:
        blok |= df.entry_type.astype(str).eq('LIMIT') & (col('dist_entry_atr') > u['LIMIT_DALEKO_ATR'])
    if u.get('EXT_ENTRY_MAX_ATR') is not None:
        blok |= col('ext_entry_atr') > u['EXT_ENTRY_MAX_ATR']
    tb, vw = col('taker_buy_1h_pct'), col('vwap_d_dist_atr')
    if u.get('PRZEPLYW_FILTR') == 'KONTRA':
        blok |= ((sd == 1) & (tb > 50)) | ((sd == -1) & (tb < 50))
    if u.get('VWAP_FILTR'):
        blok |= (sd * vw) >= 0
    if u.get('FUNDING_TLUM_MAX') is not None:                # V6.251
        blok |= (sd * col('funding_z_hist')) > u['FUNDING_TLUM_MAX']
    return ~(blok & coin)


def _v222_archiwum_warianty(var_df, arch):
    """V6.222: filtry wejscia z HIST_WARIANTY ocenione tez na archiwum (te same zasady, inne dane).
    Kolumny arch_*; 'pewny_z_archiwum' = pewny w tescie 30 dni ORAZ roznica w archiwum >= 0 (gdy da sie policzyc)."""
    if var_df is None or not len(var_df):
        return var_df
    a = _v222_baza_arch(arch)
    for c in ('arch_n', 'arch_roznica_suma_R', 'arch_roznica_p1_R', 'arch_roznica_p2_R', 'arch_ok', 'pewny_z_archiwum'):
        var_df[c] = None
    if not len(a):
        return var_df
    dni = a.snapshot_utc.astype(str).str[:10]
    mid = sorted(dni.unique())[len(dni.unique()) // 2]
    p1 = dni < mid
    baza = _v222_przepuszcza(a, _v222_ustaw())
    for w, over in HIST_WARIANTY.items():
        if not over or not set(over) <= set(_V222_KLUCZE):
            continue
        war = _v222_przepuszcza(a, _v222_ustaw(over))
        d = a.r * war.astype(float) - a.r * baza.astype(float)
        m = (var_df.wariant == w) & (var_df.grupa == 'WSZYSTKIE')
        ok = bool(d.sum() >= 0)
        var_df.loc[m, 'arch_n'] = int(war.sum())
        var_df.loc[m, 'arch_roznica_suma_R'] = rnd(float(d.sum()), 2)
        var_df.loc[m, 'arch_roznica_p1_R'] = rnd(float(d[p1].sum()), 2)
        var_df.loc[m, 'arch_roznica_p2_R'] = rnd(float(d[~p1].sum()), 2)
        var_df.loc[m, 'arch_ok'] = ok
        pw = var_df.loc[m, 'pewny'] if 'pewny' in var_df.columns else pd.Series(False)
        var_df.loc[m, 'pewny_z_archiwum'] = [bool(x is True or x == 1) and ok for x in pw]
    return var_df


def _v222_zgodnosc(hist_df, arch):
    """V6.222: test 30 dni vs archiwum na wspolnym oknie. Po typach: sredni R w obu, archiwum na kontraktach z testu
    i na pozostalych, wspolne setupy (to samo zdjecie, kontrakt, typ, strona, wejscie) - skad rozjazd."""
    kol = ['grupa', 'okno_od', 'hist_n', 'hist_sr_R', 'arch_n', 'arch_sr_R', 'arch_kontrakty_testu_n', 'arch_kontrakty_testu_sr_R',
           'arch_inne_kontrakty_n', 'arch_inne_kontrakty_sr_R', 'wspolne_n', 'wspolne_hist_sr_R', 'wspolne_arch_sr_R', 'ocena', 'przyczyna']
    if hist_df is None or not len(hist_df) or arch is None or not len(arch):
        return pd.DataFrame(columns=kol)
    h = hist_df[hist_df.status.isin(FINAL) & (hist_df.filtr.fillna('') == '')].copy()
    a = _v222_baza_arch(arch)
    if len(a):
        a = a[_v222_przepuszcza(a, _v222_ustaw())]
    if not len(h) or not len(a):
        return pd.DataFrame(columns=kol)
    h['r'] = pd.to_numeric(h.r, errors='coerce')
    od = max(str(h.snapshot_utc.min()), str(a.snapshot_utc.min()))
    do = min(str(h.snapshot_utc.max()), str(a.snapshot_utc.max()))
    h = h[(h.snapshot_utc >= od) & (h.snapshot_utc <= do)]
    a = a[(a.snapshot_utc >= od) & (a.snapshot_utc <= do)]
    hs = set(h.symbol) | set(hist_df.symbol)
    a_in = a.symbol.isin(hs)
    klucz = ['snapshot_utc', 'symbol', 'typ_wersja', 'side', 'entry_type']
    sr = lambda x: rnd(float(x.mean()), 3) if len(x) else None
    out = []
    grupy = [('WSZYSTKIE', None)] + sorted({(str(t), str(sd_)) for t, sd_ in zip(pd.concat([h.typ_wersja, a.typ_wersja]), pd.concat([h.side, a.side]))})
    for g in grupy:
        if g[1] is None:
            hh, aa, nazwa = h, a, 'WSZYSTKIE'
        else:
            hh = h[(h.typ_wersja.astype(str) == g[0]) & (h.side.astype(str) == g[1])]
            aa = a[(a.typ_wersja.astype(str) == g[0]) & (a.side.astype(str) == g[1])]
            nazwa = f'{g[0]} {g[1]}'
        ain = aa[aa.symbol.isin(hs)]; aout = aa[~aa.symbol.isin(hs)]
        w = hh[klucz + ['r']].merge(aa[klucz + ['r']], on=klucz, suffixes=('_h', '_a'))
        hr, ar = sr(hh.r), sr(aa.r)
        if len(hh) < 10 or len(aa) < 10:
            ocena = 'MALO_DANYCH'
        elif hr - ar > 0.2:
            ocena = 'ROZJAZD: test 30 dni lepszy'
        elif ar - hr > 0.2:
            ocena = 'ROZJAZD: archiwum lepsze'
        else:
            ocena = 'ZGODNE'
        przyczyna = ''
        if ocena.startswith('ROZJAZD'):
            if len(w) >= 5 and abs(w.r_h.mean() - w.r_a.mean()) > 0.2:
                przyczyna = 'te same setupy rozliczone inaczej (symulacja/dane)'
            elif len(ain) >= 5 and len(aout) >= 5 and abs(ain.r.mean() - aout.r.mean()) > 0.2:
                przyczyna = 'inne kontrakty: test 30 dni liczy tylko czesc rynku'
            else:
                przyczyna = 'inne zdjecia/okazje (siatka czasu, liczba setupow)'
        out.append({'grupa': nazwa, 'okno_od': od, 'hist_n': len(hh), 'hist_sr_R': hr, 'arch_n': len(aa), 'arch_sr_R': ar,
                    'arch_kontrakty_testu_n': len(ain), 'arch_kontrakty_testu_sr_R': sr(ain.r),
                    'arch_inne_kontrakty_n': len(aout), 'arch_inne_kontrakty_sr_R': sr(aout.r),
                    'wspolne_n': len(w), 'wspolne_hist_sr_R': sr(w.r_h) if len(w) else None,
                    'wspolne_arch_sr_R': sr(w.r_a) if len(w) else None, 'ocena': ocena, 'przyczyna': przyczyna})
    return pd.DataFrame(out, columns=kol)


def _v250_tradfi_risk_gate(live):
    """Twardy fail-closed dla TradFi 'BEZ BRAMKI' bez pozytywnej alokacji ryzyka.
    Nie modyfikuje PROBA krypto; pozycje niezrealizowane nie rezerwuja dodatkowego slotu.
    """
    blocked = 0
    for r in live:
        if not r.get('do_handlu') or r.get('asset_type') not in TRADFI_TYPES:
            continue
        if r.get('ocena') in ('A', 'B') and r.get('w_limicie_ryzyka') is True:
            continue
        r['do_handlu'] = False
        r['warunki'] = (str(r.get('warunki') or '').replace('OK', '').strip('; ') + '; '
                        if str(r.get('warunki') or '') not in ('', 'OK') else '') + 'V6.250: TradFi bez zatwierdzonego miejsca ryzyka A/B'
        r['status_setupu'] = status_setupu(r)
        r['blokady_kwalifikacji'] = (str(r.get('blokady_kwalifikacji') or '') + '; ' +
                                    'V6.250: brak miejsca ryzyka A/B').strip('; ')
        blocked += 1
    return blocked


def _v250_stop_summary(rows):
    """Porownanie PAROWANE: wszystkie okazje vs filtr SL<=8%; zero za brak sygnalu.
    Wylacznie badanie, nie ingeruje w zlecenia ani w bazowy LONG DF.
    """
    out = []
    for prov in ('RETRO_DIAGNOSTYKA', 'PROSPEKTYWNE'):
        for var in _V244_WARIANTY:
            xs = [r for r in rows if r.get('proweniencja') == prov and r.get('wariant') == var]
            ok = [r for r in xs if r.get('dopuszczony_stop_8pct') is True]
            closed = [r for r in ok if r.get('status') in FINAL and r.get('r') is not None]
            vals = [float(r['r']) for r in closed]
            out.append({'proweniencja':prov, 'wariant':var, 'okazje':len(xs),
                'stop_ponad_8pct':sum(r.get('ryzyko_stop_status') == 'PONAD_LIMIT_BADAWCZY' for r in xs),
                'stop_brak_danych':sum(r.get('ryzyko_stop_status') == 'BRAK_DANYCH' for r in xs),
                'stop_w_limicie':len(ok), 'rozliczone_w_limicie':len(closed),
                'suma_R':round(sum(vals),4) if vals else None,
                'sredni_R_rozliczone':round(sum(vals)/len(vals),4) if vals else None,
                'uwaga':'BADANIE; retro nie jest OOS; brak wejsc to nie transakcje'})
    return out


_V273 = {'wynik': None}
ANALOG_KWANTYL = 0.10            # V6.273: najblizsze 10% godzin historii (ten sam trend BTC 4h)
ANALOG_MIN_N = 8                 # min. setupow danego typu w godzinach analogicznych


def _v273_cechy_btc(PP):
    """Godzinowe cechy BTC: ruch 4h/24h, trend 4h (EMA20/50 na 4h), alty vs BTC 72h, ruch BTC po 12h/24h."""
    def s1h(sym):
        a = ((PP or {}).get(sym) or {}).get('arr', {}).get('1h')
        if a is None or len(a) < 100:
            return None
        x = pd.Series(a[:, C], index=pd.to_datetime(a[:, T].astype('int64') + HOUR_MS, unit='ms', utc=True))
        return x[~x.index.duplicated()]
    btc = s1h('BTCUSDT')
    if btc is None:
        return None
    alts = {m: s1h(m) for m in MAJORS_4H if m != 'BTCUSDT'}
    alts = pd.concat({k: v for k, v in alts.items() if v is not None}, axis=1).reindex(btc.index) if any(v is not None for v in alts.values()) else None
    f = pd.DataFrame({'btc': btc})
    f['ch4'] = (btc / btc.shift(4) - 1) * 100
    f['ch24'] = (btc / btc.shift(24) - 1) * 100
    f['alt72'] = np.log(alts.div(btc, axis=0)).diff(72).mean(axis=1) * 100 if alts is not None else np.nan
    b4 = btc.resample('4h', label='right', closed='right').last()
    ema = lambda x_, n_: x_.ewm(span=n_, adjust=False).mean()
    e20_, e50_ = ema(b4, 20), ema(b4, 50)                 # V6.284: ta sama definicja co trend_of (cena vs EMA20 vs EMA50)
    f['tr4'] = pd.Series(np.where((b4 > e20_) & (e20_ > e50_), 1, np.where((b4 < e20_) & (e20_ < e50_), -1, 0)), index=b4.index).reindex(btc.index, method='ffill')
    f['fwd12'] = (btc.shift(-12) / btc - 1) * 100
    f['fwd24'] = (btc.shift(-24) / btc - 1) * 100
    return f


def analogie_v273(PP, hist_df, arch_df):
    """V6.273: chwile w historii najbardziej podobne do teraz (ten sam trend BTC 4h; odleglosc na ruchu 4h, 24h i alty vs BTC 72h).
    Co zrobil BTC potem i jak wypadly setupy krypto (typ, kierunek) z tych godzin, osobno test 30 dni i archiwum skanow."""
    f = _v273_cechy_btc(PP)
    if f is None:
        return None
    f = f.dropna(subset=['ch4', 'ch24', 'alt72', 'tr4'])
    if len(f) < 200:
        return None
    teraz = f.iloc[-1]
    hist = f.iloc[:-24]
    k_ = ['ch4', 'ch24', 'alt72']
    sd = hist[k_].std().replace(0, np.nan)
    d = (((hist[k_] - teraz[k_]) / sd) ** 2).sum(axis=1) ** 0.5
    d = d[hist.tr4 == teraz.tr4].dropna()
    if len(d) < 50:
        return None
    an = d[d <= d.quantile(ANALOG_KWANTYL)].index
    fx, baza = f.loc[an], f[f.tr4 == teraz.tr4]
    w = {'teraz': {k: rnd(float(teraz[k]), 2) for k in k_ + ['tr4']}, 'n_godzin': len(an), 'dni': len(set(an.strftime('%m-%d'))),
         'btc_12h': rnd(float(fx.fwd12.mean()), 2), 'btc_12h_wzrost': rnd(float((fx.fwd12.dropna() > 0).mean() * 100), 0),
         'btc_24h': rnd(float(fx.fwd24.mean()), 2), 'btc_24h_wzrost': rnd(float((fx.fwd24.dropna() > 0).mean() * 100), 0),
         'baza_24h_wzrost': rnd(float((baza.fwd24.dropna() > 0).mean() * 100), 0), 'typy': []}
    an_set = set(an)
    for nm, df in (('30d', hist_df), ('archiwum', arch_df)):
        if df is None or not len(df) or 'r' not in df.columns:
            continue
        x = df[df.get('asset_type', pd.Series('COIN', index=df.index)).fillna('COIN').eq('COIN') & df.r.notna()
               & df.status.isin(['SL', 'TP1', 'TP2', 'BE', 'timeout'])].copy()
        x['ts'] = pd.to_datetime(x.snapshot_utc, utc=True, errors='coerce').dt.floor('h')
        x['an'] = x.ts.isin(an_set)
        for (typ, side), y in x.groupby(['setup_type', 'side']):
            ya, yr = y[y.an], y[~y.an]
            if len(ya) < ANALOG_MIN_N:
                continue
            w['typy'].append({'proba': nm, 'typ': typ, 'side': side, 'n': len(ya), 'R_analog': rnd(float(ya.r.mean()), 3),
                              'R_reszta': rnd(float(yr.r.mean()), 3) if len(yr) else None, 'dni': ya.ts.dt.date.nunique()})
    t2 = {}
    for r in w['typy']:
        t2.setdefault((r['typ'], r['side']), {})[r['proba']] = r
    w['zgodne_plus'] = [f"{t} {s_}" for (t, s_), v in t2.items() if len(v) == 2 and all(x['R_analog'] > 0 for x in v.values())]
    w['zgodne_minus'] = [f"{t} {s_}" for (t, s_), v in t2.items() if len(v) == 2 and all(x['R_analog'] < 0 for x in v.values())]
    return w


# ================= V6.276: KIERUNEK 24 COINOW (model CoinGlass) + LIMIT NA POZIOMIE =================
_V276 = {'model': None, 'teraz': {}, 'badanie': None, 'wybor': None, 'setupy': [], 'kalibracja': []}
K276_PROGI = (0.55, 0.60, 0.65)          # prog prawdopodobienstwa kierunku
K276_POZIOMY = ('pivot', 'hvn', 'vwap7d', 'mapa')
K276_SL_ATR = (0.3, 0.6)                 # SL za poziomem (ATR 4h)
K276_DYST = (0.3, 2.5)                   # poziom w odleglosci 0.3-2.5 ATR od ceny
K276_WAZNOSC = 6                         # zlecenie wazne 6 swiec 4h (24h)
K276_HOLD = 12                           # max 48h od wypelnienia
K276_RR = 2.0
K276_MIN_N = 30                          # min. transakcji w kazdej polowie


def model_24_v276(dpz, c4, folds=5):
    """Model kierunku 24h na wszystkich kontraktach z danymi CoinGlass: prognozy poza proba (walk-forward), kalibracja,
    model na calej historii i prognoza teraz dla kazdego symbolu."""
    df = _v241_wiersze(dpz, c4)
    if not len(df):
        return None, pd.DataFrame(), {}
    hist = df[df.r24.notna()].sort_values('t').reset_index(drop=True)
    if len(hist) < 500:
        return {'n': len(hist), 'werdykt': 'ZA_MALO_DANYCH'}, pd.DataFrame(), {}
    gr = hist.t.quantile(np.linspace(0, 1, folds + 1)).values
    oos = []
    for k in range(1, folds):
        tr = hist[hist.t < gr[k] - DAY_MS]
        te = hist[(hist.t >= gr[k]) & ((hist.t < gr[k + 1]) if k + 1 < folds else (hist.t <= gr[-1]))]
        if len(tr) < 300 or not len(te):
            continue
        X, mu, sd = _v241_macierz(tr)
        w = _v241_fit(X, (tr.r24 > 0).astype(float).values)
        Xt, _, _ = _v241_macierz(te, mu, sd)
        oos.append(te.assign(p=1 / (1 + np.exp(-Xt @ w))))
    if not oos:
        return {'n': len(hist), 'werdykt': 'ZA_MALO_DANYCH'}, pd.DataFrame(), {}
    o = pd.concat(oos)
    kal = []
    for lo, hi in ((0, .35), (.35, .4), (.4, .45), (.45, .55), (.55, .6), (.6, .65), (.65, 1.01)):
        x = o[(o.p >= lo) & (o.p < hi)]
        if len(x):
            kal.append({'zakres': f"{lo:.2f}-{min(hi, 1):.2f}", 'n': len(x), 'wzrost_pct': rnd(float((x.r24 > 0).mean() * 100), 1),
                        'sr_bps': rnd(float(x.r24.mean()), 1)})
    pew = o[(o.p - 0.5).abs() >= 0.05]
    kier = np.sign(pew.p - 0.5)
    wyn = {'n': len(hist), 'oos_n': len(o), 'symbole': int(hist.symbol.nunique()),
           'traf_pewne': rnd(float(((kier * pew.r24) > 0).mean() * 100), 1) if len(pew) else None,
           'sr_bps_pewne': rnd(float((kier * pew.r24).mean()), 1) if len(pew) else None}
    h = len(pew) // 2
    ps = pew.sort_values('t')
    kk = np.sign(ps.p - 0.5)
    wyn['polowy'] = [rnd(float(((kk.iloc[:h] * ps.r24.iloc[:h]) > 0).mean() * 100), 1), rnd(float(((kk.iloc[h:] * ps.r24.iloc[h:]) > 0).mean() * 100), 1)] if h else None
    wyn['werdykt'] = 'DZIALA' if (wyn['polowy'] and min(wyn['polowy']) > 52 and (wyn['sr_bps_pewne'] or 0) > 0) else 'NIEPOTWIERDZONY'
    X, mu, sd = _v241_macierz(hist)
    w = _v241_fit(X, (hist.r24 > 0).astype(float).values)
    teraz = {}
    for sym, x in df.sort_values('t').groupby('symbol'):
        X1, _, _ = _v241_macierz(x.tail(1), mu, sd)
        teraz[sym] = {'p': rnd(float(1 / (1 + np.exp(-X1 @ w))[0]), 3), 't': int(x.t.iloc[-1])}
    _V276['kalibracja'] = kal
    return wyn, o[['symbol', 't', 'p', 'r24']].reset_index(drop=True), teraz


def _v276_atr(a, n=14):
    h, l, c = a[:, H], a[:, L], a[:, C]
    tr = np.maximum(h[1:] - l[1:], np.maximum(abs(h[1:] - c[:-1]), abs(l[1:] - c[:-1])))
    return np.r_[np.nan, pd.Series(tr).rolling(n, min_periods=n).mean().values]


def _v276_poziom(a, i, kier, typ, atr, mapa=None):
    """Poziom (wsparcie dla kier=+1 pod cena, opor dla -1 nad cena) znany na zamknieciu swiecy i. None gdy brak w zakresie odleglosci."""
    c = a[i, C]
    lo_d, hi_d = K276_DYST
    ok = lambda lv: lv is not None and lv == lv and lo_d * atr <= kier * (c - lv) <= hi_d * atr
    if typ == 'pivot':                                     # potwierdzone dolki/szczyty 4h (3 swiece z kazdej strony), ostatnie 60 swiec
        j0 = max(3, i - 60)
        kand = []
        for j in range(j0, i - 2):
            if kier == 1 and a[j, L] == a[j - 3:j + 4, L].min():
                kand.append(a[j, L])
            if kier == -1 and a[j, H] == a[j - 3:j + 4, H].max():
                kand.append(a[j, H])
        kand = [x for x in kand if ok(x)]
        return (max(kand) if kier == 1 else min(kand)) if kand else None
    if typ == 'hvn':                                       # obszar duzego wolumenu (profil 60 swiec, koszyki 0.25 ATR)
        j0 = max(0, i - 60)
        tp = (a[j0:i + 1, H] + a[j0:i + 1, L] + a[j0:i + 1, C]) / 3
        v = a[j0:i + 1, V]
        b = np.floor(tp / (0.25 * atr))
        s = pd.Series(v).groupby(b).sum()
        hv = s[s >= 1.5 * s.median()]
        kand = [float((k + 0.5) * 0.25 * atr) for k in hv.index]
        kand = [x for x in kand if ok(x)]
        return (max(kand) if kier == 1 else min(kand)) if kand else None
    if typ == 'vwap7d':
        j0 = max(0, i - 41)
        tp = (a[j0:i + 1, H] + a[j0:i + 1, L] + a[j0:i + 1, C]) / 3
        v = a[j0:i + 1, V]
        lv = float((tp * v).sum() / v.sum()) if v.sum() > 0 else None
        return lv if ok(lv) else None
    if typ == 'mapa' and mapa is not None:
        lv = mapa.get('mapa_pod' if kier == 1 else 'mapa_nad')
        return float(lv) if ok(lv) else None
    return None


def _v276_sym(a, i, kier, lv, atr, sl_atr):
    """LIMIT na poziomie (+0.1 ATR przed nim), SL sl_atr ATR za poziomem, TP 2R; wazne K276_WAZNOSC swiec, trzymanie K276_HOLD.
    Zwraca (wypelniony, R) - R po kosztach w R; niewypelnione = (False, 0)."""
    e = lv + kier * 0.1 * atr
    sl = lv - kier * sl_atr * atr
    risk = abs(e - sl)
    if not risk > 0:
        return False, 0.0
    tp = e + kier * K276_RR * risk
    koszt = SYG_KOSZT * e / risk
    f = None
    for k in range(i + 1, min(i + 1 + K276_WAZNOSC, len(a))):
        if (kier == 1 and a[k, H] >= tp) or (kier == -1 and a[k, L] <= tp):
            if not ((kier == 1 and a[k, L] <= e) or (kier == -1 and a[k, H] >= e)):
                return False, 0.0                          # odjechal bez wypelnienia
        if (kier == 1 and a[k, L] <= e) or (kier == -1 and a[k, H] >= e):
            f = k
            break
    if f is None:
        return False, 0.0
    if (kier == 1 and a[f, L] <= sl) or (kier == -1 and a[f, H] >= sl):
        return True, -1.0 - koszt                          # ta sama swieca: najpierw SL (ostroznie)
    for k in range(f + 1, min(f + 1 + K276_HOLD, len(a))):
        if (kier == 1 and a[k, L] <= sl) or (kier == -1 and a[k, H] >= sl):
            return True, -1.0 - koszt
        if (kier == 1 and a[k, H] >= tp) or (kier == -1 and a[k, L] <= tp):
            return True, K276_RR - koszt
    k = min(f + K276_HOLD, len(a) - 1)
    return True, kier * (a[k, C] - e) / risk - koszt


def badanie_limit_kierunek_v276(oos, c4, mapy=None):
    """Na prognozach poza proba: dla progu p, typu poziomu i SL - LIMIT na poziomie w strone prognozy. Wybor na 1. polowie, sprawdzenie na 2.
    Baza: ten sam poziom bez modelu (oba kierunki zawsze)."""
    if oos is None or not len(oos):
        return []
    rows = []
    for sym, x in oos.groupby('symbol'):
        a = (c4 or {}).get(sym)
        if a is None or len(a) < 80:
            continue
        atr = _v276_atr(a)
        tt = a[:, T]
        ost = {}
        for r in x.sort_values('t').itertuples():
            i = int(np.searchsorted(tt, r.t - 4 * HOUR_MS))
            if i < 70 or i + K276_WAZNOSC + 2 >= len(a) or tt[i] + 4 * HOUR_MS != r.t or not atr[i] > 0:
                continue
            for kier in (1, -1):
                pk = r.p if kier == 1 else 1 - r.p
                for typ in K276_POZIOMY:
                    mp = (mapy or {}).get(sym, {}).get(int(r.t)) if typ == 'mapa' else None
                    if typ == 'mapa' and mp is None:
                        continue
                    lv = _v276_poziom(a, i, kier, typ, atr[i], mp)
                    if lv is None:
                        continue
                    for sl_atr in K276_SL_ATR:
                        klucz = (typ, sl_atr, kier)
                        if r.t - ost.get(klucz, -10 ** 18) < DAY_MS:
                            continue
                        wyp, R = _v276_sym(a, i, kier, lv, atr[i], sl_atr)
                        rows.append({'symbol': sym, 't': int(r.t), 'kier': kier, 'p': pk, 'typ': typ, 'sl_atr': sl_atr, 'wyp': wyp, 'R': R})
                        if pk >= min(K276_PROGI):
                            ost[klucz] = r.t
    d = pd.DataFrame(rows)
    if not len(d):
        return []
    tmed = d.t.median()
    out = []
    for (typ, sl_atr), y in d.groupby(['typ', 'sl_atr']):
        for prog in (None,) + K276_PROGI:
            z = y if prog is None else y[y.p >= prog]
            w = {'typ': typ, 'sl_atr': sl_atr, 'prog': prog, 'zlecen': len(z), 'wyp_pct': rnd(float(z.wyp.mean() * 100), 1) if len(z) else None}
            for nm, m in (('1', z.t < tmed), ('2', z.t >= tmed)):
                q = z[m & z.wyp]
                w[f'n{nm}'] = len(q)
                w[f'R{nm}'] = rnd(float(q.R.mean()), 3) if len(q) else None
                w[f'traf{nm}'] = rnd(float((q.R > 0).mean() * 100), 1) if len(q) else None
            q = z[z.wyp]
            w['n'], w['R'] = len(q), rnd(float(q.R.mean()), 3) if len(q) else None
            w['R_LONG'] = rnd(float(q[q.kier == 1].R.mean()), 3) if (q.kier == 1).any() else None
            w['R_SHORT'] = rnd(float(q[q.kier == -1].R.mean()), 3) if (q.kier == -1).any() else None
            out.append(w)
    return out


def wybor_v276(bad):
    """Konfiguracja wybrana na 1. polowie (najwyzsze R, n1 >= K276_MIN_N, tylko z modelem), werdykt na 2. polowie."""
    kand = [w for w in bad if w['prog'] is not None and (w['n1'] or 0) >= K276_MIN_N and w['R1'] is not None]
    if not kand:
        return None
    b = max(kand, key=lambda w: w['R1'])
    baza = next((w for w in bad if w['typ'] == b['typ'] and w['sl_atr'] == b['sl_atr'] and w['prog'] is None), {})
    b = dict(b, baza_R=baza.get('R'), baza_R2=baza.get('R2'))
    b['werdykt'] = 'DZIALA' if (b['R1'] > 0 and (b['n2'] or 0) >= 20 and (b['R2'] or -1) > 0) else 'NIEPOTWIERDZONY'
    return b


def setupy_limit_kierunek_v276(PP, c4, teraz, wyb, mapy_teraz=None):
    """Biezace LIMIT-y: prognoza >= prog wybranej konfiguracji -> zlecenie na poziomie tego typu. Do gry tylko gdy werdykt DZIALA."""
    out = []
    for sym, tp_ in (teraz or {}).items():
        P = (PP or {}).get(sym) or {}
        a = (P.get('arr') or {}).get('4h')
        if a is None or len(a) < 80:
            a = (c4 or {}).get(sym)
        if a is None or len(a) < 80:
            continue
        p = tp_['p']
        atr = _v276_atr(a)[-1]
        i = len(a) - 1
        cena = _v271_cena_teraz(P)[0] if P else None
        cena = cena or float(a[i, C])
        for kier in (1, -1):
            pk = p if kier == 1 else 1 - p
            konf = [wyb] if wyb else []
            for w in konf:
                if pk < w['prog']:
                    continue
                lv = _v276_poziom(a, i, kier, w['typ'], atr, (mapy_teraz or {}).get(sym))
                if lv is None:
                    continue
                e = lv + kier * 0.1 * atr
                if kier * (cena - e) <= 0:                 # cena juz za poziomem
                    continue
                sl = lv - kier * w['sl_atr'] * atr
                risk = abs(e - sl)
                tp = e + kier * K276_RR * risk
                ok = w['werdykt'] == 'DZIALA'
                r2_ = w['R2'] or 0                         # V6.277: ostrozniej przy slabej 2. polowie
                oc = ('A' if (r2_ >= 0.3 and pk >= w['prog'] + 0.05) else 'B' if r2_ >= 0.15 else 'C') if ok else 'D'
                r = {'symbol': sym, 'side': 'LONG' if kier == 1 else 'SHORT', 'setup_type': 'KIER_LIMIT', 'entry_type': 'LIMIT',
                     'entry': e, 'sl': sl, 'tp1': tp, 'rr': rnd(K276_RR - SYG_KOSZT * e / risk, 2), 'p': pk, 'poziom': w['typ'],
                     'cena': cena, 'dyst_pct': rnd(abs(cena - e) / cena * 100, 2), 'ocena': oc, 'do_gry': ok}
                try:
                    r['dzwignia'] = leverage_plan({'entry': e, 'sl': sl, 'side': r['side'], 'entry_type': 'LIMIT'}, P).get('dzwignia') if P.get('fees') else None
                except Exception:
                    r['dzwignia'] = None
                out.append(r)
    return sorted(out, key=lambda r: ({'A': 0, 'B': 1, 'C': 2, 'D': 3}[r['ocena']], -r['p']))


# ================= V6.300: TRYB KIERUNKU - kierunek z potwierdzonego sygnalu decyduje, setupy od oporow / wsparc =================
KIER300_PROG = 0.58              # min. trafnosc potwierdzonego sygnalu BTC (sekcja 7, DZIALA), zeby wlaczyc tryb kierunku
KIER300_SL_ATR = 0.6             # SL za poziomem (ATR 4h)
KIER300_POZIOMY = ('szczyt/dolek 24h', 'pivot', 'hvn', 'vwap7d', 'mapa')
_V300 = {'kierunek': None, 'setupy': []}


def kierunek_v300(teraz=None):
    """Kierunek rynku z potwierdzonego sygnalu BTC (nie z historii typow setupow). Sprzeczny potwierdzony sygnal ETH -> brak trybu."""
    t = teraz if teraz is not None else (_V230.get('teraz') or {})
    b = (t.get('BTCUSDT') or {}).get('kier_dz')
    if not b or (b.get('p') or 0) < KIER300_PROG:
        return None
    e = (t.get('ETHUSDT') or {}).get('kier_dz')
    if e and e.get('kier') and e['kier'] != b['kier']:
        return None
    return dict(b, strona='LONG' if b['kier'] == 1 else 'SHORT')


def _v300_poziom(a, i, kier, atr, mapa=None):
    """Najblizszy poziom w strone wejscia: dla SHORT opor nad cena, dla LONG wsparcie pod cena (0.3-2.5 ATR 4h). (typ, poziom) albo None."""
    kand = []
    c = a[i, C]
    lo_d, hi_d = K276_DYST
    j0 = max(0, i - 5)
    ex = float(a[j0:i + 1, H].max()) if kier == -1 else float(a[j0:i + 1, L].min())   # szczyt / dolek 24h
    if lo_d * atr <= -kier * (ex - c) <= hi_d * atr:
        kand.append(('szczyt/dolek 24h', ex))
    for typ in ('pivot', 'hvn', 'vwap7d', 'mapa'):
        try:
            lv = _v276_poziom(a, i, kier, typ, atr, mapa)     # _v276_poziom: kier=+1 wsparcie pod cena, -1 opor nad cena
        except Exception:
            lv = None
        if lv is not None:
            kand.append((typ, float(lv)))
    if not kand:
        return None
    return min(kand, key=lambda x: abs(x[1] - c))


def setupy_kierunek_v300(PP, c4, kier_info, mapy_teraz=None, symbole=None):
    """LIMIT-y w strone kierunku od najblizszego oporu (SHORT) / wsparcia (LONG) na 24 duzych. Ocena C, pol ryzyka, bez blokady
    za wczesniejsze wyniki typow - wynik mierzony w dzienniku na zywo (wypada z gry po >= 20 transakcjach na minusie)."""
    if not kier_info:
        return []
    kier = int(kier_info['kier'])
    sd = 'LONG' if kier == 1 else 'SHORT'
    syg = f"tryb kierunku {sd}"
    w_ = (_V284.get('wylaczone') or {}).get(syg)
    out = []
    for sym in (symbole or _v272_symbole()):
        P = (PP or {}).get(sym) or {}
        a = (P.get('arr') or {}).get('4h')
        if a is None or len(a) < 80:
            a = (c4 or {}).get(sym)
        if a is None or len(a) < 80:
            continue
        atr = _v276_atr(a)[-1]
        if not atr == atr or atr <= 0:
            continue
        i = len(a) - 1
        cena = (_v271_cena_teraz(P)[0] if P else None) or float(a[i, C])
        pz = _v300_poziom(a, i, kier, atr, (mapy_teraz or {}).get(sym))
        if pz is None:
            continue
        typ, lv = pz
        e = lv + kier * 0.1 * atr                          # SHORT: tuz pod oporem, LONG: tuz nad wsparciem
        if kier * (cena - e) <= 0:                         # cena juz za wejsciem
            continue
        sl = lv + kier * -KIER300_SL_ATR * atr
        risk = abs(e - sl)
        if not risk > 0:
            continue
        tp = e + kier * K276_RR * risk
        tr_ = (_V300.get('trendy') or {}).get(sym)          # V6.303: coin sam w trendzie przeciw kierunkowi rynku -> D
        przeciw = bool(tr_) and tr_[0] == tr_[1] == -kier and sym != 'BTCUSDT'   # V6.314: BTC to rynek - kierunek z jego sygnalu, nie 'silniejszy od rynku'
        r = {'symbol': sym, 'side': sd, 'setup_type': 'TRYB_KIERUNKU', 'entry_type': 'LIMIT', 'poziom': typ, 'lv': lv,
             'entry': e, 'sl': sl, 'tp1': tp, 'rr': rnd(K276_RR - SYG_KOSZT * e / risk, 2), 'p': kier_info['p'],
             'cena': cena, 'dyst_pct': rnd(abs(cena - e) / cena * 100, 2), 'ocena': 'D' if przeciw else 'C', 'do_gry': not w_ and not przeciw,
             'sygnal': syg, 'przeciw_trendowi_coina': przeciw,
             'opis': f"kierunek {sd} {kier_info['p'] * 100:.0f}% ({kier_info['sygnal']}); poziom {typ} {_v201_cena(lv)}"
                     + (f"; NA ZYWO NA MINUSIE ({w_['R']}R po {w_['n']}) - nie do gry" if w_ else '')
                     + (('; COIN SILNIEJSZY OD RYNKU (trend 4h i 1h w gore) - mozliwe wybicie, nie do gry' if kier == -1 else
                         '; COIN W TRENDZIE SPADKOWYM 4h i 1h - long przeciw trendowi (nie lapiemy noza), nie do gry') if przeciw else '')}
        try:                                               # V6.306: TP wg wariantu z testu
            _v306_zastosuj(r, a, i, kier, (mapy_teraz or {}).get(sym))
        except Exception:
            pass
        if not str(kier_info.get('sygnal', '')).startswith('kierunek wlasny'):   # V6.307: werdykt grupy (tylko tryb kierunku z sygnalu BTC)
            try:
                _v307_ocena(r, sym, kier, a, atr, cena)
            except Exception:
                pass
        try:
            r['dzwignia'] = leverage_plan({'entry': e, 'sl': sl, 'side': sd, 'entry_type': 'LIMIT'}, P).get('dzwignia') if P.get('fees') else None
        except Exception:
            r['dzwignia'] = None
        out.append(r)
    pierw = {'BTCUSDT': 0, 'ETHUSDT': 1}                    # BTC/ETH najpierw (kierunek liczony z BTC), potem najblizsze wejscia
    return sorted(out, key=lambda r: (r['ocena'] == 'D', pierw.get(r['symbol'], 2), r['dyst_pct']))   # V6.303: D na koncu


def _v300_linie():
    k = _V300.get('kierunek')
    if not k:
        tl = _v312_tlo()
        return [f"  TLO DZIENNE (potwierdzone sygnaly dzienne BTC, 3-5 dni): {tl}"] if tl else []
    przec = 'longi' if k['strona'] == 'SHORT' else 'shorty'
    gdzie = 'shortow od oporow' if k['strona'] == 'SHORT' else 'longow od wsparc'
    lin = [f"  KIERUNEK: {k['strona']} {k['p'] * 100:.0f}% w 24h (potwierdzony sygnal '{k['sygnal']}', n={k['n']}) -> miejsce na {przec} sie konczy, "
           f"szukaj {gdzie} (LIMIT, ocena C, pol ryzyka; tabela 2d)"]
    tl = _v312_tlo()                                       # V6.312
    if tl:
        lin.append(f"  TLO DZIENNE (potwierdzone sygnaly dzienne BTC, 3-5 dni): {tl}")
    return lin


def _v300_tabela():
    k = _V300.get('kierunek')
    ts = _V300.get('setupy') or []
    if not k:
        return ['', f"2d. TRYB KIERUNKU: nieaktywny (brak potwierdzonego sygnalu BTC >= {KIER300_PROG * 100:.0f}% albo sprzeczny sygnal ETH)", _v306_linia()] + _v307_linie()
    pz = {w['sygnal']: w for w in _V284.get('podsum') or []}.get(f"tryb kierunku {k['strona']}")
    linie = ['', f"2d. TRYB KIERUNKU {k['strona']} ({k['p'] * 100:.0f}%, '{k['sygnal']}'; LIMIT {KIER300_SL_ATR + 0.1:.1f} ATR 4h ryzyka, TP {K276_RR}R, wazne 24h; "
                 f"ocena C = pol ryzyka): {len(ts)} setupow, do gry {sum(1 for r in ts if r['do_gry'])}"
             + (f" | NA ZYWO: n={pz['n']}, sr {pz['R']}R" if pz else ' | NA ZYWO: jeszcze brak rozliczonych')]
    linie.append(_v306_linia())                            # V6.306
    linie += _v307_linie()                                 # V6.307
    if _V315.get('ruch_ruszyl'):
        linie.append(f"  RUCH RUSZYL (V6.315): BTC przebil ostatni {'dolek' if k['strona'] == 'SHORT' else 'szczyt'} 1h - LIMIT-y od poziomow > 0.5% od ceny anulowane (nie gonimy); w grze zostaja bliskie i setupy po wykresie")
    linie.append(_v315_linia())
    if not ts:
        return linie + ['  (brak poziomu w zasiegu 0.3-2.5 ATR)']
    nag = ['Symbol', 'Kier.', 'Poziom', 'Wejscie', 'SL', 'TP1', 'TP2*', 'TP3*', 'RR', 'Dzwignia', 'Ocena', 'Od ceny']   # V6.316: + TP3
    dane = [[r['symbol'].replace('USDT', ''), r['side'], r['poziom'], _v201_cena(r['entry']), _v201_cena(r['sl']), _v201_cena(r['tp1']),
             (_v201_cena(r['tp2']) + f" ({r.get('tp2_poziom')})") if r.get('tp2') else _v316_txt(r)[0], _v316_txt(r)[1],
             f"{r['rr']:.2f}", f"{r['dzwignia']}x" if r.get('dzwignia') else '-',
             r['ocena'] + (' DO GRY' if r['do_gry'] else (' coin silniejszy od rynku - mozliwe wybicie' if r.get('side') == 'SHORT' else ' coin w trendzie spadkowym 4h i 1h - nie lapiemy noza') if r.get('przeciw_trendowi_coina') else ' test grupy na minusie' if r.get('test_grupy_minus') else ' anulowany - ruch ruszyl' if r.get('anulowany_ruch') else ' wstrzymany - mozliwe odwrocenie' if r.get('odwrocenie_v317') else ''), f"{r['dyst_pct']}%"]
            for r in ts[:24]]
    sz = [max(len(str(x)) for x in [h_] + [d_[i_] for d_ in dane]) for i_, h_ in enumerate(nag)]
    linie += ['  ' + ' | '.join(str(x).ljust(sz[i_]) for i_, x in enumerate(nag)).rstrip(), '  ' + '-+-'.join('-' * n_ for n_ in sz)]
    linie += ['  ' + ' | '.join(str(x).ljust(sz[i_]) for i_, x in enumerate(d_)).rstrip() for d_ in dane]
    linie.append('  Anuluj niewypelnione: gdy BTC zamknie 4h za ostatnim dolkiem/szczytem 1h w strone kierunku (ruch ruszyl bez nas - nie gonimy) '
                 'i przed danymi USA (zasada makro). Zamknij przy zamknieciu 4h za SL.')
    return linie



# ================= V6.301: TRYB KIERUNKU dla mniejszych krypto + TradFi z wlasnym kierunkiem =================
KIER301_KORELACJA = 0.5          # mniejsze krypto: tylko te, ktore chodza za BTC
KIER301_MAX_MNIEJSZE = 12        # ile mniejszych coinow w tabeli (najslabsze vs BTC przy SHORT, najsilniejsze przy LONG)
TRADFI301_RUCH_24H = 1.0         # TradFi: wlasny kierunek = trend 4h i 1h zgodne + ruch 24h >= 1% w te strone
TRADFI301_INDEKSY = ('QQQUSDT', 'SPYUSDT')
_V301 = {'mniejsze': [], 'tradfi': [], 'indeks': 0}


def _v301_liczba(x):
    try:
        v = float(x)
        return v if v == v else None
    except (TypeError, ValueError):
        return None


def setupy_mniejsze_v301(PP, kier_info, summary):
    """Mniejsze krypto (plynne, korelacja z BTC >= 0.5) w strone kierunku rynku - ten sam LIMIT od oporu/wsparcia co 2d."""
    if not kier_info:
        return []
    duze = set(_v272_symbole())
    kier = int(kier_info['kier'])
    kand = []
    for r in summary or []:
        sym = r.get('symbol')
        if not sym or sym in duze or r.get('asset_type', 'COIN') not in ('COIN', None) or r.get('tradable') is not True:
            continue
        kb = _v301_liczba(r.get('corr_btc'))
        if kb is None or kb < KIER301_KORELACJA:
            continue
        rs = _v301_liczba(r.get('rs_btc_24h')) or 0.0
        kand.append((kier * rs, sym))                     # SHORT: najslabsze vs BTC najpierw
    kand = [sym for _, sym in sorted(kand)[:KIER301_MAX_MNIEJSZE * 2]]
    out = setupy_kierunek_v300(PP, {}, kier_info, None, symbole=kand)
    syg = f"tryb kierunku {'LONG' if kier == 1 else 'SHORT'} mniejsze"
    w_ = (_V284.get('wylaczone') or {}).get(syg)
    for x in out:
        x['sygnal'], x['setup_type'], x['do_gry'] = syg, 'TRYB_KIERUNKU_MNIEJSZE', not w_ and not x.get('przeciw_trendowi_coina') and not x.get('test_grupy_minus')
    poz = {sym: i for i, sym in enumerate(kand)}
    return sorted(out, key=lambda x: (x['ocena'] == 'D', poz.get(x['symbol'], 99)))[:KIER301_MAX_MNIEJSZE]


def _v301_indeks(summary):
    """Kierunek rynku akcji USA z QQQ/SPY: suma trendow 4h (+1/-1 tylko gdy oba zgodne albo jeden + drugi bok)."""
    tr = [int(_v301_liczba(r.get('trend_4h')) or 0) for r in summary or [] if r.get('symbol') in TRADFI301_INDEKSY]
    if not tr:
        return 0
    s_ = sum(tr)
    return 1 if s_ > 0 and min(tr) >= 0 else -1 if s_ < 0 and max(tr) <= 0 else 0


def setupy_tradfi_v301(PP, summary):
    """TradFi: kierunek wlasny instrumentu (ZASADA, nie test - brak potwierdzonego sygnalu kierunku dla TradFi):
    trend 4h = trend 1h = k i ruch 24h >= 1% w strone k; akcje/indeksy nie przeciw indeksowi (QQQ/SPY). LIMIT od oporu/wsparcia, ocena C."""
    idx = _v301_indeks(summary)
    _V301['indeks'] = idx
    out = []
    for r in summary or []:
        sym, at = r.get('symbol'), r.get('asset_type')
        if at not in TRADFI_TYPES or r.get('tradable') is not True:
            continue
        t4, t1, ch = (_v301_liczba(r.get(k)) for k in ('trend_4h', 'trend_1h', 'chg_24h_pct'))
        if not t4 or t4 != t1 or ch is None or t4 * ch < TRADFI301_RUCH_24H:
            continue
        k = int(t4)
        if at in ('Stocks', 'Indices', 'Pre-IPO') and idx == -k and sym not in TRADFI301_INDEKSY:
            continue                                       # przeciw rynkowi akcji
        sd = 'LONG' if k == 1 else 'SHORT'
        info = {'kier': k, 'p': 0.5, 'sygnal': f"kierunek wlasny {sd} (trend 4h/1h, 24h {ch:+.1f}%)", 'n': 0}
        x = setupy_kierunek_v300(PP, {}, info, None, symbole=[sym])
        syg = f"TradFi kierunek wlasny {sd}"
        w_ = (_V284.get('wylaczone') or {}).get(syg)
        tw_ = ((_V307.get('tradfi') or {}).get('strony') or {}).get(sd) or {}   # V6.307: test TradFi
        for y in x:
            if tw_.get('werdykt') == 'MINUS':
                y['ocena'] = 'D'
            y.update(sygnal=syg, setup_type='TRADFI_KIERUNEK', do_gry=not w_ and tw_.get('werdykt') != 'MINUS', ruch_24h=rnd(ch, 2), asset_type=at,
                     opis=f"{at}: trend 4h i 1h {sd}, 24h {ch:+.1f}%; indeks {'+' if idx > 0 else '-' if idx < 0 else '0'}; poziom {y['poziom']} {_v201_cena(y['lv'])} "
                          "(zasada dopasowania do rynku, nie test)")
        out += x
    return sorted(out, key=lambda y: y.get('dyst_pct') or 99)   # V6.302: najblizsze wejscia najpierw (SOXL 13% od ceny nie powinien wygrywac)


def _v301_tabela(tytul, ts, uwaga):
    linie = ['', tytul]
    if not ts:
        return linie + ['  (nic w zasiegu: brak kierunku albo poziomu 0.3-2.5 ATR od ceny)']
    nag = ['Symbol', 'Kier.', 'Poziom', 'Wejscie', 'SL', 'TP1', 'TP2*', 'TP3*', 'RR', 'Dzwignia', 'Ocena', 'Od ceny']   # V6.316: + TP3
    dane = [[r['symbol'].replace('USDT', ''), r['side'], r['poziom'], _v201_cena(r['entry']), _v201_cena(r['sl']), _v201_cena(r['tp1']),
             (_v201_cena(r['tp2']) + f" ({r.get('tp2_poziom')})") if r.get('tp2') else _v316_txt(r)[0], _v316_txt(r)[1],
             f"{r['rr']:.2f}", f"{r['dzwignia']}x" if r.get('dzwignia') else '-',
             r['ocena'] + (' DO GRY' if r['do_gry'] else (' coin silniejszy od rynku - mozliwe wybicie' if r.get('side') == 'SHORT' else ' coin w trendzie spadkowym 4h i 1h - nie lapiemy noza') if r.get('przeciw_trendowi_coina') else ' test grupy na minusie' if r.get('test_grupy_minus') else ' anulowany - ruch ruszyl' if r.get('anulowany_ruch') else ' wstrzymany - mozliwe odwrocenie' if r.get('odwrocenie_v317') else ''), f"{r['dyst_pct']}%"]
            for r in ts]
    sz = [max(len(str(x)) for x in [h_] + [d_[i_] for d_ in dane]) for i_, h_ in enumerate(nag)]
    linie += ['  ' + ' | '.join(str(x).ljust(sz[i_]) for i_, x in enumerate(nag)).rstrip(), '  ' + '-+-'.join('-' * n_ for n_ in sz)]
    linie += ['  ' + ' | '.join(str(x).ljust(sz[i_]) for i_, x in enumerate(d_)).rstrip() for d_ in dane]
    if uwaga:
        linie.append('  ' + uwaga)
    return linie


