    n = 40
    a = np.zeros((n, 8)); a[:, T] = np.arange(n) * t4
    a[:, C] = 100.0; a[:, H] = 100.5; a[:, L] = 99.5
    # short: wejscie 101, SL 102 (risk 1); swieca 21 wypelnia, 22 TP1 (99), 23 TP2 (96)
    a[21, H] = 101.2; a[22, L] = 98.8; a[23, L] = 95.8
    w = _v306_sym(a, 20, -1, 101.0, 102.0, 96.0)
    assert w['TP 2R'] == 2.0 and w['pol 2R + reszta do poziomu'] == 1.0 + 0.5 * 5.0 and w['TP 3R'] == 3.0 and w['TP na poziomie'] == 5.0
    b = a.copy(); b[23, L] = 99.5; b[24, H] = 101.1                     # po TP1 powrot na wejscie -> 1R z polowy
    assert _v306_sym(b, 20, -1, 101.0, 102.0, 96.0)['pol 2R + reszta do poziomu'] == 1.0
    a2 = np.zeros((80, 8)); a2[:, T] = np.arange(80) * t4; a2[:, C] = 100; a2[:, H] = 100.5; a2[:, L] = 99.5; a2[50, L] = 96.5
    tp2, typ = _v306_cel(a2, 70, -1, 100.0, 1.0)
    assert 95.9 < tp2 < 96.7 and typ in ('dolek 7d', 'pivot 4h')
    tp2b, typb = _v306_cel(a2, 70, -1, 100.0, 0.5)                    # poziom za daleko (7R) -> 3R
    assert typb == '3R' and abs(tp2b - 98.5) < 1e-9
    _V306['wariant'] = 'pol 2R + reszta do poziomu'
    try:
        r = _v306_zastosuj({'entry': 100.0, 'sl': 101.0}, a2, 70, -1)
        assert r['tp1'] == 98.0 and r['tp2'] and r['rr'] > 2.5
    finally:
        _V306['wariant'] = 'TP 2R'
    return 'PASS (warianty wyjscia, TP2 na poziomie 3-5R, polowa z SL na wejsciu)'


