def test_v297():
    import tempfile
    t4 = 4 * HOUR_MS
    pusty = pd.DataFrame(columns=['t', 'ob_bid', 'ob_ask'])
    hist = pd.DataFrame({'t': np.arange(80) * t4, 'ob_bid': 2.0, 'ob_ask': 1.0})
    f = Path(tempfile.mkdtemp()) / 'a.json'
    f.write_text(json.dumps({'BTCUSDT': {'t': [0, t4], 'ob_bid': [9.0, 9.0], 'ob_ask': [1.0, 1.0]}}))   # stare archiwum bez zrodla
    st = _v299_stuby(hist, 'aggregated-ask-bids-history', pusty)
    try:
        _V297['ob_zrodlo'] = {'BTC': 'aggregated-ask-bids-history'}
        o = _v297_arkusz({'BTCUSDT': pd.DataFrame({'t': np.arange(81) * t4, 'oi': 1.0, 'ob_bid': 3.0, 'ob_ask': 1.0})}, f)['BTCUSDT']
        assert _V297['wiersze']['BTCUSDT'] == 81 and o.ob_bid.iloc[0] == 3.0          # bez zrodla -> od nowa; ogon tego samego zrodla dopisany
        globals()['_v298_arkusz_historia'] = lambda c: pusty.copy()
        o = _v297_arkusz({'BTCUSDT': pd.DataFrame({'t': np.arange(82) * t4, 'oi': 1.0})}, f)['BTCUSDT']   # odswiezenie cache bez arkusza
        assert o.ob_bid.notna().sum() == 81
        globals()['_v299_arkusz_ogon'] = lambda c, z, lim=12: pd.DataFrame({'t': [81 * t4], 'ob_bid': [4.0], 'ob_ask': [1.0]})
        _V297['ob_zrodlo'] = {'BTC': None}
        o = _v297_arkusz({'BTCUSDT': pd.DataFrame({'t': np.arange(82) * t4, 'oi': 1.0})}, f)['BTCUSDT']   # ogon z wlasciwego zrodla
        assert _V297['wiersze']['BTCUSDT'] == 82 and o.ob_bid.iloc[-1] == 4.0
    finally:
        _v299_przywroc(st)
    return 'PASS (arkusz przetrwa odswiezenie cache, jedno zrodlo, ogon z tego samego zrodla)'


