    raw = pd.DataFrame({'t': a[:, T].astype('int64'), 'ls': 1.0, 'fund': 1e-4, 'oi': 1e9, 'liq_long': 100.0 + rng.uniform(0, 20, n),
                        'liq_short': 100.0 + rng.uniform(0, 20, n)})
    raw.loc[151, 'liq_short'] = 1e9
    k_ = lambda w: [x for x in w if x['sygnal'].startswith('likwidacje skrajne (kaskada')]
    stare = k_(badanie_pozycji_v230({'BTCUSDT': raw}, {'BTCUSDT': a}))
    nowe = k_(badanie_pozycji_v230(_v290_czas_znany({'BTCUSDT': raw}, int(a[-1, T]) + 4 * HOUR_MS), {'BTCUSDT': a}))
    assert stare and stare[0]['sr_24h_bps'] > 500 and nowe and nowe[0]['sr_24h_bps'] == 0, (stare, nowe)   # stary uklad widzial skok
    return 'PASS (czas = zamkniecie swiecy, niezamknieta pominieta, kaskada nie widzi ruchu z wlasnej swiecy)'


