def test_v280():
    """V6.280: spoznione wejscie (fill tylko gdy cena doszla, wynik w R nowego ryzyka), limit pozycji z jednego sygnalu."""
    import tempfile
    n = 60
    a = np.zeros((n, 8)); a[:, T] = np.arange(n) * 4 * HOUR_MS
    c = np.full(n, 100.0); a[:, O] = c; a[:, C] = c; a[:, H] = c + 1; a[:, L] = c - 1
    atr = _v267_atr(a); R = SYG_SL_ATR * atr[40]
    a[41, H] = 100 + 0.3 * R; a[41, L] = 100 - 0.2 * R
    a[42:, H] = 100 + 2.1 * R; a[42:, L] = 100 + 0.1 * R
    w = _v280_spozn(a, 40, 1, atr[40], 2.0, 0.25)
    assert w is not None and abs(w - (1.75 / 1.25 - SYG_KOSZT * (100 + 0.25 * R) / (1.25 * R))) < 1e-6, w
    assert _v280_spozn(a, 40, 1, atr[40], 2.0, 0.5) is None                  # cena nie doszla do +0.5R w swiecy 41
    keep = (dict(_V267), dict(_V276))
    try:
        _V276.update(model={'werdykt': 'DZIALA'}, teraz={}, wybor={}, setupy=[])
        _V267['teraz'] = [dict(symbol=f'S{i}USDT', side='LONG', sygnal='tlum zmiana 24h (kontra)', entry=1, sl=0.9, tp1=1.2, rr=1.5, dzwignia=10,
                               ocena='B', do_gry=True, test_R=0.2 - i / 100, opis='', cel='TP 2.0R') for i in range(4)]
        with tempfile.TemporaryDirectory() as d:
            plan = plan_gry_v277(d)
        assert len(plan) == PLAN_MAX_SYGNAL and any('tego samego sygnalu' in a_['przyczyna'] for a_ in _V277['audyt']), plan
    finally:
        _V267.clear(); _V267.update(keep[0]); _V276.clear(); _V276.update(keep[1])
    return 'PASS (spoznione wejscie: tylko po dojsciu ceny, R nowego ryzyka; maks. 2 pozycje z jednego sygnalu)'


