def test_v276():
    rng = np.random.default_rng(4)
    n = 300
    a = np.zeros((n, 8)); a[:, T] = np.arange(n) * 4 * HOUR_MS
    c = 100 + np.cumsum(rng.normal(0, 0.5, n)); a[:, O] = c; a[:, C] = c; a[:, H] = c + 0.6; a[:, L] = c - 0.6; a[:, V] = 10
    a[200:203, L] = c[200:203] - 0.6; a[201, L] = c[201] - 4                   # wyrazny dolek
    atr = _v276_atr(a)
    for typ in ('pivot', 'hvn', 'vwap7d'):
        lv = _v276_poziom(a, 250, 1, typ, atr[250])
        assert lv is None or (lv < a[250, C]), (typ, lv)
    b = np.zeros((20, 8)); b[:, T] = np.arange(20) * 4 * HOUR_MS
    b[:, C] = 100; b[:, H] = 100.5; b[:, L] = 99.5
    b[1, L] = 97.85; b[2:, H] = 104.5; b[2:, L] = 99                           # wypelnienie na 98, potem TP
    wyp, R = _v276_sym(b, 0, 1, 97.8, 1.0, 0.3)
    assert wyp and abs(R - (2 - SYG_KOSZT * 97.9 / 0.4)) < 1e-6, (wyp, R)
    b2 = b.copy(); b2[1, L] = 99.5
    assert _v276_sym(b2, 0, 1, 97.8, 1.0, 0.3) == (False, 0.0)
    oos = pd.DataFrame({'symbol': 'XUSDT', 't': (a[80:280:2, T] + 4 * HOUR_MS).astype('int64'), 'p': rng.uniform(0.3, 0.7, 100), 'r24': 0.0})
    bad = badanie_limit_kierunek_v276(oos, {'XUSDT': a})
    assert bad and all('R1' in w for w in bad)
    w = wybor_v276([dict(typ='pivot', sl_atr=0.3, prog=0.6, n1=40, R1=0.2, n2=25, R2=0.1, R=0.15, zlecen=90, wyp_pct=50),
                    dict(typ='pivot', sl_atr=0.3, prog=None, n1=80, R1=-0.1, n2=80, R2=-0.1, R=-0.1, zlecen=200, wyp_pct=50)])
    assert w['werdykt'] == 'DZIALA' and w['baza_R'] == -0.1
    P = {'arr': {'4h': a}, 'forming': {}}
    s = setupy_limit_kierunek_v276({'XUSDT': P}, {}, {'XUSDT': {'p': 0.7, 't': 0}}, dict(w, typ='vwap7d'))
    assert all(r['side'] == 'LONG' and r['entry'] < r['cena'] and r['sl'] < r['entry'] < r['tp1'] for r in s), s
    return 'PASS (poziomy tylko z przeszlosci, LIMIT: wypelnienie/TP/brak wypelnienia, wybor na 1. polowie, setup w strone prognozy)'


def zastosuj_kierunek_v276(out_dir):
    """V6.276: istniejace setupy krypto na 24 duzych: model kierunku coina (gdy DZIALA) mocno przeciw (<= 40%) -> ocena -1; zgodny >= 60% -> dopisek."""
    m = _V276.get('model') or {}
    if m.get('werdykt') != 'DZIALA' or not _V276.get('teraz'):
        return 0
    n, nizej = 0, {'A': 'B', 'B': 'C', 'C': 'D', 'D': 'D'}
    for plik in ('top_market.csv', 'top_limit.csv', 'setups.csv'):
        f = Path(out_dir) / plik
        if not f.is_file():
            continue
        try:
            df = pd.read_csv(f, low_memory=False)
        except Exception:
            continue
        if not len(df) or 'symbol' not in df.columns:
            continue
        for c in ('zdarzenie_v242', 'ocena'):
            if c not in df.columns:
                df[c] = None
            df[c] = df[c].astype(object)
        for i in df.index:
            t_ = _V276['teraz'].get(str(df.at[i, 'symbol']))
            if not t_:
                continue
            pk = t_['p'] if str(df.at[i, 'side']) == 'LONG' else 1 - t_['p']
            if pk <= 0.4:
                o = str(df.at[i, 'ocena']) if isinstance(df.at[i, 'ocena'], str) else ''
                if o in nizej:
                    df.at[i, 'ocena'] = nizej[o]
                dop = f"model coina przeciw ({pk * 100:.0f}% w strone setupu), ocena {o}->{nizej.get(o, o)}"
                n += plik != 'setups.csv'
            elif pk >= 0.6:
                dop = f"model coina za ({pk * 100:.0f}%)"
            else:
                continue
            old = df.at[i, 'zdarzenie_v242']
            df.at[i, 'zdarzenie_v242'] = '; '.join(([old] if isinstance(old, str) and old else []) + [dop])
        df.to_csv(f, index=False)
    return n


def test_v275():
    """V6.275: CVD coina w cechach, test setupow przeciw przeplywowi (sam 30d), obnizka oceny."""
    import tempfile
    rng = np.random.default_rng(2)
    n = 300
    t0 = pd.Timestamp('2026-10-05', tz='UTC')
    cv = rng.uniform(40, 60, n)
    side = np.where(rng.random(n) < .5, 'LONG', 'SHORT')
    s_ = np.where(side == 'LONG', 1, -1)
    k = np.where(cv - 50 >= 2, 1, np.where(cv - 50 <= -2, -1, 0))
    r = np.where(k * s_ < 0, -0.6, 0.1) + rng.normal(0, .05, n)
    h = pd.DataFrame({'snapshot_utc': [(t0 + pd.Timedelta(hours=2 * i)).strftime('%Y-%m-%dT%H:%M') for i in range(n)], 'side': side, 'r': r,
                      'status': 'SL', 'asset_type': 'COIN', 'setup_type': 'PULLBACK', 'cvd_24h_pct': cv, 'cvd_4h_pct': 50.0,
                      'btc_trend_1h': 0, 'btc_trend_4h': 0})
    wyn = badanie_setupy_btc_v248(h, None, [])
    w = next(x for x in wyn if x['sygnal'] == 'CVD coina 24h (setup za przeplywem)')
    assert str(w['wniosek']).startswith('FILTR: ocena -1'), w
    keep = dict(_V248)
    try:
        _V248['wynik'] = wyn
        with tempfile.TemporaryDirectory() as d:
            pd.DataFrame([{'symbol': 'X', 'side': 'LONG', 'ocena': 'B', 'asset_type': 'COIN', 'cvd_24h_pct': 45.0, 'cvd_4h_pct': 50},
                          {'symbol': 'Y', 'side': 'SHORT', 'ocena': 'B', 'asset_type': 'COIN', 'cvd_24h_pct': 45.0, 'cvd_4h_pct': 50},
                          {'symbol': 'Z', 'side': 'LONG', 'ocena': 'B', 'asset_type': 'Stocks', 'cvd_24h_pct': 45.0}]).to_csv(Path(d) / 'top_market.csv', index=False)
            zastosuj_cvd_coina_v275(d)
            o = pd.read_csv(Path(d) / 'top_market.csv')
            assert list(o.ocena) == ['C', 'B', 'B'], o
    finally:
        _V248.clear(); _V248.update(keep)
    return 'PASS (CVD coina: filtr z samego testu 30 dni, obnizka przeciw przeplywowi, zgodne i TradFi bez zmian)'


