def test_v271():
    """V6.271: retest po ucieczce 0.5R; setup teraz od biezacej ceny; spozniony -> limit retest."""
    n = 80
    a = np.zeros((n, 8)); a[:, T] = np.arange(n) * 4 * HOUR_MS
    c = np.full(n, 100.0); a[:, O] = c; a[:, C] = c; a[:, H] = c + 1; a[:, L] = c - 1
    atr = _v267_atr(a); R = SYG_SL_ATR * atr[60]
    a[61, H] = 100 + 0.6 * R; a[61, L] = 99.9; a[61, C] = 100 + 0.5 * R      # ucieczka
    a[62, L] = 100 + 0.2 * R; a[62, H] = 100 + 0.5 * R; a[62, C] = 100 + 0.3 * R   # wypelnienie limitu
    a[63:, L] = 100 + 0.3 * R; a[63:, H] = 100 + 2.1 * R; a[63:, C] = 100 + 2 * R  # TP
    w = _v271_retest(a, 60, 1, atr[60], 2.0)
    assert w is not None and abs(w - (1.75 / 1.25 - SYG_KOSZT * (100 + 0.25 * R) / (1.25 * R))) < 1e-6, w
    b = a.copy(); b[61:, L] = 100 + 0.4 * R; b[61:, H] = 100 + 0.6 * R
    assert _v271_retest(b, 60, 1, atr[60], 2.0) is None                     # brak wypelnienia
    keep = dict(_V267)
    try:
        _V267['badanie'] = [{'sygnal': 'likwidacje skrajne (kaskada, w strone)', 'rr': 2.0, 'wariant': wr, 'rr_limit': 1.4, 'n': 40, 'sr_R': 0.8,
                             'traf_pct': 80, 'polowy': [1, 1], 'wniosek': 'DZIALA'} for wr in ('rynek', 'retest')]
        aa = a[:61].copy()
        now = int(aa[-1, T]) + 4 * HOUR_MS + HOUR_MS
        df = pd.DataFrame({'t': [int(aa[-1, T]) + 4 * HOUR_MS], 'ls': [1.5], 'top': [1.0], 'oi': [1e9], 'fund': [1e-4], 'liq_long': [100.0], 'liq_short': [1e7]})
        orig = globals()['_v230_sygnaly']
        globals()['_v230_sygnaly'] = lambda r: {'likwidacje skrajne (kaskada, w strone)': 1}
        globals()['_v230_cechy'], oc = (lambda d: d), globals()['_v230_cechy']
        try:
            m5 = np.zeros((1, 8)); m5[0, T] = now - 300000; m5[0, O] = 100; m5[0, H] = 100 + 0.1 * R; m5[0, L] = 99.9; m5[0, C] = 100 + 0.1 * R
            P = {'arr': {'4h': aa, '5m': m5}, 'forming': {}}
            r = setupy_sygnalowe_teraz_v267({'BTCUSDT': df}, {'BTCUSDT': P}, now)
            assert len(r) == 1 and r[0]['entry_type'] == 'MARKET' and r[0]['do_gry'] and abs(r[0]['entry'] - (100 + 0.1 * R)) < 1e-9, r
            m5b = m5.copy(); m5b[0, C] = 100 + 0.8 * R; m5b[0, H] = 100 + 0.8 * R
            r = setupy_sygnalowe_teraz_v267({'BTCUSDT': df}, {'BTCUSDT': {'arr': {'4h': aa, '5m': m5b}, 'forming': {}}}, now)
            ty = {x['entry_type']: x for x in r}
            assert not ty['MARKET']['do_gry'] and ty['MARKET']['ocena'] == 'D' and 'LIMIT' not in ty, r   # V6.273: bez limitu na retest
            m5c = m5.copy(); m5c[0, H] = 100 + 2.1 * R
            assert setupy_sygnalowe_teraz_v267({'BTCUSDT': df}, {'BTCUSDT': {'arr': {'4h': aa, '5m': m5c}, 'forming': {}}}, now) == []
        finally:
            globals()['_v230_sygnaly'] = orig; globals()['_v230_cechy'] = oc
    finally:
        _V267.clear(); _V267.update(keep)
