def test_v267():
    n = 120
    t = np.arange(n) * 4 * HOUR_MS
    a = np.zeros((n, 8)); a[:, T] = t - 4 * HOUR_MS
    c = 100 + np.arange(n) * 0.0; a[:, C] = c; a[:, H] = c + 1; a[:, L] = c - 1; a[:, O] = c
    a[61:, C] = 110; a[61:, H] = 111; a[61:, L] = 109.5            # po sygnale w gore -> TP
    atr = _v267_atr(a)
    w = _v267_sym(a, 60, 1, atr[60], 2.0)
    assert w is not None and w > 1.9, w
    w2 = _v267_sym(a, 60, -1, atr[60], 2.0)
    assert w2 is not None and w2 < -0.9, w2
    rng = np.random.default_rng(1)
    df = pd.DataFrame({'t': t, 'ls': 1.5, 'top': 1.0, 'oi': 1e9, 'fund': 1e-4, 'liq_long': 100.0 + rng.uniform(0, 50, n),
                       'liq_short': 100.0 + rng.uniform(0, 50, n)})
    df.loc[60, 'liq_short'] = 1e7                               # kaskada shortow -> w gore
    wyn = badanie_setupow_sygnalowych_v267({'BTCUSDT': df}, {'BTCUSDT': a})
    k = [x for x in wyn if x['sygnal'].startswith('likwidacje') and x['rr'] == 2.0]
    assert k and k[0]['n'] >= 1 and k[0]['sr_R'] > 1.5, wyn
    return 'PASS (symulacja SL/TP z kosztami, kaskada -> transakcja w strone, tabela)'


def test_v265():
    """V6.265: nowe typy wykrywaja wybicie z retestem i wsparcie z 2 dotknieciami; sa wylaczone (tylko obserwacja)."""
    n = 200
    t0 = 1_790_000_000_000
    def arr(c, h, l, v, step):
        a = np.zeros((len(c), 8)); a[:, O] = c; a[:, H] = h; a[:, L] = l; a[:, C] = c; a[:, V] = v; a[:, T] = t0 + np.arange(len(c)) * step
        return a
    c = np.full(n, 100.0); h = c + 0.5; l = c - 0.5; v = np.full(n, 10.0)
    c[-5:] = 103.0; h[-5:] = 103.5; l[-5:] = 102.5; v[-5] = 50
    a1 = arr(c, h, l, v, HOUR_MS)
    c4 = np.linspace(80, 103, 100); a4 = arr(c4, c4 + 0.5, c4 - 0.5, np.full(100, 10.0), 4 * HOUR_MS)
    a5 = arr(np.full(300, 103.0), np.full(300, 103.2), np.full(300, 102.8), np.full(300, 1.0), 5 * 60_000)
    A = {'1h': a1, '4h': a4, '15m': a5, '5m': a5}
    f = {'atr1': 1.0, 'rs_btc_24h': 2.0}
    r = setup_retest_long(1, A, f, 103.0)
    assert r and abs(r['entry'] - 100.6) < 1e-9 and abs(r['sl'] - 99.5) < 1e-9, r
    assert setup_retest_long(1, A, dict(f, rs_btc_24h=-1), 103.0) is None and setup_retest_long(-1, A, f, 103.0) is None
    c2 = np.full(n, 105.0); l2 = c2 - 0.3; h2 = c2 + 0.3
    l2[60] = 100.0; l2[120] = 100.2; c2[-1] = 101.0
    A2 = dict(A, **{'1h': arr(c2, h2, l2, np.full(n, 10.0), HOUR_MS)})
    w = setup_wsparcie_long(1, A2, {'atr1': 1.0}, 101.0)
    assert w and abs(w['entry'] - 100.2) < 1e-9 and abs(w['sl'] - 99.0) < 1e-9, w
    assert setup_wsparcie_long(1, A2, {'atr1': 1.0}, 104.0) is None
    assert typ_wylaczony('RETEST_LONG', 'LONG') and typ_wylaczony('WSPARCIE_LONG', 'LONG')
    return 'PASS (retest po wybiciu, wsparcie z 2 dotknieciami, oba typy tylko obserwacja)'


