def test_v259():
    """V6.259: nowe sygnaly (zmiany 24h, nierownowaga likwidacji), weekend kontra bez lookahead."""
    n = 300
    t = np.arange(n) * 4 * HOUR_MS
    df = pd.DataFrame({'t': t, 'ls': 1.5 + 0.01 * np.sin(np.arange(n)), 'top': 1.0 + 0.01 * np.cos(np.arange(n)), 'oi': 1e9, 'fund': 1e-4,
                       'liq_long': 100.0, 'liq_short': 100.0})
    df.loc[n - 1, 'top'] = 3.0
    df.loc[n - 6:n - 1, 'liq_short'] = 1e5
    c = _v230_cechy(df)
    r = c.iloc[-1].to_dict(); r['ch24'] = 0.0; r['_sym'] = 'BTCUSDT'
    s = _v230_sygnaly(r)
    assert s['top traderzy zmiana 24h (za nimi)'] == 1 and s['likwidacje 24h nierownowaga (w strone)'] == 1
    r0 = c.iloc[150].to_dict(); r0['ch24'] = 0.0
    assert _v230_sygnaly(r0)['top traderzy zmiana 24h (za nimi)'] == 0
    # weekend: sztuczna seria - po kazdym wzroscie weekendu spadek w poniedzialek
    t0 = int(pd.Timestamp('2025-01-04', tz='UTC').value // 10 ** 6)        # sobota
    tt = t0 + np.arange(6 * 7 * 60) * 4 * HOUR_MS - 4 * HOUR_MS
    cc = np.full(len(tt), 100.0)
    ser = pd.Series(cc, index=tt + 4 * HOUR_MS)
    for w_ in range(60):
        sob = t0 + w_ * 7 * DAY_MS
        ser[(ser.index > sob) & (ser.index <= sob + 2 * DAY_MS)] = 103.0
        ser[(ser.index > sob + 2 * DAY_MS) & (ser.index <= sob + 4 * DAY_MS)] = 101.0
    d = pd.DataFrame({'t': tt, 'c': ser.values})
    w = badanie_weekendu_v259({'BTCUSDT': d})
    assert w['n'] >= 50 and w['traf_24h'] == 100.0, w
    return 'PASS (zmiana top 24h, nierownowaga likwidacji, weekend kontra)'


