def test_v249():
    """V6.249: dane z paczki 11:20 - top vs tlum i stablecoiny przechodza prog lagodny (ocena -1), kapitulacja OI nie."""
    def w(nm, a, b):
        d = {'sygnal': nm}
        for pr, (n, rp, rr, tr) in zip(('30d', 'archiwum'), (a, b)):
            d.update({f'{pr}_n_przeciw': n, f'{pr}_R_przeciw': rp, f'{pr}_R_reszta': rr, f'{pr}_roznica_tercje': tr})
        return d
    przyp = [w('top vs tlum (za top)', (255, -0.47, -0.132, [-0.093, -0.696, -0.19]), (1320, -0.284, -0.071, [-0.662, -0.204, 0.042])),
             w('stablecoiny 7d (za nimi)', (1466, -0.333, -0.075, [-0.331, -0.17, -0.276]), (7729, -0.232, -0.01, [-0.725, 0.027, -0.012])),
             w('kapitulacja OI (kontra)', (21, -0.434, -0.147, [None, None, -0.22]), (117, -0.555, -0.081, [None, None, -0.307])),
             w('top traderzy (za nimi)', (368, -0.326, -0.135, [-0.194, -0.351, -0.179]), (1131, -0.283, -0.073, [-0.56, -0.28, 0.045]))]
    wyn = {d['sygnal']: _v249_werdykt(d, d['sygnal']) for d in przyp}
    assert wyn['top vs tlum (za top)'].startswith('FILTR: ocena -1 (') and wyn['stablecoiny 7d (za nimi)'].startswith('FILTR: ocena -1 ('), wyn
    assert not wyn['kapitulacja OI (kontra)'].startswith('FILTR') and not wyn['top traderzy (za nimi)'].startswith('FILTR'), wyn
    return 'PASS (top vs tlum i stablecoiny -> ocena -1, kapitulacja OI za malo, top traderzy spoza listy)'


def test_v248():
    """V6.248: przeciw = strona przeciwna do sygnalu BTC; filtr tylko gdy wszystkie tercje obu prob ujemne; ocena -1."""
    import tempfile
    rng = np.random.default_rng(3)
    t0 = 1_790_000_000_000
    n = 600
    tt = t0 + np.arange(n) * HOUR_MS
    sig = pd.DataFrame({'t': tt, 'top vs tlum (za top)': np.where(np.arange(n) % 2, -1, 1), 'L/S skrajny (kontra)': 0})
    side = np.where(rng.random(n) > 0.5, 'LONG', 'SHORT')
    s = np.where(side == 'LONG', 1, -1)
    r = np.where(s == sig['top vs tlum (za top)'].values, 0.4, -0.6) + rng.normal(0, 0.05, n)
    h = pd.DataFrame({'snapshot_utc': pd.to_datetime(tt + 60_000, unit='ms', utc=True).astype(str), 'side': side, 'r': r,
                      'status': 'SL', 'asset_type': 'COIN', 'btc_trend_1h': 0, 'btc_trend_4h': 1})
    wyn = badanie_setupy_btc_v248(h, h.copy(), [('poz', sig, 2 * HOUR_MS)])
    w = {x['sygnal']: x for x in wyn}
    assert w['top vs tlum (za top)']['wniosek'] == 'FILTR: BLOKADA', w['top vs tlum (za top)']
    assert w['top vs tlum (za top)']['30d_R_przeciw'] < -0.5 and w['top vs tlum (za top)']['30d_R_zgodne'] > 0.3
    assert w['L/S skrajny (kontra)']['wniosek'] == 'brak setupow przeciw sygnalowi'
    keep = (dict(_V248), dict(_V230), dict(_V243), dict(_V246))
    try:
        w['top vs tlum (za top)']['wniosek'] = 'FILTR: ocena -1'
        _V248['wynik'] = list(w.values())
        _V230['teraz'] = {'BTCUSDT': {'syg': {'top vs tlum (za top)': -1}}}
        _V243['dni_teraz'] = {}; _V246['teraz'] = {}
        with tempfile.TemporaryDirectory() as d:
            pd.DataFrame([{'symbol': 'AUSDT', 'side': 'LONG', 'ocena': 'B', 'asset_type': 'COIN'},
                          {'symbol': 'BUSDT', 'side': 'SHORT', 'ocena': 'B', 'asset_type': 'COIN'},
                          {'symbol': 'NVDAUSDT', 'side': 'LONG', 'ocena': 'D', 'asset_type': 'Stocks'}]).to_csv(Path(d) / 'top_market.csv', index=False)
            assert zastosuj_v248(d) == 1
            x = pd.read_csv(Path(d) / 'top_market.csv')
            assert list(x.ocena) == ['C', 'B', 'D'] and 'przeciw BTC' in x.zdarzenie_v242[0] and 'zgodne' in x.zdarzenie_v242[1]
    finally:
        for dct, k in zip((_V248, _V230, _V243, _V246), keep):
            dct.clear(); dct.update(k)
    return 'PASS (przeciw/zgodne, filtr tylko przy stalej roznicy, ocena -1, TradFi bez zmian)'


