def test_v246():
    """V6.246: sygnaly tylko z przeszlosci (zmiana przyszlych swiec nie zmienia sygnalu), odstep zdarzen, test na danych."""
    rng = np.random.default_rng(7)
    n = 1500
    c = 100 * np.exp(np.cumsum(rng.normal(0, 0.01, n)))
    df = pd.DataFrame({'t': np.arange(n, dtype='int64') * 4 * HOUR_MS, 'o': c, 'h': c * 1.006, 'l': c * 0.994, 'c': c,
                       'v': rng.uniform(80, 120, n), 'tb': rng.uniform(30, 70, n)})
    a = _v246_sygnaly(df)
    df2 = df.copy(); df2.loc[1000:, ['c', 'h', 'l', 'o']] *= 1.5
    b = _v246_sygnaly(df2)
    cols = list(ZT_OPIS)
    assert (a.loc[:999, cols].values == b.loc[:999, cols].values).all(), 'lookahead'
    assert a.t.iat[0] == 4 * HOUR_MS
    for nm in cols:
        ix = _v246_zdarzenia(a, nm)
        k = a[nm].values
        for i, j in zip(ix, ix[1:]):
            assert k[i] != k[j] or j - i >= ZT_ODSTEP
    wyn, teraz = badanie_zmiany_trendu_v246({'BTCUSDT': df, 'SOLUSDT': df2}, int(df.t.iat[-1]))
    assert len(wyn) == len(cols) and 'BTCUSDT' in teraz and all('wniosek' in w for w in wyn)
    keep = dict(_V246)
    try:
        _V246.update(wynik=[{'sygnal': cols[0], 'wniosek': 'DZIALA', 'traf_48h': 60}], teraz={'BTCUSDT': {cols[0]: -1, '_t': 0}})
        assert 'SHORT' in zmiana_trendu_teraz_v246()['BTCUSDT']
    finally:
        _V246.clear(); _V246.update(keep)
    return 'PASS (bez lookahead, odstep zdarzen, test i linia teraz)'


