def test_v241():
    """V6.241: model kierunku - uczy sie prostej zaleznosci, walk-forward bez zagladania, prognoza biezaca."""
    rng = np.random.default_rng(7)
    n = 900
    t = (np.arange(n) * 4 + 4) * HOUR_MS
    ls = rng.normal(0, 1, n)
    cc = np.empty(n + 10); cc[0] = 100.0
    for i in range(1, n + 10):                       # tlum przeladowany LONG (wysokie ls) -> cena spada w kolejnych 24h
        cc[i] = cc[i - 1] * (1 - 0.002 * (ls[i - 1] if i - 1 < n else 0) + rng.normal(0, 0.003))
    a = np.zeros((n + 10, 8)); a[:, T] = np.arange(n + 10) * 4 * HOUR_MS; a[:, C] = cc
    df = pd.DataFrame({'t': t, 'ls': 1 + 0.1 * ls, 'oi': 1000.0, 'fund': 0.0001})
    wyn, teraz = model_kierunku_v241({'ETHUSDT': df}, {'ETHUSDT': a})
    assert wyn and wyn['oos_n'] > 0 and 'ETHUSDT' in teraz and 0 <= teraz['ETHUSDT'] <= 1
    assert wyn['wagi']['ls_z'] < 0, wyn['wagi']
    assert model_kierunku_v241({}, {}) == (None, {})
    return 'PASS (uczy sie zaleznosci L/S -> spadek, walk-forward, prognoza 0-1, puste dane)'


def test_v240():
    """V6.240: dywergencja szerokosci, kapitulacja OI, reset fundingu, skok DVOL."""
    n = 60; t = np.arange(n) * 4 * HOUR_MS
    def arr(c):
        a = np.zeros((n, 8)); a[:, T] = t; a[:, C] = c; return a
    btc = np.r_[np.linspace(100, 90, n - 1), 85.0]           # BTC nowy dolek na koncu
    alt = np.r_[np.linspace(100, 90, 40), np.linspace(90, 95, n - 40)]   # alty juz nie
    x = szerokosc_dywergencja_v240({'BTCUSDT': arr(btc), 'ETHUSDT': arr(alt), 'SOLUSDT': arr(alt)})
    assert x.szer_div.iloc[-1] == 1
    s_ = _v230_sygnaly({'ch24': -4, 'oi_24h': -7, 'fund_z': -0.5, 'fund_z_24h_temu': 2.0, 'szer_div': 1, 'dvol_z': 2.5})
    assert s_['kapitulacja OI (kontra)'] == 1 and s_['reset fundingu (kontra)'] == 1 and s_['dywergencja szerokosci (zwrot)'] == 1
    assert s_['DVOL skok (panika = zwrot)'] == 1
    assert _v230_sygnaly({'ch24': 4, 'oi_24h': -7})['kapitulacja OI (kontra)'] == -1
    return 'PASS (dywergencja szerokosci, kapitulacja OI, reset fundingu, skok DVOL)'


def test_v239():
    """V6.239: indeks ALT/BTC, doklejanie premium (bez lookahead), sygnaly premium i altow."""
    n = 80
    t = np.arange(n) * 4 * HOUR_MS
    def arr(c):
        a = np.zeros((n, 8)); a[:, T] = t; a[:, C] = c; return a
    btc = arr(100 * np.ones(n)); alt = arr(100 * np.exp(np.arange(n) * 0.01))
    x = alt_btc_v239({'BTCUSDT': btc, 'ETHUSDT': alt})
    assert len(x) == n and x.alt_idx.iloc[-1] > x.alt_idx.iloc[10] and x.t.iloc[0] == 4 * HOUR_MS
    cbp = pd.DataFrame({'t': np.arange(4 * n) * HOUR_MS, 'premium_pct': np.r_[np.zeros(4 * n - 4), np.ones(4)]})
    dane = {'ETHUSDT': pd.DataFrame({'t': t, 'ls': 1.0})}
    d = _v239_dolacz(dane, cbp, x)['ETHUSDT']
    assert 'cbp' in d and 'alt_idx' in d and d.cbp.iloc[-2] == 0                      # premium z przyszlosci nie wchodzi wczesniej
    s_ = _v230_sygnaly({'cbp_z': 2.0, 'alt_z': -2.0, '_sym': 'ETHUSDT'})
    assert s_['Coinbase premium (za nim)'] == 1 and s_['alty vs BTC 24h (za nimi)'] == -1 and s_['alty vs BTC 24h (kontra)'] == 1
    assert 'alty vs BTC 24h (za nimi)' not in _v230_sygnaly({'alt_z': -2.0, '_sym': 'BTCUSDT'})
    return 'PASS (indeks ALT/BTC, premium bez zagladania w przod, sygnaly premium/altow, BTC bez sygnalu altow)'


