def test_v230():
    """V6.230: cechy (z-score, OI 24h), sygnaly kontra, badanie w tercjach, prawdopodobienstwo tylko z sygnalow DZIALA."""
    n = 400
    t = (np.arange(n) * 4 + 4) * HOUR_MS
    rng = np.random.default_rng(3)
    ls = 0.5 + rng.normal(0, 0.02, n); ls[300:] = 0.62                  # tlum przeladowany LONG na koncu
    df = pd.DataFrame({'t': t, 'ls': ls, 'oi': 1000 + np.arange(n), 'fund': rng.normal(0.0001, 0.00005, n)})
    d = _v230_cechy(df)
    assert d.ls_z.iloc[305] > POZ_Z_PROG and abs(d.oi_24h.iloc[-1]) < 1
    s_ = _v230_sygnaly({'ls_z': 2.0, 'fund_z': 2.0, 'oi_24h': 5, 'ch24': 3})
    assert s_['L/S skrajny (kontra)'] == -1 and s_['funding skrajny (kontra)'] == -1 and s_['OI rosnie z ruchem (kontra)'] == -1 and s_['razem (>=2 zgodne)'] == -1
    a = np.zeros((n + 10, 8)); a[:, T] = np.arange(n + 10) * 4 * HOUR_MS; a[:, C] = 100 - np.arange(n + 10) * 0.01
    bad = badanie_pozycji_v230({'BTCUSDT': df}, {'BTCUSDT': a})
    b = next(x for x in bad if x['sygnal'] == 'L/S skrajny (kontra)')
    assert b['traf_24h_pct'] > 50 and b['sr_24h_bps'] > 0                    # LONG przeladowany -> spadek = trafione
    keep = list(_V230['badanie'])
    try:
        _V230['badanie'] = bad
        tz = pozycje_teraz_v230({'BTCUSDT': df}, {})
        assert 'BTCUSDT' in tz and tz['BTCUSDT']['ls_z'] is not None
    finally:
        _V230['badanie'] = keep
    s2 = _v230_sygnaly({'liq_long_z': 3.0, 'liq_short_z': 0.5, 'top_z': -2.0})      # V6.231
    assert s2['likwidacje skrajne (kaskada, w strone)'] == -1
    assert s2['likwidacje skrajne (odbicie)'] == 1 and s2['top traderzy (za nimi)'] == -1 and s2['razem (>=2 zgodne)'] == 0
    df2 = df.assign(top=1.0 + rng.normal(0, 0.1, n), liq_long=rng.uniform(0, 1e6, n), liq_short=rng.uniform(0, 1e6, n))
    d2 = _v230_cechy(df2)
    assert {'top_z', 'liq_long_z', 'liq_short_z'} <= set(d2.columns)
    return 'PASS (z-score, OI 24h, sygnaly kontra, likwidacje i top traderzy, trafnosc w tercjach, opis biezacy)'


def test_v229():
    """V6.229: symulacja 4h (SL/TP/timeout, koszty), strategie na syntetycznych swiecach, podsumowanie w tercjach."""
    a = np.zeros((10, 8)); a[:, O] = 100; a[:, C] = 100; a[:, H] = 101; a[:, L] = 99; a[:, T] = np.arange(10) * 4 * HOUR_MS
    a[3, H] = 105                                                        # TP 2R dla LONG (risk 2): 104
    r = _v229_symuluj(a, 1, 1, 98.0, (2.0,), max_bars=5)
    assert abs(r[2.0] - (2.0 - MAJORS_KOSZT * 100 / 2)) < 1e-9
    a[2, L] = 97.5                                                       # SL wczesniej niz TP
    assert _v229_symuluj(a, 1, 1, 98.0, (2.0,), max_bars=5)[2.0] < -1
    rng = np.random.default_rng(1); n = 400
    c = 100 + np.cumsum(rng.normal(0, 1, n)); b = np.zeros((n, 8))
    b[:, C] = c; b[:, O] = np.r_[c[0], c[:-1]]; b[:, H] = np.maximum(b[:, O], c) + 0.5; b[:, L] = np.minimum(b[:, O], c) - 0.5
    b[:, T] = np.arange(n) * 4 * HOUR_MS
    df, pod = badanie_majors_4h_v229({'BTCUSDT': b, 'ETHUSDT': b.copy()})
    assert len(df) and {'S1 struktura 4h z trendem', 'S2 falszywe wybicie 5 dni'} <= set(df.strategia)
    assert all(p_['wniosek'] in ('KANDYDAT (dodatni we wszystkich tercjach)', 'brak przewagi') for p_ in pod)
    return 'PASS (SL przed TP, koszty, timeout, strategie S1-S3, tercje)'


def test_v228():
    """V6.228: dziennik kierunku - ruch po 4h/12h w strone oceny, trafnosc, dopisek przeciw BTC."""
