def _test_v224_blokada():
    """V6.224: segment duzych - rozpoznanie, tryb ochronny segmentu z oknem 3/7 dni i fallback, warunki."""
    assert _v224_duzy({'setup_type': 'CONT_SWEEP', 'side': 'SHORT', 'vol_rank': 12, 'asset_type': 'COIN'})
    assert not _v224_duzy({'setup_type': 'CONT_SWEEP', 'side': 'SHORT', 'vol_rank': 31})
    assert not _v224_duzy({'setup_type': 'CONT_SWEEP', 'side': 'LONG', 'vol_rank': 5})
    assert not _v224_duzy({'setup_type': 'CONT_SWEEP', 'side': 'SHORT', 'vol_rank': None})
    now = parse_utc('2026-11-02T12:00')
    mk = lambda h, r_, vr=10: {'snapshot_utc': snap_iso(now - h * HOUR_MS), 'status': 'SL' if r_ < 0 else 'TP1', 'filtr': '', 'r': r_,
                               'vol_rank': vr, 'setup_type': 'CONT_SWEEP', 'side': 'SHORT'}
    a = pd.DataFrame([mk(10, 1.0)] * 8 + [mk(10, -1.0, 80)] * 30)
    seg = _v224_ochrona_segment(a, now)
    assert seg['aktywny'] is False and seg['n'] == 8 and seg['dni'] == OCHRONA_DNI
    b = pd.DataFrame([mk(10, -1.0)] * 3 + [mk(5 * 24, -0.5)] * 6)
    seg = _v224_ochrona_segment(b, now)
    assert seg['aktywny'] is True and seg['n'] == 9 and seg['dni'] == 7
    assert _v224_ochrona_segment(pd.DataFrame([mk(10, 1.0)] * 3), now) is None
    och = {'strony': {'SHORT': {'aktywny': True, 'sredni_R': -0.3}, 'LONG': {'aktywny': False}},
           'segment_duze': {'aktywny': False, 'n': 9, 'sredni_R': 0.2, 'dni': 3}}
    rr = [{'symbol': 'BTCUSDT', 'side': 'SHORT', 'setup_type': 'CONT_SWEEP', 'vol_rank': 3, 'regime_1h': 'trend', 'ocena': 'B'},
          {'symbol': 'XUSDT', 'side': 'SHORT', 'setup_type': 'CONT_SWEEP', 'vol_rank': 90, 'regime_1h': 'trend', 'ocena': 'B'}]
    apply_conditions(rr, None, och, None)
    assert 'tryb ochronny SHORT (' not in rr[0]['warunki'] and 'tryb ochronny SHORT (' in rr[1]['warunki']
    och['segment_duze'] = None
    rr2 = [{k: v for k, v in rr[0].items() if k not in ('warunki', 'do_handlu')}]; apply_conditions(rr2, None, och, None)
    assert 'tryb ochronny SHORT (' in rr2[0]['warunki']          # brak danych segmentu -> jak dotad
    return 'PASS (duze top30 CS SHORT, okno 3/7 dni, fallback na tryb strony, reszta bez zmian)'


