def _v200_weekend(rows, ts_ms):
    """V6.200: krypto (COIN) w sobote/niedziele UTC -> filtr 'weekend'. TradFi bez zmian (decyzja uzytkownika)."""
    if WEEKEND_KRYPTO is None or not rows:
        return 0
    if datetime.fromtimestamp(ts_ms / 1000, tz=timezone.utc).weekday() < 5:
        return 0
    n = 0
    for r in rows:
        if r.get('asset_type') != 'COIN':
            continue
        if WEEKEND_KRYPTO == 'BEZ_ODBICIA' and r.get('setup_type') in ('ODBICIE', 'CROWD'):
            continue
        f0 = r.get('filtr')
        f0 = f0 if isinstance(f0, str) else ''
        if 'weekend' not in f0.split(';'):
            r['filtr'] = ';'.join(x for x in (f0, 'weekend') if x)
            n += 1
    return n


