# =================== V6.189: identyfikacja uruchomionego pliku ===================
_V189_KLUCZE = ('WEEX_EXECUTED_FILE','WEEX_EXPECTED_SHA256','WEEX_LAUNCH_SHA256',
                'WEEX_LAUNCHER_VERSION','WEEX_LAUNCH_TARGET_VERSION')
_V189_STAN = {}


def _v189_wersja_pliku(path):
    import re
    try:
        raw = Path(path).read_bytes()
    except OSError:
        return None, None
    m = re.search(rb"(?m)^VERSION\s*=\s*['\"](V6\.\d+)['\"]\s*$", raw)
    return (m.group(1).decode('ascii') if m else None), hashlib.sha256(raw).hexdigest()


def _v189_kandydat(plik_modulu=None, katalogi=None):
    """Zwraca (sciezka, zrodlo). 1) __file__ (runpy/%run), 2) jedyny plik weex_v6_*.py z VERSION == biezaca."""
    if plik_modulu and str(plik_modulu).endswith('.py') and Path(plik_modulu).is_file():
        return str(Path(plik_modulu).resolve()), '__file__'
    znalezione = {}
    for d in (katalogi if katalogi is not None else ['/content', os.getcwd()]):
        try:
            for f in sorted(Path(d).glob('weex_v6_*.py')):
                wer, sha = _v189_wersja_pliku(f)
                if wer == VERSION:
                    znalezione.setdefault(sha, str(f.resolve()))
        except OSError:
            continue
    if len(znalezione) == 1:
        return next(iter(znalezione.values())), 'WYSZUKANIE_PO_WERSJI'
    if len(znalezione) > 1:
        return None, 'NIEJEDNOZNACZNE_%d_ROZNYCH_PLIKOW' % len(znalezione)
    return None, 'NIE_ZNALEZIONO'


def _v189_synchronizuj_launcher(plik_modulu=None, katalogi=None):
    """Wykrywa nieaktualne zmienne launchera z poprzedniego uruchomienia w tej samej sesji Colab.
    Nieaktualne -> zapisuje je w raporcie i zastepuje identyfikacja biezacego pliku (bez udawania dowodu launchera).
    Prawdziwa niezgodnosc (ten sam plik, inny hash) -> zostaje jawne ostrzezenie."""
    if os.environ.get('WEEX_LAUNCHER_VERSION') == 'AUTO_V202':   # V6.202: wpis z auto-identyfikacji poprzedniego uruchomienia
        for k in _V189_KLUCZE:
            os.environ.pop(k, None)
    env = {k: os.environ.get(k) for k in _V189_KLUCZE}
    sciezka, zrodlo = _v189_kandydat(plik_modulu, katalogi)
    wer, sha = _v189_wersja_pliku(sciezka) if sciezka else (None, None)
    env_path = (env['WEEX_EXECUTED_FILE'] or '').strip()
    env_wer = _v189_wersja_pliku(env_path)[0] if env_path else None
    try:
        ten_sam = bool(sciezka and env_path and Path(env_path).resolve() == Path(sciezka).resolve())
    except OSError:
        ten_sam = False
    nieaktualne = bool(env_path) and (not ten_sam if sciezka else env_wer != VERSION)
    if sciezka and ten_sam and sha and (env['WEEX_EXPECTED_SHA256'] or '').strip().lower() not in ('', sha):
        status = 'ROZBIEZNOSC_HASH_TEN_SAM_PLIK'          # plik zmieniony po uruchomieniu launchera
    elif sciezka and wer != VERSION:
        status = 'ROZBIEZNOSC_WERSJI_PLIKU'
    elif sciezka and ten_sam and not nieaktualne:
        status = 'LAUNCHER_AKTUALNY'
    elif sciezka:
        status = 'ZIDENTYFIKOWANO_AUTOMATYCZNIE'
    else:
        status = 'NIEZIDENTYFIKOWANO_' + zrodlo
    wyczyszczone = {}
    if nieaktualne and sciezka and status == 'ZIDENTYFIKOWANO_AUTOMATYCZNIE':
        wyczyszczone = {k: v for k, v in env.items() if v is not None}
        for k in _V189_KLUCZE:
            os.environ.pop(k, None)
        # Sciezka i hash z identyfikacji; WEEX_LAUNCH_SHA256 celowo puste - to nie jest dowod launchera.
        os.environ['WEEX_EXECUTED_FILE'] = sciezka
        os.environ['WEEX_EXPECTED_SHA256'] = sha
    if status == 'ZIDENTYFIKOWANO_AUTOMATYCZNIE' and sciezka and sha and not (os.environ.get('WEEX_EXECUTED_FILE') or '').strip():
        # V6.202: bez launchera - sciezka i hash z identyfikacji dla wszystkich raportow SHA (oznaczone AUTO_V202, nie launcher)
        os.environ.update(WEEX_EXECUTED_FILE=sciezka, WEEX_EXPECTED_SHA256=sha, WEEX_LAUNCHER_VERSION='AUTO_V202')
    _V189_STAN.clear()
    _V189_STAN.update({'wersja': VERSION, 'status_v189': status, 'zrodlo_identyfikacji': zrodlo,
        'plik': sciezka, 'wersja_pliku': wer, 'sha256': sha,
        'launcher_nieaktualny': nieaktualne, 'launcher_poprzedni_plik': env_path or None,
        'launcher_poprzednia_wersja': env_wer,
        'wyczyszczone_zmienne': sorted(wyczyszczone),
        'stare_wartosci': {k: (v if k in ('WEEX_EXECUTED_FILE','WEEX_LAUNCHER_VERSION','WEEX_LAUNCH_TARGET_VERSION') else (v or '')[:12] + '...')
                           for k, v in wyczyszczone.items()},
        'ostrzezenie': ({'ROZBIEZNOSC_HASH_TEN_SAM_PLIK': 'Plik zmienil sie po uruchomieniu launchera - wyniki moga pochodzic z innego kodu.',
                         'ROZBIEZNOSC_WERSJI_PLIKU': 'Zidentyfikowany plik ma inna VERSION niz wykonywany kod.'}.get(status)
                        or ('Dane launchera pochodzily z poprzedniego uruchomienia (%s) i zostaly wyczyszczone.' % (env_wer or env_path)
                            if wyczyszczone else None)),
        'ograniczenie': 'Hash potwierdza bajty pliku na dysku, nie jest niezaleznym dowodem wykonania.'})
    return dict(_V189_STAN)


def _v336_source_identity(main_func=None):
    """Conservative source identity, not cryptographic execution attestation."""
    import inspect, sys
    candidates=[]
    # %run usually supplies __file__, while exec may not.
    for val in (globals().get('__file__'),
                inspect.getsourcefile(main_func) if main_func else None,
                sys.argv[0] if sys.argv else None,
                os.environ.get('WEEX_EXECUTED_FILE')):
        if val and str(val).endswith('.py'):
            resolved=str(Path(val).expanduser().resolve())
            if resolved not in candidates:candidates.append(resolved)
    matching=[]
    for path in candidates:
        ver,sha=_v189_wersja_pliku(path)
        if ver==VERSION and sha:matching.append((path,sha))
    if len({sha for _,sha in matching})==1:
        path,sha=matching[0]
        return {'status':'ZIDENTYFIKOWANY_PLIK_NA_DYSKU','file_path':path,'sha256':sha,
                'verification':'SHA256 PLIKU NA DYSKU, NIE DOWOD WYKONANIA'}
    if matching:
        return {'status':'NIEJEDNOZNACZNE_WIELE_HASHY','candidates':[p for p,_ in matching],
                'sha256':None,'verification':'BRAK POTWIERDZENIA'}
    return {'status':'NIEZIDENTYFIKOWANO','candidates':candidates,'sha256':None,
            'verification':'BRAK POTWIERDZENIA; użyj %run /content/weex_v6_336.py'}

def test_v189():
    import tempfile
    keep = {k: os.environ.get(k) for k in _V189_KLUCZE}
    try:
        with tempfile.TemporaryDirectory() as d:
            nowy = Path(d)/'weex_v6_999.py'; nowy.write_text("VERSION = '%s'\n" % VERSION)
            stary = Path(d)/'weex_v6_000.py'; stary.write_text("VERSION = 'V6.000'\n")
            # 1) stare dane launchera -> wyczyszczone, identyfikacja z __file__
            os.environ.update(WEEX_EXECUTED_FILE=str(stary), WEEX_EXPECTED_SHA256='a'*64, WEEX_LAUNCH_SHA256='a'*64,
                              WEEX_LAUNCHER_VERSION='UNIWERSALNY_V2', WEEX_LAUNCH_TARGET_VERSION='V6.000')
            r = _v189_synchronizuj_launcher(str(nowy), [])
            assert r['status_v189'] == 'ZIDENTYFIKOWANO_AUTOMATYCZNIE' and r['launcher_nieaktualny'], r
            assert os.environ['WEEX_EXECUTED_FILE'] == str(nowy.resolve()) and 'WEEX_LAUNCH_SHA256' not in os.environ
            # 2) aktualny launcher -> bez zmian
            sha = hashlib.sha256(nowy.read_bytes()).hexdigest()
            os.environ.update(WEEX_EXECUTED_FILE=str(nowy), WEEX_EXPECTED_SHA256=sha, WEEX_LAUNCH_SHA256=sha)
            assert _v189_synchronizuj_launcher(str(nowy), [])['status_v189'] == 'LAUNCHER_AKTUALNY'
            # 3) ten sam plik, inny hash -> jawna rozbieznosc, zmienne nietkniete
            os.environ['WEEX_EXPECTED_SHA256'] = 'b'*64
            r = _v189_synchronizuj_launcher(str(nowy), [])
            assert r['status_v189'] == 'ROZBIEZNOSC_HASH_TEN_SAM_PLIK' and os.environ['WEEX_EXPECTED_SHA256'] == 'b'*64
            # 4) brak __file__ (exec) -> wyszukanie po wersji w katalogu
            for k in _V189_KLUCZE: os.environ.pop(k, None)
            r = _v189_synchronizuj_launcher(None, [d])
            assert r['zrodlo_identyfikacji'] == 'WYSZUKANIE_PO_WERSJI' and r['plik'] == str(nowy.resolve())
            # 5) dwa rozne pliki z ta sama wersja -> niejednoznaczne
            (Path(d)/'weex_v6_998.py').write_text("VERSION = '%s'\n# inny\n" % VERSION)
            assert _v189_synchronizuj_launcher(None, [d])['status_v189'].startswith('NIEZIDENTYFIKOWANO_NIEJEDNOZNACZNE')
    finally:
        for k, v in keep.items():
            if v is None: os.environ.pop(k, None)
            else: os.environ[k] = v
    return 'PASS (stary launcher czyszczony, aktualny bez zmian, prawdziwa rozbieznosc zostaje, exec -> wyszukanie, niejednoznacznosc)'


# =================== V6.189: przyczyny roznic zdarzen OOS ===================
def _v189_przyczyny_roznic(differences, old, now, old_syms, new_syms, korekta_syms=()):
    old_syms, new_syms, korekta_syms = set(old_syms or []), set(new_syms or []), set(korekta_syms or [])
    pop_znana = bool(old_syms) and bool(new_syms)
    max_old_snap = max((v.get('snapshot_utc','') for v in (old or {}).values()), default='')
    min_new_snap = min((v.get('snapshot_utc','') for v in (now or {}).values() if v.get('snapshot_utc')), default='')
    sloty = {'aktywne_przed','aktywne_po','wybrany'}
    wiersze, liczniki = [], {}
    # V6.189: to samo zdarzenie przeniesione do innego foldu walk-forward (granice foldow przesuwaja sie z czasem)
    bez_foldu = lambda e: (e.get('rynek_analizy'), e.get('variant'), e.get('abc_id'), e.get('snapshot_utc'))
    znikniete, nowe = {}, {}
    for r in differences or []:
        if r['status'] == 'BRAK_W_NOWYM_PRZEBIEGU' and (old or {}).get(r['klucz_zdarzenia']):
            e = old[r['klucz_zdarzenia']]; znikniete.setdefault(bez_foldu(e), []).append(e)
        elif r['status'] == 'NOWE_ZDARZENIE' and (now or {}).get(r['klucz_zdarzenia']):
            e = now[r['klucz_zdarzenia']]; nowe.setdefault(bez_foldu(e), []).append(e)
    def fold_przyczyna(e, druga_strona):
        para = druga_strona.get(bez_foldu(e)) or []
        if not para: return None
        if any(x.get('decyzja') == e.get('decyzja') and x.get('r_netto') == e.get('r_netto') for x in para):
            return 'PRZESUNIECIE_FOLDU_BEZ_ZMIANY_WYNIKU'
        return 'PRZESUNIECIE_FOLDU_ZMIANA_DECYZJI'
    for r in differences or []:
        key = r['klucz_zdarzenia']; o = (old or {}).get(key); n = (now or {}).get(key)
        rec = n or o or {}
        sym = str(rec.get('abc_id','')).split('|')[0]
        zmienione = set(str(r.get('zmienione_pola','')).split(';')) - {'', 'NOWE', 'BRAK'}
        fp = (fold_przyczyna(n, znikniete) if r['status'] == 'NOWE_ZDARZENIE' and n else
              fold_przyczyna(o, nowe) if r['status'] == 'BRAK_W_NOWYM_PRZEBIEGU' and o else None)
        if fp:
            przyczyna = fp
        elif pop_znana and sym and sym in new_syms and sym not in old_syms:
            przyczyna = 'KONTRAKT_DODANY_DO_POPULACJI'
        elif pop_znana and sym and sym in old_syms and sym not in new_syms:
            przyczyna = 'KONTRAKT_USUNIETY_Z_POPULACJI'
        elif sym in korekta_syms:
            przyczyna = 'KOREKTA_HISTORII_KONTRAKTU'
        elif r['status'] == 'BRAK_W_NOWYM_PRZEBIEGU' and min_new_snap and str(rec.get('snapshot_utc','')) < min_new_snap:
            przyczyna = 'WYPADNIECIE_Z_OKNA'           # V6.190: zdarzenie starsze niz poczatek nowego okna OOS
        elif r['status'] == 'NOWE_ZDARZENIE' and str(rec.get('snapshot_utc','')) > max_old_snap:
            przyczyna = 'NOWY_CZAS_OBSERWACJI'
        elif r['status'] == 'ZMIENIONE_ZDARZENIE' and o and n and (
                (not o.get('exit_utc') and n.get('exit_utc')) or
                (zmienione and zmienione <= {'status_zrodla','exit_utc','r_netto'} and str(o.get('status_zrodla','')).lower() in ('otwarty',''))):
            przyczyna = 'ROZLICZENIE_OTWARTEJ_POZYCJI'      # V6.190: takze kandydat odrzucony, ktorego wynik sie rozstrzygnal
        elif r['status'] == 'ZMIENIONE_ZDARZENIE' and zmienione and zmienione <= sloty:
            przyczyna = 'EFEKT_SLOTOW_INNYCH_ZDARZEN'
        elif r['status'] in ('NOWE_ZDARZENIE','BRAK_W_NOWYM_PRZEBIEGU') and pop_znana and old_syms != new_syms:
            przyczyna = 'POSREDNI_EFEKT_ZMIANY_POPULACJI'   # V6.190: inne kontrakty zwolnily/zajely sloty w tym oknie
        else:
            przyczyna = 'ZMIANA_ZDARZENIA_NIEPRZYPISANA'
        liczniki[przyczyna] = liczniki.get(przyczyna, 0) + 1
        wiersze.append({'klucz_zdarzenia': key, 'symbol': sym, 'status': r['status'],
                        'zmienione_pola': r.get('zmienione_pola',''), 'przyczyna': przyczyna})
    return wiersze, {'roznice': len(wiersze), 'przyczyny': dict(sorted(liczniki.items())),
                     'populacja_znana': pop_znana,
                     'uwaga': 'Przypisanie heurystyczne: kolejnosc przesuniecie foldu > populacja > korekta historii > wypadniecie z okna > nowy czas > rozliczenie > sloty.'}


def test_v189_przyczyny():
    ev = lambda sym, snap, exit_='': {'abc_id': sym+'|SHORT|1', 'snapshot_utc': snap, 'exit_utc': exit_}
    old = {'a': ev('AAA','T1'), 'b': ev('BBB','T1'), 'c': ev('CCC','T1'), 'd': ev('DDD','T1')}
    new = {'a': ev('AAA','T1','X'), 'c': dict(ev('CCC','T1'), aktywne_po='2'), 'e': ev('EEE','T1'), 'f': ev('AAA','T2')}
    diffs = [{'klucz_zdarzenia':'a','status':'ZMIENIONE_ZDARZENIE','zmienione_pola':'exit_utc'},
             {'klucz_zdarzenia':'b','status':'BRAK_W_NOWYM_PRZEBIEGU','zmienione_pola':'BRAK'},
             {'klucz_zdarzenia':'c','status':'ZMIENIONE_ZDARZENIE','zmienione_pola':'aktywne_po'},
             {'klucz_zdarzenia':'e','status':'NOWE_ZDARZENIE','zmienione_pola':'NOWE'},
             {'klucz_zdarzenia':'f','status':'NOWE_ZDARZENIE','zmienione_pola':'NOWE'}]
    w, m = _v189_przyczyny_roznic(diffs, old, new, ['AAA','BBB','CCC','DDD'], ['AAA','CCC','DDD','EEE'])
    p = {x['klucz_zdarzenia']: x['przyczyna'] for x in w}
    assert p == {'a':'ROZLICZENIE_OTWARTEJ_POZYCJI','b':'KONTRAKT_USUNIETY_Z_POPULACJI','c':'EFEKT_SLOTOW_INNYCH_ZDARZEN',
                 'e':'KONTRAKT_DODANY_DO_POPULACJI','f':'NOWY_CZAS_OBSERWACJI'}, p
    assert m['roznice'] == 5
    f1 = {'rynek_analizy':'R','variant':'V','fold':'1','abc_id':'XXX|SHORT|1','snapshot_utc':'T1','decyzja':'W','r_netto':'-1'}
    f2 = dict(f1, fold='2'); f3 = dict(f1, fold='1', decyzja='BRAK_PROGU', r_netto='')
    d2 = [{'klucz_zdarzenia':'n1','status':'NOWE_ZDARZENIE','zmienione_pola':'NOWE'},
          {'klucz_zdarzenia':'o2','status':'BRAK_W_NOWYM_PRZEBIEGU','zmienione_pola':'BRAK'}]
    w2, _ = _v189_przyczyny_roznic(d2, {'o2': f2}, {'n1': f1}, ['XXX'], ['XXX'])
    assert {x['przyczyna'] for x in w2} == {'PRZESUNIECIE_FOLDU_BEZ_ZMIANY_WYNIKU'}
    w3, _ = _v189_przyczyny_roznic(d2, {'o2': f2}, {'n1': f3}, ['XXX'], ['XXX'])
    assert {x['przyczyna'] for x in w3} == {'PRZESUNIECIE_FOLDU_ZMIANA_DECYZJI'}
    w4, m4 = _v189_przyczyny_roznic([{'klucz_zdarzenia':'s','status':'BRAK_W_NOWYM_PRZEBIEGU','zmienione_pola':'BRAK'}],
                                    {'s': {'abc_id':'OLD|SHORT|1','snapshot_utc':'2026-10-26T21:00'}},
                                    {'t': {'abc_id':'NEW|SHORT|1','snapshot_utc':'2026-10-27T03:00'}}, ['OLD','NEW'], ['OLD','NEW'])
    assert w4[0]['przyczyna'] == 'WYPADNIECIE_Z_OKNA', w4
    oo = {'z': {'abc_id':'ZZZ|SHORT|1','snapshot_utc':'T1','status_zrodla':'otwarty'}}
    nn = {'z': {'abc_id':'ZZZ|SHORT|1','snapshot_utc':'T1','status_zrodla':'TP1'}, 'y': {'abc_id':'YYY|SHORT|1','snapshot_utc':'T1'}}
    w5, _ = _v189_przyczyny_roznic([{'klucz_zdarzenia':'z','status':'ZMIENIONE_ZDARZENIE','zmienione_pola':'status_zrodla'},
                                    {'klucz_zdarzenia':'y','status':'NOWE_ZDARZENIE','zmienione_pola':'NOWE'}],
                                   oo, nn, ['ZZZ','YYY','QQQ'], ['ZZZ','YYY'])
    assert [x['przyczyna'] for x in w5] == ['ROZLICZENIE_OTWARTEJ_POZYCJI','POSREDNI_EFEKT_ZMIANY_POPULACJI'], w5
    return 'PASS (populacja +/-, rozliczenie, sloty, nowy czas, przesuniecie foldu, wypadniecie z okna)'


