# =================== V6.193: warianty wejscia Elliott ABC (badawczo) ===================
ELLIOTT_ABC_TRADFI = False        # V6.195: hipotezy ABC na TradFi poza sekcja ELLIOTT (raport wariantow liczy je dalej)
ELLIOTT_WARIANTY_V193 = True      # raport elliott_abc_warianty_v193.csv; nie zmienia handlu
ELLIOTT_WARIANTY_KROK_H = 2       # siatka zdjec (h)
ELLIOTT_WARIANTY_CO_H = 20        # przeliczenie najwyzej raz na tyle godzin (cache na Drive)
ELLIOTT_WARIANTY_OKNO_H = 24      # ile godzin od pierwszego wykrycia C mozna czekac na warunek wejscia


def _v193_kandydaci(PP, now_ms, krok_h):
    rows = []
    step = int(krok_h * HOUR_MS)
    for sym, P in PP.items():
        a5 = P['arr'].get('5m')
        if a5 is None or len(a5) < 500:
            continue
        ts = (int(a5[0, T]) + 3 * DAY_MS) // step * step + step
        while ts < now_ms - HOUR_MS:
            A = view(P, ts)
            if enough(A):
                try:
                    price = float(A['5m'][-1, C])
                    e = elliott_struktura(A)
                    if e.get('elliott_abc_status') == 'ABC_POTENCJALNIE_ZAKONCZONE':
                        f = market_features(A, price, ts, None, light=True)[0]
                        rows.append({'sym': sym, 'ts': ts, 'price': price, 'atr': float(f['atr1']),
                                     'side': e['elliott_abc_kierunek'], 'b': e['elliott_abc_b'], 'c': e['elliott_abc_c'],
                                     'c_ms': e['elliott_abc_c_utc_ms'], 'age': e['elliott_abc_wiek_h'],
                                     'dist': e['elliott_abc_od_c_atr'], 'z4h': e['elliott_abc_zgodnosc_4h'],
                                     'asset': P.get('asset_type'),
                                     'qv24': float(A['1h'][-24:, QV].sum()) if len(A['1h']) >= 24 else None})
                except (KeyError, ValueError, TypeError, ArithmeticError, IndexError):
                    pass
            ts += step
    return rows


_V193_WARIANTY = {
    'BAZA_SWIEZY_4H_SL0.2': dict(warunek='swiezy_4h', sl_atr=0.2),
    'SL_1.0_ATR': dict(warunek='swiezy_4h', sl_atr=1.0),
    'PRZEBICIE_B_4H': dict(warunek='przebicie_b_4h', sl_atr=0.2),
    'PRZEBICIE_B_4H_SL1.0': dict(warunek='przebicie_b_4h', sl_atr=1.0),
    'PRZEBICIE_B_BEZ_4H_SL1.0': dict(warunek='przebicie_b', sl_atr=1.0),
}


def _v193_warunek(r, w):
    s = 1 if r['side'] == 'LONG' else -1
    try:
        age, dist, b = float(r['age']), float(r['dist']), float(r['b'])
    except (TypeError, ValueError):
        return False
    swiezy = age <= 12 and dist <= 1.5
    zg = r['z4h'] == 'ZGODNE'
    przebicie = s * (r['price'] - b) > 0 and dist <= 3
    return {'swiezy_4h': swiezy and zg, 'przebicie_b_4h': przebicie and zg, 'przebicie_b': przebicie}[w]


def _v193_symuluj(PP, kand, okno_h=24):
    grupy = {}
    for r in sorted(kand, key=lambda x: x['ts']):
        grupy.setdefault((r['sym'], r['side'], r['c_ms']), []).append(r)
    out = []
    for nazwa, w in _V193_WARIANTY.items():
        for (sym, side, c_ms), g in grupy.items():
            t0 = g[0]['ts']
            q = [r for r in g if r['ts'] - t0 <= okno_h * HOUR_MS and _v193_warunek(r, w['warunek'])]
            if not q:
                continue
            r0 = q[0]; s = 1 if side == 'LONG' else -1; P = PP[sym]
            entry = r0['price']; sl = float(r0['c']) - s * w['sl_atr'] * r0['atr']; risk = s * (entry - sl)
            if not (risk > 0 and np.isfinite(risk)):
                continue
            row = {'side': side, 'entry': entry, 'sl': sl, 'tp1': entry + s * 1.5 * risk, 'entry_type': 'MARKET',
                   'setup_type': 'ELLIOTT_ABC', 'wait_h': 0, 'slip_bps': historical_slip_for(P, int(r0['ts']), r0['qv24'])}
            sim = simulate(P['arr']['5m'], int(r0['ts']), row, P['fees'], funding_points(P.get('raw')))
            if sim['status'] not in FINAL or sim.get('luka_danych') or sim.get('r') is None:
                continue
            out.append({'wariant': nazwa, 'symbol': sym, 'side': side, 'asset_type': r0['asset'],
                        'snapshot_utc': snap_iso(int(r0['ts'])), 'status': sim['status'], 'r': float(sim['r'])})
    return out


def _v193_podsumuj(tr):
    if not tr:
        return []
    d = pd.DataFrame(tr); mid = sorted(d.snapshot_utc)[len(d) // 2]
    base = d[d.wariant == 'BAZA_SWIEZY_4H_SL0.2']
    bp1, bp2 = base[base.snapshot_utc < mid].r, base[base.snapshot_utc >= mid].r
    rows = []
    for (w, rynek), g in [((w, 'RAZEM'), g) for w, g in d.groupby('wariant')] + \
                         [((w, 'COIN' if a == 'COIN' else 'TRADFI'), g) for (w, a), g in d.assign(
                             a=np.where(d.asset_type == 'COIN', 'COIN', 'TRADFI')).groupby(['wariant', 'a'])]:
        p1, p2 = g[g.snapshot_utc < mid].r, g[g.snapshot_utc >= mid].r
        row = {'wariant': w, 'rynek': rynek, 'transakcje': len(g), 'sredni_R': rnd(g.r.mean(), 3), 'suma_R': rnd(g.r.sum(), 1),
               'TP1_pct': rnd((g.status == 'TP1').mean() * 100, 1),
               'p1_n': len(p1), 'p1_sredni_R': rnd(p1.mean(), 3) if len(p1) else None,
               'p2_n': len(p2), 'p2_sredni_R': rnd(p2.mean(), 3) if len(p2) else None,
               'LONG_sredni_R': rnd(g[g.side == 'LONG'].r.mean(), 3) if (g.side == 'LONG').any() else None,
               'SHORT_sredni_R': rnd(g[g.side == 'SHORT'].r.mean(), 3) if (g.side == 'SHORT').any() else None}
        if rynek == 'RAZEM' and w != 'BAZA_SWIEZY_4H_SL0.2' and len(bp1) and len(bp2) and len(p1) and len(p2):
            row['lepszy_sredni_w_obu_polowach'] = bool(p1.mean() > bp1.mean() and p2.mean() > bp2.mean())
            row['dodatni_w_obu_polowach'] = bool(p1.mean() > 0 and p2.mean() > 0)
        rows.append(row)
    return rows


def elliott_warianty_v193(PP, now_ms, drive_ok):
    cache = Path(DRIVE_DIR) / 'elliott_abc_warianty_v193.json' if drive_ok else None
    if cache is not None and cache.is_file():
        try:
            c = json.loads(cache.read_text(encoding='utf-8'))
            if (now_ms - int(c.get('computed_ms', 0))) < ELLIOTT_WARIANTY_CO_H * HOUR_MS and c.get('wersja_metody') == 'v193':
                c['status'] = 'Z_CACHE'
                return c
        except (OSError, ValueError, TypeError):
            pass
    t0 = time.time()
    kand = _v193_kandydaci(PP, now_ms, ELLIOTT_WARIANTY_KROK_H)
    tr = _v193_symuluj(PP, kand, ELLIOTT_WARIANTY_OKNO_H)
    snaps = sorted(r['snapshot_utc'] for r in tr)
    res = {'wersja_metody': 'v193', 'computed_ms': int(now_ms), 'status': 'PRZELICZONO',
           'sekundy': round(time.time() - t0, 1), 'kandydaci_zdjecia': len(kand), 'transakcje': len(tr),
           'okres': [snaps[0], snaps[-1]] if snaps else None, 'wiersze': _v193_podsumuj(tr),
           'uwaga': 'Badawczo: wejscie MARKET w cenie zdjecia, TP1 1.5R, zarzadzanie jak silnik simulate; nie zmienia handlu.',
           'warunek_zmiany': 'Zmiana definicji ABC tylko gdy wariant dodatni i lepszy od BAZY w obu polowach.'}
    if cache is not None:
        try:
            zapisz_atomowo(cache, lambda temp: Path(temp).write_text(json.dumps(res, ensure_ascii=False, default=str), encoding='utf-8'), kopia=False)
        except (OSError, ValueError, TypeError):
            pass
    return res


def test_v193():
    r = {'side': 'LONG', 'price': 105., 'b': 104., 'age': 3, 'dist': 1.0, 'z4h': 'ZGODNE'}
    assert _v193_warunek(r, 'swiezy_4h') and _v193_warunek(r, 'przebicie_b_4h') and _v193_warunek(r, 'przebicie_b')
    assert not _v193_warunek(dict(r, price=103.), 'przebicie_b')
    assert not _v193_warunek(dict(r, z4h='PRZECIWNE'), 'przebicie_b_4h') and _v193_warunek(dict(r, z4h='PRZECIWNE'), 'przebicie_b')
    assert _v193_warunek({'side': 'SHORT', 'price': 95., 'b': 96., 'age': 2, 'dist': 0.5, 'z4h': 'ZGODNE'}, 'przebicie_b_4h')
    tr = [{'wariant': w, 'symbol': 'X', 'side': 'LONG', 'asset_type': 'COIN', 'snapshot_utc': '2026-10-%02dT00:00' % d,
           'status': 'TP1', 'r': (0.5 if w != 'BAZA_SWIEZY_4H_SL0.2' else -0.5)} for w in _V193_WARIANTY for d in (1, 2, 3, 4)]
    rows = _v193_podsumuj(tr)
    x = [r for r in rows if r['wariant'] == 'PRZEBICIE_B_4H' and r['rynek'] == 'RAZEM'][0]
    assert x['lepszy_sredni_w_obu_polowach'] and x['dodatni_w_obu_polowach']
    return 'PASS (warunki przebicia B LONG/SHORT, wymog 4h, porownanie z BAZA w obu polowach)'


# =================== V6.194: metodologia Elliott ABC (badawczo) ===================
def _v194_geometria(p, a, trend_4h, tf_ms):
    """ABC z pivotow p + geometria fal: impuls, A, C, C/A, zniesienie; None gdy brak ABC."""
    e = elliott_abc_badanie(p, a, trend_4h)
    if e.get('elliott_abc_status') != 'ABC_POTENCJALNIE_ZAKONCZONE':
        return None
    v = [float(x[2]) for x in p[-5:]]
    imp, fa, fc = abs(v[1] - v[0]), abs(v[2] - v[1]), abs(v[4] - v[3])
    at = atr(a[:, H], a[:, L], a[:, C])
    if not (at and np.isfinite(at) and at > 0 and fa > 0):
        return None
    return {'side': e['elliott_abc_kierunek'], 'b': v[3], 'c': v[4], 'c_ms': e['elliott_abc_c_utc_ms'],
            'age': e['elliott_abc_wiek_h'], 'dist': e['elliott_abc_od_c_atr'], 'z4h': e['elliott_abc_zgodnosc_4h'],
            'retr': e['elliott_abc_fib'], 'c_do_a': fc / fa, 'impuls_atr': imp / at, 'atr_det': at,
            'pelny_impuls': _v208_pelny_impuls(p, e['elliott_abc_kierunek']), 'strategia': 'ABC'}


def _v208_pelny_impuls(p, side):
    """V6.208: czy przed korekta ABC jest pelny impuls 1-5 (zasady Elliotta) konczacy sie na poczatku fali A.
    Punkty w0..w5 = p[-9]..p[-4] (p[-4] = szczyt/dolek impulsu, od ktorego zaczyna sie A)."""
    if len(p) < 9:
        return False
    w = [float(x[2]) for x in p[-9:-3]]
    d = 1 if side == 'LONG' else -1               # ABC LONG = korekta po impulsie wzrostowym
    f1, f3, f5 = d * (w[1] - w[0]), d * (w[3] - w[2]), d * (w[5] - w[4])
    return bool(f1 > 0 and f3 > 0 and f5 > 0
                and d * (w[2] - w[0]) > 0                 # fala 2 nie schodzi ponizej poczatku 1
                and d * (w[3] - w[1]) > 0                 # fala 3 za koniec 1
                and d * (w[4] - w[1]) > 0                 # fala 4 nie wchodzi w obszar fali 1
                and d * (w[5] - w[3]) > 0                 # fala 5 za koniec 3
                and f3 >= min(f1, f5))                    # fala 3 nie najkrotsza


def _v208_fala3(p, a, trend_4h, price, ts, atr1):
    """V6.208: kandydat FALA3 = fala 1 (w0->w1) i korekta 2 (w1->w2, zniesienie 38.2-78.6%), cena wybija koniec fali 1.
    Tylko potwierdzone pivoty (bez przyszlych swiec). None gdy brak ukladu."""
    if len(p) < 3 or not atr1:
        return None
    q = p[-3:]; t = [x[1] for x in q]; w = [float(x[2]) for x in q]
    if t == ['L', 'H', 'L']:
        side, d = 'LONG', 1
    elif t == ['H', 'L', 'H']:
        side, d = 'SHORT', -1
    else:
        return None
    f1 = d * (w[1] - w[0])
    if not (f1 > 0 and d * (w[2] - w[0]) > 0 and d * (w[1] - w[2]) > 0):
        return None
    retr = d * (w[1] - w[2]) / f1
    at = atr(a[:, H], a[:, L], a[:, C])
    if not (at and np.isfinite(at) and at > 0):
        return None
    return {'side': side, 'b': w[1], 'c': w[2], 'w0': w[0], 'c_ms': int(q[-1][0]), 'age': (ts - int(q[-1][0])) / HOUR_MS,
            'dist': d * (price - w[1]) / atr1, 'z4h': 'ZGODNE' if trend_4h == side else 'INNE', 'retr': retr,
            'c_do_a': None, 'impuls_atr': f1 / at, 'atr_det': at, 'pelny_impuls': None, 'strategia': 'FALA3'}


def _v208_ok_fala3(r, z4h=False, impuls=None, swiezy_h=24, max_wybicie_atr=1.0):
    try:
        age, dist, retr = float(r['age']), float(r['dist']), float(r['retr'])
    except (TypeError, ValueError):
        return False
    if not (0.382 <= retr <= 0.786 and age <= swiezy_h and 0 < dist <= max_wybicie_atr):
        return False                                  # wybicie konca fali 1, ale nie pozniej niz 1 ATR za nim
    if z4h and r['z4h'] != 'ZGODNE':
        return False
    if impuls is not None and r['impuls_atr'] < impuls:
        return False
    return True


def _v194_kandydaci(PP, now_ms, krok_h):
    rows = []
    step = int(krok_h * HOUR_MS)
    for sym, P in PP.items():
        a5 = P['arr'].get('5m')
        if a5 is None or len(a5) < 500:
            continue
        ts = (int(a5[0, T]) + 3 * DAY_MS) // step * step + step
        while ts < now_ms - HOUR_MS:
            A = view(P, ts)
            if enough(A):
                try:
                    price = float(A['5m'][-1, C])
                    p4 = elliott_pivoty(A['4h'])
                    tr4 = elliott_trend_pivotow(p4)
                    dets = {'p08': (elliott_pivoty(A['1h']), A['1h']),
                            'p15': (elliott_pivoty(A['1h'], min_atr=1.5), A['1h']),     # V6.212
                            'p175': (elliott_pivoty(A['1h'], min_atr=1.75), A['1h']),   # V6.212
                            'p20': (elliott_pivoty(A['1h'], min_atr=2.0), A['1h']),
                            'p4h': (p4, A['4h'])}
                    atr1 = None
                    for det, (pv, arr) in dets.items():
                        g = _v194_geometria(pv, arr, tr4, None)
                        if g is None:
                            continue
                        if atr1 is None:
                            atr1 = float(atr(A['1h'][:, H], A['1h'][:, L], A['1h'][:, C]))
                        g.update(det=det, sym=sym, ts=ts, price=price, atr=atr1, asset=P.get('asset_type'),
                                 qv24=float(A['1h'][-24:, QV].sum()) if len(A['1h']) >= 24 else None,
                                 wybicie15=_v209_wybicie15(A, g['side'], price))
                        rows.append(g)
                    for det in ('p08', 'p20'):                   # V6.208: FALA3 z pivotow 1h
                        pv, arr = dets[det]
                        if atr1 is None:
                            atr1 = float(atr(A['1h'][:, H], A['1h'][:, L], A['1h'][:, C]))
                        g = _v208_fala3(pv, arr, tr4, price, ts, atr1)
                        if g is not None and _v208_ok_fala3(g, swiezy_h=48, max_wybicie_atr=3.0):   # wstepnie, warianty ostrzej
                            g.update(det=det, sym=sym, ts=ts, price=price, atr=atr1, asset=P.get('asset_type'),
                                     qv24=float(A['1h'][-24:, QV].sum()) if len(A['1h']) >= 24 else None)
                            rows.append(g)
                except (KeyError, ValueError, TypeError, ArithmeticError, IndexError):
                    pass
            ts += step
    return rows


def _v209_wybicie15(A, side, price, n=8):
    """V6.209: cena wybila lokalna strukture 15m (ekstremum ostatnich n zamknietych swiec 15m) w strone sygnalu."""
    a = A.get('15m') if isinstance(A, dict) else None
    if a is None or len(a) < n + 1:
        return False
    seg = a[-n - 1:-1]
    return bool(price > float(seg[:, H].max())) if side == 'LONG' else bool(price < float(seg[:, L].min()))


def _v194_ok(r, swiezy=True, z4h=True, proporcje=False, impuls=None, przebicie=False, pelny=False, wybicie15=False, wiek_h=None, tryb_4h=None):
    s = 1 if r['side'] == 'LONG' else -1
    if wybicie15 and not r.get('wybicie15'):        # V6.209: wejscie dopiero po wybiciu struktury 15m
        return False
    if pelny and not r.get('pelny_impuls'):          # V6.208: ABC tylko po pelnym impulsie 1-5
        return False
    try:
        age, dist = float(r['age']), float(r['dist'])
    except (TypeError, ValueError):
        return False
    if swiezy and not (age <= (wiek_h or (48 if r['det'] == 'p4h' else 12)) and dist <= 1.5):   # V6.213: wiek_h
        return False
    if z4h and r['z4h'] != 'ZGODNE':
        return False
    if tryb_4h is not None and r['z4h'] != tryb_4h:   # V6.214: tylko wybrany stan trendu 4h
        return False
    if proporcje and not (0.618 <= r['c_do_a'] <= 1.618 and 0.5 <= (r['retr'] or 0) <= 0.786):
        return False
    if impuls is not None and r['impuls_atr'] < impuls:
        return False
    if przebicie and not (s * (r['price'] - r['b']) > 0 and dist <= 3):
        return False
    return True


