def _v194_symuluj(PP, kand, okno_h=24):
    grupy = {}
    for r in sorted(kand, key=lambda x: x['ts']):
        grupy.setdefault((r.get('strategia', 'ABC'), r['det'], r['sym'], r['side'], r['c_ms']), []).append(r)
    out = []
    for nazwa, w in _V194_WARIANTY.items():
        okno = okno_h * (4 if w['det'] == 'p4h' else 1)
        strat = w.get('strat', 'ABC')
        okf = _v208_ok_fala3 if strat == 'FALA3' else _v194_ok
        for (st_, det, sym, side, c_ms), g in grupy.items():
            if det != w['det'] or st_ != strat:
                continue
            t0 = g[0]['ts']
            q = [r for r in g if r['ts'] - t0 <= okno * HOUR_MS and okf(r, **w['ok'])]
            if not q:
                continue
            r0 = q[0]; s = 1 if side == 'LONG' else -1; P = PP[sym]
            entry = r0['price']; sl = r0['c'] - s * w['sl_atr'] * r0['atr_det']; risk = s * (entry - sl)
            # Ta sama geometria co hipotezy V6.156: SL za C, cena po wlasciwej stronie C.
            if not (risk > 0 and np.isfinite(risk) and s * (entry - r0['c']) > 0 and s * (r0['c'] - sl) > 0):
                continue
            if w['cel'] == '1.5R':
                tp = entry + s * 1.5 * risk
            elif w['cel'] == 'EXT':                       # V6.208: fala 3 = 1.618 x fala 1 od konca fali 2
                tp = r0['c'] + s * 1.618 * abs(r0['b'] - r0['w0'])
            else:
                tp = r0['b']
            if s * (tp - entry) < 1.0 * risk:            # cel B blizej niz 1R -> brak transakcji
                continue
            row = {'side': side, 'entry': entry, 'sl': sl, 'tp1': tp, 'entry_type': 'MARKET',
                   'setup_type': 'ELLIOTT_ABC', 'wait_h': 0, 'slip_bps': historical_slip_for(P, int(r0['ts']), r0['qv24'])}
            sim = simulate(P['arr']['5m'], int(r0['ts']), row, P['fees'], funding_points(P.get('raw')))
            if sim['status'] not in FINAL or sim.get('luka_danych') or sim.get('r') is None:
                continue
            out.append({'wariant': nazwa, 'symbol': sym, 'side': side, 'asset_type': r0['asset'],
                        'snapshot_utc': snap_iso(int(r0['ts'])), 'status': sim['status'], 'r': float(sim['r'])})
    return out


def _v194_podsumuj(tr):
    if not tr:
        return []
    d = pd.DataFrame(tr); mid = sorted(d.snapshot_utc)[len(d) // 2]
    base = d[d.wariant == 'BAZA']
    bp1, bp2 = base[base.snapshot_utc < mid].r, base[base.snapshot_utc >= mid].r
    d['rynek'] = np.where(d.asset_type == 'COIN', 'COIN', 'TRADFI')
    d['rynek_kier'] = np.where(d.asset_type == 'COIN', 'COIN_' + d.side.astype(str), 'TRADFI_' + d.side.astype(str))   # V6.208
    rows = []
    for (w, rynek), g in [((w, 'RAZEM'), g) for w, g in d.groupby('wariant', sort=False)] + \
                         [((w, rk), g) for (w, rk), g in d.groupby(['wariant', 'rynek'], sort=False)] + \
                         [((w, rk), g) for (w, rk), g in d.groupby(['wariant', 'rynek_kier'], sort=False) if rk.startswith('COIN_')]:
        p1, p2 = g[g.snapshot_utc < mid].r, g[g.snapshot_utc >= mid].r
        if rynek.startswith('COIN_'):                     # V6.208: kandydat osobno dla kierunku (vs BAZA tego kierunku)
            bb = d[(d.wariant == 'BAZA') & (d.rynek_kier == rynek)]
            bq1, bq2 = bb[bb.snapshot_utc < mid].r, bb[bb.snapshot_utc >= mid].r
        else:
            bq1, bq2 = bp1, bp2
        row = {'wariant': w, 'rynek': rynek, 'transakcje': len(g), 'sredni_R': rnd(g.r.mean(), 3), 'suma_R': rnd(g.r.sum(), 1),
               'TP1_pct': rnd((g.status == 'TP1').mean() * 100, 1),
               'p1_n': len(p1), 'p1_sredni_R': rnd(p1.mean(), 3) if len(p1) else None,
               'p2_n': len(p2), 'p2_sredni_R': rnd(p2.mean(), 3) if len(p2) else None,
               'LONG_sredni_R': rnd(g[g.side == 'LONG'].r.mean(), 3) if (g.side == 'LONG').any() else None,
               'SHORT_sredni_R': rnd(g[g.side == 'SHORT'].r.mean(), 3) if (g.side == 'SHORT').any() else None}
        if (rynek == 'RAZEM' or rynek.startswith('COIN_')) and w != 'BAZA' and len(bq1) and len(bq2) and len(p1) and len(p2):
            row['lepszy_sredni_w_obu_polowach'] = bool(p1.mean() > bq1.mean() and p2.mean() > bq2.mean())
            row['dodatni_w_obu_polowach'] = bool(p1.mean() > 0 and p2.mean() > 0)
            row['kandydat_do_zmiany'] = bool(row['lepszy_sredni_w_obu_polowach'] and row['dodatni_w_obu_polowach'] and len(g) >= 30)
        rows.append(row)
    return rows


def elliott_warianty_v194(PP, now_ms, drive_ok):
    cache = Path(DRIVE_DIR) / 'elliott_abc_warianty_v208.json' if drive_ok else None
    if cache is not None and cache.is_file():
        try:
            c = json.loads(cache.read_text(encoding='utf-8'))
            if (now_ms - int(c.get('computed_ms', 0))) < ELLIOTT_WARIANTY_CO_H * HOUR_MS and c.get('wersja_metody') == 'v214':
                c['status'] = 'Z_CACHE'
                return c
        except (OSError, ValueError, TypeError):
            pass
    t0 = time.time()
    kand = _v194_kandydaci(PP, now_ms, ELLIOTT_WARIANTY_KROK_H)
    tr = _v194_symuluj(PP, kand, ELLIOTT_WARIANTY_OKNO_H)
    snaps = sorted(r['snapshot_utc'] for r in tr)
    res = {'wersja_metody': 'v214', 'computed_ms': int(now_ms), 'status': 'PRZELICZONO',
           'sekundy': round(time.time() - t0, 1), 'kandydaci_zdjecia': len(kand), 'transakcje': len(tr),
           'okres': [snaps[0], snaps[-1]] if snaps else None, 'wiersze': _v194_podsumuj(tr),
           'warianty': {k: {'strategia': v.get('strat', 'ABC'), 'pivoty': v['det'], 'warunki': v['ok'], 'sl_atr': v['sl_atr'], 'cel': v['cel']} for k, v in _V194_WARIANTY.items()},
           'kandydaci_FALA3': sum(1 for r in kand if r.get('strategia') == 'FALA3'),
           'zasada': 'Warianty ustalone z gory. Zmiana definicji ABC tylko przy kandydat_do_zmiany=True (dodatni i lepszy od BAZY w obu polowach, >=30 transakcji).',
           'uwaga': 'Badawczo: wejscie MARKET w cenie zdjecia, silnik simulate (czesc +1R, BE); nie zmienia handlu.'}
    if cache is not None:
        try:
            zapisz_atomowo(cache, lambda temp: Path(temp).write_text(json.dumps(res, ensure_ascii=False, default=str), encoding='utf-8'), kopia=False)
        except (OSError, ValueError, TypeError):
            pass
    return res


def test_v194():
    r = {'side': 'LONG', 'price': 105., 'b': 104., 'c': 100., 'age': 3, 'dist': 1.0, 'z4h': 'ZGODNE', 'det': 'p08',
         'c_do_a': 1.0, 'retr': 0.6, 'impuls_atr': 4.0}
    assert _v194_ok(r) and _v194_ok(r, proporcje=True) and _v194_ok(r, impuls=3.0) and _v194_ok(r, przebicie=True)
    assert not _v194_ok(dict(r, c_do_a=2.0), proporcje=True) and not _v194_ok(dict(r, retr=0.4), proporcje=True)
    assert not _v194_ok(dict(r, impuls_atr=2.0), impuls=3.0)
    assert not _v194_ok(dict(r, age=20)) and _v194_ok(dict(r, age=20, det='p4h'))
    assert _v194_ok(dict(r, z4h='PRZECIWNE'), z4h=False) and not _v194_ok(dict(r, z4h='PRZECIWNE'))
    tr = [{'wariant': w, 'symbol': 'X', 'side': 'LONG', 'asset_type': 'COIN', 'snapshot_utc': '2026-10-%02dT00:00' % (dd % 28 + 1),
           'status': 'TP1', 'r': (0.4 if w == 'FALE_4H' else -0.4)} for w in _V194_WARIANTY for dd in range(40)]
    rows = {(x['wariant'], x['rynek']): x for x in _v194_podsumuj(tr)}
    assert rows[('FALE_4H', 'RAZEM')]['kandydat_do_zmiany'] and not rows[('DUZE_FALE_2ATR', 'RAZEM')]['kandydat_do_zmiany']
    return 'PASS (warunki: swiezosc 1h/4h, 4h, proporcje, impuls, przebicie; kandydat tylko gdy dodatni i lepszy w obu polowach)'


