_V209_KOL = ['id', 'wariant', 'symbol', 'wykryto_utc', 'ts_ms', 'c_ms', 'entry', 'sl', 'tp1', 'risk_pct', 'status', 'r', 'exit_utc', 'mfe_R', 'wersja',
             'mae_R', 'trzymano_h', 'w15_przy_wykryciu']   # V6.223: pola V6.221 tez w zapisie


_V211_LEJEK = {}


def _v211_lejek_krok(g):
    """Pierwszy warunek LONG-DF, ktorego uklad ABC LONG nie spelnia (kolejnosc jak w _v194_ok)."""
    try:
        age, dist = float(g['age']), float(g['dist'])
    except (TypeError, ValueError):
        return 'brak_danych'
    if age > 12:
        return 'C_starsze_niz_12h'
    if dist > 1.5:
        return 'cena_dalej_niz_1.5ATR_od_C'
    if g['z4h'] != 'ZGODNE':
        return 'trend_4h_niezgodny'
    if not (0.618 <= (g.get('c_do_a') or 0) <= 1.618):
        return 'proporcja_C_do_A'
    if not (0.5 <= (g.get('retr') or 0) <= 0.786):
        return 'zniesienie_poza_0.5-0.786'
    return None


def _v209_wykryj(PP, ts):
    """Sygnaly ELLIOTT_ABC_LONG_DF w chwili ts (tylko zamkniete swiece, ta sama definicja co wariant DUZE_FALE_PROPORCJE).
    V6.211: lejek odrzucen w _V211_LEJEK (diagnostyka, definicja bez zmian)."""
    out = []
    lej = {'kontrakty_COIN': 0, 'brak_ABC_na_pivotach_2ATR': 0, 'ABC_SHORT': 0, 'ABC_LONG': 0}
    for sym, P in PP.items():
        if P.get('asset_type') != 'COIN' or '5m' not in P.get('arr', {}):
            continue
        try:
            A = view(P, ts)
            if not enough(A):
                continue
            lej['kontrakty_COIN'] += 1
            price = float(A['5m'][-1, C])
            tr4 = elliott_trend_pivotow(elliott_pivoty(A['4h']))
            g = _v194_geometria(elliott_pivoty(A['1h'], min_atr=2.0), A['1h'], tr4, None)
            if g is None:
                lej['brak_ABC_na_pivotach_2ATR'] += 1
                continue
            if g['side'] != 'LONG':
                lej['ABC_SHORT'] += 1
                continue
            lej['ABC_LONG'] += 1
            g.update(det='p20', price=price)
            krok = _v211_lejek_krok(g)
            if krok is not None:
                lej[krok] = lej.get(krok, 0) + 1
            if not _v194_ok(g, proporcje=True):
                continue
            lej['spelnia_warunki'] = lej.get('spelnia_warunki', 0) + 1
            w15 = _v209_wybicie15(A, 'LONG', price)
            for wn, wc in _V209_WARIANTY.items():          # V6.210: trzy warianty, BAZA bez zmian
                if wc['w15'] and not w15:
                    continue
                sl = g['c'] - wc['sl_atr'] * g['atr_det']; risk = price - sl
                if not (risk > 0 and price > g['c'] and np.isfinite(risk)):
                    continue
                out.append({'id': (f"{sym}|{int(g['c_ms'])}" if wn == 'BAZA' else f"{wn}|{sym}|{int(g['c_ms'])}"), 'wariant': wn,
                            'symbol': sym, 'wykryto_utc': snap_iso(int(ts)), 'ts_ms': int(ts),
                            'c_ms': int(g['c_ms']), 'entry': psig(price, 7), 'sl': psig(sl, 7), 'tp1': psig(price + 1.5 * risk, 7),
                            'risk_pct': rnd(risk / price * 100, 2), 'status': 'otwarty', 'r': None, 'exit_utc': None, 'mfe_R': None,
                            'mae_R': None, 'trzymano_h': None, 'w15_przy_wykryciu': bool(w15),     # V6.221
                            'wersja': VERSION})
        except (KeyError, ValueError, TypeError, ArithmeticError, IndexError):
            continue
    _V211_LEJEK.clear(); _V211_LEJEK.update(lej)
    return out


def _v209_rozlicz(PP, log):
    """Rozlicza otwarte sygnaly na swiecach 5m (te same koszty i zarzadzanie co test)."""
    for r in log:
        if r.get('status') in FINAL or r.get('status') in ('luka_danych', 'anulowany', 'brak_danych'):
            continue
        P = PP.get(r['symbol'])
        if P is None or '5m' not in P.get('arr', {}):
            continue
        try:
            row = {'side': 'LONG', 'entry': float(r['entry']), 'sl': float(r['sl']), 'tp1': float(r['tp1']), 'entry_type': 'MARKET',
                   'setup_type': 'ELLIOTT_ABC', 'wait_h': 0, 'slip_bps': historical_slip_for(P, int(r['ts_ms']), None)}
            sim = simulate(P['arr']['5m'], int(r['ts_ms']), row, P['fees'], funding_points(P.get('raw')))
        except (KeyError, ValueError, TypeError, ArithmeticError, IndexError):
            continue
        if sim.get('status') in FINAL or sim.get('status') in ('luka_danych', 'anulowany'):
            r.update(status=sim['status'], r=sim.get('r'), exit_utc=sim.get('exit_utc'), mfe_R=sim.get('mfe_R'),
                     mae_R=sim.get('mae_R'), trzymano_h=(rnd(sim['bars_held'] / 12, 1) if sim.get('bars_held') is not None else None))   # V6.221
        elif sim.get('mfe_R') is not None:
            r['mfe_R'] = sim.get('mfe_R'); r['mae_R'] = sim.get('mae_R')
    return log


def _v209_podsumowanie(log):
    roz = [r for r in log if r.get('status') in FINAL and r.get('r') not in (None, '')]
    rr = [float(r['r']) for r in roz]
    n = len(rr)
    sd = float(np.std(rr, ddof=1)) if n >= 2 else None
    t = (float(np.mean(rr)) / (sd / np.sqrt(n))) if n >= 2 and sd else None
    _num = lambda k: [float(r[k]) for r in roz if r.get(k) not in (None, '') and np.isfinite(float(r[k]))]   # V6.221
    _mae, _h = _num('mae_R'), _num('trzymano_h')
    _w = [r.get('w15_przy_wykryciu') for r in log]
    return {'sr_MAE_R': rnd(float(np.mean(_mae)), 3) if _mae else None, 'sr_trzymano_h': rnd(float(np.mean(_h)), 1) if _h else None,
            'bez_wybicia_15m': sum(1 for x in _w if x is False or str(x) == 'False'),
            'z_wybiciem_15m': sum(1 for x in _w if x is True or str(x) == 'True'),
            'definicja': V209_DEF, 'sygnaly': len(log), 'otwarte': sum(1 for r in log if r.get('status') == 'otwarty'),
            'rozliczone': n, 'sredni_R': rnd(float(np.mean(rr)), 3) if n else None, 'suma_R': rnd(float(np.sum(rr)), 2) if n else None,
            't': rnd(t, 2) if t is not None else None, 'TP1_pct': rnd(100 * sum(r['status'] == 'TP1' for r in roz) / n, 1) if n else None,
            'werdykt': ('ZA_MALO_DANYCH (<30)' if n < 30 else 'PRZEWAGA_POTWIERDZONA' if (t or 0) >= 2 else
                        'DODATNI_BEZ_PEWNOSCI' if (rr and np.mean(rr) > 0) else 'BRAK_PRZEWAGI')}


def elliott_long_df_oos_v209(PP, now_ms, drive_ok):
    """V6.209: dziennik OOS w przod. Na Drive (trwaly) albo lokalnie (replay). Pierwsze wykrycie = jedyny wpis sygnalu."""
    plik = (Path(DRIVE_DIR) if drive_ok else OUT_ROOT / 'weex_cache') / 'elliott_long_df_oos_v209.csv'
    log = []
    if plik.is_file():
        try:
            log = pd.read_csv(plik).to_dict('records')
        except (OSError, ValueError, pd.errors.EmptyDataError):
            log = []
    for r in log:                                          # V6.210: wpisy V6.209 = wariant BAZA
        if not isinstance(r.get('wariant'), str) or not r.get('wariant'):
            r['wariant'] = 'BAZA'
    znane = {str(r['id']) for r in log}
    nowe = [r for r in _v209_wykryj(PP, now_ms) if r['id'] not in znane]
    log = _v209_rozlicz(PP, log + nowe)
    try:
        plik.parent.mkdir(parents=True, exist_ok=True)
        df = pd.DataFrame(log, columns=_V209_KOL)
        zapisz_atomowo(plik, lambda temp: df.to_csv(temp, index=False), kopia=False)
    except (OSError, ValueError, TypeError):
        pass
    pod = _v209_podsumowanie([r for r in log if r.get('wariant') == 'BAZA'])
    pod['warianty'] = {wn: _v209_podsumowanie([r for r in log if r.get('wariant') == wn]) for wn in _V209_WARIANTY}
    pod['lejek_teraz'] = dict(_V211_LEJEK)                 # V6.211
    for v in pod['warianty'].values():
        v.pop('definicja', None)
    return log, nowe, pod



# ================= V6.244: ELLIOTT - niezalezny test wejsc po C =================
# Ta sekcja NIE aktualizuje zamrozonego V209, simulate(), gate, PROBA ani do_handlu.
_V244_COLS = ['okazja_id','symbol','wariant','proweniencja','wykryto_utc','sygnal_ms',
              'potwierdzono_utc','entry_utc','entry','sl','tp1','status','r','exit_utc',
              'mfe_R','mae_R','powod','fill_utc']
_V244_WARIANTY = ('POTW_15M_BOS_MARKET', 'POTW_15M_BOS_LIMIT', 'POTW_15M_BOS_CEL_B')


def _v244_15m_bos(a5, ts, sl, now_ms, lookback=8, ttl_h=2):
    """Pierwszy BOS z ZAMKNIETEJ swiecy 15m po sygnale; wejscie dopiero po jej zamknieciu.
    15m skladane z trzech kolejnych 5m; przerwa danych -> brak potwierdzenia.
    Nie uwzglednia otwartych swiec ani pozniejszego wybicia przy ocenie wczesniejszych.
    """
    q = 15 * 60_000; step = 5 * 60_000
    if len(a5) < 3 * (lookback + 1):
        return None, 'ZA_MALO_15M'
    # T oznacza poczatek swiecy 5m; pelna 15m zamknieta najpozniej w now_ms
    start = int(np.searchsorted(a5[:, T], ts, side='left'))
    history = []
    first = max(0, start - 3 * (lookback + 2))
    i = first
    while i + 2 < len(a5):
        t = int(a5[i, T]); end = int(a5[i + 2, T]) + step
        if end > now_ms:
            break
        if t % q or int(a5[i + 1, T]) != t + step or int(a5[i + 2, T]) != t + 2 * step:
            i += 1
            continue
        if end <= ts:
            history.append((t, float(np.max(a5[i:i+3, H])), float(a5[i+2, C])))
            history = history[-lookback:]
        else:
            # Nie mozna wejsc, gdy przed potwierdzeniem dotknieto SL.
            if float(np.min(a5[i:i+3, L])) <= sl:
                return None, 'SL_PRZED_POTWIERDZENIEM'
            if end > ts + ttl_h * 3_600_000:
                return None, 'TTL_POTWIERDZENIA'
            if len(history) >= lookback and float(a5[i+2, C]) > max(x[1] for x in history):
                j = i + 3  # pierwsza swieca 5m po ZAMKNIECIU potwierdzajacej 15m
                if j >= len(a5) or int(a5[j, T]) != end or end >= now_ms:
                    return None, 'OCZEKUJE_NA_WEJSCIE'
                return {'potw_ms': end, 'entry_ms': end, 'close_potw': float(a5[i+2, C]),
                        'open_next': float(a5[j, O])}, 'OK'
            history.append((t, float(np.max(a5[i:i+3, H])), float(a5[i+2, C])))
            history = history[-lookback:]
        i += 3
    return None, ('OCZEKUJE_POTWIERDZENIA' if now_ms < ts + ttl_h * 3_600_000 else 'BRAK_BOS_15M')


def _v244_cel_b(P, ts):
    """Poziom B liczony WYŁĄCZNIE ze swiec dostepnych w chwili sygnalu."""
    A = view(P, int(ts))
    if not enough(A):
        return None
    g = _v194_geometria(elliott_pivoty(A['1h'], min_atr=2.0), A['1h'],
                         elliott_trend_pivotow(elliott_pivoty(A['4h'])), None)
    return float(g['b']) if g and g.get('side') == 'LONG' else None


def _v244_badanie(PP, base_log, now_ms, drive_ok):
    """Rownolegle, sparowane na bazowych okazjach V209; trwale oznaczenie RETRO/PROSPEKTYWNE.
    Brak nowego sygnalu bazowego = brak nowej okazji. Nie miesza tych grup w OOS.
    """
    path = (Path(DRIVE_DIR) if drive_ok else OUT_ROOT / 'weex_cache') / 'elliott_v244_pochodzenie.json'
    try:
        provenance = json.loads(path.read_text(encoding='utf-8')) if path.is_file() else {}
        if not isinstance(provenance, dict): provenance = {}
    except (OSError, ValueError, TypeError):
        provenance = {}
    # Pierwszy przebieg: wszystkie juz zarejestrowane okazje oznacz RETRO raz na zawsze.
    if '_inicjalizacja' not in provenance:
        provenance['_inicjalizacja'] = int(now_ms)
    init_ts = int(provenance['_inicjalizacja'])
    base = sorted((x for x in base_log if x.get('wariant') == 'BAZA'), key=lambda x: int(x['ts_ms']))
    rows=[]
    for b in base:
        sym=b['symbol']; P=PP.get(sym); ts=int(b['ts_ms']); key=str(b['id'])
        if key not in provenance:
            provenance[key] = 'RETRO_DIAGNOSTYKA' if ts < init_ts else 'PROSPEKTYWNE'
        for var in _V244_WARIANTY:
            r=dict(okazja_id=key, symbol=sym, wariant=var, proweniencja=provenance[key],
                   wykryto_utc=b.get('wykryto_utc'), sygnal_ms=ts,
                   potwierdzono_utc=None, entry_utc=None, entry=None, sl=b.get('sl'),
                   tp1=None, status='OCZEKUJE', r=None, exit_utc=None, mfe_R=None, mae_R=None, powod='', fill_utc=None)
            try:
                if not P or '5m' not in P.get('arr', {}):
                    r.update(status='BRAK_DANYCH', powod='BRAK_5M'); rows.append(r); continue
                a5=P['arr']['5m']; sl=float(b['sl'])
                confirm, reason=_v244_15m_bos(a5, ts, sl, int(now_ms))
                if confirm is None:
                    r.update(status='OCZEKUJE' if reason.startswith('OCZEKUJE') else 'BEZ_WEJSCIA', powod=reason)
                    rows.append(r); continue
                ent=float(confirm['open_next']); entry_ts=int(confirm['entry_ms'])
                if not np.isfinite(ent) or ent <= sl:
                    r.update(status='BEZ_WEJSCIA', powod='LUKA_CENY_PRZEZ_SL'); rows.append(r); continue
                risk=ent-sl
                if var == 'POTW_15M_BOS_LIMIT':
                    ent=float(confirm['close_potw']) - 0.25 * risk
                    if ent <= sl:
                        r.update(status='BEZ_WEJSCIA', powod='LIMIT_POD_SL'); rows.append(r); continue
                tp=ent+1.5*(ent-sl)
                if var == 'POTW_15M_BOS_CEL_B':
                    level=_v244_cel_b(P, ts)
                    if level is None or level <= ent + (ent-sl):
                        r.update(status='BEZ_WEJSCIA', powod='B_NIE_DAJE_1R'); rows.append(r); continue
                    tp=level
                r.update(potwierdzono_utc=snap_iso(confirm['potw_ms']), entry_utc=snap_iso(entry_ts),
                         entry=psig(ent, 8), tp1=psig(tp, 8))
                order={'side':'LONG','entry':ent,'sl':sl,'tp1':tp,
                       'entry_type':'LIMIT' if var == 'POTW_15M_BOS_LIMIT' else 'MARKET',
                       'setup_type':'ELLIOTT_ABC','wait_h':1 if var == 'POTW_15M_BOS_LIMIT' else 0,
                       'slip_bps':historical_slip_for(P,entry_ts,None)}
                sim=simulate(a5,entry_ts,order,P['fees'],funding_points(P.get('raw')))
                st=sim.get('status','OCZEKUJE')
                r.update(status=st, r=sim.get('r') if st in FINAL else None,
                         exit_utc=sim.get('exit_utc'), fill_utc=sim.get('fill_utc'), mfe_R=sim.get('mfe_R'), mae_R=sim.get('mae_R'),
                         powod=sim.get('niejednoznaczne') or ('LUKA_5M' if sim.get('luka_danych') else ''))
            except (KeyError, ValueError, TypeError, ArithmeticError, IndexError) as ex:
                r.update(status='BRAK_DANYCH', powod=type(ex).__name__)
            rows.append(r)
    try:
        path.parent.mkdir(parents=True,exist_ok=True)
        zapisz_atomowo(path,lambda tmp: Path(tmp).write_text(json.dumps(provenance,ensure_ascii=False), encoding='utf-8'),kopia=False)
    except (OSError, ValueError, TypeError):
        for r in rows:
            r['proweniencja'] = 'NIEZWERYFIKOWANA_BRAK_ZAPISU'
    return rows



# ================= V6.245: Elliott — niezmienny dziennik dowodow OOS =================
# Tylko badanie; nie ingeruje w V209, produkcyjne bramki, zlecenia ani klasyczny ranking.
_V245_MAX_STOP_PCT = 8.0  # prog BADAWCZY; porownac bez filtra, nie optymalizowac na 5 okazjach
_V245_COLS = _V244_COLS + ['pierwsza_obserwacja_utc','chronologia','entry_utrwalone',
    'stop_proc','ryzyko_stop_status','limit_fill_status','dowod_zrodlo',
    'zapis_trwaly','kontrola_zmiany','faza_oos','dopuszczony_stop_8pct',
    'pierwszy_odczyt_entry_utc','dowod_egzekucji_v255','oos_wykonalne_v255',
    'plan_warunkowy_zapis_utc','plan_warunkowy_status','plan_warunkowy_wazny_do_utc']
_V245_FREEZE = ('okazja_id','symbol','wariant','proweniencja','sygnal_ms',
    'potwierdzono_utc','entry_utc','entry','sl','tp1')


def _v245_fingerprint(r):
    # Stabilny odcisk decyzji; bez pol wynikowych zależnych od uplywu czasu.
    import hashlib as _hashlib
    data = {k: r.get(k) for k in _V245_FREEZE}
    return _hashlib.sha256(json.dumps(data, sort_keys=True, ensure_ascii=False,
                                    default=str).encode('utf-8')).hexdigest()


def _v245_first_observation(r, now_ms, old=None):
    """Brak retrospektywnego awansu na OOS: 15m MUSIALO byc widoczne przed fill.

    Gdy pierwsza obserwacja byla juz po otwarciu swiecy wejscia,
    historyczne odtworzenie nie moze stac sie wiarygodnym wejsciem live.
    """
    seen = int(old.get('first_seen_ms', now_ms)) if old else int(now_ms)
    if r.get('proweniencja') != 'PROSPEKTYWNE':
        return seen, 'RETRO_LUB_BRAK_DOWODU'
    if r.get('entry_utc'):
        try:
            entry_ms = parse_utc(str(r['entry_utc']))
        except (ValueError, TypeError):
            return seen, 'NIEPRAWIDLOWY_CZAS_ENTRY'
        if seen > entry_ms:
            return seen, 'PO_FAKCIE_BRAK_DOWODU_OOS'
    if seen > int(r['sygnal_ms']) + 2 * 3_600_000 and not old:
        return seen, 'PO_TTL_BRAK_DOWODU_OOS'
    return seen, 'POTWIERDZONA_OBSERWACJA'


def _v245_apply(rows, now_ms, drive_ok, replay=False, *, state_path=None):
    """Zachowuje pierwsze poziomy i proweniencje, wykrywa późniejsze korekty.
    Brak trwalego zapisu => zadna pozycja nie dostaje klasy PROSPEKTYWNE_ZWERYFIKOWANE.
    """
    state_path_default = state_path is None
    if state_path is None:
        root = Path(DRIVE_DIR) if drive_ok and not replay else OUT_ROOT / 'weex_cache'
        state_path = root / 'elliott_v245_dziennik.json'
    state_path = Path(state_path)
    state = {'schema': 1, 'rows': {}}
    load_error = None
    if state_path.exists():
        try:
            loaded = json.loads(state_path.read_text(encoding='utf-8'))
            if loaded.get('schema') != 1 or not isinstance(loaded.get('rows'), dict):
                raise ValueError('SCHEMA')
            state = loaded
        except (OSError, ValueError, TypeError, AttributeError) as e:
            load_error = type(e).__name__
    if load_error:
        return [dict(r, chronologia='NIEZWERYFIKOWANA_STAN_USZKODZONY',
                     zapis_trwaly='BLAD_ODCZYTU', kontrola_zmiany=load_error,
                     dowod_zrodlo='BRAK', ryzyko_stop_status='NIEOBLICZONE',
                     limit_fill_status='NIEOBLICZONE') for r in rows], {'status':'BLAD_STANU', 'blad':load_error}
    # V6.285: pelny skan moze trwac >5 minut. Czas snapshotu NIE jest
    # czasem uzbrojenia planu ani pierwszego odczytu entry.
    # Testy z jawnym state_path zachowuja deterministyczny zegar testowy.
    observed_ms = int(time.time()*1000) if state_path_default else int(now_ms)
    enriched = []
    for rec in rows:
        r = dict(rec)
        key = str(r['okazja_id']) + '|' + str(r['wariant'])
        prev = state['rows'].get(key)
        seen, chronology = _v245_first_observation(r, observed_ms, prev)
        # V6.262: w chwili PIERWSZEGO wykrycia ABC zapisujemy w dzienniku
        # WARUNKOWY plan BOS, zanim pojawi sie entry. To NIE jest zlecenie
        # ani dowod realizacji; nie odtwarzamy planu z dawnych swiec.
        # Parametry sa zamrozone i nie wolno ich nadpisac pozniejszym skanem.
        armed = (prev or {}).get('precommit') if prev else None
        try:
            ts_signal = int(r.get('sygnal_ms'))
            sl_signal = float(r.get('sl'))
            can_arm = (r.get('proweniencja') == 'PROSPEKTYWNE'
                       and ts_signal <= observed_ms <= ts_signal + 2*3_600_000
                       and np.isfinite(sl_signal) and sl_signal > 0
                       and r.get('entry') is None and r.get('potwierdzono_utc') is None)
        except (TypeError, ValueError, OverflowError):
            can_arm = False
        if armed is None and not prev and can_arm:
            armed = {'armed_ms':observed_ms, 'signal_ms':ts_signal,
                     'sl':sl_signal, 'expiry_ms':ts_signal+2*3_600_000,
                     'rule':'BOS_15M_ZAMKNIETY_8_SWIEC;MARKET_NASTEPNA_5M;LIMIT_RETEST_TTL_1H',
                     'observed_version':VERSION}
        if armed is not None:
            if prev:
                # plan pozostaje niezmienny nawet gdy sygnal sie przesuwa
                pass
            r['plan_warunkowy_zapis_utc'] = snap_iso(int(armed['armed_ms']))
            r['plan_warunkowy_wazny_do_utc'] = snap_iso(int(armed['expiry_ms']))
            r['plan_warunkowy_status'] = ('WYGASL_BEZ_BOS' if r.get('entry') is None and observed_ms > int(armed['expiry_ms'])
                else 'UZBROJONY_PRZED_BOS' if r.get('entry') is None
                else 'PLAN_ZAPISANY_PRZED_BOS' if r.get('potwierdzono_utc') and
                     int(armed['armed_ms']) <= parse_utc(str(r['potwierdzono_utc']))
                else 'BRAK_DOWODU_PRZED_BOS')
        else:
            r['plan_warunkowy_zapis_utc'] = None
            r['plan_warunkowy_wazny_do_utc'] = None
            r['plan_warunkowy_status'] = ('RETRO_DIAGNOSTYKA' if r.get('proweniencja') != 'PROSPEKTYWNE'
                else 'BRAK_WCZESNEGO_PLANU')
        decision = {k: r.get(k) for k in _V245_FREEZE}
        correction = ''
        if prev:
            stored = prev['decision']
            # Dozwolone przejscie: oczekiwanie na BOS -> pierwszy rzeczywisty sygnal.
            # Zamrazamy ceny dopiero w chwili, gdy pojawi sie pierwszy komplet poziomow.
            if stored.get('entry') is None and decision.get('entry') is not None and \
                    all(stored.get(k) == decision.get(k) for k in ('okazja_id','symbol','wariant','proweniencja','sygnal_ms')):
                state['rows'][key]['decision'] = decision
                state['rows'][key]['first_hash'] = _v245_fingerprint(decision)
                state['rows'][key]['chronologia'] = chronology
                stored = decision
            if _v245_fingerprint(stored) != _v245_fingerprint(decision):
                correction = 'ZMIANA_POZIOMOW_LUB_PROWENIENCJI'
                # Fail-closed: poziomy pierwotnego zdarzenia nie sa modyfikowane.
                for field in _V245_FREEZE:
                    r[field] = stored.get(field)
                chronology = 'NIEZWERYFIKOWANA_ZMIANA_DECYZJI'
                # Nie wolno przenosic rozliczenia ze zmienionych poziomow.
                for field in ('status','r','exit_utc','mfe_R','mae_R'):
                    r[field] = 'BRAK_DANYCH' if field == 'status' else None
            else:
                chronology = prev.get('chronologia', chronology)
                if chronology == 'POTWIERDZONA_OBSERWACJA' and seen > int(r['sygnal_ms']) + 2*3_600_000:
                    # Poprzednia poprawna obserwacja zostaje wazna.
                    pass
        else:
            state['rows'][key] = {'first_seen_ms': seen, 'decision': decision,
                'chronologia': chronology, 'first_hash': _v245_fingerprint(decision)}
        if armed is not None and not prev:
            state['rows'][key]['precommit'] = armed
        # V6.255: czas pierwszego ZOBACZENIA OKREŚLONEGO WEJSCIA, a nie
        # czas pierwszego zauważenia struktury ABC. Nie wolno wstecznie
        # deklarowac mozliwosci wykonania MARKET o 12:15 na podstawie
        # obserwacji ABC o 11:00 i skanu dopiero po 12:15.
        if r.get('entry') is not None and r.get('entry_utc'):
            if prev:
                first_entry_seen = prev.get('first_entry_seen_ms')
                if first_entry_seen is None:
                    first_entry_seen = observed_ms
                    state['rows'][key]['first_entry_seen_ms'] = first_entry_seen
            else:
                first_entry_seen = observed_ms
                state['rows'][key]['first_entry_seen_ms'] = first_entry_seen
        else:
            first_entry_seen = prev.get('first_entry_seen_ms') if prev else None
        r['pierwszy_odczyt_entry_utc'] = snap_iso(first_entry_seen) if first_entry_seen is not None else None
        if r.get('proweniencja') != 'PROSPEKTYWNE':
            evidence = 'RETRO_DIAGNOSTYKA'
        elif correction or chronology != 'POTWIERDZONA_OBSERWACJA':
            evidence = 'NIEZWERYFIKOWANE'
        elif first_entry_seen is None:
            evidence = 'BRAK_WEJSCIA'
        else:
            try:
                # Scenariusz scanu dostarczającego sygnał po otwarciu kolejnej
                # swiecy to REPLAY, nawet gdy okazja ABC jest prospektywna.
                entry_millis = parse_utc(str(r['entry_utc']))
                evidence = ('WEJSCIE_OBSERWOWANE_PRZED_CZASEM' if first_entry_seen <= entry_millis
                            else 'WEJSCIE_ODTWORZONE_PO_FAKCIE')
            except (TypeError, ValueError):
                evidence = 'NIEPRAWIDLOWY_CZAS_WEJSCIA'
        r['dowod_egzekucji_v255'] = evidence
        r['oos_wykonalne_v255'] = evidence == 'WEJSCIE_OBSERWOWANE_PRZED_CZASEM'
        r['pierwsza_obserwacja_utc'] = snap_iso(seen)
        r['chronologia'] = chronology
        r['entry_utrwalone'] = r.get('entry')
        r['kontrola_zmiany'] = correction or 'ZGODNE'
        r['dowod_zrodlo'] = 'DZIENNIK_V245'
        r['zapis_trwaly'] = 'OCZEKUJE_ZAPISU'
        try:
            ent, sl = float(r['entry']), float(r['sl'])
            pct = 100 * abs(ent-sl) / ent if ent > 0 else float('nan')
            r['stop_proc'] = round(pct, 4) if np.isfinite(pct) else None
            r['ryzyko_stop_status'] = ('PONAD_LIMIT_BADAWCZY' if pct > _V245_MAX_STOP_PCT
                     else 'W_LIMIT_BADAWCZY') if np.isfinite(pct) else 'BRAK_DANYCH'
        except (ValueError, TypeError, ZeroDivisionError):
            r['stop_proc'] = None
            r['ryzyko_stop_status'] = 'BRAK_DANYCH'
        if r['wariant'] == 'POTW_15M_BOS_LIMIT':
            st = str(r.get('status','')).lower()
            r['limit_fill_status'] = ('NIEWYPELNIONY' if st in ('niewypelniony','anulowany')
                else 'WYPELNIONY_ROZLICZONY' if r.get('status') in FINAL and r.get('fill_utc')
                else 'ROZLICZONE_BEZ_DOWODU_FILL' if r.get('status') in FINAL
                else 'WYPELNIONY_OTWARTY' if st == 'otwarty' and r.get('fill_utc')
                else 'OCZEKUJE_NA_FILL' if st in ('oczekuje','otwarty')
                else 'BRAK_WEJSCIA' if st in ('bez_wejscia','brak_danych') else 'INNY')
        else:
            r['limit_fill_status'] = 'NIE_DOTYCZY'
        # V6.250: fill pochodzi wylacznie z rzeczywistej symulacji po dostepnych swiecach.
        # Nie dopisuj fikcyjnego fill przy braku dowodu wykonania.
        if not r.get('fill_utc'):
            r['fill_utc'] = None
        r['dopuszczony_stop_8pct'] = r['ryzyko_stop_status'] == 'W_LIMIT_BADAWCZY'
        r['faza_oos'] = ('RETRO' if r.get('proweniencja') != 'PROSPEKTYWNE'
                          else 'NIEZWERYFIKOWANE' if r['chronologia'] != 'POTWIERDZONA_OBSERWACJA'
                          else 'OCZEKUJE' if r.get('status') == 'OCZEKUJE'
                          else 'BRAK_WEJSCIA' if r.get('status') == 'BEZ_WEJSCIA'
                          else 'ZLECENIE_NIEWYPELNIONE' if r.get('limit_fill_status') == 'NIEWYPELNIONY'
                          else 'ROZLICZONE' if r.get('status') in FINAL
                          else 'OTWARTE')
        enriched.append(r)
    saved = False
    if drive_ok and not replay:
        try:
            zapisz_atomowo(state_path, lambda tmp: Path(tmp).write_text(
                json.dumps(state, ensure_ascii=False, sort_keys=True, indent=2),encoding='utf-8'), kopia=True)
            saved = True
        except (OSError, ValueError, TypeError):
            pass
    for r in enriched:
        r['zapis_trwaly'] = 'TAK_DRIVE' if saved else 'NIE_TYLKO_RAPORT'
        if not saved:
            if r.get('plan_warunkowy_status') in ('UZBROJONY_PRZED_BOS','PLAN_ZAPISANY_PRZED_BOS'):
                r['plan_warunkowy_status'] = 'BRAK_TRWALEGO_ZAPISU'
            r['oos_wykonalne_v255'] = False
            if r['dowod_egzekucji_v255'] == 'WEJSCIE_OBSERWOWANE_PRZED_CZASEM':
                r['dowod_egzekucji_v255'] = 'BRAK_TRWALEGO_ZAPISU'
        if not saved and r['chronologia'] == 'POTWIERDZONA_OBSERWACJA':
            r['chronologia'] = 'NIEZWERYFIKOWANA_BRAK_TRWALEGO_ZAPISU'
    meta = {'status':'BADANIE_NIE_DO_HANDLU','zapis_trwaly':saved,
            'warianty':list(_V244_WARIANTY),'prog_stop_proc_badawczy':_V245_MAX_STOP_PCT,
            'prospektywne_zweryfikowane_okazje':len({r['okazja_id'] for r in enriched
                if r['chronologia']=='POTWIERDZONA_OBSERWACJA' and r['proweniencja']=='PROSPEKTYWNE'}),
            'retro_wiersze':sum(r['proweniencja']=='RETRO_DIAGNOSTYKA' for r in enriched),
            'bez_dowodu_wiersze':sum(r['chronologia']!='POTWIERDZONA_OBSERWACJA' for r in enriched),
            'zmiany_decyzji':sum(r['kontrola_zmiany']!='ZGODNE' for r in enriched),
            'v255_wejscia_z_dowodem':sum(r.get('oos_wykonalne_v255') is True for r in enriched),
            'v255_wejscia_odtworzone_po_fakcie':sum(r.get('dowod_egzekucji_v255') == 'WEJSCIE_ODTWORZONE_PO_FAKCIE' for r in enriched)}
    return enriched, meta


def _v255_egzekucja_summary(rows):
    """Oddziela prospektywne odkrycie ABC od prospektywnego, wykonalnego zlecenia."""
    out = []
    for var in _V244_WARIANTY:
        a = [r for r in rows if r.get('wariant') == var and r.get('proweniencja') == 'PROSPEKTYWNE']
        verified = [r for r in a if r.get('oos_wykonalne_v255') is True]
        vals = [float(r['r']) for r in verified if r.get('status') in FINAL and r.get('r') is not None]
        out.append({'wariant': var, 'okazje_prospektywne':len(a),
                    'wejscia_z_dowodem':len(verified),
                    'wejscia_po_fakcie':sum(r.get('dowod_egzekucji_v255') == 'WEJSCIE_ODTWORZONE_PO_FAKCIE' for r in a),
                    'brak_wejscia':sum(r.get('dowod_egzekucji_v255') == 'BRAK_WEJSCIA' for r in a),
                    'rozliczone_z_dowodem':len(vals),
                    'suma_R_z_dowodem':round(sum(vals),4) if vals else None,
                    'ostroznosc':'WEJSCIE_OBSERWOWANE_PRZED_CZASEM nie dowodzi faktycznej realizacji na gieldzie'})
    return out


# ================= V6.260: niezalezny audyt chronologii decyzji BOS =================
# Nie dopisuje sygnalow do handlu. Historyczny fill z simulate() to
# dowod modelowego wyniku, nie faktycznego wykonania zlecenia.
_V260_COLS = ['okazja_id','symbol','wariant','proweniencja','abc_wykryto_utc',
    'bos_zamkniety_utc','planowane_wejscie_utc','pierwszy_zapis_planu_utc',
    'fill_symulowany_utc','pierwszy_skan_utc','status_modelu','dowod_egzekucji',
    'wykonalnosc_oos','stop_proc','wariant_sl8_status','limit_status',
    'r_modelu','r_zweryfikowane_oos','powod','kontrola_zmiany','zapis_trwaly']


def _v260_audyt(rows, now_ms):
    """Konserwatywny dowod PLANU, a nie rzeczywistego fillu.

    Aby okreslic wejscie jako prospektywne, utrwalony plan musial istniec
    najpozniej przed momentem rozpoczecia swiecy wejscia. Pusty lub
    nielogiczny znacznik czasu oznacza BRAK_DOWODU. Wynik OOS jest
    raportowany osobno, bez awansu starych symulacji.
    """
    out=[]
    for r in rows:
        def ms(value):
            if value in (None, '', 'nan'):
                return None
            try:
                x=parse_utc(str(value))
                return int(x) if x is not None else None
            except (ValueError, TypeError, OverflowError):
                return None
        first=ms(r.get('pierwszy_odczyt_entry_utc'))
        entry=ms(r.get('entry_utc'))
        bos=ms(r.get('potwierdzono_utc'))
        fill=ms(r.get('fill_utc'))
        abc=ms(r.get('wykryto_utc'))
        is_limit=r.get('wariant')=='POTW_15M_BOS_LIMIT'
        status=str(r.get('status') or '')
        stop_status=str(r.get('ryzyko_stop_status') or '')
        risk=('ODRZUCONY_RYZYKO' if stop_status=='PONAD_LIMIT_BADAWCZY'
              else 'W_LIMIT_BADAWCZY' if stop_status=='W_LIMIT_BADAWCZY'
              else 'BRAK_WEJSCIA_LUB_DANYCH')
        reason=''
        if r.get('proweniencja')!='PROSPEKTYWNE':
            evidence='RETRO_DIAGNOSTYKA'
        elif r.get('zapis_trwaly')!='TAK_DRIVE':
            evidence='BRAK_TRWALEGO_ZAPISU'
        elif r.get('kontrola_zmiany')!='ZGODNE':
            evidence='ZMIANA_DECYZJI'
        elif entry is None or r.get('entry') is None:
            evidence='BRAK_WEJSCIA'
        elif None in (abc,bos,first):
            evidence='BRAK_DOWODU_CZASU'
        elif not (abc <= bos <= entry):
            evidence='NIESPOJNA_CHRONOLOGIA'
        elif first > entry:
            evidence='PLAN_ODTWORZONY_PO_FAKCIE'
        elif first > now_ms or entry > now_ms + 5*60_000:
            evidence='NIESPOJNY_ZEGAR'
        elif r.get('dowod_egzekucji_v255')!='WEJSCIE_OBSERWOWANE_PRZED_CZASEM':
            evidence='BRAK_DOWODU_V255'
        else:
            evidence='PLAN_ZAREJESTROWANY_NA_CZAS'
        # V6.271: pierwszy odczyt entry NIE zastępuje trwałego planu ABC sprzed BOS.
        # Utrwalony precommit musi byc przed BOS, po wykryciu ABC, nie wygasly,
        # a czas zapisu musi pochodzic z trwalego dziennika.
        precommit=ms(r.get('plan_warunkowy_zapis_utc'))
        expires=ms(r.get('plan_warunkowy_wazny_do_utc'))
        precommit_ok=(r.get('zapis_trwaly')=='TAK_DRIVE'
                      and precommit is not None and bos is not None
                      and abc is not None and expires is not None
                      and abc <= precommit <= bos <= expires
                      and r.get('plan_warunkowy_status')=='PLAN_ZAPISANY_PRZED_BOS')
        if r.get('proweniencja')=='PROSPEKTYWNE' and evidence=='PLAN_ZAREJESTROWANY_NA_CZAS' and not precommit_ok:
            evidence='BRAK_WCZESNEGO_PLANU_BOS'
        plan_ok=evidence=='PLAN_ZAREJESTROWANY_NA_CZAS' and precommit_ok
        # W symulacji LIMIT fill musi pozostac odrebny od samego planu.
        if is_limit:
            if status in ('BEZ_WEJSCIA','BRAK_DANYCH'):
                limit_state='BRAK_ZLECENIA'
            elif r.get('limit_fill_status')=='NIEWYPELNIONY':
                limit_state='NIEWYPELNIONY'
            elif fill is None:
                limit_state='BRAK_DOWODU_FILL'
            elif entry is not None and fill < entry:
                limit_state='FILL_PRZED_ZLECENIEM'
            else:
                limit_state='FILL_SYMULOWANY'
        else:
            limit_state='NIE_DOTYCZY'
        # Bez logu gieldy nie mamy DOWODU REALNEGO wykonania; raportujemy
        # tylko potencjalna wykonalnosc i modelowe R.
        qualified=plan_ok and risk=='W_LIMIT_BADAWCZY' and (
            not is_limit or limit_state=='FILL_SYMULOWANY')
        raw_r=r.get('r')
        rr=None
        if qualified and status in FINAL and raw_r is not None:
            try:
                x=float(raw_r)
                rr=round(x,5) if np.isfinite(x) else None
            except (TypeError,ValueError):
                pass
        out.append({
            'okazja_id':r.get('okazja_id'),'symbol':r.get('symbol'),'wariant':r.get('wariant'),
            'proweniencja':r.get('proweniencja'),'abc_wykryto_utc':r.get('wykryto_utc'),
            'bos_zamkniety_utc':r.get('potwierdzono_utc'),
            'planowane_wejscie_utc':r.get('entry_utc'),
            'pierwszy_zapis_planu_utc':r.get('pierwszy_odczyt_entry_utc'),
            'fill_symulowany_utc':r.get('fill_utc'),
            'pierwszy_skan_utc':r.get('pierwsza_obserwacja_utc'),
            'status_modelu':status,'dowod_egzekucji':evidence,
            'wykonalnosc_oos':'PLAN_NA_CZAS_SYMULACJA' if qualified else 'NIEZWERYFIKOWANE',
            'stop_proc':r.get('stop_proc'),'wariant_sl8_status':risk,
            'limit_status':limit_state,'r_modelu':raw_r,
            'r_zweryfikowane_oos':rr,
            'powod':r.get('powod') or reason,'kontrola_zmiany':r.get('kontrola_zmiany'),
            'zapis_trwaly':r.get('zapis_trwaly')})
    return out


def _v260_podsumowanie(rows):
    return [{'wariant':var,
             'prospektywne_okazje':len({r['okazja_id'] for r in rows
                  if r['wariant']==var and r['proweniencja']=='PROSPEKTYWNE'}),
             'plan_na_czas':sum(r['wariant']==var and r['dowod_egzekucji']=='PLAN_ZAREJESTROWANY_NA_CZAS' for r in rows),
             'odtworzone_po_fakcie':sum(r['wariant']==var and r['dowod_egzekucji']=='PLAN_ODTWORZONY_PO_FAKCIE' for r in rows),
             'odrzucone_sl8':sum(r['wariant']==var and r['wariant_sl8_status']=='ODRZUCONY_RYZYKO' for r in rows),
             'limit_niewypelnione':sum(r['wariant']==var and r['limit_status']=='NIEWYPELNIONY' for r in rows),
             'model_rozliczony_oos':sum(r['wariant']==var and r['r_zweryfikowane_oos'] is not None for r in rows),
             'suma_R_modelu_oos':(round(sum(float(r['r_zweryfikowane_oos']) for r in rows
                 if r['wariant']==var and r['r_zweryfikowane_oos'] is not None),4)
                 if any(r['wariant']==var and r['r_zweryfikowane_oos'] is not None for r in rows)
                 else None),
             'uwaga':'Brak potwierdzenia rzeczywistego wykonania na gieldzie'}
            for var in _V244_WARIANTY]



# V6.262: oddzielamy zaplanowany, warunkowy sygnal BOS od dowodu
# egzekucji. Plan zapisany przed BOS nie jest sam w sobie transakcja.
_V262_COLS = ['okazja_id','symbol','wariant','proweniencja','plan_zapis_utc',
    'plan_wazny_do_utc','plan_status','bos_utc','entry_model_utc',
    'pierwszy_zapis_entry_utc','dowod_egzekucji','ryzyko_sl8',
    'status_modelu','r_modelu','r_z_kontrola_oos','uwaga']


def _v262_raport(journal, audit):
    by_key = {(str(x.get('okazja_id')), str(x.get('wariant'))):x for x in audit}
    out=[]
    for r in journal:
        a=by_key.get((str(r.get('okazja_id')),str(r.get('wariant'))),{})
        out.append({'okazja_id':r.get('okazja_id'),'symbol':r.get('symbol'),
            'wariant':r.get('wariant'),'proweniencja':r.get('proweniencja'),
            'plan_zapis_utc':r.get('plan_warunkowy_zapis_utc'),
            'plan_wazny_do_utc':r.get('plan_warunkowy_wazny_do_utc'),
            'plan_status':r.get('plan_warunkowy_status'),
            'bos_utc':r.get('potwierdzono_utc'),'entry_model_utc':r.get('entry_utc'),
            'pierwszy_zapis_entry_utc':r.get('pierwszy_odczyt_entry_utc'),
            'dowod_egzekucji':a.get('dowod_egzekucji'),
            'ryzyko_sl8':a.get('wariant_sl8_status'),
            'status_modelu':r.get('status'),'r_modelu':r.get('r'),
            'r_z_kontrola_oos':a.get('r_zweryfikowane_oos'),
            'uwaga':'Plan warunkowy nie dowodzi fill; dowod wejscia wymaga rejestracji na czas'})
    return out


# V6.271: spojnosc niezmiennego planu, status OOS fail-closed, niezalezny audyt.
# V6.265: diagnostyka mozliwosci OOS, bez symulowania wstecz obserwacji.
_V265_COLS = ['okazja_id','symbol','wariant','proweniencja','status_planu',
    'pierwszy_skan_utc','plan_zapis_utc','bos_utc','entry_model_utc',
    'opoznienie_pierwszego_skanu_min','wyprzedzenie_planu_przed_bos_min',
    'status_chronologii','status_zlecenia','uwaga']


def _v265_plan_timing(journal):
    """Audyt OOS: plan wymaga zapisu PRZED BOS; brak skanu nie jest fill."""
    def _ms(x):
        if x is None or str(x).strip() in ('', 'nan', 'None'):
            return None
        try:
            return int(parse_utc(str(x)))
        except (TypeError, ValueError, OverflowError):
            return None
    result=[]
    for r in journal:
        signal=_ms(r.get('wykryto_utc'))
        first=_ms(r.get('pierwsza_obserwacja_utc'))
        plan=_ms(r.get('plan_warunkowy_zapis_utc'))
        bos=_ms(r.get('potwierdzono_utc'))
        entry=_ms(r.get('entry_utc'))
        p=str(r.get('plan_warunkowy_status') or '')
        if r.get('proweniencja')!='PROSPEKTYWNE':
            verdict='RETRO_DIAGNOSTYKA'
        elif str(r.get('zapis_trwaly'))!='TAK_DRIVE':
            verdict='BRAK_TRWALEGO_ZAPISU'
        elif plan is None:
            verdict='BRAK_WCZESNEGO_PLANU'
        elif signal is not None and plan < signal:
            verdict='NIESPOJNY_CZAS_PLANU'
        elif bos is not None and plan > bos:
            verdict='PLAN_PO_BOS'
        elif bos is not None and _ms(r.get('plan_warunkowy_wazny_do_utc')) is not None and bos > _ms(r.get('plan_warunkowy_wazny_do_utc')):
            verdict='BOS_PO_WYGASNIECIU_PLANU'
        elif bos is None and p=='WYGASL_BEZ_BOS':
            verdict='WYGASL_BEZ_BOS'
        elif bos is None:
            verdict='PLAN_PRZED_BOS_OCZEKUJE'
        elif entry is not None and entry < bos:
            verdict='ENTRY_PRZED_BOS'
        else:
            verdict='PLAN_PRZED_BOS_BEZ_DOWODU_FILL'
        status=str(r.get('limit_fill_status') or '') if r.get('wariant')=='POTW_15M_BOS_LIMIT' else str(r.get('status') or '')
        result.append({'okazja_id':r.get('okazja_id'),'symbol':r.get('symbol'),
            'wariant':r.get('wariant'),'proweniencja':r.get('proweniencja'),
            'status_planu':p, 'pierwszy_skan_utc':r.get('pierwsza_obserwacja_utc'),
            'plan_zapis_utc':r.get('plan_warunkowy_zapis_utc'),
            'bos_utc':r.get('potwierdzono_utc'),'entry_model_utc':r.get('entry_utc'),
            'opoznienie_pierwszego_skanu_min':round((first-signal)/60000,2) if first is not None and signal is not None else None,
            'wyprzedzenie_planu_przed_bos_min':round((bos-plan)/60000,2) if bos is not None and plan is not None else None,
            'status_chronologii':verdict,'status_zlecenia':status,
            'uwaga':'Plan warunkowy != zlecenie; brak planu przed BOS nie moze byc uzupelniony retrospektywnie'})
    return result


# V6.271: osobne poziomy dowodu; nigdy nie utozsamiaj symulacji fill z realizacja giełdową.
_V271_COLS = ['okazja_id','symbol','wariant','proweniencja','status_planu',
    'status_chronologii','potwierdzony_plan_przed_bos','model_rozliczony',
    'model_R','kwalifikowany_model_OOS_R','faktyczny_fill_WEEX','powod']


def _v271_evidence(rows, audited, timing):
    by_key={(str(r.get('okazja_id')),str(r.get('wariant'))):r for r in audited}
    timings={(str(r.get('okazja_id')),str(r.get('wariant'))):r for r in timing}
    result=[]
    for r in rows:
        key=(str(r.get('okazja_id')),str(r.get('wariant')))
        a=by_key.get(key,{})
        t=timings.get(key,{})
        pre=t.get('status_chronologii')=='PLAN_PRZED_BOS_BEZ_DOWODU_FILL'
        validated=(pre and a.get('dowod_egzekucji')=='PLAN_ZAREJESTROWANY_NA_CZAS')
        r_model=r.get('r') if r.get('status') in FINAL else None
        qualified=a.get('r_zweryfikowane_oos') if validated else None
        result.append({'okazja_id':key[0],'symbol':r.get('symbol'),'wariant':key[1],
            'proweniencja':r.get('proweniencja'),
            'status_planu':r.get('plan_warunkowy_status'),
            'status_chronologii':t.get('status_chronologii'),
            'potwierdzony_plan_przed_bos':bool(pre),
            'model_rozliczony':r_model is not None,
            'model_R':r_model,
            'kwalifikowany_model_OOS_R':qualified,
            'faktyczny_fill_WEEX':False,
            'powod':a.get('dowod_egzekucji') or 'BRAK_DOWODU'})
    return result


def test_v271_elliott():
    import tempfile
    t=1_800_000_000_000
    def ts(offset): return snap_iso(t+offset)
    r={'okazja_id':'TEST','symbol':'TESTUSDT','wariant':'POTW_15M_BOS_MARKET',
       'proweniencja':'PROSPEKTYWNE','status':'timeout','r':0.3,
       'wykryto_utc':ts(0),'potwierdzono_utc':ts(900000),
       'entry_utc':ts(900000),'pierwszy_odczyt_entry_utc':ts(900000),
       'entry':100.,'sl':95.,'ryzyko_stop_status':'W_LIMIT_BADAWCZY',
       'zapis_trwaly':'TAK_DRIVE','kontrola_zmiany':'ZGODNE',
       'dowod_egzekucji_v255':'WEJSCIE_OBSERWOWANE_PRZED_CZASEM',
       'plan_warunkowy_zapis_utc':None,'plan_warunkowy_wazny_do_utc':None,
       'plan_warunkowy_status':'BRAK_WCZESNEGO_PLANU'}
    a=_v260_audyt([r],t+1800000)[0]
    assert a['dowod_egzekucji']=='BRAK_WCZESNEGO_PLANU_BOS' and a['r_zweryfikowane_oos'] is None
    r.update(plan_warunkowy_zapis_utc=ts(300000),
             plan_warunkowy_wazny_do_utc=ts(7200000),
             plan_warunkowy_status='PLAN_ZAPISANY_PRZED_BOS')
    b=_v260_audyt([r],t+1800000)[0]
    assert b['dowod_egzekucji']=='PLAN_ZAREJESTROWANY_NA_CZAS' and b['r_zweryfikowane_oos']==0.3
    tt=_v265_plan_timing([r])
    ev=_v271_evidence([r],[b],tt)
    assert ev[0]['kwalifikowany_model_OOS_R']==0.3 and ev[0]['faktyczny_fill_WEEX'] is False
    r['plan_warunkowy_wazny_do_utc']=ts(600000)
    c=_v260_audyt([r],t+1800000)[0]
    assert c['dowod_egzekucji']=='BRAK_WCZESNEGO_PLANU_BOS' and c['r_zweryfikowane_oos'] is None
    assert _v265_plan_timing([r])[0]['status_chronologii']=='BOS_PO_WYGASNIECIU_PLANU'
    r['plan_warunkowy_wazny_do_utc']=ts(7200000)
    r['pierwszy_odczyt_entry_utc']=ts(960000)
    d=_v260_audyt([r],t+1800000)[0]
    assert d['r_zweryfikowane_oos'] is None
    return 'PASS (precommit wymagany, plan wygasly, OOS bez retro, oddzielny model i fill)' 


# ================= V6.274: gotowosc planow BOS w skanach live =================
# Oddziela gotowosc do monitorowania od historycznego wykrycia wejscia.
# Żaden raport z tej sekcji nie dowodzi realnego fillu ani nie zmienia handlu.
_V274_COLS = ['okazja_id','symbol','wariant','proweniencja','abc_wykryto_utc',
    'pierwszy_skan_utc','plan_zapis_utc','plan_wazny_do_utc','bos_utc',
    'czas_do_wygasniecia_min','opoznienie_zapisu_po_abc_min','plan_przed_bos',
    'status_monitorowania','status_wariant_sl8','status_modelu','powod','zapis_trwaly']


def _v274_bos_gotowosc(journal, now_ms):
    """Wyłącznie czas zaobserwowany, brak rekonstrukcji z historii świec.

    Rozdziela nowy plan oczekujący, kwalifikowany plan po BOS,
    późny/brak planu i archiwalne okazje. Zegar/dane nieznane => fail closed.
    """
    def ms(value):
        if value is None or str(value).strip().lower() in ('', 'none', 'nan'):
            return None
        try:
            return int(parse_utc(str(value)))
        except (ValueError, TypeError, OverflowError):
            return None
    out=[]
    for r in journal:
        signal=ms(r.get('wykryto_utc'))
        first=ms(r.get('pierwsza_obserwacja_utc'))
        armed=ms(r.get('plan_warunkowy_zapis_utc'))
        expiry=ms(r.get('plan_warunkowy_wazny_do_utc'))
        bos=ms(r.get('potwierdzono_utc'))
        prospective=r.get('proweniencja')=='PROSPEKTYWNE'
        durable=r.get('zapis_trwaly')=='TAK_DRIVE'
        risk=str(r.get('ryzyko_stop_status') or 'BRAK_DANYCH')
        early=(durable and signal is not None and armed is not None
               and expiry is not None and signal <= armed <= expiry
               and (bos is None or armed <= bos <= expiry))
        # Używamy wyłącznie zapisanego statusu planu, nigdy fikcyjnego planu.
        status_plan=str(r.get('plan_warunkowy_status') or '')
        if not prospective:
            status='RETRO_DIAGNOSTYKA'
        elif not durable:
            status='BRAK_TRWALEGO_ZAPISU'
        elif signal is None or signal > now_ms or (armed is not None and armed > now_ms):
            status='NIESPOJNY_ZEGAR'
        elif armed is None or expiry is None:
            status='BRAK_WCZESNEGO_PLANU'
        elif armed < signal:
            status='PLAN_PRZED_WYKRYCIEM_ABC'
        elif bos is not None and armed > bos:
            status='PLAN_PO_BOS'
        elif bos is not None and bos > expiry:
            status='BOS_PO_WYGASNIECIU'
        elif now_ms > expiry and bos is None:
            status='WYGASL_BEZ_BOS'
        elif bos is None and early and status_plan=='UZBROJONY_PRZED_BOS':
            status='UZBROJONY_OCZEKUJE_BOS'
        elif bos is not None and early and status_plan=='PLAN_ZAPISANY_PRZED_BOS':
            status='PLAN_PRZED_BOS_WERYFIKUJ_ENTRY'
        else:
            status='NIESPOJNY_STAN_PLANU'
        if status=='UZBROJONY_OCZEKUJE_BOS':
            reason='Kolejny skan musi nastapic przed zamknieciem BOS; bez tego nie bedzie dowodu wejscia.'
        elif status=='PLAN_PRZED_BOS_WERYFIKUJ_ENTRY':
            reason='Sprawdz niezaleznie czas pierwszego odczytu entry i symulowany fill.'
        elif status=='RETRO_DIAGNOSTYKA':
            reason='Historyczny wynik nie jest niezaleznym OOS.'
        else:
            reason='Nie kwalifikuj jako terminowy plan BOS ani jako wykonane zlecenie.'
        out.append({'okazja_id':r.get('okazja_id'),'symbol':r.get('symbol'),
            'wariant':r.get('wariant'),'proweniencja':r.get('proweniencja'),
            'abc_wykryto_utc':r.get('wykryto_utc'),
            'pierwszy_skan_utc':r.get('pierwsza_obserwacja_utc'),
            'plan_zapis_utc':r.get('plan_warunkowy_zapis_utc'),
            'plan_wazny_do_utc':r.get('plan_warunkowy_wazny_do_utc'),
            'bos_utc':r.get('potwierdzono_utc'),
            'czas_do_wygasniecia_min':round((expiry-now_ms)/60000,2) if expiry is not None else None,
            'opoznienie_zapisu_po_abc_min':round((armed-signal)/60000,2) if signal is not None and armed is not None else None,
            'plan_przed_bos':bool(early and bos is not None),
            'status_monitorowania':status,'status_wariant_sl8':risk,
            'status_modelu':r.get('status'),'powod':reason,
            'zapis_trwaly':r.get('zapis_trwaly')})
    return out


def test_v274_elliott():
    t=1_800_000_000_000
    def ts(v): return snap_iso(t+v)
    r={'okazja_id':'NEW','symbol':'TESTUSDT','wariant':'POTW_15M_BOS_MARKET',
       'proweniencja':'PROSPEKTYWNE','wykryto_utc':ts(0),
       'pierwsza_obserwacja_utc':ts(60_000),
       'plan_warunkowy_zapis_utc':ts(60_000),
       'plan_warunkowy_wazny_do_utc':ts(7_200_000),
       'plan_warunkowy_status':'UZBROJONY_PRZED_BOS',
       'potwierdzono_utc':None,'zapis_trwaly':'TAK_DRIVE',
       'ryzyko_stop_status':'BRAK_DANYCH','status':'OCZEKUJE'}
    a=_v274_bos_gotowosc([r],t+120_000)[0]
    assert a['status_monitorowania']=='UZBROJONY_OCZEKUJE_BOS'
    assert not a['plan_przed_bos'] and a['czas_do_wygasniecia_min']==118.0
    r.update(potwierdzono_utc=ts(900_000),plan_warunkowy_status='PLAN_ZAPISANY_PRZED_BOS')
    a=_v274_bos_gotowosc([r],t+1_000_000)[0]
    assert a['status_monitorowania']=='PLAN_PRZED_BOS_WERYFIKUJ_ENTRY' and a['plan_przed_bos']
    r['plan_warunkowy_zapis_utc']=ts(960_000)
    assert _v274_bos_gotowosc([r],t+1_000_000)[0]['status_monitorowania']=='PLAN_PO_BOS'
    r['plan_warunkowy_zapis_utc']=None
    assert _v274_bos_gotowosc([r],t+1_000_000)[0]['status_monitorowania']=='BRAK_WCZESNEGO_PLANU'
    r.update(plan_warunkowy_zapis_utc=ts(60_000),potwierdzono_utc=None,plan_warunkowy_status='WYGASL_BEZ_BOS')
    assert _v274_bos_gotowosc([r],t+8_000_000)[0]['status_monitorowania']=='WYGASL_BEZ_BOS'
    r['zapis_trwaly']='NIE_TYLKO_RAPORT'
    assert _v274_bos_gotowosc([r],t+8_000_000)[0]['status_monitorowania']=='BRAK_TRWALEGO_ZAPISU'
    r['proweniencja']='RETRO_DIAGNOSTYKA'
    assert _v274_bos_gotowosc([r],t+8_000_000)[0]['status_monitorowania']=='RETRO_DIAGNOSTYKA'
    return 'PASS (uzbrojenie, BOS, pozny plan, brak planu, wygasanie, brak Drive, retro)'


def _v265_api_diag(by_endpoint, fetch_stats):
    """Raport audytowy: liczniki, nie przypisuje przyczyn bez danych."""
    rows=[]
    for endpoint, stat in sorted(by_endpoint.items(), key=lambda z: str(z[0])):
        rows.append({'kategoria':'HTTP_ENDPOINT','nazwa':str(endpoint),
            'zapytania':int(stat.get('count',0)),
            'czas_http_s':round(float(stat.get('seconds',0)),3),
            'uwaga':'Zapytania HTTP; sprawdz tryby_pobierania dla przyczyn'})
    for mode, count in sorted(fetch_stats.items(), key=lambda z: str(z[0])):
        rows.append({'kategoria':'TRYB_POBIERANIA','nazwa':str(mode),
            'zapytania':int(count) if isinstance(count,(int,float)) else None,
            'czas_http_s':None,
            'uwaga':'Licznik etapu; nie musi odpowiadac 1:1 zapytaniom HTTP'})
    return rows


