def _v245_limit_summary(rows):
    out = []
    for prov in ('RETRO_DIAGNOSTYKA','PROSPEKTYWNE'):
        a = [r for r in rows if r.get('wariant') == 'POTW_15M_BOS_LIMIT' and r.get('proweniencja') == prov]
        vals = [float(r['r']) for r in a if r.get('status') in FINAL and r.get('r') is not None]
        out.append({'proweniencja':prov,'okazje':len(a),
                    'bez_wejscia':sum(r.get('status') == 'BEZ_WEJSCIA' for r in a),
                    'niewypelnione':sum(r.get('limit_fill_status') == 'NIEWYPELNIONY' or
                                        str(r.get('status','')).lower() in ('niewypelniony','anulowany') for r in a),
                    'oczekujace_lub_otwarte':sum(r.get('status') in ('OCZEKUJE','otwarty') for r in a),
                    'rozliczone':len(vals), 'suma_R':round(sum(vals),4) if vals else None,
                    'sredni_R_na_rozliczona':round(sum(vals)/len(vals),4) if vals else None,
                    'sredni_R_na_okazje_0_za_brak_fill':round(sum(vals)/len(a),4) if a else None,
                    'ostrzezenie':'ZESTAWIENIE_BADAWCZE; brak fill_utc w V244; nie jest OOS wykonania'})
    return out


def test_v245():
    import tempfile
    with tempfile.TemporaryDirectory() as d:
        path = Path(d)/'ledger.json'
        base = {'okazja_id':'A','symbol':'AAAUSDT','wariant':'POTW_15M_BOS_LIMIT',
            'proweniencja':'PROSPEKTYWNE','sygnal_ms':1000000,
            'entry_utc':snap_iso(1300000),'potwierdzono_utc':snap_iso(1300000),
            'entry':100.,'sl':90.,'tp1':115.,'status':'niewypelniony','r':None}
        # brak Drive/replay nigdy nie produkuje potwierdzonego OOS
        r,m = _v245_apply([base],1200000,False,state_path=path)
        assert 'BRAK_TRWALEGO' in r[0]['chronologia'] and r[0]['stop_proc'] == 10.
        # Zapis / kolejny przebieg / zmiana decyzji -> fail-closed.
        r,m = _v245_apply([base],1200000,True,state_path=path)
        assert m['zapis_trwaly'] and r[0]['chronologia']=='POTWIERDZONA_OBSERWACJA'
        changed = dict(base, entry=105.,status='SL',r=-1.0)
        r,m = _v245_apply([changed],1800000,True,state_path=path)
        assert m['zmiany_decyzji']==1 and r[0]['entry']==100. and r[0]['r'] is None
        # historyczne wejscie nie moze udawac przyszlego
        late=dict(base,okazja_id='B')
        r,m = _v245_apply([late],1800000,True,state_path=path)
        assert r[0]['chronologia']=='PO_FAKCIE_BRAK_DOWODU_OOS'
        pending=dict(base, okazja_id='P', entry=None, entry_utc=None, tp1=None, status='OCZEKUJE')
        r,m = _v245_apply([pending],1100000,True,state_path=path)
        later=dict(base, okazja_id='P')
        r,m = _v245_apply([later],1200000,True,state_path=path)
        assert m['zmiany_decyzji']==0 and r[0]['entry']==100. and r[0]['chronologia']=='POTWIERDZONA_OBSERWACJA'
        retro=dict(base,okazja_id='C',proweniencja='RETRO_DIAGNOSTYKA')
        r,m = _v245_apply([retro],1200000,True,state_path=path)
        assert r[0]['chronologia']=='RETRO_LUB_BRAK_DOWODU'
        s=_v245_limit_summary([dict(base,status='niewypelniony'),dict(base,status='SL',r=-1.2)])
        assert s[1]['niewypelnione']==1 and s[1]['rozliczone']==1 and s[1]['suma_R']==-1.2
    return 'PASS (journal immutable, late signal fail-closed, brak Drive, LIMIT no-fill, SL 8% badawczy)'

def test_v244():
    # 15m: 8 pelnych blokow z max 10, przebicie dopiero po zamknieciu 9 bloku.
    q=15*60_000; step=5*60_000; t0=1000*q
    a=np.zeros((3*12,8))
    for i in range(len(a)):
        a[i,[O,H,L,C,T]]=[9.8,10,9.5,9.8,t0+i*step]
    a[26,C]=10.5; a[24:27,H]=10.6
    ts=t0+8*q; now=t0+10*q
    c,status=_v244_15m_bos(a,ts,9.,now)
    assert status=='OK' and c['entry_ms']==t0+27*step and c['open_next']==9.8
    c,status=_v244_15m_bos(a,ts,9.,t0+9*q)
    assert c is None and status.startswith('OCZEKUJE')
    bad=a.copy();bad[24,L]=8.8
    assert _v244_15m_bos(bad,ts,9.,now)[1]=='SL_PRZED_POTWIERDZENIEM'
    assert set(_V209_WARIANTY)=={'BAZA','SL_0.5','POTW_15M'}
    return 'PASS (BOS na zamknietych 15m, nastepne 5m, brak lookahead, SL przed fill; V209 bez zmian)'

