# V6.327: statusy kwalifikacji sa rozdzielone od liczby rekordow.
_V327_COUNTS_COLS = ['czas_utc','wariant','rekordy_wariantow','kwalifikowane_lacznie',
    'aktywne_czeka_bos','bos_paper','wygasle_bez_bos','ttl_brak_danych','odrzucone_filtry',
    'market_paper_fill','limit_paper_fill','limit_bez_fill',
    'unikalne_okazje_w_wariancie','rzeczywiste_weex_fill','wersja']


def _v327_validate_state(state, now_ms):
    """Istniejace plany sa niemutowalnymi zobowiazaniami; uszkodzony stan = STOP."""
    if not isinstance(state,dict) or not isinstance(state.get('plans'),dict):
        raise ValueError('V327_NIEPOPRAWNY_STAN')
    last=state.get('last_cycle_ms')
    if last is not None and int(now_ms)<int(last):
        raise ValueError('V327_ZEGAR_COFNIETY_FAIL_CLOSED')
    for key,p in state['plans'].items():
        try:
            if (not isinstance(p,dict) or p['plan_id']!=key or
                p['wariant'] not in _V326_NAMES or
                key!=p['okazja_id']+'|'+p['wariant'] or
                p['symbol'] != p['okazja_id'].split('|')[0] or
                p.get('real_fill') is not False or p.get('research_only') is not True or
                not (0<int(p['first_seen_ms'])<=int(now_ms)) or
                int(p['expiry_ms'])<=int(p['first_seen_ms']) or
                not (0<float(p['b'])<float(p['c'])<float(p['sl']))):
                raise ValueError('bad immutable plan')
            if p.get('bos_ms') is not None and (int(p['bos_ms'])<=int(p['first_seen_ms'])
                    or int(p['bos_seen_ms'])<int(p['bos_ms'])):
                raise ValueError('bad BOS chronology')
            for mode in ('market','limit'):
                if mode not in p or not isinstance(p[mode],dict):raise ValueError('bad mode')
                if p[mode].get('entry_ms') is not None:
                    if p.get('bos_seen_ms') is None or int(p[mode]['entry_ms'])<int(p['bos_seen_ms']):
                        raise ValueError('retro fill')
        except (KeyError,ValueError,TypeError,OverflowError) as exc:
            raise ValueError('V327_DZIENNIK_PLANOW_USZKODZONY_FAIL_CLOSED') from exc
    return True


def _v327_counts(state,now_ms):
    plans=list(state['plans'].values()); rows=[]
    for v in _V326_NAMES:
        ps=[p for p in plans if p['wariant']==v]
        rows.append({'czas_utc':snap_iso(now_ms),'wariant':v,
            'rekordy_wariantow':len(ps),
            'unikalne_okazje_w_wariancie':len({p['okazja_id'] for p in ps}),
            'kwalifikowane_lacznie':sum(p['status']!='ODRZUCONE_FILTRY' for p in ps),
            'aktywne_czeka_bos':sum(p['status']=='CZEKANIE_BOS' and int(p['expiry_ms'])>int(now_ms) for p in ps),
            'bos_paper':sum(p.get('bos_ms') is not None for p in ps),
            'wygasle_bez_bos':sum(p['status']=='WYGASL_BEZ_BOS' for p in ps),
            'ttl_brak_danych':sum(p['status']=='TTL_BRAK_DANYCH' for p in ps),
            'odrzucone_filtry':sum(p['status']=='ODRZUCONE_FILTRY' for p in ps),
            'market_paper_fill':sum(p['market'].get('entry_ms') is not None for p in ps),
            'limit_paper_fill':sum(p['limit'].get('entry_ms') is not None for p in ps),
            'limit_bez_fill':sum(p['limit']['status']=='BEZ_FILL' for p in ps),
            'rzeczywiste_weex_fill':0,'wersja':VERSION})
    return rows



def _v326_load_state(root):
    p=Path(root)/'elliott_v326_short_prospective.json'
    if not p.exists():
        return {'schema':1,'plans':{},'events':[]}
    try:
        state=json.loads(p.read_text(encoding='utf-8'))
        if (state.get('schema')!=1 or not isinstance(state.get('plans'),dict)
                or not isinstance(state.get('events'),list)):
            raise ValueError('niepoprawny format')
        return state
    except (OSError,ValueError,TypeError) as exc:
        raise ValueError('V326_DZIENNIK_USZKODZONY_FAIL_CLOSED') from exc


def _v326_write_state(root,state):
    p=Path(root)/'elliott_v326_short_prospective.json'
    zapisz_atomowo(p,lambda tmp:Path(tmp).write_text(
        json.dumps(state,ensure_ascii=False,separators=(',',':')),
        encoding='utf-8'),kopia=False)


def _v326_snapshot_candles(root,symbol,tf,now_ms):
    """Tylko cache zatwierdzonych OHLCV. Brak danych = bez zdarzenia."""
    p=Path(root)/'v286_candles'/(symbol+'_'+tf+'.json')
    if not p.exists(): return None
    blob=json.loads(p.read_text(encoding='utf-8'))
    arr=np.asarray(blob['candles'],dtype=float)
    if blob.get('symbol')!=symbol or blob.get('tf')!=tf or arr.ndim!=2 or arr.shape[1]!=8:
        raise ValueError('V326_NIEWIARYGODNY_CACHE_'+tf)
    if not len(arr) or not np.isfinite(arr).all():
        raise ValueError('V326_USZKODZONE_SWIECE_'+tf)
    # Weryfikacja historii nie oznacza, ze ostatnia swieca musi byc swieza:
    # mozna uczciwie przeliczyc dotychczasowe zdarzenia, ale nie udawac swiezego BOS.
    if not _v323_cache_ok(arr,tf,int(arr[-1,T]),min_bars=len(arr)):
        raise ValueError('V326_LUKI_SWIEC_'+tf)
    return arr[arr[:,T]+INTERVAL_MS[tf]<=now_ms]


def _v328_full_bos_window(a15, first_ms, expiry_ms):
    """Dowod kompletnego okna 15m od pierwszej DOZWOLONEJ swiecy po planie.

    Brak swiec lub luk = nie mozna orzec BRAK_BOS. Nie wolno doszacowywac.
    """
    if a15 is None or not len(a15):return False
    ms=INTERVAL_MS['15m']
    first_open=((int(first_ms)+ms-1)//ms)*ms
    last_open=(int(expiry_ms)//ms)*ms-ms
    if last_open<first_open:return False
    relevant=a15[(a15[:,T]>=first_open)&(a15[:,T]<=last_open)]
    return bool(len(relevant)==(last_open-first_open)//ms+1 and
                int(relevant[0,T])==first_open and int(relevant[-1,T])==last_open and
                np.all(np.diff(relevant[:,T])==ms))


def _v326_short_prospective(root,now_ms):
    """Zapis planu PRZED BOS; cztery filtry, po BOS papierowe MARKET/LIMIT.

    Nie awansuje historycznych BOS i nie nadaje kwalifikacji do prawdziwego handlu.
    Zdarzenia i wyniki wyznaczone deterministycznie z zamknietych swiec 5m;
    gdy oba poziomy TP/SL dotkniete w jednej swiecy: SL pierwszy (ostroznie).
    """
    root=Path(root);now_ms=int(now_ms)
    state=_v326_load_state(root)
    _v327_validate_state(state,now_ms)
    prior=root/'elliott_v324_short_precommit.json'
    source={'schema':1,'rows':{}}
    if prior.is_file():
        source=json.loads(prior.read_text(encoding='utf-8'))
        if source.get('schema')!=1 or not isinstance(source.get('rows'),dict):
            raise ValueError('V326_ZRODLOWY_DZIENNIK_FAIL_CLOSED')
    grouped={}
    for record in source['rows'].values():
        try:
            sym=str(record['symbol']); cm=int(record['c_ms']); seen=int(record['first_seen_ms'])
            ca=float(record['c_do_a']); fib=float(record['fib']); b=float(record['b']); c=float(record['c'])
            atr=float(record['pivot_atr'])
            if (not sym or cm<=0 or seen<=0 or not all(np.isfinite(x) for x in (ca,fib,b,c,atr))
                    or not (0<b<c) or atr<=0):
                raise ValueError('invalid geometry')
        except (KeyError,ValueError,TypeError,OverflowError) as exc:
            raise ValueError('V326_ZRODLOWA_GEOMETRIA_FAIL_CLOSED') from exc
        grouped.setdefault((sym,cm),[]).append(record)
    created=0
    for (sym,cm),group in sorted(grouped.items()):
        # Nie uzbrajaj historycznych, wygaslych okazji przy aktualizacji kodu.
        fresh=[r for r in group if int(r['first_seen_ms'])<=now_ms and
               now_ms<int(r.get('expiry_ms',int(r['first_seen_ms'])+2*HOUR_MS)) and
               str(r.get('status','')) in ('OCZEKUJE_BOS','OBSERWACJA_NEAR_MISS')]
        if not fresh:continue
        best=sorted(fresh,key=lambda r:(float(r['pivot_atr']),-int(r['first_seen_ms'])),reverse=True)[0]
        ca=float(best['c_do_a']);fib=float(best['fib']);b=float(best['b']);c=float(best['c'])
        trend=(best.get('trend_4h')=='ZGODNE')
        opp=f'{sym}|SHORT|C{cm}'
        for variant in _V326_NAMES:
            key=opp+'|'+variant
            if key in state['plans']:continue  # trwaly plan_id, brak ponownego uzbrajania
            no_ca=variant in ('BEZ_C_A','BEZ_C_A_I_FIB')
            no_fib=variant in ('BEZ_FIB','BEZ_C_A_I_FIB')
            okay=(trend and (no_ca or 0.618<=ca<=1.618) and
                  (no_fib or 0.5<=fib<=0.786))
            stop=c+0.1*(c-b)
            if stop<=b:raise ValueError('V326_NIEPOPRAWNY_SL')
            # W obu trybach ten sam precommit geometrii, zasady R i kosztow.
            state['plans'][key]={'plan_id':key,'okazja_id':opp,'symbol':sym,
                'wariant':variant,'pivot_atr':float(best['pivot_atr']),
                'first_seen_ms':now_ms,'c_ms':cm,'b':b,'c':c,'sl':stop,
                'ca':ca,'fib':fib,'trend_4h':best.get('trend_4h',''),
                'status':'CZEKANIE_BOS' if okay else 'ODRZUCONE_FILTRY',
                'expiry_ms':min(now_ms+2*HOUR_MS,int(best.get('expiry_ms',now_ms+2*HOUR_MS))),
                'bos_ms':None,'bos_seen_ms':None,
                'market':{'status':'NIEAKTYWNY','entry':None,'tp':None,'entry_ms':None,'r_netto':None},
                'limit':{'status':'NIEAKTYWNY','entry':b,'tp':b-1.5*(stop-b),
                         'entry_ms':None,'r_netto':None},
                'real_fill':False,'research_only':True,'wersja':VERSION}
            # Trwaly precommit - zapis kazdej konfiguracji przed sprawdzaniem swiec.
            _v326_write_state(root,state);created+=1
    events_added=0
    def event(plan,mode,what,when,entry=None,tp=None,r=None):
        nonlocal events_added
        state['events'].append({'plan_id':plan['plan_id'],'symbol':plan['symbol'],
            'wariant':plan['wariant'],'typ':mode,'zdarzenie':what,'czas_ms':int(when),
            'entry':entry,'sl':plan['sl'],'tp':tp,'r_netto':r,'real_fill':False})
        events_added+=1
    for plan in state['plans'].values():
        if plan['status'] in ('ODRZUCONE_FILTRY','KONIEC_BADANIA','WYGASL_BEZ_BOS','TTL_BRAK_DANYCH'):continue
        sym=plan['symbol']
        a15=_v326_snapshot_candles(root,sym,'15m',now_ms)
        a5=_v326_snapshot_candles(root,sym,'5m',now_ms)
        first=int(plan['first_seen_ms']);end=int(plan['expiry_ms'])
        if a15 is None:
            if plan['status']=='CZEKANIE_BOS' and now_ms>=end:
                plan['status']='TTL_BRAK_DANYCH'
                event(plan,'BOS','TTL_BEZ_DOWODU_Z_BRAKU_SWIEC',now_ms)
                _v326_write_state(root,state)
            continue
        if plan['status']=='CZEKANIE_BOS':
            # Dla BOS uzywamy swiec ROZPOCZETYCH po prospektywnym precommit.
            for i in range(8,len(a15)):
                op=int(a15[i,T]);close=op+INTERVAL_MS['15m']
                if op<first or close>now_ms or close>end:continue
                border=min(float(plan['b']),float(np.min(a15[i-8:i,L])))
                if float(a15[i,C])<border:
                    # Fail closed: BOS bez kompletnego ciaglego okna 15m
                    # od prospektywnego zapisu planu NIE jest dowodem OOS.
                    if not _v328_full_bos_window(a15,first,close):
                        continue
                    plan['bos_ms']=close;plan['bos_seen_ms']=now_ms
                    plan['status']='BOS_PAPER_ZAUWAZONY'
                    plan['market']['status']='OCZEKUJE_NA_NASTEPNA_5M'
                    plan['limit']['status']='OCZEKUJE_LIMIT_1H'
                    plan['limit']['limit_expiry_ms']=now_ms+HOUR_MS
                    event(plan,'BOS','BOS_PAPIEROWY',close)
                    _v326_write_state(root,state)
                    break
            if plan['status']=='CZEKANIE_BOS' and now_ms>=end:
                if _v328_full_bos_window(a15,first,end):
                    plan['status']='WYGASL_BEZ_BOS'
                    event(plan,'BOS','WYGASL_BEZ_BOS_Z_PELNYMI_SWIECAMI',now_ms)
                else:
                    plan['status']='TTL_BRAK_DANYCH'
                    event(plan,'BOS','TTL_BEZ_DOWODU_Z_BRAKU_SWIEC',now_ms)
                _v326_write_state(root,state)
        if plan['status']!='BOS_PAPER_ZAUWAZONY' or a5 is None:continue
        # Symulowany fill jest mozliwy dopiero PO pierwszym odczycie BOS.
        seen=int(plan['bos_seen_ms'])
        for mode in ('market','limit'):
            item=plan[mode];st=item['status']
            if st in ('NIEAKTYWNY','TP','SL','BEZ_FILL','NIEWAZNA_GEOMETRIA'):continue
            if st.startswith('OCZEKUJE'):
                for k in range(len(a5)):
                    op=int(a5[k,T]);close=op+INTERVAL_MS['5m']
                    if op<seen or close>now_ms:continue
                    if mode=='market':
                        # Z gory zadana zasada: najblizszy OPEN 5m po obserwacji.
                        entry=float(a5[k,O]);sl=float(plan['sl'])
                        if not (0<entry<sl):
                            item['status']='NIEWAZNA_GEOMETRIA';event(plan,mode,'NIEWAZNA_GEOMETRIA',close)
                        else:
                            item.update(status='PAPER_FILL',entry=entry,
                                tp=entry-1.5*(sl-entry),entry_ms=op)
                            event(plan,mode,'PAPER_FILL',op,entry,item['tp'])
                        _v326_write_state(root,state)
                        break
                    if close>int(item['limit_expiry_ms']):break  # swieca musi w calosci byc w TTL
                    entry=float(item['entry'])
                    if float(a5[k,L])<=entry<=float(a5[k,H]):
                        item.update(status='PAPER_FILL',entry_ms=op)
                        event(plan,mode,'PAPER_FILL',op,entry,item['tp'])
                        _v326_write_state(root,state)
                        break
                # Fail-closed: brak fill po TTL tylko przy ciaglym pokryciu swiec
                # od pierwszej potencjalnej 5m po odczycie BOS do konca TTL.
                ttl=int(item.get('limit_expiry_ms',0))
                first_possible=((seen+m5-1)//m5)*m5 if (m5:=INTERVAL_MS['5m']) else seen
                has_full_ttl=(len(a5)>0 and int(a5[0,T])<=first_possible and
                    int(a5[-1,T])+m5>=ttl and
                    _v323_cache_ok(a5,'5m',int(a5[-1,T]),min_bars=len(a5)))
                if (mode=='limit' and item['status']=='OCZEKUJE_LIMIT_1H'
                        and now_ms>=ttl and has_full_ttl):
                    item['status']='BEZ_FILL';event(plan,mode,'LIMIT_TTL_BRAK_FILL',now_ms)
                    _v326_write_state(root,state)
            # Rozliczenie TYLKO swiec po teoretycznym fill. SL ma priorytet,
            # jesli z powodu braku tickow TP i SL sa w jednej swiecy.
            if item['status']=='PAPER_FILL':
                entry=float(item['entry']);sl=float(plan['sl']);tp=float(item['tp'])
                risk=sl-entry
                if risk<=0:raise ValueError('V326_NIEDODATNIE_RYZYKO')
                for k in range(len(a5)):
                    op=int(a5[k,T]);close=op+INTERVAL_MS['5m']
                    if op<int(item['entry_ms']) or close>now_ms:continue
                    lo=float(a5[k,L]);hi=float(a5[k,H])
                    if hi>=sl or lo<=tp:
                        gross=(-1.0 if hi>=sl else (entry-tp)/risk)
                        net=round(gross-_V326_COST_PCT*entry/risk,5)
                        item['status']='SL' if hi>=sl else 'TP'
                        item['r_netto']=net
                        event(plan,mode,item['status'],close,entry,tp,net)
                        _v326_write_state(root,state)
                        break
    # Zapis raportow, bez zlecen: slady wyniku sa tylko na zamknietych swiecach.
    report=[]
    for p in state['plans'].values():
        report.append({'obserwacja_utc':snap_iso(now_ms),'plan_id':p['plan_id'],
            'okazja_id':p['okazja_id'],'symbol':p['symbol'],'wariant':p['wariant'],
            'pivot_atr':p['pivot_atr'],'first_seen_utc':snap_iso(int(p['first_seen_ms'])),
            'bos_utc':snap_iso(int(p['bos_ms'])) if p.get('bos_ms') else '',
            'bos_zauwazony_utc':snap_iso(int(p['bos_seen_ms'])) if p.get('bos_seen_ms') else '',
            'status':p['status'],'entry_limit':p['limit']['entry'],'sl':p['sl'],
            'tp_model_R':1.5,'market_status':p['market']['status'],
            'market_entry':p['market']['entry'],'market_r_netto':p['market']['r_netto'],
            'limit_status':p['limit']['status'],'limit_entry':p['limit']['entry'],
            'limit_r_netto':p['limit']['r_netto'],'potwierdzony_weex_fill':False,
            'tylko_badanie':True,'wersja':VERSION})
    ev=[]
    for e in state['events']:
        ev.append({'obserwacja_utc':snap_iso(now_ms),'plan_id':e['plan_id'],
            'symbol':e['symbol'],'wariant':e['wariant'],'typ':e['typ'],
            'zdarzenie':e['zdarzenie'],'czas_zdarzenia_utc':snap_iso(int(e['czas_ms'])),
            'entry':e['entry'],'sl':e['sl'],'tp':e['tp'],'r_netto':e['r_netto'],
            'real_fill':False,'wersja':VERSION})
    _v286_write_csv(root/'elliott_v326_short_plany.csv',_V326_PLAN_COLS,report)
    _v286_write_csv(root/'elliott_v326_short_zdarzenia.csv',_V326_EVENT_COLS,ev)
    perf=[]
    for variant in _V326_NAMES:
        subset=[p for p in state['plans'].values() if p['wariant']==variant]
        mr=[float(p['market']['r_netto']) for p in subset if p['market']['r_netto'] is not None]
        lr=[float(p['limit']['r_netto']) for p in subset if p['limit']['r_netto'] is not None]
        perf.append({'obserwacja_utc':snap_iso(now_ms),'wariant':variant,
            'unikalne_okazje':len({p['okazja_id'] for p in subset}),
            'plany':len(subset),'bos_paper':sum(bool(p['bos_ms']) for p in subset),
            'market_fill_paper':sum(p['market']['entry_ms'] is not None for p in subset),
            'market_tp_sl':len(mr),'market_avg_r_netto':round(float(np.mean(mr)),5) if mr else '',
            'limit_fill_paper':sum(p['limit']['entry_ms'] is not None for p in subset),
            'limit_bez_fill':sum(p['limit']['status']=='BEZ_FILL' for p in subset),
            'limit_tp_sl':len(lr),'limit_avg_r_netto':round(float(np.mean(lr)),5) if lr else '',
            'wersja':VERSION})
    _v286_write_csv(root/'elliott_v326_short_wyniki.csv',_V326_PERF_COLS,perf)
    counts=_v327_counts(state,now_ms)
    _v286_write_csv(root/'elliott_v327_short_liczniki.csv',_V327_COUNTS_COLS,counts)
    _v327_validate_state(state,now_ms)
    # Ostatni cykl zapisujemy atomowo w trwalym stanie; zaden plan ani jego
    # pierwotne parametry nie sa rekonstruowane przy kolejnym uruchomieniu.
    state['last_cycle_ms']=now_ms
    _v326_write_state(root,state)
    status={'wersja':VERSION,'czas_utc':snap_iso(now_ms),'tylko_badanie':True,
        'wyniki_wariantow_paper':perf,
        'unikalne_okazje':len({p['okazja_id'] for p in state['plans'].values()}),
        'warianty':len(state['plans']),'nowe_plany':created,'nowe_rekordy_wariantow':created,
        'nowe_zdarzenia':events_added,
        'kwalifikowane_plany_lacznie':sum(p['status']!='ODRZUCONE_FILTRY' for p in state['plans'].values()),
        'aktywne_czeka_bos':sum(p['status']=='CZEKANIE_BOS' and int(p['expiry_ms'])>int(now_ms) for p in state['plans'].values()),
        'nowe_aktywne_plany':sum(p['status']=='CZEKANIE_BOS' and p['first_seen_ms']==now_ms for p in state['plans'].values()),
        'wygasle_bez_bos':sum(p['status']=='WYGASL_BEZ_BOS' for p in state['plans'].values()),
        'ttl_brak_danych':sum(p['status']=='TTL_BRAK_DANYCH' for p in state['plans'].values()),
        'odrzucone_filtry':sum(p['status']=='ODRZUCONE_FILTRY' for p in state['plans'].values()),
        'po_ttl_bez_zweryfikowanego_bos':sum(p['status']=='CZEKANIE_BOS' and int(p['expiry_ms'])<=now_ms for p in state['plans'].values()),
        'liczniki_wariantow':counts,
        'bos_paper':sum(bool(p['bos_ms']) for p in state['plans'].values()),
        'market_paper_fill':sum(p['market']['entry_ms'] is not None for p in state['plans'].values()),
        'limit_paper_fill':sum(p['limit']['entry_ms'] is not None for p in state['plans'].values()),
        'potwierdzone_fill_weex':0,'rzeczywiste_zlecenia_weex':0,
        'koszt_roundtrip_pct':100*_V326_COST_PCT,
        'uwaga':'Tylko paper, bez retro BOS, bez realnego fill; warianty odrzucone sa nieaktywne.'}
    status['v329_ttl_audyt']=_v329_ttl_audyt(root,state,now_ms)
    zapisz_atomowo(root/'elliott_v326_short_status.json',lambda tmp:Path(tmp).write_text(
        json.dumps(status,ensure_ascii=False,indent=2),encoding='utf-8'),kopia=False)
    return status


_V329_TTL_COLS = ['czas_utc','plan_id','okazja_id','symbol','wariant','first_seen_utc',
                  'expiry_utc','status','po_ttl','pelne_okno_15m','dowod','bos_utc',
                  'market_paper_fill','limit_paper_fill','rzeczywisty_fill_weex']


def _v329_ttl_audyt(root,state,now_ms):
    """Read-only audit: brak dowodu na BOS to nie dowod braku BOS."""
    root=Path(root); rows=[]
    for p in state['plans'].values():
        first=int(p['first_seen_ms']); expiry=int(p['expiry_ms'])
        after=int(now_ms)>=expiry
        full=None
        if after and p.get('status')!='ODRZUCONE_FILTRY':
            try:
                candles=_v326_snapshot_candles(root,p['symbol'],'15m',now_ms)
                full=_v328_full_bos_window(candles,first,expiry)
            except (ValueError,KeyError,OSError,TypeError,IndexError):
                full=False
        if not after:reason='PRZED_TTL'
        elif p.get('bos_ms'):reason='BOS_ZAREJESTROWANY'
        elif p.get('status')=='ODRZUCONE_FILTRY':reason='WARIANT_ODRZUCONY'
        elif not full:reason='BRAK_KOMPLETNYCH_SWIEC_NIE_WOLNO_ORZEKAC_BRAKU_BOS'
        elif p.get('status')=='WYGASL_BEZ_BOS':reason='PELNE_SWIECE_BEZ_BOS'
        else:reason='WYMAGA_KONTROLI'
        rows.append({'czas_utc':snap_iso(now_ms),'plan_id':p['plan_id'],'okazja_id':p['okazja_id'],
          'symbol':p['symbol'],'wariant':p['wariant'],'first_seen_utc':snap_iso(first),
          'expiry_utc':snap_iso(expiry),'status':p['status'],'po_ttl':after,
          'pelne_okno_15m':full,'dowod':reason,
          'bos_utc':snap_iso(int(p['bos_ms'])) if p.get('bos_ms') else '',
          'market_paper_fill':p['market'].get('entry_ms') is not None,
          'limit_paper_fill':p['limit'].get('entry_ms') is not None,
          'rzeczywisty_fill_weex':False})
    _v286_write_csv(root/'elliott_v329_ttl_audyt.csv',_V329_TTL_COLS,rows)
    return {'rekordy':len(rows),'po_ttl':sum(r['po_ttl'] for r in rows),
            'nieweryfikowalne':sum(r['status']=='TTL_BRAK_DANYCH' for r in rows),
            'wygasle':sum(r['status']=='WYGASL_BEZ_BOS' for r in rows)}


def _v286_discover(now_ms, root=None, symbols=None, requester=None):
    """Skany 24 majors bez OI/depth. Atomowo uzbraja nowe okazje.

    Niezalezna dokumentacja, bez wstecznego przypisywania egzekucji.
    """
    root=Path(root) if root is not None else Path(DRIVE_DIR)
    _V328_CACHE_AUDIT.clear()
    symbols=tuple(symbols) if symbols is not None else MAJORS_4H
    state_path=root/'elliott_v286_abc_plany.json'
    funnel_path=root/'elliott_v286_lejek.csv'
    root.mkdir(parents=True,exist_ok=True)
    if state_path.exists():
        state=json.loads(state_path.read_text(encoding='utf-8'))
        if state.get('schema')!=1 or not isinstance(state.get('rows'),dict):
            raise ValueError('V286_BLEDNY_DZIENNIK_FAIL_CLOSED')
    else:
        state={'schema':1,'rows':{}}
    v322_diagnostics=[]
    short_new=0; short_updates=0
    records=[]; stats={'kontrakty':0,'kompletne':0,'nowe_okazje':0,'nowe_plany':0,
                      'aktywne_plany':0,'api':0,'cache':0,'bledy':0}
    for symbol in symbols:
        stats['kontrakty']+=1
        try:
            arr={}
            for tf in _V286_TIMEFRAMES:
                arr[tf],src=_v286_candles(symbol,tf,now_ms,root/'v286_candles',requester)
                stats['cache' if src=='CACHE' else 'api']+=1
            A={tf:cut(a,tf,now_ms,WIN[tf]) for tf,a in arr.items()}
            if not enough(A):
                records.append({'symbol':symbol,'status':'BRAK_HISTORII',
                                'powod':','.join(tf+':'+str(len(A[tf])) for tf in A)})
                continue
            stats['kompletne']+=1
            # V6.322: roznice progow sa WYŁACZNIE badaniem. Bazowy
            # _v209_wykryj i precommit dla 2 ATR pozostaja nietkniete.
            symbol_diag=_v322_threshold_diagnostics(symbol,A,now_ms)
            v322_diagnostics.extend(symbol_diag)
            nshort,ushort=_v324_short_research(root,symbol,symbol_diag,A['15m'],now_ms,
                                               live=(requester is None))
            short_new+=nshort;short_updates+=ushort
            # Wykorzystujemy niezmieniona definicje LONG DF i lejek V211.
            found=_v209_wykryj({symbol:{'asset_type':'COIN','arr':arr}},now_ms)
            base=[r for r in found if r.get('wariant')=='BAZA']
            rejection=next((k for k,v in _V211_LEJEK.items() if k not in (
                'kontrakty_COIN','ABC_LONG','ABC_SHORT','brak_ABC_na_pivotach_2ATR',
                'spelnia_warunki') and v),None)
            reason=('BRAK_ABC_2ATR' if _V211_LEJEK.get('brak_ABC_na_pivotach_2ATR')
                    else 'ABC_SHORT' if _V211_LEJEK.get('ABC_SHORT')
                    else rejection or 'BEZ_QUALIFIKACJI')
            for b in base:
                eid=str(b['id'])
                variants=('POTW_15M_BOS_MARKET','POTW_15M_BOS_LIMIT','POTW_15M_BOS_CEL_B')
                fresh=not any((eid+'|'+v) in state['rows'] for v in variants)
                changed=False
                if fresh:stats['nowe_okazje']+=1
                for var in variants:
                    key=eid+'|'+var
                    if key in state['rows']:
                        continue
                    stop=float(b['sl']);signal_ms=int(now_ms)
                    commit_ms=max(signal_ms,int(time.time()*1000)) if requester is None else signal_ms
                    if commit_ms>signal_ms+2*HOUR_MS:
                        continue
                    if not (np.isfinite(stop) and stop>0 and signal_ms>0):
                        continue
                    row={'precommit':{'armed_ms':commit_ms,'signal_ms':signal_ms,
                         'expiry_ms':signal_ms+2*HOUR_MS,'sl':stop,
                         'rule':'BOS_15M_ZAMKNIETY_8_SWIEC;MARKET_NASTEPNA_5M;LIMIT_RETEST_TTL_1H',
                         'observed_version':VERSION},
                         'decision':{'okazja_id':eid,'symbol':symbol,'wariant':var,
                         'proweniencja':'PROSPEKTYWNE','entry':None},
                         'source':'V286_MONITOR_WCZESNA_OBSERWACJA',
                         'first_saved_utc':snap_iso(commit_ms)}
                    state['rows'][key]=row
                    stats['nowe_plany']+=1
                    changed=True
                # Zapis musi nastapic przed sprawdzeniem BOS; blad nie moze
                # zostac przemilczany ani uznany za terminowy precommit.
                if changed:
                    zapisz_atomowo(state_path,lambda tmp:Path(tmp).write_text(
                        json.dumps(state,ensure_ascii=False,separators=(',',':')),
                        encoding='utf-8'),kopia=False)
            records.append({'symbol':symbol,'status':'ABC_QUALIFIKOWANE' if base else 'ODRZUCONE',
                            'sygnaly_BAZA':len(base),'powod':'OK' if base else reason})
        except Exception as exc:
            for v in (1.5,1.75,2.0):
                if not any(x['symbol']==symbol and x['pivot_atr']==v for x in v322_diagnostics):
                    v322_diagnostics.append({'symbol':symbol,'pivot_atr':v,'status':'BRAK_DANYCH',
                        'powod':type(exc).__name__,'kierunek':'','wiek_C_h':'',
                        'odleglosc_C_atr':'','c_ms':''})
            stats['bledy']+=1
            records.append({'symbol':symbol,'status':'BLAD_BRAK_DOWODU',
                            'powod':type(exc).__name__+':'+str(exc)[:70]})
    if not state_path.is_file():
        zapisz_atomowo(state_path,lambda tmp:Path(tmp).write_text(
            json.dumps(state,ensure_ascii=False),encoding='utf-8'),kopia=False)
    # Fail-closed: diagnostyka ma tylko charakter opisowy, nie tworzy planow.
    diag_rows=[dict(r,obserwacja_utc=snap_iso(now_ms),tylko_badanie=True,
                    wersja=VERSION) for r in v322_diagnostics]
    zapisz_atomowo(root/'elliott_v322_progi_aktualne.csv',
                   lambda tmp:_v286_write_csv(tmp,_V322_DIAG_COLS,diag_rows),kopia=False)
    v323_rows=_v323_compare_rows(v322_diagnostics,records,now_ms)
    zapisz_atomowo(root/'elliott_v323_porownanie_abc.csv',
                   lambda tmp:_v286_write_csv(tmp,_V323_COLS,v323_rows),kopia=False)
    _v286_write_csv(root/'elliott_v328_cache_audyt.csv',_V328_CACHE_COLS,_V328_CACHE_AUDIT)
    stats['v328_cache_powody']={key:sum(x['powod']==key for x in _V328_CACHE_AUDIT)
             for key in sorted({x['powod'] for x in _V328_CACHE_AUDIT})}
    stats['v329_zakres_monitora']={
        'liczba_symboli':len(symbols),
        'majors':sum(x in MAJORS_4H for x in symbols),
        'dodatkowe':sum(x not in MAJORS_4H for x in symbols),
        'symbole_dodatkowe':[x for x in symbols if x not in MAJORS_4H],
        'tryb':'badawczy; bez zlecen WEEX'}
    stats['v324_nowe_struktury_short']=short_new
    stats['v324_zmiany_short']=short_updates
    short_stats=_v324_short_export(root,now_ms)
    stats['v324_short']=short_stats
    stats['v325_short']=_v325_short_reports(root,now_ms)
    stats['v326_short']=_v326_short_prospective(root,now_ms)
    stats['v323_wiersze']=len(v323_rows)
    stats['v323_lejek']={str(th):{stage:sum(r['pivot_atr']==th and
        r['geometria']==stage for r in v323_rows) for stage in _V323_STAGES}
        for th in (1.5,1.75,2.0)}
    stats['v323_rozbieznosci']=sum(r['roznica_skanerow'] in (
        'BADAWCZY_KANDYDAT_BAZOWY_ODRZUCA',
        'BAZOWY_QUALIFIKUJE_BADAWCZY_ODRZUCA') for r in v323_rows)
    stats['v322_diag_wiersze']=len(diag_rows)
    stats['v322_kandydaci_badawczo']={str(v):sum(x.get('pivot_atr')==v and
         x.get('status')=='KANDYDAT_BADAWCZY' for x in v322_diagnostics)
         for v in (1.5,1.75,2.0)}
    stats['aktywne_plany']=sum(_v280_aktywny(v,max(now_ms,int(time.time()*1000)) if requester is None else now_ms) for v in state['rows'].values())
    import csv as _csv
    previous=[]
    if funnel_path.is_file():
        with funnel_path.open(encoding='utf-8',newline='') as f:
            previous=list(_csv.DictReader(f))
    rows=[dict(r,obserwacja_utc=snap_iso(now_ms),wersja=VERSION) for r in records]
    previous=(previous+rows)[-5000:]
    zapisz_atomowo(funnel_path,lambda tmp: _v286_write_csv(tmp,_V286_FUNNEL_COLS,previous),kopia=False)
    stats['status']='BRAK_ZWERYFIKOWANYCH_DANYCH' if stats['bledy']==len(symbols) else 'SKAN_OK'
    stats['last_cycle_utc']=snap_iso(now_ms)
    zapisz_atomowo(root/'elliott_v286_abc_status.json',lambda tmp:Path(tmp).write_text(
        json.dumps(stats,ensure_ascii=False,indent=2),encoding='utf-8'),kopia=False)
    return stats


def _v286_write_csv(path, cols, rows):
    import csv
    with open(path,'w',encoding='utf-8',newline='') as f:
        w=csv.DictWriter(f,fieldnames=cols,extrasaction='ignore')
        w.writeheader();w.writerows(rows)


def _v286_monitor_once(root=None,now_ms=None,discover=True,requester=None,symbols=None):
    root=Path(root) if root is not None else Path(DRIVE_DIR)
    now_ms=int(time.time()*1000) if now_ms is None else int(now_ms)
    stats=_v286_discover(now_ms,root,symbols,requester) if discover else {'status':'SKAN_WYLACZONY'}
    # Dopiero po trwalym zapisie planow sprawdzamy starsze BOS.
    state=root/'elliott_v286_abc_plany.json'
    if not state.is_file():
        return {'abc':stats,'bos':0,'status':'BRAK_PLANOW'}
    def _request(sym):
        arr,_=_v286_candles(sym,'5m',now_ms,root/'v286_candles',requester)
        # _v280_monitor_once oczekuje surowego formatu WEEX; konwersja odwrotna.
        return [[int(x[T]),x[O],x[H],x[L],x[C],x[V],int(x[T]+300000-1),x[5],0,x[6]] for x in arr]
    events=_v280_monitor_once(state_path=state,report_path=root/'elliott_v286_monitor.csv',
        requester=_request,now_ms=(int(time.time()*1000) if root==Path(DRIVE_DIR) and requester is None else now_ms),
        status_path=root/'elliott_v286_monitor_status.json')
    return {'abc':stats,'bos':len(events),'status':'CYKL_OK'}


def _v286_export(drive_ok,replay=False,root=None):
    root=Path(root) if root is not None else Path(DRIVE_DIR)
    for name in ('elliott_v329_ttl_audyt.csv','elliott_v328_cache_audyt.csv','elliott_v327_short_liczniki.csv','elliott_v326_short_plany.csv','elliott_v326_short_zdarzenia.csv','elliott_v326_short_wyniki.csv','elliott_v326_short_status.json','elliott_v325_short_okazje.csv','elliott_v325_short_filtry.csv','elliott_v325_short_status.json','elliott_v324_short_oos.csv','elliott_v323_porownanie_abc.csv','elliott_v322_progi_aktualne.csv','elliott_v286_lejek.csv','elliott_v286_monitor.csv',
                 'elliott_v286_abc_status.json','elliott_v286_monitor_status.json'):
        src=root/name
        if drive_ok and not replay and src.is_file():
            import shutil
            shutil.copyfile(src,OUT/name)
        elif name.endswith('.csv'):
            _v286_write_csv(OUT/name,_V329_TTL_COLS if 'v329_ttl_audyt' in name else _V328_CACHE_COLS if 'v328_cache_audyt' in name else _V327_COUNTS_COLS if 'v327_short_liczniki' in name else _V326_PLAN_COLS if 'v326_short_plany' in name else _V326_PERF_COLS if 'v326_short_wyniki' in name else _V326_EVENT_COLS if 'v326_short_zdarzenia' in name else _V325_OPP_COLS if 'v325_short_okazje' in name else _V325_FILTER_COLS if 'v325_short_filtry' in name else _V324_SHORT_COLS if 'v324_short' in name else _V323_COLS if 'v323_porownanie' in name else _V322_DIAG_COLS if 'v322_progi' in name else _V286_FUNNEL_COLS if 'lejek' in name else _V280_COLUMNS,[])
        else:
            save_json(name,{'status':'BRAK_DANYCH' if drive_ok else 'BRAK_DRIVE',
                            'monitor_research_only':True},pretty=True)


def test_v286_abc_monitor():
    import tempfile
    with tempfile.TemporaryDirectory() as d:
        root=Path(d)
        sig=1_800_000_000_000
        # Nie ma historii: brak fikcyjnych planow i brak wpisow OOS.
        def no_candles(sym,tf,n):return []
        a=_v286_discover(sig,root,('BTCUSDT',),no_candles)
        assert a['nowe_plany']==0 and a['bledy']==1
        assert (root/'elliott_v286_lejek.csv').exists()
        assert _v286_discover(sig+300000,root,(),no_candles)['nowe_plany']==0
        # Brak danych nie moze wplynac na zamrozony dziennik V209/V245.
        assert not (root/'elliott_v245_dziennik.json').exists()
        assert not (root/'elliott_long_df_oos_v209.csv').exists()
        assert _v286_monitor_once(root,sig,False)['status']=='CYKL_OK'
        # Oddzielny przypadek: pierwszy prospektywny sygnal buduje 3 immutable plans.
        root2=root/'positive';root2.mkdir()
        now=(int(time.time()*1000)//(4*HOUR_MS))*4*HOUR_MS+2*HOUR_MS
        def synthetic(sym,tf,n):
            ms=INTERVAL_MS[tf]
            last_open=(now//ms-1)*ms
            return [[last_open-(n-i-1)*ms,100,102,98,100,10,
                     last_open-(n-i-2)*ms-1,1000,0,5] for i in range(n)]
        original=globals()['_v209_wykryj']
        def fake_detector(PP,ts):
            _V211_LEJEK.clear();_V211_LEJEK.update({'kontrakty_COIN':1,'ABC_LONG':1,'spelnia_warunki':1})
            return [{'id':'TESTUSDT|123456','wariant':'BAZA','symbol':'TESTUSDT','sl':90.0}]
        try:
            globals()['_v209_wykryj']=fake_detector
            first=_v286_discover(now,root2,('TESTUSDT',),synthetic)
            assert first['nowe_plany']==3 and first['nowe_okazje']==1,first
            journal=json.loads((root2/'elliott_v286_abc_plany.json').read_text())
            assert len(journal['rows'])==3
            assert all(x['precommit']['armed_ms']<=x['precommit']['expiry_ms']
                       for x in journal['rows'].values())
            second=_v286_discover(now,root2,('TESTUSDT',),synthetic)
            assert second['nowe_plany']==0 and second['api']==0,second
            assert journal==json.loads((root2/'elliott_v286_abc_plany.json').read_text())
        finally:
            globals()['_v209_wykryj']=original
    return 'PASS (pusty lejek, pierwsze ABC -> 3 immutable plans, cache, dedup, brak falszywych fill)' 


# ================= V6.285: DIAGNOSTYKA MONITORA W ZIP =================
def _v285_export_monitor(drive_ok, now_ms, replay=False, *, root=None):
    """Eksportuje rzeczywisty heartbeat i dziennik bez tworzenia fikcyjnych fill."""
    root=Path(root) if root else Path(DRIVE_DIR)
    state=root/'elliott_v245_dziennik.json'
    beat=root/'elliott_v285_monitor_status.json'
    report=root/'elliott_v280_monitor.csv'
    meta={'wersja':VERSION,'czas_raportu_utc':snap_iso(now_ms),
          'status':'NIEURUCHOMIONY','aktywne_plany':0,
          'ostatni_cykl_utc':None,'potwierdzone_fill_WEEX':0,
          'tylko_badanie':True}
    if replay:
        meta['status']='REPLAY_BRAK_DOWODU'
    elif not drive_ok:
        meta['status']='BRAK_DRIVE'
    elif not state.is_file():
        meta['status']='BRAK_DZIENNIKA'
    else:
        try:
            obj=json.loads(state.read_text(encoding='utf-8'))
            if obj.get('schema')!=1 or not isinstance(obj.get('rows'),dict):
                raise ValueError('BAD_SCHEMA')
            meta['aktywne_plany']=sum(_v280_aktywny(x,now_ms) for x in obj['rows'].values())
            meta['plany_uzbrojone_ogolem']=sum(isinstance(x.get('precommit'),dict) for x in obj['rows'].values())
            meta['status']='BRAK_AKTYWNYCH_PLANOW' if not meta['aktywne_plany'] else 'PLAN_CZEKA_NA_MONITOR'
            if beat.is_file():
                b=json.loads(beat.read_text(encoding='utf-8'))
                stamp=parse_utc(str(b['last_cycle_utc']))
                meta['ostatni_cykl_utc']=b['last_cycle_utc']
                meta['status_cyklu']=b.get('status')
                meta['minuty_od_cyklu']=round((now_ms-stamp)/60000,2)
                meta['status']='MONITOR_AKTYWNY' if 0<=now_ms-stamp<=20*60000 else 'MONITOR_NIEAKTUALNY'
        except (OSError,ValueError,TypeError,KeyError,OverflowError) as exc:
            meta['status']='BLAD_ODCZYTU_FAIL_CLOSED'
            meta['blad']=type(exc).__name__
    # Zawsze plik CSV w ZIP; pusta tabela != wykonany monitor.
    if drive_ok and not replay and report.is_file():
        try:
            import shutil
            shutil.copyfile(report,OUT/'elliott_v285_monitor_obserwacje.csv')
            meta['obserwacje']='Z_DRIVE'
        except OSError:
            write_csv('elliott_v285_monitor_obserwacje.csv',[],_V280_COLUMNS,cols=_V280_COLUMNS)
            meta['obserwacje']='BLAD_KOPIOWANIA'
    else:
        write_csv('elliott_v285_monitor_obserwacje.csv',[],_V280_COLUMNS,cols=_V280_COLUMNS)
        meta['obserwacje']='BRAK'
    save_json('elliott_v285_monitor_meta.json',meta,pretty=True)
    return meta


def _v285_monitor_fullscan(drive_ok, now_ms, replay=False):
    """Jedna obserwacja po utrwaleniu planow; zero API przy braku planow."""
    if not drive_ok or replay:
        return {'status':'BRAK_TRWALEGO_ZAPISU_LUB_REPLAY'}
    try:
        if not (Path(DRIVE_DIR)/'elliott_v245_dziennik.json').is_file():
            return {'status':'BRAK_DZIENNIKA'}
        rows=_v280_monitor_once(now_ms=now_ms)
        return {'status':'CYKL_OK','liczba_obserwacji':len(rows)}
    except Exception as exc:
        return {'status':'BLAD_FAIL_CLOSED','blad':type(exc).__name__}


def test_v285_monitor():
    import tempfile
    global OUT
    previous=OUT
    try:
        with tempfile.TemporaryDirectory() as folder:
            root=Path(folder);OUT=root/'out';OUT.mkdir()
            t=1_800_000_000_000
            st=root/'elliott_v245_dziennik.json'
            st.write_text(json.dumps({'schema':1,'rows':{}}),encoding='utf-8')
            def no_request(sym):
                raise AssertionError('API niedozwolone przy zerze planow')
            assert _v280_monitor_once(st,root/'elliott_v280_monitor.csv',no_request,t,
                           root/'elliott_v285_monitor_status.json')==[]
            assert _v285_export_monitor(True,t,root=root)['status']=='MONITOR_AKTYWNY'
            assert _v285_export_monitor(True,t+3_600_000,root=root)['status']=='MONITOR_NIEAKTUALNY'
            assert _v285_export_monitor(True,t,replay=True,root=root)['status']=='REPLAY_BRAK_DOWODU'
            assert (OUT/'elliott_v285_monitor_obserwacje.csv').is_file()
    finally:
        OUT=previous
    return 'PASS (heartbeat bez API, eksport do ZIP, stale, replay fail-closed)'


def test_v280_monitor():
    import tempfile
    base=1_800_000_000_000
    t0=(base//900000)*900000
    sig=t0+9*900000
    plan={'precommit':{'armed_ms':sig+60_000,'signal_ms':sig,
                       'expiry_ms':sig+7_200_000,'sl':95.0},
          'decision':{'okazja_id':'TEST280','symbol':'TESTUSDT',
                      'wariant':'POTW_15M_BOS_MARKET','proweniencja':'PROSPEKTYWNE',
                      'entry':None}}
    assert _v280_aktywny(plan,sig+120000)
    assert not _v280_aktywny(plan,sig+9_000_000)
    assert _v280_wylicz(plan,np.zeros((0,8)),sig+120000)['status']=='BRAK_DANYCH_5M'
    assert _v280_wylicz(plan,np.zeros((0,8)),sig+7_300_000)['status']=='BRAK_DANYCH_5M'
    with tempfile.TemporaryDirectory() as folder:
        f=Path(folder)/'state.json';out=Path(folder)/'monitor.csv'
        f.write_text(json.dumps({'schema':1,'rows':{'test|market':plan}}))
        def sample(_):
            # 5m consecutive, at least 3h before ABC; no BOS
            return [[t0+i*300000,100,100.1,99,99.5,1,0,1,0,0] for i in range(70)]
        a=_v280_monitor_once(f,out,sample,sig+120000)
        assert len(a)==1 and a[0]['fill_weex'] is False
        _v280_monitor_once(f,out,sample,sig+120000)
        with out.open(encoding='utf-8') as h:
            assert len(list(__import__('csv').DictReader(h)))==1
    return 'PASS (fail closed, trwaly dziennik, dedup, bez order/fill, niezalezny tryb)'


def _v320_save_session(root, cycle_rows, started_ms, current_ms, final=False):
    """Nie tworzy fikcyjnego BOS: zapisuje metadane cykli, istniejące raporty i statusy."""
    import csv as _csv
    root=Path(root)
    columns=['numer','obserwacja_utc','status_abc','kontrakty','kompletne','nowe_okazje',
             'nowe_plany','aktywne_plany','bledy','api','cache','status_bos','obserwacje_bos','blad']
    session=root/'elliott_v320_sesja_cykle.csv'
    zapisz_atomowo(session,lambda tmp:_v286_write_csv(tmp,columns,cycle_rows),kopia=False)
    status={'wersja':VERSION,'badanie_bez_zlecen':True,'start_utc':snap_iso(started_ms),
            'ostatni_cykl_utc':snap_iso(current_ms),'cykle':len(cycle_rows),
            'zakonczona':bool(final),'ostatni_status':cycle_rows[-1] if cycle_rows else None}
    zapisz_atomowo(root/'elliott_v320_sesja_status.json',lambda tmp:Path(tmp).write_text(
        json.dumps(status,ensure_ascii=False,indent=2),encoding='utf-8'),kopia=False)
    return session


def _v320_bundle(root, cycle_rows, started_ms, current_ms, final=True):
    """Archiwum wyników monitora; gdy brak danych, wpisy ze statusem wyjaśniają dlaczego."""
    import zipfile as _zip
    root=Path(root)
    _v320_save_session(root,cycle_rows,started_ms,current_ms,final=final)
    filenames=('elliott_v329_ttl_audyt.csv','elliott_v328_cache_audyt.csv','elliott_v327_short_liczniki.csv',
               'elliott_v326_short_plany.csv','elliott_v326_short_zdarzenia.csv',
               'elliott_v326_short_wyniki.csv','elliott_v326_short_status.json',
               'elliott_v325_short_okazje.csv','elliott_v325_short_filtry.csv',
               'elliott_v324_short_oos.csv','elliott_v323_porownanie_abc.csv','elliott_v322_progi_aktualne.csv','elliott_v320_sesja_cykle.csv','elliott_v320_sesja_status.json',
               'elliott_v286_lejek.csv','elliott_v286_monitor.csv',
               'elliott_v286_abc_status.json','elliott_v286_monitor_status.json',
               'elliott_v280_monitor.csv','elliott_v285_monitor_status.json')
    dest=root/'elliott_v320_sesja_ostatnia.zip'
    # ZIP tworzony atomowo; nie wysyłamy dziennika precommit na serwer zewnętrzny.
    def _save(tmp):
        with _zip.ZipFile(tmp,'w',compression=_zip.ZIP_DEFLATED) as archive:
            for name in filenames:
                path=root/name
                if path.is_file(): archive.write(path,arcname=name)
    zapisz_atomowo(dest,_save,kopia=False)
    return dest


def _v320_monitor_cycle(root, now_ms, abc_scan=True, requester=None, symbols=None):
    """Odseparowane błędy: awaria starego V245 nie blokuje odkrywania nowych ABC."""
    result={'abc':{'status':'SKAN_WYLACZONY'},'bos':{'status':'BRAK_DZIENNIKA_V245'},'error':''}
    try:
        result['abc']=_v286_monitor_once(root=root,now_ms=now_ms,discover=abc_scan,requester=requester,symbols=symbols)
    except Exception as exc:
        result['abc']={'status':'BLAD_FAIL_CLOSED','blad':type(exc).__name__}
        result['error']='ABC: '+type(exc).__name__+': '+str(exc)[:130]
    # Stary dziennik V245 jest dodatkiem, nie wymaganiem V286.
    old=root/'elliott_v245_dziennik.json'
    if old.is_file():
        try:
            rows=_v280_monitor_once(state_path=old,report_path=root/'elliott_v280_monitor.csv',
                now_ms=now_ms,status_path=root/'elliott_v285_monitor_status.json')
            result['bos']={'status':'CYKL_OK','obserwacje':len(rows)}
        except Exception as exc:
            result['bos']={'status':'BLAD_FAIL_CLOSED','blad':type(exc).__name__}
            result['error']+=' V245: '+type(exc).__name__+': '+str(exc)[:130]
    return result


def _v280_cli(argv):
    import argparse
    parser=argparse.ArgumentParser(description='Elliott ABC/BOS monitor: badanie, bez zlecen')
    parser.add_argument('--elliott-monitor',action='store_true')
    parser.add_argument('--once',action='store_true',help='Jednorazowe sprawdzenie')
    parser.add_argument('--abc-scan',dest='abc_scan',action='store_true',default=True,
                        help='Wykrywanie ABC 24 majors (domyslnie wlaczone)')
    parser.add_argument('--no-abc-scan',dest='abc_scan',action='store_false')
    parser.add_argument('--abc-extra',default='',help='Dodatkowe symbole USDT po przecinku, tylko badanie (np. IDOLUSDT,GMXUSDT)')
    parser.add_argument('--abc-extra-file',default='',help='Opcjonalny plik TXT z lista do 100 dodatkowych plynnych kontraktow USDT (jeden symbol w linii)')
    parser.add_argument('--minutes',type=int,default=5)
    parser.add_argument('--hours',type=float,default=2.0)
    args=parser.parse_args(argv)
    if not IN_COLAB:
        raise RuntimeError('Monitor wymaga Google Colab i trwalego Google Drive')
    if drive is not None:
        drive.mount('/content/drive')
    root=Path(DRIVE_DIR)
    root.mkdir(parents=True,exist_ok=True)
    # Zapis kontrolny nawet wtedy, gdy nie istnieje jakikolwiek dziennik.
    proof=root/'elliott_v320_zapis_probe.json'
    zapisz_atomowo(proof,lambda tmp:Path(tmp).write_text(
        json.dumps({'sprawdzono_utc':snap_iso(int(time.time()*1000))}),encoding='utf-8'),kopia=False)
    if not proof.is_file(): raise RuntimeError('Nie udalo sie utrwalic stanu na Drive')
    print('WEEX',VERSION,'Elliott ABC+BOS, tylko badanie BEZ zlecen')
    began=int(time.time()*1000)
    interval=max(5,min(15,args.minutes))*60
    until=time.monotonic()+(0 if args.once else max(0.1,min(args.hours,12))*3600)
    extra=[x.strip().upper() for x in args.abc_extra.split(',') if x.strip()]
    if len(extra)>30 or any(not (x.endswith('USDT') and x[:-4].replace('1000','').isalnum()
                              and 5<=len(x)<=25) for x in extra):
        raise ValueError('Niepoprawna lista --abc-extra (max 30 symboli ...USDT)')
    extra_file=[]
    if args.abc_extra_file:
        p=Path(args.abc_extra_file)
        if not p.is_file():raise ValueError('Brak pliku --abc-extra-file')
        extra_file=[x.strip().upper() for x in p.read_text(encoding='utf-8').splitlines()
                    if x.strip() and not x.lstrip().startswith('#')]
        if len(extra_file)>100:raise ValueError('Maksymalnie 100 symboli w --abc-extra-file')
        if any(not (x.endswith('USDT') and x[:-4].replace('1000','').isalnum()
                      and 5<=len(x)<=25) for x in extra_file):
            raise ValueError('Niepoprawny symbol w --abc-extra-file')
    abc_symbols=tuple(dict.fromkeys(tuple(MAJORS_4H)+tuple(extra)+tuple(extra_file)))
    print('Elliott kontrakty:',len(abc_symbols),'dodatkowe:',extra,'z pliku:',len(extra_file))
    cycles=[]
    try:
        while args.once or time.monotonic()<until:
            started=time.monotonic();now=int(time.time()*1000)
            result=_v320_monitor_cycle(root,now,args.abc_scan,symbols=abc_symbols)
            abc=result.get('abc',{});abc_stats=abc.get('abc',abc)
            bos=result.get('bos',{})
            row={'numer':len(cycles)+1,'obserwacja_utc':snap_iso(now),
                 'status_abc':abc.get('status',abc_stats.get('status','BRAK')),
                 'kontrakty':abc_stats.get('kontrakty',0),'kompletne':abc_stats.get('kompletne',0),
                 'nowe_okazje':abc_stats.get('nowe_okazje',0),
                 'nowe_plany':abc_stats.get('nowe_plany',0),
                 'aktywne_plany':abc_stats.get('aktywne_plany',0),
                 'bledy':abc_stats.get('bledy',0),'api':abc_stats.get('api',0),
                 'cache':abc_stats.get('cache',0),
                 'status_bos':bos.get('status','BRAK'),
                 'obserwacje_bos':bos.get('obserwacje',0),'blad':result.get('error','')}
            cycles.append(row)
            _v320_bundle(root,cycles,began,now,final=False)
            print('Elliott cykl',len(cycles),'ABC:',abc_stats,'V245:',bos,
                  'bledy:',result.get('error','brak'))
            if args.once:break
            remaining=until-time.monotonic()
            if remaining<=0:break
            pause=min(max(0,interval-(time.monotonic()-started)),remaining)
            if pause>0:time.sleep(pause)
    finally:
        end=int(time.time()*1000)
        final_path=_v320_bundle(root,cycles,began,end,final=True)
        print('Elliott raport:',final_path)
        try:
            from google.colab import files as _colab_files
            _colab_files.download(str(final_path))
        except (ImportError,OSError,RuntimeError) as exc:
            print('Raport pozostaje na Drive:',type(exc).__name__)


def test_v320_session():
    import tempfile,zipfile
    with tempfile.TemporaryDirectory() as folder:
        root=Path(folder); t=1_800_000_000_000
        # Brak V245 i brak ABC przy pustym monitorze: start nie moze sie zatrzymac.
        x=_v320_monitor_cycle(root,t,False)
        assert x['bos']['status']=='BRAK_DZIENNIKA_V245',x
        assert x['abc']['status']=='BRAK_PLANOW',x
        assert x['abc']['abc']['status']=='SKAN_WYLACZONY',x
        archive=_v320_bundle(root,[{'numer':1,'obserwacja_utc':snap_iso(t),
                            'status_abc':'SKAN_WYLACZONY'}],t,t)
        with zipfile.ZipFile(archive) as z:
            assert z.testzip() is None
            assert 'elliott_v320_sesja_cykle.csv' in z.namelist()
            assert 'elliott_v320_sesja_status.json' in z.namelist()
    return 'PASS (brak V245, zapis statusu i ZIP, brak sztucznych fill)'

# ================= V6.321: AKTUALNY LEJEK ABC W PELNYM SKANIE =================
def _v321_fullscan_elliott(drive_ok, replay=False, *, root=None, output=None,
                          now_ms=None, requester=None, symbols=None):
    """Skan prospektywny na koncu pelnego przebiegu, nie kopiowanie starego lejka.

    Pliki V286 pozostaja historia. V321 publikuje jedynie wiersze z TEGO
    wywolania, z jednoznacznym wynikiem nawet przy awarii/API/Drive.
    """
    import csv as _csv
    root=Path(root) if root is not None else Path(DRIVE_DIR)
    output=Path(output) if output is not None else Path(OUT)
    output.mkdir(parents=True,exist_ok=True)
    now_ms=int(time.time()*1000) if now_ms is None else int(now_ms)
    marker=snap_iso(now_ms)
    status={'wersja':VERSION,'czas_skanu_utc':marker,
            'status':'NIEURUCHOMIONY','aktualny_lejek':False,
            'tylko_badanie':True,'realne_zlecenia_WEEX':0,'potwierdzone_fill_WEEX':0,
            'kontrakty':0,'kompletne':0,'nowe_okazje':0,'nowe_plany':0,
            'aktywne_plany':0,'bledy':0,'api':0,'cache':0,
            'bos_status':'NIEURUCHOMIONY','bos_obserwacje':0}
    current=[]
    if replay or not drive_ok:
        status['status']='REPLAY_BRAK_DOWODU' if replay else 'BRAK_TRWALEGO_DRIVE'
    else:
        try:
            # Wywolanie V320 zapewnia niezaleznosc od starego dziennika V245.
            result=_v320_monitor_cycle(root,now_ms,True,requester=requester,symbols=symbols)
            abc=result.get('abc',{})
            stats=abc.get('abc',{})
            for key in ('kontrakty','kompletne','nowe_okazje','nowe_plany',
                        'aktywne_plany','bledy','api','cache'):
                status[key]=int(stats.get(key,0) or 0)
            status['bos_status']=str(abc.get('status','BRAK'))
            status['bos_obserwacje']=int(abc.get('bos',0) or 0)
            status['v245_status']=result.get('bos',{}).get('status','BRAK')
            status['v245_obserwacje']=result.get('bos',{}).get('obserwacje',0)
            status['blad']=result.get('error','')
            if abc.get('status')=='CYKL_OK' and stats.get('status')=='SKAN_OK':
                status['status']='SKAN_OK' if status['bledy']==0 else 'SKAN_CZESCIOWY'
            else:
                status['status']='BLAD_SKANU_FAIL_CLOSED'
            src=root/'elliott_v286_lejek.csv'
            if src.is_file():
                with src.open(encoding='utf-8',newline='') as f:
                    current=[r for r in _csv.DictReader(f)
                             if r.get('obserwacja_utc')==marker]
            status['wiersze_aktualnego_lejka']=len(current)
            status['aktualny_lejek']=(len(current)==status['kontrakty'] and
                                     status['kontrakty']>0 and
                                     status['status'] in ('SKAN_OK','SKAN_CZESCIOWY'))
            if status['status'] in ('SKAN_OK','SKAN_CZESCIOWY') and not status['aktualny_lejek']:
                status['status']='NIEZGODNOSC_LEJKA_FAIL_CLOSED'
        except Exception as exc:
            status['status']='BLAD_SKANU_FAIL_CLOSED'
            status['blad']=type(exc).__name__+': '+str(exc)[:180]
    # V322: diagnostyka moze byc pokazana tylko gdy cykl skanu jest swiezy.
    diag_src=root/'elliott_v322_progi_aktualne.csv'
    diag_out=output/'elliott_v322_progi_aktualne.csv'
    if status.get('aktualny_lejek') and diag_src.is_file():
        import shutil as _shutil
        _shutil.copyfile(diag_src,diag_out)
    else:
        _v286_write_csv(diag_out,_V322_DIAG_COLS,[])
    # V324: oddzielny dziennik SHORT jest prospektywnym badaniem, bez fill/PnL.
    src_short=root/'elliott_v324_short_oos.csv'
    out_short=output/'elliott_v324_short_oos.csv'
    if status.get('aktualny_lejek') and src_short.is_file():
        import shutil as _shutil
        _shutil.copyfile(src_short,out_short)
    else:
        _v286_write_csv(out_short,_V324_SHORT_COLS,[])
    # V323: raport tylko z aktualnego cyklu; odrzucamy dane z poprzednich skanow.
    cmp_src=root/'elliott_v323_porownanie_abc.csv'
    cmp_out=output/'elliott_v323_porownanie_abc.csv'
    fresh=[]
    if status.get('aktualny_lejek') and cmp_src.is_file():
        with cmp_src.open(encoding='utf-8',newline='') as f:
            fresh=[r for r in _csv.DictReader(f) if r.get('obserwacja_utc')==marker]
    status['v323_wiersze']=len(fresh)
    status['v323_porownanie_aktualne']=(bool(status.get('aktualny_lejek')) and
        len(fresh)==3*status['kontrakty'])
    if not status['v323_porownanie_aktualne']:
        fresh=[]
        if status['status'] in ('SKAN_OK','SKAN_CZESCIOWY'):
            status['status']='BRAK_AKTUALNEGO_POROWNANIA_V323'
    _v286_write_csv(cmp_out,_V323_COLS,fresh)
    # W razie awarii current jest puste: nigdy nie kopiuj starego pliku jako nowy.
    _v286_write_csv(output/'elliott_v321_lejek_biezacy.csv',_V286_FUNNEL_COLS,current)
    zapisz_atomowo(output/'elliott_v321_skan_status.json',lambda tmp:Path(tmp).write_text(
        json.dumps(status,ensure_ascii=False,indent=2),encoding='utf-8'),kopia=False)
    return status


