def test_v324_short_and_cache():
    import tempfile, csv as _csv
    with tempfile.TemporaryDirectory() as td:
        root=Path(td)
        now=1_800_000_000_000
        interval=INTERVAL_MS['15m']
        # 30 zamknietych swiec, bez BOS w pierwszym cyklu.
        opens=np.arange(30,dtype=float)*interval+(now//interval-30)*interval
        a=np.zeros((30,8),float);a[:,T]=opens
        a[:,O]=100;a[:,H]=101;a[:,L]=99;a[:,C]=100
        cand={'symbol':'AAVEUSDT','status':'SHORT_OBSERWACJA','kierunek':'SHORT',
              'pivot_atr':2.0,'c_ms':now-2*HOUR_MS,'b':99.0,'c':105.0,
              'c_do_a':0.5799,'zniesienie_fib':0.818,'wiek_C_h':2,
              'odleglosc_C_atr':0.68,'zgodnosc_4h':'ZGODNE'}
        x,y=_v324_short_research(root,'AAVEUSDT',[cand],a,now,live=False)
        assert (x,y)==(1,0)
        state=json.loads((root/'elliott_v324_short_precommit.json').read_text())
        r=next(iter(state['rows'].values()))
        assert r['status']=='OBSERWACJA_NEAR_MISS' and r['powod']=='C_A_POZA_ZAKRESEM'
        # Ten sam odczyt = brak duplikatow; frozen precommit.
        assert _v324_short_research(root,'AAVEUSDT',[cand],a,now,live=False)==(0,0)
        assert state==json.loads((root/'elliott_v324_short_precommit.json').read_text())
        # Kwalifikowana geometrycznie oddzielna wersja; pierwsza swieca po precommit.
        good=dict(cand,pivot_atr=1.75,c_do_a=0.8,zniesienie_fib=0.65)
        x,_=_v324_short_research(root,'AAVEUSDT',[good],a,now,live=False)
        assert x==1
        later=np.zeros((1,8));later[0,T]=now//interval*interval
        later[0,O]=98;later[0,H]=100;later[0,L]=97;later[0,C]=97.5
        all_a=np.concatenate((a,later))
        # Zmieniamy testowa historie w strefie ostatnich swiec na stale 100,
        # aby prawdziwe przebicie bylo < B=99 i < ostatnie minima=99.
        x,y=_v324_short_research(root,'AAVEUSDT',[],all_a,now+interval,live=False)
        assert x==0 and y==2,(x,y)
        summary=_v324_short_export(root,now+interval)
        assert summary['struktury']==2 and summary['bos_badawczy']==1
        with (root/'elliott_v324_short_oos.csv').open(encoding='utf-8') as f:
            rr=list(_csv.DictReader(f))
        assert len(rr)==2 and all(r['real_fill']=='False' and not r['r_netto'] for r in rr)
        # cache: 320 historycznych + 1 zamknieta -> pobiera TYLKO ogon
        cache=root/'v286_candles';cache.mkdir()
        end=(now//INTERVAL_MS['5m']-2)*INTERVAL_MS['5m']
        a5=np.zeros((320,8));a5[:,T]=end-np.arange(319,-1,-1)*INTERVAL_MS['5m']
        oldpath=cache/'BTCUSDT_5m.json'
        oldpath.write_text(json.dumps({'symbol':'BTCUSDT','tf':'5m','candles':a5.tolist()}))
        counts=[]
        def req(sym,tf,n):
            counts.append(n)
            out=np.zeros((n,8));out[:,T]=end+INTERVAL_MS['5m']-(n-1-np.arange(n))*INTERVAL_MS['5m']
            return [[int(r[T]),0,0,0,0,0,int(r[T])+INTERVAL_MS['5m']-1,0,0,0] for r in out]
        got,src=_v286_candles('BTCUSDT','5m',now,cache,req)
        assert src=='API' and counts[0]<320 and len(got)==320,(src,counts)
        assert _v286_candles('BTCUSDT','5m',now,cache,req)[1]=='CACHE'
    return 'PASS (SHORT near-miss vs qualified; frozen precommit; BOS only later; no fill; incremental cache)'

def test_v325_short_research():
    import tempfile, csv as _csv
    with tempfile.TemporaryDirectory() as tmp:
        root=Path(tmp); now=1_800_000_000_000
        state={'schema':1,'rows':{}}
        def r(th,ratio,fib,qual,reason,status):
            return {'symbol':'AAVEUSDT','c_ms':now-2*HOUR_MS,
                'first_seen_ms':now,'pivot_atr':th,'c_do_a':ratio,'fib':fib,
                'kwalifikacja':qual,'powod':reason,'trend_4h':'ZGODNE',
                'status':status}
        state['rows']['k1']=r(1.75,0.5799,0.818,'NEAR_MISS_NIEKWALIFIKOWANY',
                              'C_A_POZA_ZAKRESEM','OBSERWACJA_NEAR_MISS')
        state['rows']['k2']=r(2.0,0.5799,0.818,'NEAR_MISS_NIEKWALIFIKOWANY',
                              'C_A_POZA_ZAKRESEM','WYGASL_BEZ_BOS')
        (root/'elliott_v324_short_precommit.json').write_text(json.dumps(state))
        out=_v325_short_reports(root,now)
        assert out['lejek']['unikalne_okazje']==1 and out['lejek']['warianty_atr']==2
        assert out['lejek']['spelnia_short']==0 and out['lejek']['bos_zarejestrowane']==0
        assert out['warianty_filtrow']=={'BAZA':0,'BEZ_C_A':0,'BEZ_FIB':0,'BEZ_C_A_I_FIB':1}
        with (root/'elliott_v325_short_okazje.csv').open() as f:
            rows=list(_csv.DictReader(f))
        assert len(rows)==1 and rows[0]['potwierdzone_weex_fill']=='False' and not rows[0]['r_netto']
        # Powtorzony przebieg nie zmienia starego planu ani nie dopisuje wejsc.
        before=(root/'elliott_v324_short_precommit.json').read_bytes()
        assert _v325_short_reports(root,now)['lejek']==out['lejek']
        assert (root/'elliott_v324_short_precommit.json').read_bytes()==before
        state['rows']['k3']=r(1.5,0.9,0.7,'SPELNIA_SHORT_BADAWCZY','OK','BOS_15M_BADAWCZY_BEZ_FILL')
        state['rows']['k3']['symbol']='BTCUSDT'
        (root/'elliott_v324_short_precommit.json').write_text(json.dumps(state))
        out=_v325_short_reports(root,now+HOUR_MS)
        assert out['lejek']['unikalne_okazje']==2 and out['lejek']['spelnia_short']==1
        assert out['lejek']['bos_zarejestrowane']==1 and out['weex_fills']==0
        assert out['warianty_filtrow']['BAZA']==1
    return 'PASS (dedup okazji, 4 filtry, near-miss fail-closed, OOS bez fill)'

def test_v326_short_prospective():
    import tempfile,csv as _csv
    with tempfile.TemporaryDirectory() as td:
        root=Path(td);now=1_800_000_000_000
        sym='AAVEUSDT';ms=INTERVAL_MS['15m']; m5=INTERVAL_MS['5m']
        c_ms=now-3*HOUR_MS
        src={'schema':1,'rows':{'a':{'symbol':sym,'c_ms':c_ms,
            'first_seen_ms':now-10*60_000,'expiry_ms':now+2*HOUR_MS,
            'pivot_atr':2.0,'c_do_a':0.5799,'fib':0.818,'b':90.,'c':110.,
            'trend_4h':'ZGODNE','status':'OBSERWACJA_NEAR_MISS'}}}
        (root/'elliott_v324_short_precommit.json').write_text(json.dumps(src))
        cache=root/'v286_candles';cache.mkdir()
        def mk(tf,last,n=40,close=100,low=95,high=105):
            dt=INTERVAL_MS[tf];rows=[]
            for i in range(n):
                op=last-(n-1-i)*dt
                rows.append([close,high,low,close,10,0,0,op])
            (cache/(sym+'_'+tf+'.json')).write_text(json.dumps(
                {'symbol':sym,'tf':tf,'candles':rows}))
        # Wszystkie swiece przed precommit -> zadnego retro BOS.
        mk('15m',(now//ms-1)*ms,close=100,low=95)
        mk('5m',(now//m5-1)*m5,close=100,low=95)
        res=_v326_short_prospective(root,now)
        assert res['unikalne_okazje']==1 and res['warianty']==4
        assert res['bos_paper']==0 and res['potwierdzone_fill_weex']==0
        data=_v326_load_state(root)
        assert sum(x['status']=='CZEKANIE_BOS' for x in data['plans'].values())==1
        assert all(x['real_fill'] is False for x in data['plans'].values())
        # Powtorzenie skanu nie tworzy zadnych nowych planow.
        assert _v326_short_prospective(root,now)['nowe_plany']==0
        # W następnym cyklu kolejna zamknieta 15m potwierdza BOS.
        future=((now//ms)+1)*ms
        mk('15m',future,close=100,low=95)
        # ostatnia swieca: close ponizej poziomu B=90 i 8 poprzednich low=95
        p=cache/(sym+'_15m.json');blob=json.loads(p.read_text());blob['candles'][-1][3]=88
        blob['candles'][-1][2]=87;p.write_text(json.dumps(blob))
        mk('5m',future,close=89,low=88,high=90)
        # Monitor uruchomiony po zamknieciu 15m; samej swiecy BOS nie wolno
        # uzywac jako fill, bo nie bylo jeszcze obserwacji w chwili jej otwarcia.
        t2=future+ms
        res=_v326_short_prospective(root,t2)
        assert res['bos_paper']==1 and res['market_paper_fill']==0
        data=_v326_load_state(root)
        armed=[x for x in data['plans'].values() if x['status']=='BOS_PAPER_ZAUWAZONY']
        assert len(armed)==1 and armed[0]['bos_seen_ms']==t2
        # Po przyszlej swiecy 5m - wyłącznie papierowy fill.
        mk('15m',future,close=100,low=95)
        blob=json.loads(p.read_text());blob['candles'][-1][3]=88;blob['candles'][-1][2]=87;p.write_text(json.dumps(blob))
        mk('5m',t2,close=89,low=88,high=90)
        res=_v326_short_prospective(root,t2+m5)
        assert res['market_paper_fill']==1 and res['potwierdzone_fill_weex']==0
        with (root/'elliott_v326_short_plany.csv').open() as f:
            rows=list(_csv.DictReader(f))
        assert len(rows)==4 and all(x['potwierdzony_weex_fill']=='False' for x in rows)
        assert (root/'elliott_v326_short_zdarzenia.csv').exists()
    return 'PASS (4 immutable warianty; BOS po precommit; fill paper pozniej; bez realnych zlecen)'



