# ================= V6.331: tick, dowody TP i identyfikacja =================
def _v331_tick(out, symbol):
    """Tick z faktycznie pobranego exchangeInfo zapisanego w snapshotcie coina.
    Nie zaklada, ze pricePrecision jest zawsze dostepne ani ze step moze byc zgadniety.
    """
    import re
    sym=str(symbol or '').strip().upper()
    if not re.fullmatch(r'[A-Z0-9]{2,40}',sym):return None,'NIEPOPRAWNY_SYMBOL'
    path=Path(out)/'coins'/(sym+'.json')
    if not path.is_file():return None,'BRAK_SNAPSHOTU_WEEX'
    try:
        meta=json.loads(path.read_text(encoding='utf-8')).get('meta') or {}
        for field in ('priceTick','tickSize','priceStep'):
            tick=_v330_float(meta.get(field))
            if tick and tick>0:return tick,'WEEX_'+field
        d=tick_decimals(meta)
        if d is None:return None,'BRAK_PRICE_PRECISION'
        return 10.0**(-d),'WEEX_pricePrecision'
    except (OSError,ValueError,TypeError,KeyError):
        return None,'BLAD_SNAPSHOTU_WEEX'


def _v331_align_levels(row, tick):
    """Wartosci Z BADANIA: round SL away from entry, TP toward entry; bez zmian zlecen."""
    from decimal import Decimal, ROUND_FLOOR, ROUND_CEILING
    side=str(row.get('side') or row.get('kierunek') or '').upper()
    sign={'LONG':1,'SHORT':-1}.get(side)
    e=_v330_float(row.get('entry'));sl=_v330_float(row.get('sl'))
    tps=[_v330_float(row.get('tp1')),_v330_float(row.get('tp2')),_v330_float(row.get('tp3'))]
    if sign is None or e is None or sl is None or tps[0] is None or min(e,sl,tps[0])<=0:
        return {'status':'BRAK_GEOMETRII'}
    if sign*(e-sl)<=0 or sign*(tps[0]-e)<=0:return {'status':'BLEDNA_GEOMETRIA'}
    if tick is None or tick<=0 or not math.isfinite(tick):return {'status':'BRAK_TICK_SIZE'}
    t=Decimal(str(tick))
    def q(x, how):return float((Decimal(str(x))/t).to_integral_value(rounding=how)*t)
    # dla ceny wejscia tylko diagnostyczna najblizsza wartosc, dla SL na zewnatrz
    e2=q(e,ROUND_CEILING if sign==1 else ROUND_FLOOR)
    sl2=q(sl,ROUND_FLOOR if sign==1 else ROUND_CEILING)
    tp2s=[q(x,ROUND_FLOOR if sign==1 else ROUND_CEILING) if x is not None else None for x in tps]
    if not e2>0 or not sl2>0 or not tp2s[0]>0 or sign*(e2-sl2)<=0 or sign*(tp2s[0]-e2)<=0:
        return {'status':'PO_TICK_NIEPOPRAWNE'}
    for i in (1,2):
        if tp2s[i] is not None and (tp2s[i]<=0 or sign*(tp2s[i]-tp2s[i-1])<=0):
            return {'status':'TP_PO_TICK_ZLEJ_KOLEJNOSCI'}
    risk=sign*(e2-sl2)
    rr=sign*(tp2s[0]-e2)/risk
    oldrr=sign*(tps[0]-e)/(sign*(e-sl))
    return {'status':'OK','entry_tick':e2,'sl_tick':sl2,'tp1_tick':tp2s[0],
            'tp2_tick':tp2s[1],'tp3_tick':tp2s[2],
            'rr1_brutto_tick':rr,'zmiana_rr_po_tick':rr-oldrr,
            'uwaga':'SYMULACJA_PO_TICK_BEZ_ZMIANY_ZLECEN'}


def _v331_future_path(candles, entry_ms, side, entry, sl, portions, fee_frac=0.0017):
    """Wylacznie PAPER. Czas wejscia musi byc potwierdzonym timestampem eventu.
    Zwroty R sa dostepne DOPIERO po zamknieciu wszystkich legow.
    Priorytet SL przed TP w kazdej 5m; kontrola ciaglosci bez domyslania swiec.
    """
    ms=INTERVAL_MS['5m']; k={'LONG':1,'SHORT':-1}.get(str(side).upper())
    if k is None:return {'status':'BRAK_STRONY','R':None}
    risk=k*(entry-sl)
    if risk<=0 or entry<=0 or sl<=0 or not math.isfinite(risk):return {'status':'ZLA_GEOMETRIA','R':None}
    if not portions or abs(sum(float(w) for w,r in portions)-1.0)>1e-8:
        return {'status':'ZLE_UDZIALY','R':None}
    # Każdy wiersz: [open_ts, open, high, low, close].
    rows=sorted((int(x[0]),float(x[2]),float(x[3])) for x in candles
                if len(x)>=5 and int(x[0])>=int(entry_ms))
    if not rows or rows[0][0]!=int(entry_ms) or int(entry_ms)%ms:
        return {'status':'BRAK_SWIECY_WEJSCIA','R':None}
    if any(rows[i][0]-rows[i-1][0]!=ms for i in range(1,len(rows))):
        return {'status':'BRAK_CIAGLOSCI_5M','R':None}
    remaining=[(float(w),float(target)) for w,target in portions]
    realized=0.;fee=fee_frac*entry/risk
    for op,high,low in rows:
        if not all(math.isfinite(x) and x>0 for x in (high,low)) or low>high:
            return {'status':'USZKODZONE_OHLC','R':None}
        sl_hit=high>=sl if k==-1 else low<=sl
        if sl_hit:
            realized-=sum(w for w,t in remaining)
            return {'status':'ZAMKNIETA_SL','R':round(realized-fee,6)}
        new=[]
        for w,target in remaining:
            tp=entry+k*target*risk
            tp_hit=low<=tp if k==-1 else high>=tp
            if tp<=0:return {'status':'NIEDODATNI_TP','R':None}
            if tp_hit:realized+=w*target
            else:new.append((w,target))
        remaining=new
        if not remaining:
            return {'status':'ZAMKNIETA_TP','R':round(realized-fee,6)}
    return {'status':'OTWARTA_BRAK_KONCOWEGO_R','R':None}


def _v331_prospective_paths(out):
    """NIGDY nie licz R bez precommit, BOS zauważonego i odrębnego PAPER_FILL.
    Brak danych => puste R. Symulacja od czasu wejścia, nie od wystąpienia ABC.
    """
    import csv
    out=Path(out);pfile=out/'elliott_v326_short_plany.csv';efile=out/'elliott_v326_short_zdarzenia.csv'
    plans=[];events=[]
    if pfile.exists():
        with pfile.open(encoding='utf-8-sig',newline='') as f:plans=list(csv.DictReader(f))
    if efile.exists():
        with efile.open(encoding='utf-8-sig',newline='') as f:events=list(csv.DictReader(f))
    def millis(ts):
        from datetime import datetime,timezone
        try:
            dt=datetime.fromisoformat(str(ts).replace('Z','+00:00'))
            if dt.tzinfo is None:dt=dt.replace(tzinfo=timezone.utc)
            return int(dt.timestamp()*1000)
        except (ValueError,TypeError):return None
    outrows=[]
    cache={}
    for p in plans:
        key=p.get('plan_id','');symbol=p.get('symbol','');first=millis(p.get('first_seen_utc'))
        bos=millis(p.get('bos_zauwazony_utc'))
        for mode in ('market','limit'):
            row=dict(plan_id=key,symbol=symbol,wariant=p.get('wariant',''),mode=mode,
                     status='BRAK_DOWODU_PAPER_FILL',r_100_tp1='',r_50_50='',r_33_33_34='')
            fills=[x for x in events if x.get('plan_id')==key and x.get('typ','').lower()==mode
                   and x.get('zdarzenie')=='PAPER_FILL']
            if len(fills)!=1 or first is None or bos is None or bos<=first:
                outrows.append(row);continue
            f=fills[0];ts=millis(f.get('czas_zdarzenia_utc'))
            e=_v330_float(f.get('entry'));sl=_v330_float(p.get('sl'))
            if ts is None or ts<bos or e is None or sl is None or not 0<e<sl:
                row['status']='NIEPOPRAWNA_CHRONOLOGIA_LUB_GEOMETRIA';outrows.append(row);continue
            if symbol not in cache:
                try:
                    blob=json.loads((out/'coins'/(symbol+'.json')).read_text(encoding='utf-8'))
                    cache[symbol]=blob['klines']['5m']['data']
                except (OSError,ValueError,TypeError,KeyError):cache[symbol]=None
            candles=cache[symbol]
            if not candles:
                row['status']='BRAK_SWIEC_5M';outrows.append(row);continue
            # Tylko zamknięte świeczki w paczce; utworzony raport pozostaje archiwalny.
            closed=[c for c in candles if len(c)>=7 and int(c[6])+1 <= int(time.time()*1000)]
            cfg={'r_100_tp1':[(1,1.5)],'r_50_50':[(.5,1),(.5,1.5)],
                 'r_33_33_34':[(.33,1.5),(.33,2),(.34,3)]}
            statuses=[]
            for field,legs in cfg.items():
                result=_v331_future_path(closed,ts,'SHORT',e,sl,legs)
                statuses.append(result['status'])
                if result['R'] is not None:row[field]=result['R']
            row['status']=';'.join(statuses)
            outrows.append(row)
    cols=['plan_id','symbol','wariant','mode','status','r_100_tp1','r_50_50','r_33_33_34']
    with (out/'audyt_take_profit_v331_sciezki_oos.csv').open('w',newline='',encoding='utf-8') as f:
        w=csv.DictWriter(f,fieldnames=cols);w.writeheader();w.writerows(outrows)
    return len(outrows)


def _v331_raport(out):
    """Audyt: nigdy nie symuluje historycznego fill bez chronologicznego dowodu."""
    import csv
    out=Path(out)
    a=out/'audyt_take_profit_v330.csv'
    rows=[]
    if a.exists():
        with a.open(encoding='utf-8-sig',newline='') as fh:
            for r in csv.DictReader(fh):
                tick,zrodlo=_v331_tick(out,r.get('symbol'))
                entry={'side':r.get('side'),'entry':r.get('entry'),'sl':r.get('sl'),
                       'tp1':r.get('tp1'),'tp2':r.get('tp2_informacyjny'),
                       'tp3':r.get('tp3_informacyjny')}
                d=_v331_align_levels(entry,tick)
                rows.append(dict(zrodlo=r.get('zrodlo',''),symbol=r.get('symbol',''),
                    side=r.get('side',''),wariant=r.get('wariant',''),
                    status_planu=r.get('status_planu',''),tick_size=tick,
                    tick_zrodlo=zrodlo,**d))
    columns=['zrodlo','symbol','side','wariant','status_planu','tick_size','tick_zrodlo',
             'status','entry_tick','sl_tick','tp1_tick','tp2_tick','tp3_tick',
             'rr1_brutto_tick','zmiana_rr_po_tick','uwaga']
    with (out/'audyt_take_profit_v331_tick.csv').open('w',newline='',encoding='utf-8') as fh:
        w=csv.DictWriter(fh,fieldnames=columns,extrasaction='ignore');w.writeheader();w.writerows(rows)
    # Nie naliczaj wynikow z samych ustawionych poziomow; papiery wymagaja bos, first-fill i ciaglych swiec.
    paper=out/'elliott_v326_short_plany.csv'; evidence=[]
    if paper.exists():
        with paper.open(encoding='utf-8-sig',newline='') as fh:
            for p in csv.DictReader(fh):
                entry_known=bool(p.get('bos_utc') and p.get('bos_zauwazony_utc') and
                    p.get('market_entry') and p.get('market_status') not in ('NIEAKTYWNY',''))
                evidence.append({'plan_id':p.get('plan_id',''),'symbol':p.get('symbol',''),
                    'wariant':p.get('wariant',''),'bos_utc':p.get('bos_utc',''),
                    'status':'NIEPELNY_DOWOD_ENTRY' if not entry_known else 'BRAK_ZWERYFIKOWANEJ_SCIEZKI_5M',
                    'r_100_tp1_netto':'','r_50_50_netto':'','r_33_33_34_netto':'',
                    'reason':'Badawcze scenariusze sa niewyliczalne bez niezaleznie dowiedzionego fill, kompletnych swiec po fill i zasad dla SL/TP na jednej swiecy.'})
    c=['plan_id','symbol','wariant','bos_utc','status','r_100_tp1_netto','r_50_50_netto','r_33_33_34_netto','reason']
    with (out/'audyt_take_profit_v331_sciezki_oos.csv').open('w',newline='',encoding='utf-8') as fh:
        w=csv.DictWriter(fh,fieldnames=c);w.writeheader();w.writerows(evidence)
    n_sciezek=_v331_prospective_paths(out)
    # Cache: osobno manifest decyzji i licznik API; po pelnym skanie raport juz istnieje.
    cpath=out/'elliott_v328_cache_audyt.csv'
    cached=[]
    if cpath.exists():
        with cpath.open(encoding='utf-8-sig',newline='') as fh: cached=list(csv.DictReader(fh))
    from collections import Counter
    reasons=Counter((x.get('tf',''),x.get('decyzja',''),x.get('powod','')) for x in cached)
    with (out/'elliott_v331_cache_powody.csv').open('w',newline='',encoding='utf-8') as fh:
        w=csv.writer(fh);w.writerow(['tf','decyzja','powod','liczba'])
        for k,v in sorted(reasons.items()):w.writerow([*k,v])
    ident=dict(_V189_STAN)
    ident['wersja']=VERSION
    ident['pewnosc_wykonania']='NIEPOTWIERDZONA' if not ident.get('sha256') else 'ODCISK_PLIKU_NIE_DOWOD_WYKONANIA'
    (out/'identyfikacja_skryptu_v331.json').write_text(json.dumps(ident,ensure_ascii=False,indent=2,default=str),encoding='utf-8')
    return {'tp_wiersze':len(rows),'tick_potwierdzone':sum(bool(r.get('tick_size')) for r in rows),
            'sciezki_badan_paper':n_sciezek,'cache_decyzje':len(cached),
            'identyfikacja':ident.get('status_v189','BRAK')}


