# ================= V6.332: osobny replay TAKE PROFIT MARKET / LIMIT =================
# Krytyczne: archiwalne `filled` to wynik symulacji, NIE rzeczywiste wykonanie WEEX.
# Schematy nie zmieniaja zadnych obecnych zlecen ani wyborow strategii.
V332_HORIZON_H = 12
V332_FEE_ROUNDTRIP_FRAC = 0.0017  # przyblizone oplaty+poslizg, nie rzeczywisty koszt rachunku
V332_SCHEMES = {
    '100_TP1': lambda r: [(1.0, r)],
    '50_1R_50_TP1': lambda r: [(0.5, 1.0), (0.5, r)],
    '33_TP1_33_2R_34_3R': lambda r: [(0.33, r), (0.33, 2.0), (0.34, 3.0)],
}


def _v332_time_ms(x):
    from datetime import datetime, timezone
    try:
        if x is None or str(x).strip().lower() in ('','nan','nat','none'): return None
        dt=datetime.fromisoformat(str(x).strip().replace('Z','+00:00'))
        if dt.tzinfo is None: dt=dt.replace(tzinfo=timezone.utc)
        return int(dt.timestamp()*1000)
    except (TypeError, ValueError, OverflowError):return None


def _v332_simulate(candles, fill_ms, side, entry, sl, tp1, legs,
                   horizon_h=V332_HORIZON_H, cost=V332_FEE_ROUNDTRIP_FRAC, entry_type='MARKET'):
    """Test R z zamknietych 5m, bez przesuwania fill i zgadywania luk.
    Brak wymaganych swiec -> brak wyniku. SL przed TP na tej samej swiecy.
    Po zamknieciu horyzontu pozostala czesc zamykana na cenie close.
    """
    step=300000
    k={'LONG':1,'SHORT':-1}.get(str(side).upper())
    if k is None:return 'BRAK_STRONY',None
    vals=(entry,sl,tp1)
    if any(not isinstance(v,(int,float)) or not math.isfinite(v) or v<=0 for v in vals):return 'NIEPOPRAWNE_CENY',None
    risk=k*(entry-sl)
    if risk<=0 or k*(tp1-entry)<=0:return 'BLEDNA_GEOMETRIA',None
    if fill_ms is None or fill_ms%step!=0:return 'NIEJEDNOZNACZNY_CZAS_FILL',None
    if not legs or any(w<=0 or rr<=0 for w,rr in legs) or abs(sum(w for w,rr in legs)-1)>1e-8:
        return 'BLEDNY_PODZIAL_TP',None
    n=int(horizon_h*3600000//step)
    if n<=0:return 'BLEDNY_HORYZONT',None
    end=fill_ms+n*step
    if candles is None:return 'BRAK_SWIEC_5M',None
    # Tylko przedzial, ktory byl zamkniety w chwili archiwizacji; bez uzupelniania.
    xs=[]
    for c in candles:
        try:
            tm=int(c[0]);
            if fill_ms<=tm<end:xs.append((tm,)+tuple(float(v) for v in c[1:5]))
        except (IndexError,TypeError,ValueError,OverflowError):return 'USZKODZONE_SWIECE',None
    xs.sort(key=lambda r:r[0])
    if not xs or xs[0][0]!=fill_ms:return 'BRAK_POCZATKU_5M',None
    last=fill_ms-step
    remaining=list(legs); realized=0.0
    fee=cost*entry/risk
    for tm,op,hi,lo,cl in xs:
        if tm!=last+step:return 'LUKA_LUB_DUPLIKAT_5M',None
        last=tm
        if not all(math.isfinite(v) and v>0 for v in (op,hi,lo,cl)) or lo>min(op,cl) or hi<max(op,cl):
            return 'USZKODZONE_OHLC',None
        if (lo<=sl if k==1 else hi>=sl):
            realized-=sum(w for w,r in remaining)
            return 'SL',round(realized-fee,6)
        # LIMIT: fill moze nastapic w srodku swiecy; jej TP moglo byc przed fill.
        # Zachowawczo zalicz mozliwy SL, nigdy TP na swiecy wypelnienia.
        if tm==fill_ms and str(entry_type).upper()=='LIMIT': continue
        pending=[]
        for w,rr in remaining:
            target=entry+k*rr*risk
            if target<=0:return 'NIEDODATNI_TP',None
            if (hi>=target if k==1 else lo<=target):realized+=w*rr
            else:pending.append((w,rr))
        remaining=pending
        if not remaining:return 'TP',round(realized-fee,6)
    # Bez kompletnych 12 godzin nie rozliczamy CZAS; zmienna pozycja zostaje otwarta.
    if len(xs)<n:return 'OTWARTE_LUB_BRAK_HORYZONTU',None
    realized+=sum(w*k*(xs[-1][4]-entry)/risk for w,rr in remaining)
    return 'CZAS',round(realized-fee,6)


def _v332_replay_tp(out):
    """Retrospektywny test tylko z potwierdzonym *symulowanym* fill w backtest.csv.
    Nie scala przypadkow replay z rzeczywistym kontem ani z Elliott OOS.
    Nie pobiera swiec; korzysta tylko z lokalnych snapshotow pelnego skanu.
    """
    import csv
    from collections import Counter, defaultdict
    out=Path(out)
    fields=['symbol','side','entry_type','entry','sl','tp1','fill_utc','status','event_id','filled','luka_danych','niejednoznaczne']
    trades=[];source=out/'backtest.csv'
    counts=Counter(); symbols={}; rows=[]
    if source.is_file():
        try:
            with source.open(encoding='utf-8-sig',newline='') as f:
                reader=csv.DictReader(f)
                for r in reader:
                    counts['wszystkie_rekordy']+=1
                    if str(r.get('entry_type','')).upper() not in ('MARKET','LIMIT'):continue
                    if not r.get('fill_utc'):counts['brak_fill']+=1;continue
                    if str(r.get('filled','')).strip().lower() not in ('true','1','tak'):
                        counts['brak_potwierdzonego_fill_w_backtescie']+=1;continue
                    if str(r.get('status','')).strip().lower()=='luka_danych':
                        counts['status_luka_danych']+=1;continue
                    if str(r.get('luka_danych','')).strip().lower() in ('true','1','tak') or str(r.get('niejednoznaczne','')).strip().lower() not in ('','nan','none','false','0'):
                        counts['odrzucone_oznaczone_jako_niejednoznaczne']+=1;continue
                    trades.append(r)
        except (OSError,UnicodeError,csv.Error) as exc:counts['blad_zrodla']+=1;trades=[]
    else:counts['brak_backtest_csv']=1
    seen=set()
    for r in trades:
        symbol=str(r['symbol']).strip().upper(); side=str(r['side']).upper()
        mode=str(r['entry_type']).upper(); event_id=str(r.get('event_id','')).strip()
        ts=_v332_time_ms(r['fill_utc']);e=_v330_float(r.get('entry'))
        sl=_v330_float(r.get('sl'));tp=_v330_float(r.get('tp1'))
        unique=event_id or '|'.join(map(str,(symbol,side,mode,ts,e,sl,tp)))
        if unique in seen:counts['duplikat']+=1;continue
        seen.add(unique)
        if not symbol.endswith('USDT') or ts is None or None in (e,sl,tp):
            counts['brak_wiarygodnych_pol']+=1;continue
        if symbol not in symbols:
            try:
                blob=json.loads((out/'coins'/(symbol+'.json')).read_text(encoding='utf8'))
                symbols[symbol]=blob['klines']['5m']['data']
            except (OSError,ValueError,KeyError,TypeError):symbols[symbol]=None
        risk=(e-sl) if side=='LONG' else (sl-e)
        if risk<=0:counts['zla_geometria']+=1;continue
        rr=(tp-e)/risk if side=='LONG' else (e-tp)/risk
        if rr<=0 or not math.isfinite(rr):counts['zla_geometria']+=1;continue
        for name, fn in V332_SCHEMES.items():
            status, R=_v332_simulate(symbols[symbol],ts,side,e,sl,tp,fn(rr),entry_type=mode)
            rows.append(dict(event_id=unique,symbol=symbol,side=side,entry_type=mode,
                fill_utc=r['fill_utc'],schemat=name,rr_tp1_brutto=round(rr,4),
                horyzont_h=V332_HORIZON_H,koszt_frac=V332_FEE_ROUNDTRIP_FRAC,
                status=status,r_netto='' if R is None else R,
                metodologia='HISTORYCZNY_REPLAY_NIE_LIVE_OOS'))
            counts['przypadki_'+status]+=1
    columns=['event_id','symbol','side','entry_type','fill_utc','schemat','rr_tp1_brutto',
             'horyzont_h','koszt_frac','status','r_netto','metodologia']
    with (out/'audyt_tp_v332_transakcje.csv').open('w',newline='',encoding='utf8') as f:
        w=csv.DictWriter(f,fieldnames=columns);w.writeheader();w.writerows(rows)
    groups=defaultdict(list);indep=defaultdict(set)
    for r in rows:
        if r['r_netto']!='':
            key=(r['entry_type'],r['schemat']);groups[key].append(float(r['r_netto']))
            indep[key].add((r['symbol'],str(r['fill_utc'])[:10]))
    sm=[]
    for mode in ('MARKET','LIMIT'):
        for scheme in V332_SCHEMES:
            key=mode,scheme;vals=groups[key]
            sm.append(dict(entry_type=mode,schemat=scheme,rozliczone=len(vals),
                symbol_dni=len(indep[key]),srednie_r_netto=round(sum(vals)/len(vals),5) if vals else '',
                suma_r_netto=round(sum(vals),5) if vals else '',
                win_rate_proc=round(100*sum(v>0 for v in vals)/len(vals),2) if vals else '',
                wiarygodnosc='ZA_MALO_NIEZALEZNYCH_DNI' if len(indep[key])<30 else 'TYLKO_REPLAY_BEZ_OOS'))
    with (out/'audyt_tp_v332_podsumowanie.csv').open('w',newline='',encoding='utf8') as f:
        w=csv.DictWriter(f,fieldnames=list(sm[0]));w.writeheader();w.writerows(sm)
    # Porownanie sparowane: TYLKO te same event_id z 3 kompletnymi wynikami.
    # Inaczej srednie moga sie roznic przez selekcje cenzurowanych pozycji.
    by_event=defaultdict(dict)
    for r in rows:
        if r['r_netto']!='':
            by_event[(r['entry_type'],r['event_id'])][r['schemat']]=float(r['r_netto'])
    paired=defaultdict(list)
    for (mode,eid), record in by_event.items():
        if len(record)==len(V332_SCHEMES):
            for scheme,val in record.items():paired[(mode,scheme)].append(val)
    matched=[]
    for mode in ('MARKET','LIMIT'):
        for scheme in V332_SCHEMES:
            vals=paired[(mode,scheme)]
            matched.append(dict(entry_type=mode,schemat=scheme,
                wspolne_kompletne_zdarzenia=len(vals),srednie_r_netto=round(sum(vals)/len(vals),6) if vals else '',
                metodologia='REPLAY_SPAROWANY_BEZ_OOS'))
    with (out/'audyt_tp_v332_porownanie_sparowane.csv').open('w',newline='',encoding='utf8') as f:
        w=csv.DictWriter(f,fieldnames=list(matched[0]));w.writeheader();w.writerows(matched)

    report={'wersja':VERSION,'metodologia':'RETROSPEKTYWNY_BACKTEST_NIE_WEEX_FILL','zrodlo':'backtest.csv',
        'koszt_round_trip_frac':V332_FEE_ROUNDTRIP_FRAC,'staly_horyzont_godzin':V332_HORIZON_H,
        'liczba_unikalnych_zdarzen':len(seen),'wiersze_wariantow':len(rows),
        'z_rozwiazanym_wynikiem':sum(r['r_netto']!='' for r in rows),
        'ograniczenia':['fill_utc z symulacji backtest, nie dowod wykonania WEEX',
        'przeglad wsteczny; bez OOS i bez automatycznego wyboru strategii',
        'oplaty+poslizg stale 0.17 procent; finansowanie i zmienny spread niepoliczone',
        'braki historii 5m lub otwarty wynik: brak R, a nie zero',
        'na swiecy z TP i SL SL ma pierwszenstwo'],
        'liczniki':dict(counts)}
    (out/'audyt_tp_v332_status.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf8')
    return report


def test_v332_take_profit():
    import tempfile,csv
    ms=300000;tm=1_800_000_000_000
    # Dwa kierunki, SL na tej samej swiecy, podzialy i terminowosc.
    rows=[[tm+i*ms,100,102,99,101] for i in range(144)]
    tp_rows=[list(x) for x in rows];tp_rows[0][2]=111
    st,r=_v332_simulate(tp_rows,tm,'LONG',100,95,110,[(1,2)])
    assert st=='TP' and 1.9<r<2.0,(st,r)
    bad=[list(x) for x in rows];bad[0][3]=94;bad[0][2]=115
    assert _v332_simulate(bad,tm,'LONG',100,95,110,[(1,2)])[0]=='SL'
    assert _v332_simulate(rows[:15],tm,'LONG',100,95,110,[(1,2)])[1] is None
    assert _v332_simulate(rows[1:],tm,'LONG',100,95,110,[(1,2)])[1] is None
    assert _v332_simulate(rows[:3]+rows[4:],tm,'LONG',100,95,110,[(1,2)])[1] is None
    assert _v332_simulate(rows,tm+1,'LONG',100,95,110,[(1,2)])[1] is None
    # LIMIT: nie wolno zaliczac TP dotknietego na swiecy wypelnienia.
    assert _v332_simulate(tp_rows,tm,'LONG',100,95,110,[(1,2)],entry_type='LIMIT')[0]=='CZAS'
    with tempfile.TemporaryDirectory() as td:
        out=Path(td);(out/'coins').mkdir()
        (out/'coins'/'BTCUSDT.json').write_text(json.dumps({'klines':{'5m':{'data':rows}}}))
        with (out/'backtest.csv').open('w',newline='') as f:
            w=csv.DictWriter(f,fieldnames=['symbol','side','entry_type','entry','sl','tp1','fill_utc','event_id','filled']);w.writeheader()
            from datetime import datetime,timezone
            t=datetime.fromtimestamp(tm/1000,timezone.utc).isoformat()
            for mode in ('MARKET','LIMIT'):
                w.writerow(dict(symbol='BTCUSDT',side='LONG',entry_type=mode,entry=100,sl=95,tp1=110,fill_utc=t,event_id=mode,filled='True'))
        summary=_v332_replay_tp(out)
        assert summary['liczba_unikalnych_zdarzen']==2 and summary['wiersze_wariantow']==6
        assert (out/'audyt_tp_v332_podsumowanie.csv').exists()
        assert (out/'audyt_tp_v332_porownanie_sparowane.csv').exists()
    return 'PASS (historyczny MARKET/LIMIT, 3 schematy, SL first, brak swiec fail-closed, eksport)'

# ================= V6.333: sparowany audyt TP z kontrola podzialu w czasie =================
# Metodologia: retrospective replay, no live/OOS claim; frozen decisions.
V333_MIN_TRAIN_DAYS = 10
V333_MIN_HOLDOUT_DAYS = 10
V333_MIN_HOLDOUT_EVENTS = 30
V333_MIN_DELTA_R = 0.03
V333_MIN_DAY_CONSISTENCY = 0.55


def _v333_csv(path):
    import csv
    if not path.is_file():return []
    with path.open('r',encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))


def _v333_report(out):
    """Audyt bez ingerencji w zlecenia: strategia×strona×stan, 60/40 UTC dni.

    Zdarzenia: jeden event_id z trzema rozliczonymi schematami TP.
    Dni globalne, dzielone chronologicznie, nie losowo ani po pojedynczych wierszach.
    Klasyfikacja setup_type i rynku pochodzi TYLKO z chwili pierwotnego wejscia.
    """
    import csv,math,statistics
    from collections import defaultdict,Counter
    out=Path(out)
    basic=['grupa','strategia','strona','stan_rynku','okres','schemat','dni','zdarzenia',
           'srednie_r_netto','sredni_delta_vs_tp1','mediana_dzien_delta','dni_z_dodatnia_delta_proc',
           'mae_R_srednie_z_archiwum','mfe_R_srednie_z_archiwum','metodologia']
    decisions=['grupa','dni_uczace','dni_testowe','zdarzenia_uczace','zdarzenia_testowe',
               'wariant_wybrany_train','train_delta_vs_tp1','holdout_delta_vs_tp1',
               'holdout_srednie_r','holdout_dni_z_poprawa_proc','werdykt','metodologia']
    reports=[];chosen=[];counters=Counter()
    prior=_v333_csv(out/'backtest.csv')
    tests=_v333_csv(out/'audyt_tp_v332_transakcje.csv')
    by_event={}; duplicate_events=set()
    for r in prior:
        eid=str(r.get('event_id','')).strip()
        if not eid:continue
        if eid in by_event:
            duplicate_events.add(eid)
        else:by_event[eid]=r
    trials=defaultdict(dict)
    for t in tests:
        eid=str(t.get('event_id','')).strip();sch=str(t.get('schemat',''))
        if eid in duplicate_events or not eid or sch not in V332_SCHEMES:continue
        try:
            value=float(t.get('r_netto',''))
            if not math.isfinite(value):continue
        except (TypeError,ValueError):continue
        if str(t.get('metodologia',''))!='HISTORYCZNY_REPLAY_NIE_LIVE_OOS':continue
        key=eid,sch
        if sch in trials[eid]:
            duplicate_events.add(eid)
        else:trials[eid][sch]=value
    complete=[]
    for eid,result in trials.items():
        if eid in duplicate_events or set(result)!=set(V332_SCHEMES):
            counters['niekompletne_lub_duplikat']+=1;continue
        row=by_event.get(eid)
        if row is None:counters['brak_zrodla']+=1;continue
        day=str(row.get('fill_utc',''))[:10]
        try:
            from datetime import date
            date.fromisoformat(day)
        except ValueError:counters['bledny_dzien']+=1;continue
        typ=str(row.get('setup_type') or '').strip().upper() or 'BRAK_TYPU'
        side=str(row.get('side') or '').strip().upper()
        mode=str(row.get('entry_type') or '').strip().upper()
        if side not in ('LONG','SHORT') or mode not in ('MARKET','LIMIT'):
            counters['bledna_strona']+=1;continue
        trend=str(row.get('btc_trend_4h','')).strip()
        if trend in ('1','1.0','LONG','UP','WZROSTOWY'):regime='BTC_4H_WZROST'
        elif trend in ('-1','-1.0','SHORT','DOWN','SPADKOWY'):regime='BTC_4H_SPADEK'
        else:regime='BTC_4H_BRAK'  # Brak trendu nie jest zgadywany.
        def optfloat(v):
            try:
                x=float(v);return x if math.isfinite(x) and x>=0 else None
            except (ValueError,TypeError):return None
        complete.append(dict(eid=eid,day=day,typ=typ,side=side,mode=mode,regime=regime,
                             mae=optfloat(row.get('mae_R')),mfe=optfloat(row.get('mfe_R')),returns=result))
    all_days=sorted({t['day'] for t in complete})
    cut=max(1,int(len(all_days)*.6)) if len(all_days)>=2 else len(all_days)
    train=set(all_days[:cut]);holdout=set(all_days[cut:])
    counters['dni_wszystkie']=len(all_days);counters['zdarzenia_sparowane']=len(complete)
    def keyfunc(t):
        return [f"{t['mode']}",f"{t['mode']}|{t['side']}",
                f"{t['mode']}|{t['side']}|{t['typ']}",
                f"{t['mode']}|{t['side']}|{t['typ']}|{t['regime']}"]
    grouped=defaultdict(list)
    for t in complete:
        for key in keyfunc(t):grouped[key].append(t)
    def mean(v):return sum(v)/len(v) if v else None
    def rounded(v):return round(v,6) if v is not None else ''
    for group,events in sorted(grouped.items()):
        variants={}
        for name, subset in [('TRAIN', [x for x in events if x['day'] in train]),
                             ('HOLDOUT',[x for x in events if x['day'] in holdout])]:
            if not subset:continue
            variants[name]={}
            for scheme in V332_SCHEMES:
                diffs=[x['returns'][scheme]-x['returns']['100_TP1'] for x in subset]
                perday=defaultdict(list)
                for x,d in zip(subset,diffs):perday[x['day']].append(d)
                daydiffs=[mean(v) for day,v in sorted(perday.items())]
                delta=mean(diffs); avg=mean([x['returns'][scheme] for x in subset])
                variants[name][scheme]=dict(avg=avg,delta=delta,n=len(subset),days=len(perday),
                                           pct=100*sum(v>0 for v in daydiffs)/len(daydiffs))
                reports.append(dict(grupa=group,strategia='|'.join(group.split('|')[2:3]) or 'WSZYSTKIE',
                    strona=next((v for v in group.split('|') if v in ('LONG','SHORT')),'OBA'),
                    stan_rynku=next((v for v in group.split('|') if v.startswith('BTC_4H_')),'WSZYSTKIE'),
                    okres=name,schemat=scheme,dni=len(perday),zdarzenia=len(subset),
                    srednie_r_netto=rounded(avg),sredni_delta_vs_tp1=rounded(delta),
                    mediana_dzien_delta=rounded(statistics.median(daydiffs)),
                    dni_z_dodatnia_delta_proc=round(variants[name][scheme]['pct'],2),
                    mae_R_srednie_z_archiwum=rounded(mean([x['mae'] for x in subset if x['mae'] is not None])),
                    mfe_R_srednie_z_archiwum=rounded(mean([x['mfe'] for x in subset if x['mfe'] is not None])),
                    metodologia='REPLAY_SPAROWANY_NIE_OOS_ZALEZNOSC_DNI'))
        tr=variants.get('TRAIN',{});te=variants.get('HOLDOUT',{})
        # Wybierz wyłącznie na zbiorze uczącym; walidacja później tylko raportowana.
        trained=max(tr,key=lambda k:tr[k]['avg']) if tr else ''
        a=tr.get(trained,{});b=te.get(trained,{})
        verdict='NIE_DOTYCZY_BRAK_DANYCH'
        if len(train)<V333_MIN_TRAIN_DAYS or len(holdout)<V333_MIN_HOLDOUT_DAYS:
            verdict='ZA_MALO_ROZNYCH_DNI'
        elif a.get('n',0)<V333_MIN_HOLDOUT_EVENTS or b.get('n',0)<V333_MIN_HOLDOUT_EVENTS:
            verdict='ZA_MALO_ZDARZEN'
        elif trained=='100_TP1':verdict='BAZA_NAJLEPSZA_TRAIN'
        elif a['delta']<V333_MIN_DELTA_R:verdict='POPRAWA_TRAIN_ZA_MALA'
        elif b['delta']<=0 or b['pct']<100*V333_MIN_DAY_CONSISTENCY:
            verdict='BRAK_STABILNEJ_POPRAWY_HOLDOUT'
        elif b['avg']<=0:verdict='WYNIK_NETTO_NADAL_UJEMNY'
        else:verdict='KANDYDAT_DO_DALSZEGO_OOS_BEZ_AUTOMATYCZNEJ_ZMIANY'
        chosen.append(dict(grupa=group,dni_uczace=a.get('days',0),dni_testowe=b.get('days',0),
            zdarzenia_uczace=a.get('n',0),zdarzenia_testowe=b.get('n',0),
            wariant_wybrany_train=trained,train_delta_vs_tp1=rounded(a.get('delta')),
            holdout_delta_vs_tp1=rounded(b.get('delta')),
            holdout_srednie_r=rounded(b.get('avg')),
            holdout_dni_z_poprawa_proc=round(b['pct'],2) if b else '',
            werdykt=verdict,metodologia='HISTORYCZNY_HOLDOUT_NIE_PROSPEKTYWNY_OOS'))
    def export(filename,columns,content):
        with (out/filename).open('w',newline='',encoding='utf-8') as f:
            w=csv.DictWriter(f,fieldnames=columns);w.writeheader();w.writerows(content)
    export('audyt_tp_v333_segmenty.csv',basic,reports)
    export('audyt_tp_v333_walkforward.csv',decisions,chosen)
    # Near-duplicate AAVE: tylko ostrzegamy o ponownym utworzeniu tej samej struktury B.
    plans=_v333_csv(out/'elliott_v326_short_plany.csv');opps={}
    for p in plans:
        oid=p.get('okazja_id','');sym=p.get('symbol','')
        if not oid or not sym or oid in opps:continue
        try:b=float(p.get('entry_limit',''));fs=_v332_time_ms(p.get('first_seen_utc'))
        except (TypeError,ValueError):continue
        if not math.isfinite(b) or b<=0 or fs is None:continue
        opps[oid]=dict(symbol=sym,okazja_id=oid,first_seen_utc=p['first_seen_utc'],ms=fs,b=b)
    overlap=[]
    for symbol in sorted({v['symbol'] for v in opps.values()}):
        xx=sorted((v for v in opps.values() if v['symbol']==symbol),key=lambda v:v['ms'])
        for i,x in enumerate(xx):
            for y in xx[i+1:]:
                dh=(y['ms']-x['ms'])/3600000
                if dh>12:break
                delta=abs(y['b']-x['b'])/max(x['b'],y['b'])
                if delta<=.001:
                    overlap.append(dict(symbol=symbol,okazja_wczesniejsza=x['okazja_id'],
                        okazja_pozniejsza=y['okazja_id'],odstep_h=round(dh,3),
                        roznica_B_pct=round(100*delta,5),status='PODOBNA_STRUKTURA_DO_RECZNEGO_AUDYTU',
                        decyzja='NIE_SCALONO_AUTOMATYCZNIE'))
    export('elliott_v333_podobne_okazje.csv',['symbol','okazja_wczesniejsza',
        'okazja_pozniejsza','odstep_h','roznica_B_pct','status','decyzja'],overlap)
    status={'wersja':VERSION,'status':'AUDYT_REPLAY_NIE_OOS',
            'zdarzenia_sparowane':len(complete),'dni_treningowe':len(train),
            'dni_holdout':len(holdout),'segmenty':len(grouped),
            'podobne_okazje_elliott':len(overlap),'liczniki':dict(counters),
            'ostrzezenia':['wyniki retrospektywne, nie prospektywne OOS','podzial wg dni UTC jest globalny, bez mieszania wierszy jednego dnia',
              'srednie po zdarzeniach sa skorelowane; osobno pokazano dni',
              'MAE/MFE sa wartosciami z historycznego backtestu, nie nowym niezaleznym wyliczeniem',
              'brak automatycznych zmian strategii lub zlecen']}
    (out/'audyt_tp_v333_status.json').write_text(json.dumps(status,ensure_ascii=False,indent=2),encoding='utf8')
    return status


