# V6.338 reports only: diagnostics from immutable scanner outputs.
def _v338_diagnostyka(root):
    """Create a read-only rejection funnel, Elliott unique opportunity view, and daily TP stability.

    Unknown precise 1b rejection reason remains UNKNOWN; do not reverse engineer a predicate
    from its grade or fabricate a reason. No order, signal, risk or OOS code is changed.
    """
    from collections import Counter, defaultdict
    import csv as _csv
    import math as _math
    root = Path(root)
    def read(name):
        p = root / name
        if not p.is_file(): return []
        try:
            with p.open(encoding='utf-8-sig', newline='') as f:
                return list(_csv.DictReader(f))
        except (OSError, UnicodeError, _csv.Error):
            return []
    def output(name, cols, rows):
        with (root / name).open('w', encoding='utf-8', newline='') as f:
            w = _csv.DictWriter(f, fieldnames=cols, extrasaction='ignore')
            w.writeheader(); w.writerows(rows)
    def val(r, key):
        return str(r.get(key) or '').strip()
    def unique(rows):
        return len({(val(r,'symbol').upper(), val(r,'side').upper()) for r in rows
                    if val(r,'symbol')})
    def float_ok(v):
        try:
            x=float(v)
            return x if _math.isfinite(x) else None
        except (ValueError,TypeError):return None
    def reasons(r):
        # Explicit source fields only. A single row may have multiple reasons.
        found=[]
        for field in ('blokady_bezpieczenstwa','blokady_kwalifikacji',
                      'blokady_wykonania_tradfi','not_tradable_reason'):
            v=val(r,field)
            if v and v.lower() not in ('nan','none','false','-'):
                found.append(field+': '+v)
        if not found and val(r,'status_setupu')=='ZABLOKOWANY':
            found.append('BRAK_SZCZEGOLU_W_POLACH_BLOKAD')
        return found
    ranking=read('ranking.csv')
    ranked_market=[r for r in ranking if val(r,'entry_type').upper()=='MARKET']
    ranked_limit=[r for r in ranking if val(r,'entry_type').upper()=='LIMIT']
    b1=read('sygnaly_1b_status_v329.csv')
    plan=read('plan_gry_v277.csv')
    approved_market=read('setups_market.csv')
    approved_limit=read('setups_limit.csv')
    top_market=read('top_market.csv')
    top_limit=read('top_limit.csv')
    diagnostic=[]; histogram=Counter()
    for r in ranking:
        reasons_list=reasons(r)
        for reason in reasons_list:histogram[(val(r,'entry_type') or 'BRAK',reason)]+=1
        diagnostic.append({'rodzina':'RANKING_'+(val(r,'entry_type').upper() or 'NIEZNANA'),
            'symbol':val(r,'symbol'),'side':val(r,'side'),
            'wariant':val(r,'setup_type'), 'ocena':val(r,'ocena'),
            'status':val(r,'status_setupu'), 'kwalifikacja':val(r,'do_handlu'),
            'powod_zrodlowy':' | '.join(reasons_list),
            'precyzja':'POLA_RANKINGU' if reasons_list and reasons_list!=['BRAK_SZCZEGOLU_W_POLACH_BLOKAD'] else 'BRAK_DOKLADNEJ_PRZYCZYNY',
            'nie_jest_fill':True})
    for r in b1:
        reason=val(r,'powod')
        generic=('Wariant nie przeszedl aktualnych filtrow sygnalu' in reason
                 or 'BRAK_PRECYZYJNEGO_POWODU_W_SILNIKU_1B' in reason)
        diagnostic.append({'rodzina':'SYGNAL_1B','symbol':val(r,'symbol'), 'side':val(r,'side'),
            'wariant':val(r,'sygnal'),'ocena':val(r,'ocena'),
            'status':val(r,'status_wykonawczy'),'kwalifikacja':val(r,'kwalifikacja_1b'),
            'powod_zrodlowy':reason or 'BRAK',
            'precyzja':'NIEUSTALONY_KONKRETNY_FILTR_1B' if generic or not reason else 'POWOD_ZRODLOWY',
            'nie_jest_fill':True})
    dcols=['rodzina','symbol','side','wariant','ocena','status','kwalifikacja',
           'powod_zrodlowy','precyzja','nie_jest_fill']
    output('odrzucenia_szczegoly_v338.csv',dcols,diagnostic)
    output('blokady_ranking_v338.csv',['rodzina','powod_zrodlowy','wiersze_w_zrodlowym_rankingu'],
           [{'rodzina':kind,'powod_zrodlowy':r,'wiersze_w_zrodlowym_rankingu':n}
            for (kind,r),n in sorted(histogram.items(),key=lambda x:(x[0][0],-x[1],x[0][1]))])
    funnel=[]
    for family,ranked,approved,top in [
        ('MARKET',ranked_market,approved_market,top_market),
        ('LIMIT',ranked_limit,approved_limit,top_limit)]:
        funnel.append({'rodzina':family, 'ranking_wiersze':len(ranked),
            'ranking_symbol_kierunek':unique(ranked),
            'ranking_zablokowane':sum(val(r,'status_setupu')=='ZABLOKOWANY' for r in ranked),
            'ranking_bez_wskazanej_przyczyny':sum('BRAK_SZCZEGOLU_W_POLACH_BLOKAD' in reasons(r) for r in ranked),
            'setups_wiersze':len(approved),'top_wiersze':len(top),
            'plan_gry_unikalne_symbol_kierunek':unique([r for r in plan if family in val(r,'typ').upper() or
                 (family=='MARKET' and 'LIMIT' not in val(r,'typ').upper())]),
            'status':'LICZNIKI_Z_OSOBNYCH_PLIKOW_NIE_JEST_TO_ZAMKNIETY_LEJEK_PRZEJSC'})
    output('lejek_market_limit_v338.csv',list(funnel[0]),funnel)
    # Variant counts and independent opportunities: use source okazja_id; don't merge similar IDs.
    opportunities=read('elliott_v325_short_okazje.csv')
    variants=read('elliott_v326_short_plany.csv')
    grouped=defaultdict(list)
    for r in variants:grouped[val(r,'okazja_id')].append(r)
    opportunities_view=[]
    known=set()
    for opp in opportunities:
        oid=val(opp,'okazja_id');known.add(oid)
        group=grouped.get(oid,[])
        opportunities_view.append({'okazja_id':oid,'symbol':val(opp,'symbol'),
            'kierunek':val(opp,'kierunek'),'liczba_wariantow_raport':len(group),
            'statusy_wariantow':' | '.join(sorted({val(x,'status') for x in group if val(x,'status')})),
            'przyczyny_odrzucenia':val(opp,'przyczyny_odrzucenia'),
            'bos_po_precommit':val(opp,'bos_po_precommit'),
            'potwierdzone_weex_fill':val(opp,'potwierdzone_weex_fill'),
            'uwaga':'ODREBNA_OKAZJA_C; podobienstwo innej struktury NIE oznacza automatycznego scalenia'})
    for oid,group in sorted(grouped.items()):
        if oid not in known:
            opportunities_view.append({'okazja_id':oid,'symbol':val(group[0],'symbol'),
                'kierunek':'SHORT','liczba_wariantow_raport':len(group),
                'statusy_wariantow':' | '.join(sorted({val(x,'status') for x in group})),
                'przyczyny_odrzucenia':'BRAK_W_REJESTRZE_OKAZJI',
                'bos_po_precommit':'','potwierdzone_weex_fill':'',
                'uwaga':'BRAK REJESTRU — kontrola spójności'})
    ecols=['okazja_id','symbol','kierunek','liczba_wariantow_raport',
           'statusy_wariantow','przyczyny_odrzucenia','bos_po_precommit',
           'potwierdzone_weex_fill','uwaga']
    output('elliott_unikalne_okazje_v338.csv',ecols,opportunities_view)
    # Paired historical replay by event_id and day. Daily means avoid treating variations
    # or symbols from the same day as independent days.
    events=read('audyt_tp_v332_transakcje.csv')
    byevent=defaultdict(dict)
    day_by_event={};type_by_event={};duplicates=0
    for r in events:
        eid=val(r,'event_id');scheme=val(r,'schemat');date=val(r,'fill_utc')[:10]
        rvalue=float_ok(r.get('r_netto'))
        if not eid or not date or not scheme or rvalue is None:continue
        if scheme in byevent[eid]:duplicates+=1;continue
        byevent[eid][scheme]=rvalue
        day_by_event[eid]=date;type_by_event[eid]=val(r,'entry_type').upper()
    groups=defaultdict(list)
    for eid,s in byevent.items():
        baseline=s.get('100_TP1')
        if baseline is None:continue
        for scheme,v in s.items():
            if scheme=='100_TP1':continue
            groups[(type_by_event[eid],day_by_event[eid],scheme)].append(v-baseline)
    daily=[]
    for (kind,day,scheme),vs in sorted(groups.items()):
        daily.append({'rodzina':kind,'dzien_utc':day,'wariant_tp':scheme,
                      'zdarzenia_sparowane':len(vs),'srednia_delta_r':round(sum(vs)/len(vs),8),
                      'mediana_delta_r':round(float(pd.Series(vs).median()),8),
                      'status':'HISTORYCZNY_REPLAY_NIE_PROSPEKTYWNY_OOS'})
    output('tp_dni_stabilnosc_v338.csv',['rodzina','dzien_utc','wariant_tp',
        'zdarzenia_sparowane','srednia_delta_r','mediana_delta_r','status'],daily)
    st=defaultdict(list)
    for row in daily:st[(row['rodzina'],row['wariant_tp'])].append(row)
    summary=[]
    for (kind,scheme),days in sorted(st.items()):
        positives=sum(r['srednia_delta_r']>0 for r in days)
        summary.append({'rodzina':kind,'wariant_tp':scheme,'rozne_dni':len(days),
            'dni_z_poprawa':positives,'udzial_dni_z_poprawa':round(positives/len(days),4),
            'srednia_dziennych_delta_r':round(sum(r['srednia_delta_r'] for r in days)/len(days),8),
            'status':'ZA_MALO_DNI_NIE_WLACZAC_AUTOMATYCZNIE' if len(days)<20 else 'WYMAGA_NIEZALEZNEGO_OOS'})
    output('tp_stabilnosc_podsumowanie_v338.csv',
           ['rodzina','wariant_tp','rozne_dni','dni_z_poprawa','udzial_dni_z_poprawa',
            'srednia_dziennych_delta_r','status'],summary)
    reason_counts=Counter(val(r,'precyzja') for r in diagnostic if val(r,'rodzina')=='SYGNAL_1B')
    lines=[f'# WEEX {VERSION} — AUDYT ODRZUCEŃ I STABILNOŚCI',
           'Raport tylko diagnostyczny: NIE zmienia wejść, scoringu, filtrów, TP, SL ani handlu.',
           '', '## Lejek MARKET / LIMIT (źródłowe pliki)',
           '| Rodzina | Ranking | Zablokowane | Setups | TOP | Plan (unikalne pary) |',
           '|---|---:|---:|---:|---:|---:|']
    for r in funnel:lines.append('| '+ ' | '.join(str(r[k]) for k in ['rodzina','ranking_wiersze','ranking_zablokowane','setups_wiersze','top_wiersze','plan_gry_unikalne_symbol_kierunek'])+' |')
    lines+=['','**Uwaga:** pliki ranking/setups/top mogą reprezentować różne etapy lub podzbiory. To nie jest udowodniony, zamknięty lejek tych samych rekordów.',
            '', '## Sygnały 1b',
            f'- Rekordy: {len(b1)}; unikalne symbol+kierunek: {unique(b1)}.',
            f'- Nieustalony konkretny filtr w źródle: {reason_counts.get("NIEUSTALONY_KONKRETNY_FILTR_1B",0)} rekordów.',
            '- Szczegółowe odrzucenia są dostępne tylko tam, gdzie zapisano je w źródłowym CSV. Ogólny komunikat nie pozwala przypisać konkretnego filtra.',
            '', '## Elliott SHORT',
            f'- Okazje ABC z osobnymi identyfikatorami: {len(opportunities_view)}; warianty filtrów: {len(variants)}.',
            '- Podobnych struktur nie scala się automatycznie. Nie traktować wariantów jak niezależnych transakcji.',
            '', '## Take Profit — dzienna stabilność replay',
            f'- Różne dni: {len(set(r["dzien_utc"] for r in daily))}; rekordy dzienne: {len(daily)}; zdublowane event_id+schemat: {duplicates}.',
            '- Badanie historyczne, zależne od dni, bez zatwierdzenia do zmiany realizacji TP.',
            '', 'Szczegóły: `odrzucenia_szczegoly_v338.csv`, `blokady_ranking_v338.csv`, `lejek_market_limit_v338.csv`, `elliott_unikalne_okazje_v338.csv`, `tp_dni_stabilnosc_v338.csv`, `tp_stabilnosc_podsumowanie_v338.csv`.']
    (root/'AUDYT_ODRZUCEN_TP_V338.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
    return {'ranking':len(ranking),'sygnaly_1b':len(b1),
        '1b_nieznany_konkretny_filtr':reason_counts.get('NIEUSTALONY_KONKRETNY_FILTR_1B',0),
        'elliott_okazje':len(opportunities_view),'elliott_warianty':len(variants),
        'tp_dni':len(set(r['dzien_utc'] for r in daily)),'tp_sparowane_eventy':len(byevent),
        'tp_duplikaty_event_schemat':duplicates}


def _v339_raport_odrzucen_1b(root):
    """Reconstruct counted source decisions without inferring unavailable predicates."""
    import csv
    from collections import Counter
    root=Path(root)
    inp=root/'sygnaly_1b_status_v329.csv'
    rows=[]
    if inp.is_file():
        with inp.open(encoding='utf-8-sig', newline='') as f:
            rows=list(csv.DictReader(f))
    codes=Counter()
    details=[]
    for r in rows:
        raw=str(r.get('v339_powody_odrzucenia') or '')
        active=str(r.get('status_wykonawczy') or '')
        known=bool(raw.strip())
        filters=[x.strip() for x in raw.split(' | ') if x.strip()]
        if active == 'NIE_ZAKWALIFIKOWANY' and not filters:
            filters=['BRAK_PRECYZYJNEGO_POWODU_W_SILNIKU_1B']
        for code in filters:codes[code.split(':',1)[0]]+=1
        details.append({'symbol':r.get('symbol',''),'side':r.get('side',''),
                        'sygnal':r.get('sygnal',''), 'status':active,
                        'powody': ' | '.join(filters),
                        'atrybucja':'CZESCIOWA_UDOKUMENTOWANA' if known else 'BRAK_ZAPISANEGO_WARUNKU',
                        'uwaga':'Powody to warunki udokumentowane, nie dowod wyczerpania wszystkich bramek.'})
    with (root/'odrzucenia_1b_v339.csv').open('w',encoding='utf-8',newline='') as f:
        fields=['symbol','side','sygnal','status','powody','atrybucja','uwaga']
        w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(details)
    with (root/'filtry_1b_liczniki_v339.csv').open('w',encoding='utf-8',newline='') as f:
        w=csv.DictWriter(f,fieldnames=['kod_filtra','warianty_z_przyczyna']);w.writeheader()
        w.writerows({'kod_filtra':code,'warianty_z_przyczyna':n} for code,n in sorted(codes.items()))
    return {'warianty':len(rows),'zapisany_powod':sum(bool(str(r.get('v339_powody_odrzucenia') or '').strip()) for r in rows),
            'bez_powodu':sum(str(r.get('status_wykonawczy'))=='NIE_ZAKWALIFIKOWANY' and not str(r.get('v339_powody_odrzucenia') or '').strip() for r in rows)}


def test_v339_powody_1b():
    from tempfile import TemporaryDirectory
    from unittest.mock import patch
    import csv
    x={'symbol':'XUSDT','side':'LONG','sygnal':'test','do_gry':True,'ocena':'B',
       'entry':1,'sl':0.9,'tp1':1.2,'rr':2,'v339_powody_odrzucenia':[]}
    _v339_dodaj_powod_1b(x,'KONFLIKT_MODELU_COINA','pk=0.2 <= 0.4')
    assert x['do_gry'] is True and x['ocena']=='B'
    assert len(x['v339_powody_odrzucenia'])==1
    assert 'KONFLIKT_MODELU_COINA' in x['v339_powody_odrzucenia'][0]
    with TemporaryDirectory() as td:
        root=Path(td)
        fields=['symbol','side','sygnal','status_wykonawczy','v339_powody_odrzucenia']
        with (root/'sygnaly_1b_status_v329.csv').open('w',encoding='utf8',newline='') as f:
            w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
            w.writerow({'symbol':'XUSDT','side':'LONG','sygnal':'s','status_wykonawczy':'NIE_ZAKWALIFIKOWANY',
                        'v339_powody_odrzucenia':x['v339_powody_odrzucenia'][0]})
            w.writerow({'symbol':'YUSDT','side':'SHORT','sygnal':'s','status_wykonawczy':'NIE_ZAKWALIFIKOWANY'})
        q=_v339_raport_odrzucen_1b(root)
        assert q=={'warianty':2,'zapisany_powod':1,'bez_powodu':1},q
        assert (root/'filtry_1b_liczniki_v339.csv').exists()
    return 'PASS: zapis warunku, brak zmiany kwalifikacji, jawna niekompletna atrybucja'


def test_v338_diagnostyka():
    from tempfile import TemporaryDirectory
    with TemporaryDirectory() as tmp:
        p=Path(tmp)
        pd.DataFrame([{'symbol':'LINKUSDT','side':'LONG','entry_type':'MARKET',
            'status_setupu':'ZABLOKOWANY','blokady_kwalifikacji':'ocena D; makro',
            'ocena':'D','do_handlu':False}]).to_csv(p/'ranking.csv',index=False)
        pd.DataFrame([{'symbol':'LINKUSDT','side':'LONG','sygnal':'test1','ocena':'D',
            'kwalifikacja_1b':'NIE','status_wykonawczy':'NIE_ZAKWALIFIKOWANY',
            'powod':'Wariant nie przeszedl aktualnych filtrow sygnalu'},
            {'symbol':'LINKUSDT','side':'LONG','sygnal':'test2','ocena':'D',
            'kwalifikacja_1b':'NIE','status_wykonawczy':'NIE_ZAKWALIFIKOWANY',
            'powod':'Wariant nie przeszedl aktualnych filtrow sygnalu'}]).to_csv(p/'sygnaly_1b_status_v329.csv',index=False)
        pd.DataFrame([{'okazja_id':'AAVE|SHORT|C1','symbol':'AAVEUSDT','kierunek':'SHORT'},
            {'okazja_id':'AAVE|SHORT|C2','symbol':'AAVEUSDT','kierunek':'SHORT'}]).to_csv(p/'elliott_v325_short_okazje.csv',index=False)
        pd.DataFrame([{'okazja_id':'AAVE|SHORT|C1','status':'ODRZUCONE'},
            {'okazja_id':'AAVE|SHORT|C1','status':'ODRZUCONE'},
            {'okazja_id':'AAVE|SHORT|C2','status':'WYGASL'}]).to_csv(p/'elliott_v326_short_plany.csv',index=False)
        pd.DataFrame([{'event_id':'e1','entry_type':'MARKET','fill_utc':'2026-10-01T12:00',
            'schemat':'100_TP1','r_netto':-0.8},
            {'event_id':'e1','entry_type':'MARKET','fill_utc':'2026-10-01T12:00',
            'schemat':'50_1R_50_TP1','r_netto':-0.5},
            {'event_id':'e2','entry_type':'MARKET','fill_utc':'2026-10-02T12:00',
            'schemat':'100_TP1','r_netto':0.2},
            {'event_id':'e2','entry_type':'MARKET','fill_utc':'2026-10-02T12:00',
            'schemat':'50_1R_50_TP1','r_netto':0.1}]).to_csv(p/'audyt_tp_v332_transakcje.csv',index=False)
        q=_v338_diagnostyka(p)
        assert q['ranking']==1 and q['1b_nieznany_konkretny_filtr']==2,q
        assert q['elliott_okazje']==2 and q['elliott_warianty']==3,q
        assert q['tp_dni']==2 and q['tp_sparowane_eventy']==2,q
        d=pd.read_csv(p/'tp_stabilnosc_podsumowanie_v338.csv')
        assert int(d.iloc[0]['dni_z_poprawa'])==1,d.to_dict('records')
        assert 'nie pozwala przypisać konkretnego filtra' in (p/'AUDYT_ODRZUCEN_TP_V338.md').read_text()
    return 'PASS (generyczne 1b, ranking, Elliott okazje, dzienne TP, bez zmiany handlu)'


