            r['oi_override_powod'] = (f"OI WEEX {w_oi / 1e6:.2f}M < prog {min_oi / 1e6:.1f}M, ale bez potwierdzenia z Gate "
                                      f"(OI WEEX bywa bledne) - prog OI pominiety; {dalej}")
